window.KS_COURSE={"title": "KS3 Science", "site": "ks3-science", "reviewed": "2026-10-24", "units": [{"id": "y7-unit-01", "year": 7, "number": 1, "title": "Working scientifically", "skills": ["safety", "variables", "planning", "burner", "data", "evaluate"], "test": {"mcq": [{"q": "Which piece of equipment should you use to measure 50 cm³ of water accurately?", "opts": ["Beaker.", "Conical flask.", "Measuring cylinder."], "a": 2, "why": "A measuring cylinder has a fine scale for volume."}, {"q": "A balance reads 0.3 g with nothing on it. This causes…", "opts": ["an anomaly.", "a systematic error.", "a random error."], "a": 1, "why": "Every reading will be 0.3 g too high."}, {"q": "Which graph should you draw for temperature against time?", "opts": ["A line graph.", "A bar chart.", "A pie chart."], "a": 0, "why": "Both variables are continuous."}], "parts": [{"q": "Name the independent and dependent variables when testing how the length of a pendulum affects the time for one swing.", "m": 2, "ms": ["Independent: length of the pendulum.", "Dependent: time for one swing."]}, {"q": "Times for ten swings were 14.2 s, 14.6 s and 14.4 s. Calculate the mean time for one swing.", "m": 3, "ms": ["Mean for ten swings = (14.2 + 14.6 + 14.4) ÷ 3 = 14.4 s.", "One swing = 14.4 ÷ 10…", "… = 1.44 s."]}, {"q": "Explain why scientists repeat measurements and calculate a mean.", "m": 3, "ms": ["Readings vary because of random errors.", "Repeats help you spot anomalies.", "A mean of repeats is closer to the true value / more reliable."]}, {"q": "A student heats water with a Bunsen burner. Describe four things she should do to work safely.", "m": 4, "ms": ["Wear safety goggles.", "Use a heatproof mat and the yellow flame when not heating.", "Tie back long hair and stand up.", "Use tongs or wait for equipment to cool before touching it."]}]}}, {"id": "y7-unit-02", "year": 7, "number": 2, "title": "Cells", "skills": ["microscope", "cell", "specialised", "diffusion"], "test": {"mcq": [{"q": "Which cell part controls what enters and leaves the cell?", "opts": ["Cell wall.", "Nucleus.", "Cell membrane."], "a": 2, "why": "The membrane controls movement in and out."}, {"q": "An eyepiece is ×10 and the objective is ×10. The total magnification is…", "opts": ["×1.", "×100.", "×20."], "a": 1, "why": "10 × 10 = 100."}, {"q": "Oxygen moves into cells by…", "opts": ["diffusion.", "filtration.", "condensation."], "a": 0, "why": "From high to low concentration."}], "parts": [{"q": "Name two parts found in plant cells but not in animal cells.", "m": 2, "ms": ["Cell wall / chloroplast / permanent vacuole.", "Any second correct part."]}, {"q": "Describe how to prepare a slide of cheek cells to see them clearly.", "m": 3, "ms": ["Gently scrape the inside of the cheek with a clean cotton bud and smear onto a slide.", "Add a drop of stain such as methylene blue.", "Lower a cover slip carefully to avoid air bubbles."]}, {"q": "Explain how a red blood cell is adapted to carry oxygen.", "m": 3, "ms": ["It has no nucleus, so there is more room for haemoglobin.", "It has a biconcave (dimpled disc) shape giving a large surface area.", "It is small and flexible to squeeze through capillaries."]}, {"q": "A drop of ink is added to still water. Describe and explain what happens over time, and how the result would change in warmer water.", "m": 4, "ms": ["The ink spreads out through the water.", "Its particles move from high to low concentration (diffusion).", "Particles keep moving randomly until they are evenly spread.", "In warmer water particles move faster, so it spreads faster."]}]}}, {"id": "y7-unit-03", "year": 7, "number": 3, "title": "Movement", "skills": ["organisation", "muscles", "planning"], "test": {"mcq": [{"q": "A group of similar cells working together is…", "opts": ["a tissue.", "an organ.", "an organ system."], "a": 0, "why": "Tissues are made of similar cells."}, {"q": "What joins a muscle to a bone?", "opts": ["A ligament.", "Cartilage.", "A tendon."], "a": 2, "why": "Tendons attach muscles to bones."}, {"q": "When you bend your arm, the biceps…", "opts": ["pushes the bone.", "contracts.", "relaxes."], "a": 1, "why": "The biceps pulls the forearm up."}], "parts": [{"q": "Give two functions of the skeleton.", "m": 2, "ms": ["Support / protection of organs.", "Movement / making blood cells."]}, {"q": "Describe what the biceps and triceps do when you straighten your arm.", "m": 3, "ms": ["The triceps contracts and pulls the forearm down.", "The biceps relaxes.", "They work as an antagonistic pair."]}, {"q": "Explain why a joint needs cartilage and synovial fluid.", "m": 3, "ms": ["Cartilage covers the ends of the bones.", "It is smooth and absorbs shocks.", "Synovial fluid lubricates the joint so bones move without rubbing."]}, {"q": "Explain why muscles must work in pairs, using the knee as an example.", "m": 4, "ms": ["Muscles can only pull when they contract; they cannot push.", "One muscle (at the front of the thigh) contracts to straighten the knee.", "Another muscle (at the back of the thigh) contracts to bend it.", "While one contracts, the other relaxes."]}]}}, {"id": "y7-unit-04", "year": 7, "number": 4, "title": "Particle model", "skills": ["particles", "state", "diffusion", "gas", "atoms"], "test": {"mcq": [{"q": "In which state are particles far apart and moving quickly in all directions?", "opts": ["Gas.", "Solid.", "Liquid."], "a": 0, "why": "Gas particles are widely spaced."}, {"q": "A liquid turning into a gas at its surface below the boiling point is…", "opts": ["condensation.", "melting.", "evaporation."], "a": 2, "why": "Evaporation happens at the surface."}, {"q": "Heating a sealed container of gas makes the pressure…", "opts": ["stay the same.", "increase.", "decrease."], "a": 1, "why": "Particles hit the walls harder and more often."}], "parts": [{"q": "Describe the arrangement and movement of particles in a solid.", "m": 2, "ms": ["Particles are close together in a regular pattern.", "They vibrate about fixed positions."]}, {"q": "Use the particle model to explain why a gas can be compressed but a liquid cannot.", "m": 3, "ms": ["In a gas there are large spaces between particles.", "Pushing moves gas particles closer together.", "In a liquid the particles are already touching, so there is no space."]}, {"q": "Explain the difference between an element, a compound and a mixture.", "m": 3, "ms": ["An element contains only one type of atom.", "A compound has two or more elements chemically joined.", "A mixture has substances that are not chemically joined and can be separated physically."]}, {"q": "Ice at −10 °C is heated until it becomes steam. Describe what happens to the particles at each stage.", "m": 4, "ms": ["The particles in the ice vibrate faster as it warms.", "At 0 °C they break free of fixed positions and the ice melts.", "In the liquid, particles move faster as it heats up.", "At 100 °C they escape from the liquid completely as a gas (boiling)."]}]}}, {"id": "y7-unit-05", "year": 7, "number": 5, "title": "Separating mixtures", "skills": ["atoms", "solution", "filter", "distil"], "test": {"mcq": [{"q": "Which method separates sand from water?", "opts": ["Chromatography.", "Filtration.", "Distillation."], "a": 1, "why": "Sand is insoluble, so filter paper traps it."}, {"q": "In salty water, salt is the…", "opts": ["solute.", "solvent.", "solution."], "a": 0, "why": "The solute is what dissolves."}, {"q": "Which method collects pure water from sea water?", "opts": ["Filtration.", "Crystallisation.", "Distillation."], "a": 2, "why": "Water evaporates and condenses; salt stays behind."}], "parts": [{"q": "10 g of sugar dissolves completely in 90 g of water. What is the mass of the solution? Give a reason.", "m": 2, "ms": ["100 g.", "Mass is conserved when a substance dissolves."]}, {"q": "Describe how to obtain salt crystals from rock salt.", "m": 3, "ms": ["Dissolve the rock salt in warm water and stir.", "Filter to remove the sand and grit.", "Heat the filtrate to evaporate some water, then leave it to crystallise."]}, {"q": "A chromatogram of a brown sweet colouring shows three spots. A yellow colouring shows one spot at the same height as one of them. What can you conclude?", "m": 3, "ms": ["The brown colouring is a mixture of at least three dyes.", "The yellow colouring is a single (pure) dye.", "The brown colouring probably contains the yellow dye."]}, {"q": "Explain how distillation separates water from inky water.", "m": 4, "ms": ["The mixture is heated so the water boils/evaporates.", "The ink does not evaporate and is left behind.", "The water vapour passes into a condenser, where it is cooled.", "It condenses back into pure liquid water, which is collected."]}]}}, {"id": "y7-unit-06", "year": 7, "number": 6, "title": "Energy costs", "skills": ["energy", "food-energy", "resources", "power"], "test": {"mcq": [{"q": "Which is a renewable energy resource?", "opts": ["Coal.", "Natural gas.", "Wind."], "a": 2, "why": "Wind will not run out."}, {"q": "What is 2500 W in kilowatts?", "opts": ["0.25 kW.", "2.5 kW.", "25 kW."], "a": 1, "why": "Divide by 1000."}, {"q": "A food sample raises water temperature more than another of the same mass. It probably…", "opts": ["contains more energy.", "contains less energy.", "has more water."], "a": 0, "why": "More energy was transferred to the water."}], "parts": [{"q": "Give one advantage and one disadvantage of using fossil fuels to generate electricity.", "m": 2, "ms": ["Advantage: reliable / available whenever needed.", "Disadvantage: release carbon dioxide / will run out / pollution."]}, {"q": "A 2 kW heater is used for 3 hours. Electricity costs 28p per kWh. Calculate the cost.", "m": 3, "ms": ["Energy = 2 × 3 = 6 kWh.", "Cost = 6 × 28…", "… = 168p (£1.68)."]}, {"q": "In the burning-food experiment, explain why the measured energy is less than the real energy in the food.", "m": 3, "ms": ["Some energy heats the air around the tube.", "Some heats the tube and clamp, not the water.", "Some food may not burn completely."]}, {"q": "Compare wind turbines and a coal power station for generating electricity.", "m": 4, "ms": ["Wind is renewable; coal will run out.", "Wind does not release carbon dioxide when running; coal does.", "Coal is reliable at any time; wind depends on the weather.", "Wind farms take up lots of space / can be noisy or spoil views."]}]}}, {"id": "y7-unit-07", "year": 7, "number": 7, "title": "Energy transfers", "skills": ["energy", "efficiency"], "test": {"mcq": [{"q": "A moving car has energy in its…", "opts": ["kinetic store.", "elastic store.", "nuclear store."], "a": 0, "why": "Moving objects have kinetic energy."}, {"q": "A device transfers 200 J; 50 J is useful. Its efficiency is…", "opts": ["75%.", "4%.", "25%."], "a": 2, "why": "50 ÷ 200 × 100."}, {"q": "Energy cannot be…", "opts": ["stored.", "created or destroyed.", "transferred."], "a": 1, "why": "The law of conservation of energy."}], "parts": [{"q": "Describe the energy transfer when a battery-powered fan is switched on.", "m": 2, "ms": ["Energy is transferred from the chemical store of the battery…", "… to the kinetic store of the blades (and wasted to the thermal store of the surroundings)."]}, {"q": "A kettle uses 2000 J and transfers 1800 J to the water. Calculate its efficiency as a percentage.", "m": 3, "ms": ["1800 ÷ 2000 = 0.9.", "0.9 × 100…", "… = 90%."]}, {"q": "Explain why an LED bulb is better than a filament bulb.", "m": 3, "ms": ["The LED is more efficient.", "It wastes less energy by heating the surroundings.", "So it uses less electricity for the same light, saving money."]}, {"q": "A ball is dropped from a height and bounces. Describe the energy changes until it comes to rest.", "m": 4, "ms": ["As it falls, energy transfers from the gravitational store to the kinetic store.", "On impact some energy is stored elastically as it squashes.", "Some energy is transferred to the thermal store of the ball and floor and carried away by sound.", "Each bounce is lower until all the energy has spread to the surroundings."]}]}}, {"id": "y7-unit-08", "year": 7, "number": 8, "title": "Variation and adaptation", "skills": ["variation", "adaptation", "data"], "test": {"mcq": [{"q": "Which is an example of continuous variation?", "opts": ["Blood group.", "Tongue rolling.", "Height."], "a": 2, "why": "Height can take any value in a range."}, {"q": "Which variation is caused only by the environment?", "opts": ["Blood group.", "A scar.", "Natural eye colour."], "a": 1, "why": "Scars come from injuries."}, {"q": "Why does a cactus have spines?", "opts": ["To reduce water loss.", "To photosynthesise faster.", "To attract insects."], "a": 0, "why": "Spines have a small surface area."}], "parts": [{"q": "Give one example of inherited variation and one of environmental variation in humans.", "m": 2, "ms": ["Inherited: blood group / natural eye colour.", "Environmental: scars / language spoken / tattoos."]}, {"q": "Describe how to collect and display data on the hand spans of students in your class.", "m": 3, "ms": ["Measure each hand span with a ruler in cm.", "Group the data into class intervals (e.g. 16–17 cm).", "Draw a histogram/bar chart of how many students are in each group."]}, {"q": "Explain two ways a polar bear is adapted to the Arctic.", "m": 3, "ms": ["Thick fur and a layer of fat insulate it, reducing heat loss.", "White fur gives camouflage on snow for hunting.", "Small ears reduce heat loss / large feet spread weight on ice."]}, {"q": "Explain why some features show both inherited and environmental variation, using body mass as an example.", "m": 4, "ms": ["Genes affect body build and how the body uses food.", "The environment also affects mass, such as diet and exercise.", "So identical twins (same genes) can have different masses.", "Body mass therefore depends on both causes."]}]}}, {"id": "y7-unit-09", "year": 7, "number": 9, "title": "Human reproduction", "skills": ["puberty", "cycle", "pregnancy"], "test": {"mcq": [{"q": "Where are sperm cells made?", "opts": ["Testes.", "Ovaries.", "Uterus."], "a": 0, "why": "Sperm are made in the testes."}, {"q": "Where does fertilisation usually happen?", "opts": ["Uterus.", "Vagina.", "Oviduct."], "a": 2, "why": "The egg meets a sperm in the oviduct."}, {"q": "What does the placenta do?", "opts": ["Makes sperm.", "Passes oxygen and food to the fetus and removes waste.", "Makes eggs."], "a": 1, "why": "It is the exchange organ."}], "parts": [{"q": "Name two hormones involved in puberty and where each is made.", "m": 2, "ms": ["Testosterone, made in the testes.", "Oestrogen, made in the ovaries."]}, {"q": "Describe what happens during the menstrual cycle if an egg is not fertilised.", "m": 3, "ms": ["The uterus lining thickens and an egg is released (ovulation).", "If not fertilised, the lining breaks down.", "It leaves the body through the vagina as a period."]}, {"q": "Explain how the fetus gets oxygen while in the uterus.", "m": 3, "ms": ["Oxygen in the mother’s blood passes into the placenta.", "It diffuses into the fetus’s blood.", "It travels along the umbilical cord to the fetus."]}, {"q": "Explain why pregnant women are advised not to smoke or drink alcohol.", "m": 4, "ms": ["Harmful chemicals can cross the placenta into the fetus’s blood.", "Carbon monoxide from smoking reduces the oxygen the fetus receives.", "This can cause low birth weight or premature birth.", "Alcohol can damage the developing brain and organs."]}]}}, {"id": "y7-unit-10", "year": 7, "number": 10, "title": "Plant reproduction", "skills": ["flower", "seed", "germination"], "test": {"mcq": [{"q": "Which part of the flower makes pollen?", "opts": ["Anther.", "Stigma.", "Ovary."], "a": 0, "why": "The anther is a male part."}, {"q": "Which feature suggests a flower is wind-pollinated?", "opts": ["Bright petals.", "Nectar.", "Feathery stigmas hanging outside the flower."], "a": 2, "why": "Wind flowers do not need to attract insects."}, {"q": "Which condition is NOT needed for germination?", "opts": ["Warmth.", "Light.", "Water."], "a": 1, "why": "Seeds use stored food."}], "parts": [{"q": "What is the difference between pollination and fertilisation?", "m": 2, "ms": ["Pollination is the transfer of pollen to a stigma.", "Fertilisation is when the male and female nuclei join."]}, {"q": "Describe what happens after a pollen grain lands on a stigma until a seed forms.", "m": 3, "ms": ["A pollen tube grows down the style to the ovule.", "The male nucleus travels down the tube and joins the egg nucleus.", "The fertilised ovule develops into a seed."]}, {"q": "Describe how you could show that seeds need water to germinate.", "m": 3, "ms": ["Put seeds on damp cotton wool in one dish and dry cotton wool in another.", "Keep both in the same warm place.", "Compare after a few days; only the damp dish should germinate."]}, {"q": "Explain why it is useful for plants to disperse their seeds, and describe two methods.", "m": 4, "ms": ["If seeds land near the parent, they compete for light, water and minerals.", "Dispersal spreads them so more survive.", "Wind: seeds with wings or parachutes, e.g. sycamore, dandelion.", "Animals: fruits eaten or hooks caught on fur / explosion: pea pods."]}]}}, {"id": "y7-unit-11", "year": 7, "number": 11, "title": "Acids and alkalis", "skills": ["reaction", "acid", "neutral"], "test": {"mcq": [{"q": "A solution has a pH of 2. It is…", "opts": ["alkaline.", "strongly acidic.", "neutral."], "a": 1, "why": "pH 2 is well below 7."}, {"q": "What colour is universal indicator in a neutral solution?", "opts": ["Green.", "Red.", "Purple."], "a": 0, "why": "pH 7 is green."}, {"q": "Acid + alkali → ?", "opts": ["Hydrogen + oxygen.", "Carbon dioxide only.", "Salt + water."], "a": 2, "why": "This is neutralisation."}], "parts": [{"q": "Give two signs that a chemical reaction has taken place.", "m": 2, "ms": ["Colour change / fizzing.", "Temperature change / solid forms."]}, {"q": "Name the salt made when hydrochloric acid reacts with sodium hydroxide, the other product, and the type of reaction.", "m": 3, "ms": ["Sodium chloride.", "Water.", "Neutralisation."]}, {"q": "Explain how a farmer could treat acidic soil and why.", "m": 3, "ms": ["Add lime (a base) to the soil.", "It neutralises the acid.", "Most crops grow better when the soil is near neutral."]}, {"q": "Describe how to use universal indicator to find the volume of alkali needed to neutralise 25 cm³ of acid.", "m": 4, "ms": ["Measure 25 cm³ of acid with a measuring cylinder and add universal indicator.", "Add alkali a little at a time from a burette/syringe, swirling.", "Stop when the indicator turns green (pH 7).", "Record the volume of alkali added and repeat for reliability."]}]}}, {"id": "y7-unit-12", "year": 7, "number": 12, "title": "Metals and non-metals", "skills": ["metals", "metal-acid"], "test": {"mcq": [{"q": "Which is a property of most metals?", "opts": ["Brittle.", "Low melting point.", "Good electrical conductor."], "a": 2, "why": "Metals conduct electricity."}, {"q": "Which metal does NOT react with dilute acid?", "opts": ["Zinc.", "Copper.", "Magnesium."], "a": 1, "why": "Copper is low in reactivity."}, {"q": "The test for hydrogen is…", "opts": ["a lit splint gives a squeaky pop.", "limewater turns milky.", "a glowing splint relights."], "a": 0, "why": "Hydrogen burns rapidly."}], "parts": [{"q": "Complete the word equation “magnesium + oxygen → …” and name this type of reaction.", "m": 2, "ms": ["Magnesium oxide.", "Oxidation (combustion/burning)."]}, {"q": "Write the word equation for zinc reacting with hydrochloric acid, and describe the test for the gas made.", "m": 3, "ms": ["Zinc + hydrochloric acid → zinc chloride…", "… + hydrogen.", "A lit splint gives a squeaky pop."]}, {"q": "Explain why gold is used for electrical connections in computers even though copper is cheaper.", "m": 3, "ms": ["Gold is very unreactive.", "It does not corrode or form an oxide layer.", "So it keeps a good electrical connection for a long time."]}, {"q": "Describe how you could compare the reactivity of three metals using acid.", "m": 4, "ms": ["Use the same mass/size of each metal.", "Add each to the same volume and concentration of acid at the same temperature.", "Observe the rate of bubbling or measure the temperature rise.", "The faster the bubbling (or bigger the temperature rise), the more reactive the metal."]}]}}, {"id": "y7-unit-13", "year": 7, "number": 13, "title": "Current and charge", "skills": ["charge", "current"], "test": {"mcq": [{"q": "A rubbed balloon gains electrons. It becomes…", "opts": ["negatively charged.", "positively charged.", "neutral."], "a": 0, "why": "Electrons are negative."}, {"q": "Two positively charged objects will…", "opts": ["attract.", "do nothing.", "repel."], "a": 2, "why": "Like charges repel."}, {"q": "Current is measured with…", "opts": ["an ammeter connected in parallel.", "an ammeter connected in series.", "a voltmeter connected in series."], "a": 1, "why": "Ammeters go in series."}], "parts": [{"q": "What is an electric current?", "m": 2, "ms": ["A flow of charge (electrons) around a circuit.", "It is measured in amps (A)."]}, {"q": "A series circuit has a cell and two lamps. One lamp breaks. Explain what happens to the other.", "m": 3, "ms": ["It goes out.", "There is only one path, so the circuit is broken.", "No current flows."]}, {"q": "Explain why you sometimes get a small shock touching a metal door handle after walking on a carpet.", "m": 3, "ms": ["Rubbing your shoes on the carpet transfers electrons, so you become charged.", "When you touch the metal handle, the charge flows quickly to it.", "This flow is a spark that you feel as a shock."]}, {"q": "Compare series and parallel circuits for the lights in a house.", "m": 4, "ms": ["In series there is one path; in parallel each light has its own branch.", "In series, if one bulb breaks all go out; in parallel the others stay on.", "In parallel each light can be switched on or off separately.", "In parallel each light gets the full voltage so stays bright."]}]}}, {"id": "y7-unit-14", "year": 7, "number": 14, "title": "Potential difference and resistance", "skills": ["voltage", "current"], "test": {"mcq": [{"q": "Potential difference is measured in…", "opts": ["amps (A).", "ohms (Ω).", "volts (V)."], "a": 2, "why": "Voltage is in volts."}, {"q": "A voltmeter is connected…", "opts": ["anywhere in the circuit.", "in parallel across a component.", "in series."], "a": 1, "why": "It measures energy difference across a part."}, {"q": "Increasing the resistance in a circuit (same cells) makes the current…", "opts": ["smaller.", "bigger.", "stay the same."], "a": 0, "why": "More resistance opposes the flow more."}], "parts": [{"q": "A 9 V battery drives 3 A through a component. Calculate its resistance.", "m": 2, "ms": ["R = V ÷ I = 9 ÷ 3.", "= 3 Ω."]}, {"q": "A 12 V supply is connected to a 6 Ω resistor. Calculate the current and state the units.", "m": 3, "ms": ["I = V ÷ R = 12 ÷ 6.", "= 2…", "… A (amps)."]}, {"q": "Explain why the wires in a circuit are made of copper and covered in plastic.", "m": 3, "ms": ["Copper has low resistance, so it conducts current easily.", "Plastic is an insulator.", "It stops current flowing into people and prevents short circuits."]}, {"q": "Describe how to measure the resistance of a piece of wire.", "m": 4, "ms": ["Connect the wire in series with a cell and an ammeter.", "Connect a voltmeter in parallel across the wire.", "Record the current and the potential difference.", "Calculate resistance = voltage ÷ current (repeat at different voltages)."]}]}}, {"id": "y8-unit-01", "year": 8, "number": 1, "title": "Interdependence", "skills": ["foodweb", "ecosystem"], "test": {"mcq": [{"q": "In the food chain grass → rabbit → fox, the rabbit is a…", "opts": ["primary consumer.", "producer.", "top predator."], "a": 0, "why": "It eats the producer."}, {"q": "Arrows in a food chain show…", "opts": ["which animal is biggest.", "where animals live.", "the direction energy moves."], "a": 2, "why": "They point to the eater."}, {"q": "Placing quadrats randomly helps to…", "opts": ["find rare plants.", "avoid bias.", "count faster."], "a": 1, "why": "Random sampling is fair."}], "parts": [{"q": "Give two things that plants compete for.", "m": 2, "ms": ["Light / water.", "Space / minerals (nutrients)."]}, {"q": "A 40 m² lawn is sampled with five 1 m² quadrats containing 2, 4, 3, 5 and 1 daisies. Estimate the number of daisies on the lawn.", "m": 3, "ms": ["Mean = (2 + 4 + 3 + 5 + 1) ÷ 5 = 3 per m².", "3 × 40…", "… = 120 daisies."]}, {"q": "Owls eat mice, and mice eat seeds. Explain what would happen to the seeds if the owls were removed.", "m": 3, "ms": ["The mouse population would increase.", "More mice would eat more seeds.", "So the number of seeds would decrease."]}, {"q": "A pesticide is sprayed on a field. Explain how it could harm birds of prey even though they do not eat the plants.", "m": 4, "ms": ["Small amounts of pesticide are taken in by insects or small animals eating the plants.", "The pesticide is not broken down, so it builds up in their bodies.", "Birds of prey eat many of these animals.", "So the pesticide builds up to harmful levels in the top predator (bioaccumulation)."]}]}}, {"id": "y8-unit-02", "year": 8, "number": 2, "title": "Speed", "skills": ["speed", "dt", "data"], "test": {"mcq": [{"q": "A runner covers 100 m in 20 s. The average speed is…", "opts": ["5 m/s.", "2000 m/s.", "0.2 m/s."], "a": 0, "why": "100 ÷ 20."}, {"q": "On a distance–time graph, a horizontal line means the object is…", "opts": ["speeding up.", "moving at a steady speed.", "stationary."], "a": 2, "why": "Distance is not changing."}, {"q": "Which is a typical speed for walking?", "opts": ["150 m/s.", "1.5 m/s.", "15 m/s."], "a": 1, "why": "About 1–2 m/s."}], "parts": [{"q": "A train travels at 50 m/s for 120 s. Calculate the distance travelled.", "m": 2, "ms": ["Distance = speed × time = 50 × 120.", "= 6000 m."]}, {"q": "A cyclist travels 3 km in 10 minutes. Calculate her average speed in m/s.", "m": 3, "ms": ["3 km = 3000 m and 10 minutes = 600 s.", "Speed = 3000 ÷ 600…", "… = 5 m/s."]}, {"q": "A distance–time graph shows a straight line that becomes steeper halfway. Describe and explain the motion.", "m": 3, "ms": ["First the object moves at a steady speed.", "Then it moves at a faster steady speed.", "A steeper line means more distance per second."]}, {"q": "Describe how to find the average speed of a student running 100 m, and one way to make the timing more accurate.", "m": 4, "ms": ["Measure out 100 m with a long tape measure.", "Start a stopwatch as the runner starts and stop it as they cross the line.", "Calculate speed = 100 ÷ time.", "Use light gates or a video to remove reaction time errors."]}]}}, {"id": "y8-unit-03", "year": 8, "number": 3, "title": "Gravity and forces", "skills": ["force", "gravity", "crater"], "test": {"mcq": [{"q": "Weight is measured in…", "opts": ["kilograms (kg).", "metres (m).", "newtons (N)."], "a": 2, "why": "Weight is a force."}, {"q": "Forces of 30 N right and 30 N left act on a box. The box…", "opts": ["speeds up to the left.", "does not change its motion.", "speeds up to the right."], "a": 1, "why": "The forces are balanced."}, {"q": "On the Moon, a person’s mass…", "opts": ["stays the same.", "gets smaller.", "gets bigger."], "a": 0, "why": "Mass does not depend on gravity."}], "parts": [{"q": "A 4 kg bag is on Earth, where g = 10 N/kg. Calculate its weight.", "m": 2, "ms": ["W = m × g = 4 × 10.", "= 40 N."]}, {"q": "A boat has a 600 N forward force and 450 N of drag. Calculate the resultant force and describe the boat’s motion.", "m": 3, "ms": ["600 − 450 = 150 N.", "Forwards.", "The boat speeds up."]}, {"q": "In a crater investigation, a ball is dropped from different heights into flour. Explain why the crater gets wider as the height increases.", "m": 3, "ms": ["The ball falls further, so it gains more speed.", "It has more kinetic energy when it lands.", "More energy pushes more flour aside."]}, {"q": "Explain the difference between mass and weight, and why an astronaut weighs less on the Moon.", "m": 4, "ms": ["Mass is the amount of matter, in kg.", "Weight is the force of gravity on an object, in N.", "The Moon has a weaker gravitational field strength than Earth.", "So the same mass has a smaller weight there."]}]}}, {"id": "y8-unit-04", "year": 8, "number": 4, "title": "Elements and materials", "skills": ["atoms", "elements", "metals", "polymer"], "test": {"mcq": [{"q": "Which is the correct symbol for magnesium?", "opts": ["Ma.", "Mg.", "MG."], "a": 1, "why": "First capital, then lower case."}, {"q": "How many atoms are in one molecule of H₂O?", "opts": ["3.", "2.", "1."], "a": 0, "why": "Two hydrogen and one oxygen."}, {"q": "Which is a synthetic polymer?", "opts": ["Wool.", "Cotton.", "Polythene."], "a": 2, "why": "It is made in factories."}], "parts": [{"q": "Name the elements in sodium chloride and give its formula.", "m": 2, "ms": ["Sodium and chlorine.", "NaCl."]}, {"q": "Give the number of each type of atom in Ca(OH)₂.", "m": 3, "ms": ["1 calcium.", "2 oxygen.", "2 hydrogen."]}, {"q": "Explain why copper is used for wires but plastic is used to cover them.", "m": 3, "ms": ["Copper is a good electrical conductor.", "It is also ductile, so it can be drawn into wires.", "Plastic is an insulator, which keeps people safe from shocks."]}, {"q": "Evaluate the use of plastic for drinks bottles.", "m": 4, "ms": ["Plastic is light, cheap and does not break easily.", "It is waterproof and can be moulded into shapes.", "However, most plastics do not biodegrade and cause litter or harm wildlife.", "Recycling or reusable bottles reduce this problem."]}]}}, {"id": "y8-unit-05", "year": 8, "number": 5, "title": "Periodic table", "skills": ["periodic", "groups", "transition"], "test": {"mcq": [{"q": "A vertical column in the periodic table is a…", "opts": ["period.", "row.", "group."], "a": 2, "why": "Groups have similar properties."}, {"q": "Which element is a noble gas?", "opts": ["Chlorine.", "Neon.", "Sodium."], "a": 1, "why": "Group 0."}, {"q": "Going down Group 1, the metals become…", "opts": ["more reactive.", "less reactive.", "gases."], "a": 0, "why": "Potassium reacts faster than lithium."}], "parts": [{"q": "Name the group that contains the halogens, and give one example.", "m": 2, "ms": ["Group 7.", "Fluorine / chlorine / bromine / iodine."]}, {"q": "Describe what you would see when potassium is added to water.", "m": 3, "ms": ["It floats and moves quickly across the surface.", "It fizzes and melts into a ball.", "It burns with a lilac flame / may make a small bang."]}, {"q": "Rubidium is below potassium in Group 1. Predict how it reacts with water and explain your prediction.", "m": 3, "ms": ["It reacts even more vigorously (possibly explosively).", "It makes an alkaline solution and hydrogen.", "Reactivity increases down Group 1."]}, {"q": "Compare the properties of Group 1 metals and transition metals.", "m": 4, "ms": ["Group 1 metals are soft (can be cut with a knife); transition metals are hard.", "Group 1 metals have low melting points; transition metals have high melting points.", "Group 1 metals are very reactive; transition metals are much less reactive.", "Transition metals form coloured compounds and are used as catalysts."]}]}}, {"id": "y8-unit-06", "year": 8, "number": 6, "title": "Breathing and health", "skills": ["lungs", "drugs"], "test": {"mcq": [{"q": "Gas exchange happens in the…", "opts": ["alveoli.", "trachea.", "diaphragm."], "a": 0, "why": "Tiny air sacs."}, {"q": "When you breathe in, the diaphragm…", "opts": ["relaxes and moves up.", "stays still.", "contracts and flattens."], "a": 2, "why": "This increases the chest volume."}, {"q": "Which substance in tobacco smoke is addictive?", "opts": ["Carbon dioxide.", "Nicotine.", "Tar."], "a": 1, "why": "Nicotine causes dependence."}], "parts": [{"q": "Name the gas that diffuses from the blood into the alveoli and the gas that diffuses the other way.", "m": 2, "ms": ["Carbon dioxide into the alveoli.", "Oxygen into the blood."]}, {"q": "Describe what happens to the ribs, diaphragm and chest volume when you breathe out.", "m": 3, "ms": ["The intercostal muscles relax and the ribs move down and in.", "The diaphragm relaxes and moves up.", "The chest volume decreases, so air is pushed out."]}, {"q": "Explain two ways the alveoli are adapted for gas exchange.", "m": 3, "ms": ["Large surface area from millions of alveoli.", "Walls one cell thick for a short diffusion distance.", "Good blood supply keeps a high concentration difference."]}, {"q": "Explain how smoking damages health.", "m": 4, "ms": ["Tar coats the lungs and contains chemicals that cause cancer.", "Smoke damages the cilia, so mucus and dirt build up, causing coughing and infections.", "Carbon monoxide reduces the oxygen the blood can carry.", "Nicotine raises heart rate and blood pressure, increasing the risk of heart disease."]}]}}, {"id": "y8-unit-07", "year": 8, "number": 7, "title": "Digestion and nutrition", "skills": ["nutrition", "food-tests", "digestion"], "test": {"mcq": [{"q": "Which nutrient is needed for growth and repair?", "opts": ["Protein.", "Fibre.", "Water."], "a": 0, "why": "Protein builds cells."}, {"q": "Iodine solution turns blue-black with…", "opts": ["protein.", "fat.", "starch."], "a": 2, "why": "The starch test."}, {"q": "Where are most small food molecules absorbed into the blood?", "opts": ["Large intestine.", "Small intestine.", "Stomach."], "a": 1, "why": "Villi absorb food."}], "parts": [{"q": "Name the enzyme that digests fats and the products formed.", "m": 2, "ms": ["Lipase.", "Fatty acids and glycerol."]}, {"q": "Describe how to test a food sample for sugar.", "m": 3, "ms": ["Grind the food and mix with water.", "Add Benedict’s solution and heat in a water bath.", "A colour change from blue to brick-red shows sugar."]}, {"q": "Explain why the small intestine is good at absorbing food.", "m": 3, "ms": ["It is very long.", "It has villi, which give a huge surface area.", "The villi have thin walls and a good blood supply."]}, {"q": "Explain why a balanced diet is important, giving the role of three different nutrients.", "m": 4, "ms": ["A balanced diet gives the right amounts of each nutrient.", "Carbohydrates (and fats) provide energy.", "Protein is used for growth and repair.", "Vitamins and minerals keep the body healthy; fibre keeps food moving through the gut."]}]}}, {"id": "y8-unit-08", "year": 8, "number": 8, "title": "Sound", "skills": ["sound", "ear"], "test": {"mcq": [{"q": "Sound cannot travel through…", "opts": ["water.", "steel.", "a vacuum."], "a": 2, "why": "There are no particles."}, {"q": "A larger amplitude makes a sound…", "opts": ["faster.", "louder.", "higher-pitched."], "a": 1, "why": "Amplitude affects loudness."}, {"q": "The part of the ear that changes vibrations into nerve impulses is the…", "opts": ["cochlea.", "eardrum.", "ear canal."], "a": 0, "why": "It contains hair cells."}], "parts": [{"q": "A sound wave has a frequency of 500 Hz. What does this mean?", "m": 2, "ms": ["500 vibrations (waves)…", "… every second."]}, {"q": "Thunder is heard 3 s after lightning is seen. Sound travels at 340 m/s. How far away is the storm?", "m": 3, "ms": ["Distance = speed × time.", "= 340 × 3…", "… = 1020 m."]}, {"q": "Explain why sound travels faster in solids than in gases.", "m": 3, "ms": ["Sound is passed on by vibrating particles.", "In a solid, the particles are much closer together.", "So vibrations are passed on more quickly."]}, {"q": "Describe how sound from a drum reaches and is detected by your ear.", "m": 4, "ms": ["The drum skin vibrates and makes the air particles vibrate.", "The vibrations pass through the air as a longitudinal wave.", "They make the eardrum vibrate, and the ossicles pass the vibrations to the cochlea.", "The cochlea sends electrical impulses along the auditory nerve to the brain."]}]}}, {"id": "y8-unit-09", "year": 8, "number": 9, "title": "Light", "skills": ["light", "colour"], "test": {"mcq": [{"q": "The angle of reflection is equal to the…", "opts": ["angle of incidence.", "angle of refraction.", "normal."], "a": 0, "why": "The law of reflection."}, {"q": "White light is split into colours by a…", "opts": ["plane mirror.", "red filter.", "prism."], "a": 2, "why": "This is dispersion."}, {"q": "A red book seen in blue light looks…", "opts": ["blue.", "black.", "red."], "a": 1, "why": "It absorbs the blue light."}], "parts": [{"q": "Light travels from air into glass. Describe how its speed and direction change.", "m": 2, "ms": ["It slows down.", "It bends towards the normal."]}, {"q": "A ray of light hits a mirror at 40° to the normal. State the angle of reflection and between which two lines it is measured, and name the law this shows.", "m": 3, "ms": ["40°.", "Between the normal and the reflected ray.", "The law of reflection: angle of incidence = angle of reflection."]}, {"q": "Explain why a white shirt looks white in sunlight.", "m": 3, "ms": ["Sunlight contains all the colours.", "The white shirt reflects all of them.", "All the colours together reach our eyes and look white."]}, {"q": "Describe an experiment to show that light travels in straight lines and reflects at equal angles.", "m": 4, "ms": ["Shine a narrow ray of light from a ray box at a plane mirror on paper.", "Draw the normal and mark the incident and reflected rays.", "Measure the angles of incidence and reflection with a protractor.", "Repeat for different angles; the two angles are equal each time."]}]}}, {"id": "y8-unit-10", "year": 8, "number": 10, "title": "Reaction types", "skills": ["reaction", "combustion", "mass"], "test": {"mcq": [{"q": "Burning a fuel in oxygen is…", "opts": ["neutralisation.", "combustion.", "thermal decomposition."], "a": 1, "why": "Reaction with oxygen."}, {"q": "The test for carbon dioxide is…", "opts": ["it turns limewater milky.", "a squeaky pop.", "it relights a glowing splint."], "a": 0, "why": "Limewater goes cloudy."}, {"q": "In a sealed flask, the total mass during a reaction…", "opts": ["increases.", "decreases.", "stays the same."], "a": 2, "why": "Atoms are conserved."}], "parts": [{"q": "Give two products of the complete combustion of methane.", "m": 2, "ms": ["Carbon dioxide.", "Water."]}, {"q": "Write the word equation for the thermal decomposition of calcium carbonate.", "m": 3, "ms": ["Calcium carbonate →", "calcium oxide +", "carbon dioxide."]}, {"q": "A student heats magnesium in a crucible and the mass increases. Explain why.", "m": 3, "ms": ["The magnesium reacts with oxygen from the air.", "Oxygen atoms join to form magnesium oxide.", "The added oxygen makes the mass increase."]}, {"q": "Explain why the mass of an open beaker of acid and marble chips decreases, and how to show that mass is really conserved.", "m": 4, "ms": ["The reaction makes carbon dioxide gas.", "The gas escapes into the air, so it is not weighed.", "Do the reaction in a sealed container (e.g. a flask with a balloon over it).", "The total mass then stays the same, showing atoms are conserved."]}]}}, {"id": "y8-unit-11", "year": 8, "number": 11, "title": "Chemical energy", "skills": ["chemical-energy", "catalyst"], "test": {"mcq": [{"q": "A reaction that makes the surroundings warmer is…", "opts": ["exothermic.", "endothermic.", "reversible only."], "a": 0, "why": "Energy is released."}, {"q": "A catalyst…", "opts": ["is used up in the reaction.", "always slows reactions.", "speeds up a reaction and is not used up."], "a": 2, "why": "It can be reused."}, {"q": "Which is endothermic?", "opts": ["Neutralisation.", "Thermal decomposition.", "Combustion."], "a": 1, "why": "It takes in energy."}], "parts": [{"q": "The temperature of a reaction mixture falls from 21 °C to 14 °C. Calculate the change and name the type of reaction.", "m": 2, "ms": ["A decrease of 7 °C.", "Endothermic."]}, {"q": "Give three ways to speed up the reaction between magnesium and acid.", "m": 3, "ms": ["Increase the temperature.", "Use more concentrated acid.", "Use powder instead of a ribbon (larger surface area) / add a catalyst."]}, {"q": "Explain why enzymes stop working at high temperatures.", "m": 3, "ms": ["Enzymes are proteins with a special shape.", "High temperatures change their shape (denature them).", "The substrate no longer fits, so the reaction is not sped up."]}, {"q": "Describe how to find out whether dissolving a salt in water is exothermic or endothermic.", "m": 4, "ms": ["Measure the starting temperature of water in an insulated cup.", "Add the salt and stir.", "Record the highest or lowest temperature reached.", "A rise means exothermic; a fall means endothermic."]}]}}, {"id": "y8-unit-12", "year": 8, "number": 12, "title": "Respiration", "skills": ["respiration", "anaerobic", "planning"], "test": {"mcq": [{"q": "Aerobic respiration happens in the…", "opts": ["cell wall.", "mitochondria.", "nucleus."], "a": 1, "why": "Mitochondria release energy."}, {"q": "Which is a product of anaerobic respiration in muscles?", "opts": ["Lactic acid.", "Oxygen.", "Ethanol."], "a": 0, "why": "Lactic acid builds up."}, {"q": "Yeast makes bread rise because it releases…", "opts": ["oxygen.", "lactic acid.", "carbon dioxide."], "a": 2, "why": "Gas bubbles get trapped."}], "parts": [{"q": "Write the word equation for aerobic respiration.", "m": 2, "ms": ["Glucose + oxygen →", "carbon dioxide + water."]}, {"q": "Give three differences between aerobic and anaerobic respiration in humans.", "m": 3, "ms": ["Aerobic uses oxygen; anaerobic does not.", "Aerobic releases more energy per glucose.", "Aerobic makes carbon dioxide and water; anaerobic makes lactic acid."]}, {"q": "Explain why your breathing rate stays high for a while after a sprint.", "m": 3, "ms": ["During the sprint muscles respired anaerobically, making lactic acid.", "Extra oxygen is needed to break down the lactic acid.", "This is called the oxygen debt."]}, {"q": "A student measures her pulse before and after exercise. Describe the method and explain the result she should expect.", "m": 4, "ms": ["Measure resting pulse for 1 minute, then exercise for a set time.", "Measure pulse immediately after, then every minute until it returns to normal.", "The pulse rate rises during exercise.", "The heart beats faster to deliver more oxygen and glucose for respiration in the muscles."]}]}}, {"id": "y8-unit-13", "year": 8, "number": 13, "title": "Photosynthesis", "skills": ["photosynthesis", "leaf", "plant-practical"], "test": {"mcq": [{"q": "Photosynthesis happens in the…", "opts": ["nucleus.", "chloroplasts.", "mitochondria."], "a": 1, "why": "They contain chlorophyll."}, {"q": "Which gas do plants take in for photosynthesis?", "opts": ["Carbon dioxide.", "Oxygen.", "Nitrogen."], "a": 0, "why": "CO₂ enters through stomata."}, {"q": "Tiny pores on leaves are called…", "opts": ["alveoli.", "villi.", "stomata."], "a": 2, "why": "They let gases in and out."}], "parts": [{"q": "Write the word equation for photosynthesis.", "m": 2, "ms": ["Carbon dioxide + water →", "glucose + oxygen (using light)."]}, {"q": "Give three ways a leaf is adapted for photosynthesis.", "m": 3, "ms": ["Broad to absorb lots of light.", "Thin so gases diffuse a short distance.", "Contains many chloroplasts / has stomata for gas exchange."]}, {"q": "Pondweed gives 30 bubbles per minute with a lamp 10 cm away and 8 bubbles per minute at 40 cm. Explain the result.", "m": 3, "ms": ["Closer lamp means more light intensity.", "More light gives a faster rate of photosynthesis.", "So more oxygen bubbles are produced."]}, {"q": "Describe how to test a leaf for starch and explain why this shows photosynthesis has happened.", "m": 4, "ms": ["Boil the leaf in water to kill it, then in ethanol (heated in a water bath) to remove chlorophyll.", "Rinse and spread on a tile.", "Add iodine: blue-black shows starch.", "Glucose made by photosynthesis is stored as starch."]}]}}, {"id": "y8-unit-14", "year": 8, "number": 14, "title": "Working scientifically investigations", "skills": ["investigate-candle", "investigate-bounce", "investigate-bungee", "investigate-conduction", "investigate-cupcake", "investigate-salt", "investigate-diffusion"], "test": {"mcq": [{"q": "A test is fair when…", "opts": ["only one result is taken.", "only the independent variable is changed.", "all variables are changed."], "a": 1, "why": "Control variables stay the same."}, {"q": "Terminal velocity is reached when…", "opts": ["air resistance equals weight.", "weight is zero.", "air resistance is zero."], "a": 0, "why": "Forces balance."}, {"q": "Conduction is fastest in…", "opts": ["plastics.", "air.", "metals."], "a": 2, "why": "Metals have free electrons."}], "parts": [{"q": "A cord is 30 cm long and stretches to 38 cm. Calculate the extension.", "m": 2, "ms": ["38 − 30…", "… = 8 cm."]}, {"q": "In a bouncing-ball test, give three control variables.", "m": 3, "ms": ["The same ball.", "The same surface.", "The same way of releasing the ball (no throwing) / same temperature."]}, {"q": "A student times how long salt takes to dissolve at different temperatures. Suggest one improvement and explain how it helps.", "m": 3, "ms": ["Use a data logger/conductivity meter or a black background to judge the end point.", "This makes the end point less subjective.", "So the times are more accurate and repeatable."]}, {"q": "Plan an investigation into how the mass of a paper case affects its falling time.", "m": 4, "ms": ["Change mass by stacking cases (1–5 cases).", "Drop from the same height each time.", "Time the fall with a stopwatch and repeat three times to find a mean.", "Plot mass against mean time and look for a pattern."]}]}}, {"id": "y9-unit-01", "year": 9, "number": 1, "title": "Electromagnets", "skills": ["magnet", "electromagnet", "planning"], "test": {"mcq": [{"q": "Which is a magnetic material?", "opts": ["Copper.", "Aluminium.", "Nickel."], "a": 2, "why": "Iron, nickel and cobalt are magnetic."}, {"q": "Opposite magnetic poles…", "opts": ["have no effect.", "attract.", "repel."], "a": 1, "why": "N and S attract."}, {"q": "Adding an iron core to a coil makes the electromagnet…", "opts": ["stronger.", "weaker.", "stop working."], "a": 0, "why": "Iron concentrates the field."}], "parts": [{"q": "Give two ways to make an electromagnet stronger, other than adding an iron core.", "m": 2, "ms": ["More turns of wire on the coil.", "A bigger current."]}, {"q": "Describe how to use a plotting compass to find the shape of a bar magnet’s field.", "m": 3, "ms": ["Place the compass near the magnet and mark where the needle points.", "Move the compass to the mark and repeat, building a line.", "Join the marks and repeat from different starting points."]}, {"q": "Explain why electromagnets are used in scrapyard cranes instead of permanent magnets.", "m": 3, "ms": ["An electromagnet can be switched on to pick up iron and steel.", "Switching it off releases the scrap where it is needed.", "A permanent magnet cannot be switched off."]}, {"q": "Plan an investigation into how the number of coils affects the strength of an electromagnet.", "m": 4, "ms": ["Change the number of coils (e.g. 10, 20, 30, 40, 50).", "Keep the current, core and wire the same.", "Measure strength by counting paperclips picked up.", "Repeat each test and calculate a mean, then plot a graph."]}]}}, {"id": "y9-unit-02", "year": 9, "number": 2, "title": "Work and machines", "skills": ["work", "food-energy", "moments"], "test": {"mcq": [{"q": "A force of 100 N moves an object 3 m. The work done is…", "opts": ["33 J.", "103 J.", "300 J."], "a": 2, "why": "W = F × d."}, {"q": "The turning effect of a force is called a…", "opts": ["pivot.", "moment.", "pressure."], "a": 1, "why": "Moment = force × distance."}, {"q": "A long spanner makes it easier to undo a nut because…", "opts": ["the distance from the pivot is bigger.", "it is heavier.", "it reduces friction."], "a": 0, "why": "Bigger distance, bigger moment."}], "parts": [{"q": "A 250 N force acts 0.4 m from a pivot. Calculate the moment.", "m": 2, "ms": ["M = 250 × 0.4.", "= 100 N m."]}, {"q": "A 500 N child sits 1.2 m from a seesaw pivot. How far from the pivot must a 400 N child sit to balance it?", "m": 3, "ms": ["500 × 1.2 = 600 N m.", "600 ÷ 400…", "… = 1.5 m."]}, {"q": "Explain how a ramp makes it easier to lift a heavy box into a van.", "m": 3, "ms": ["The box is pushed along a longer distance.", "So a smaller force is needed.", "The work done (force × distance) is about the same."]}, {"q": "A crane lifts a 1200 N load 20 m in 40 s. Calculate the work done and explain where the energy goes.", "m": 4, "ms": ["W = 1200 × 20 = 24 000 J.", "Energy is transferred to the load’s gravitational potential store.", "Some energy is wasted heating the motor and surroundings.", "So the crane uses more than 24 000 J in total."]}]}}, {"id": "y9-unit-03", "year": 9, "number": 3, "title": "Heating and cooling", "skills": ["thermal", "convection"], "test": {"mcq": [{"q": "Energy is transferred by heating from…", "opts": ["a hotter object to a colder one.", "a colder object to a hotter one.", "objects at the same temperature."], "a": 0, "why": "Heat flows from hot to cold."}, {"q": "Which surface emits infrared best?", "opts": ["Shiny silver.", "White gloss.", "Dull black."], "a": 2, "why": "Matt black is the best emitter."}, {"q": "Warm air rises because it is…", "opts": ["heavier.", "less dense.", "more dense."], "a": 1, "why": "This causes convection."}], "parts": [{"q": "Name the three ways energy can be transferred by heating.", "m": 2, "ms": ["Conduction and convection.", "Radiation (infrared)."]}, {"q": "Describe how a radiator heats a whole room.", "m": 3, "ms": ["Air next to the radiator is heated and expands, becoming less dense.", "The warm air rises and cooler air sinks to replace it.", "This convection current carries energy around the room."]}, {"q": "Explain why a vacuum flask keeps a drink hot.", "m": 3, "ms": ["The vacuum stops conduction and convection.", "The silvered walls reflect infrared radiation back.", "The stopper reduces energy loss by convection and evaporation."]}, {"q": "Explain four ways a family can reduce energy loss from their house.", "m": 4, "ms": ["Loft insulation traps air, reducing conduction and convection through the roof.", "Cavity wall insulation reduces energy loss through walls.", "Double glazing has a gap that reduces conduction through windows.", "Draught excluders stop warm air escaping (convection)."]}]}}, {"id": "y9-unit-04", "year": 9, "number": 4, "title": "Climate", "skills": ["atmosphere", "climate"], "test": {"mcq": [{"q": "Most of the air is…", "opts": ["carbon dioxide.", "nitrogen.", "oxygen."], "a": 1, "why": "About 78%."}, {"q": "Which process removes carbon dioxide from the atmosphere?", "opts": ["Photosynthesis.", "Combustion.", "Respiration."], "a": 0, "why": "Plants take in CO₂."}, {"q": "Which is a greenhouse gas?", "opts": ["Nitrogen.", "Oxygen.", "Methane."], "a": 2, "why": "Methane traps infrared."}], "parts": [{"q": "Give two human activities that increase carbon dioxide in the atmosphere.", "m": 2, "ms": ["Burning fossil fuels.", "Cutting down/burning forests (deforestation)."]}, {"q": "Describe the greenhouse effect.", "m": 3, "ms": ["The Sun’s radiation warms the Earth’s surface.", "The Earth emits infrared radiation.", "Greenhouse gases absorb some and send it back, keeping Earth warm."]}, {"q": "Explain the difference between weather and climate.", "m": 3, "ms": ["Weather is the conditions on a particular day.", "Climate is the average weather over many years.", "So one cold winter does not disprove climate change."]}, {"q": "Describe two effects of climate change and two ways to reduce it.", "m": 4, "ms": ["Rising sea levels from melting ice and warming water.", "More extreme weather / changing habitats.", "Use renewable energy instead of fossil fuels.", "Plant trees / use public transport / insulate homes."]}]}}, {"id": "y9-unit-05", "year": 9, "number": 5, "title": "Earth’s resources", "skills": ["extraction", "metals", "recycle"], "test": {"mcq": [{"q": "A rock containing enough metal to extract is an…", "opts": ["alloy.", "element.", "ore."], "a": 2, "why": "Ores are mined."}, {"q": "Iron is extracted from iron oxide by heating with…", "opts": ["water.", "carbon.", "oxygen."], "a": 1, "why": "Carbon is more reactive."}, {"q": "Recycling aluminium saves energy because…", "opts": ["extracting it by electrolysis uses lots of electricity.", "aluminium is rare.", "it is heavy."], "a": 0, "why": "Recycling uses about 5% of the energy."}], "parts": [{"q": "Complete: iron oxide + carbon → …", "m": 2, "ms": ["Iron.", "Carbon dioxide."]}, {"q": "Explain why aluminium cannot be extracted by heating its ore with carbon.", "m": 3, "ms": ["Aluminium is more reactive than carbon.", "Carbon cannot remove the oxygen from aluminium oxide.", "So electrolysis must be used."]}, {"q": "Give three advantages of recycling metals.", "m": 3, "ms": ["Saves energy.", "Saves finite ores.", "Less mining damage / less landfill / less carbon dioxide."]}, {"q": "Evaluate recycling steel cans compared with making new steel.", "m": 4, "ms": ["Recycling uses less energy and fewer raw materials.", "It reduces waste in landfill and damage from mining.", "But cans must be collected, sorted and transported, which costs money and energy.", "Overall recycling is usually better for the environment."]}]}}, {"id": "y9-unit-06", "year": 9, "number": 6, "title": "Evolution and biodiversity", "skills": ["selection", "evidence-evolution", "biodiversity"], "test": {"mcq": [{"q": "Who developed the theory of evolution by natural selection?", "opts": ["Charles Darwin.", "Gregor Mendel.", "Isaac Newton."], "a": 0, "why": "Darwin published in 1859."}, {"q": "Fossils are usually found in…", "opts": ["igneous rock.", "metamorphic rock.", "sedimentary rock."], "a": 2, "why": "Sediment buries remains."}, {"q": "A species with no living members is…", "opts": ["adapted.", "extinct.", "endangered."], "a": 1, "why": "It has died out."}], "parts": [{"q": "Give two types of evidence for evolution.", "m": 2, "ms": ["Fossils.", "DNA similarities / antibiotic resistance in bacteria."]}, {"q": "Explain why the fossil record is incomplete.", "m": 3, "ms": ["Most organisms decay before they can fossilise.", "Fossils need special conditions to form.", "Many fossils are destroyed or not yet found."]}, {"q": "Give three ways people can protect endangered species.", "m": 3, "ms": ["Nature reserves / protecting habitats.", "Captive breeding in zoos.", "Seed banks / laws against hunting."]}, {"q": "Explain how bacteria become resistant to an antibiotic by natural selection.", "m": 4, "ms": ["There is variation: a few bacteria have a gene for resistance.", "The antibiotic kills the non-resistant bacteria.", "Resistant bacteria survive and reproduce.", "The resistant gene is passed on, so the population becomes resistant."]}]}}, {"id": "y9-unit-07", "year": 9, "number": 7, "title": "Inheritance", "skills": ["inheritance", "dna-practical", "cross", "gm"], "test": {"mcq": [{"q": "A section of DNA that codes for a characteristic is a…", "opts": ["nucleus.", "gene.", "chromosome."], "a": 1, "why": "Genes are on chromosomes."}, {"q": "How many chromosomes are in a human egg cell?", "opts": ["23.", "46.", "92."], "a": 0, "why": "Sex cells have half."}, {"q": "Choosing parents with useful features to breed is…", "opts": ["natural selection.", "fertilisation.", "selective breeding."], "a": 2, "why": "Humans choose the parents."}], "parts": [{"q": "What is the difference between a genotype and a phenotype?", "m": 2, "ms": ["Genotype is the alleles an organism has, e.g. Bb.", "Phenotype is the feature that shows, e.g. brown eyes."]}, {"q": "In peas, tall (T) is dominant to short (t). Two Tt plants are crossed. Give the possible genotypes of the offspring and the chance of a short plant.", "m": 3, "ms": ["TT, Tt, Tt, tt.", "Short plants are tt.", "Chance = 1 in 4 (25%)."]}, {"q": "Describe how to extract DNA from strawberries.", "m": 3, "ms": ["Mash the strawberries with washing-up liquid and salt to break cells open.", "Filter the mixture.", "Pour ice-cold ethanol on top; DNA appears as white strands."]}, {"q": "Discuss one benefit and one concern of genetic modification of crops, and of selective breeding.", "m": 4, "ms": ["GM benefit: pest resistance or extra vitamins, e.g. golden rice.", "GM concern: possible effects on wildlife or genes spreading to wild plants.", "Selective breeding benefit: higher yields / more milk.", "Selective breeding concern: less variation, so disease can wipe out a whole crop or herd."]}]}}, {"id": "y9-unit-08", "year": 9, "number": 8, "title": "Waves and the EM spectrum", "skills": ["waves", "ultrasound", "em"], "test": {"mcq": [{"q": "In a longitudinal wave, the vibrations are…", "opts": ["parallel to the direction of travel.", "at right angles to the direction of travel.", "random."], "a": 0, "why": "Sound is longitudinal."}, {"q": "Ultrasound has a frequency…", "opts": ["below 20 Hz.", "between 20 and 2000 Hz.", "above 20 000 Hz."], "a": 2, "why": "Too high to hear."}, {"q": "Which EM wave has the shortest wavelength?", "opts": ["Microwaves.", "Gamma rays.", "Radio waves."], "a": 1, "why": "Gamma has the highest frequency."}], "parts": [{"q": "A wave has frequency 4 Hz and wavelength 3 m. Calculate its speed.", "m": 2, "ms": ["v = f × λ = 4 × 3.", "= 12 m/s."]}, {"q": "A sonar pulse takes 0.6 s to return from the sea bed. Sound in water travels at 1500 m/s. Calculate the depth.", "m": 3, "ms": ["Distance there and back = 1500 × 0.6 = 900 m.", "Depth = 900 ÷ 2…", "… = 450 m."]}, {"q": "Explain why ultrasound rather than X-rays is used to scan an unborn baby.", "m": 3, "ms": ["X-rays have high energy and can damage cells and DNA.", "Ultrasound does not harm cells.", "Ultrasound reflects from tissue boundaries to build an image."]}, {"q": "Describe one use and one danger of three different parts of the EM spectrum.", "m": 4, "ms": ["Radio waves: communication; little danger at normal levels.", "Microwaves: cooking/phones; can heat body tissue.", "Ultraviolet: tanning/sterilising; causes sunburn and skin cancer.", "X-rays/gamma: seeing bones/treating cancer; can damage cells and cause cancer."]}]}}, {"id": "y9-unit-09", "year": 9, "number": 9, "title": "Earth structure and rocks", "skills": ["earth", "sediment", "rock-cycle"], "test": {"mcq": [{"q": "Which layer of the Earth is liquid?", "opts": ["Inner core.", "Crust.", "Outer core."], "a": 2, "why": "It is liquid metal."}, {"q": "Rock formed from cooled magma is…", "opts": ["metamorphic.", "igneous.", "sedimentary."], "a": 1, "why": "Granite and basalt."}, {"q": "Freeze–thaw weathering happens because water…", "opts": ["expands when it freezes.", "contracts when it freezes.", "dissolves rock."], "a": 0, "why": "Ice takes up more space."}], "parts": [{"q": "Name the four main layers of the Earth from the outside in.", "m": 2, "ms": ["Crust and mantle.", "Outer core and inner core."]}, {"q": "Explain why granite has large crystals but basalt has small crystals.", "m": 3, "ms": ["Granite cooled slowly underground.", "Crystals had a long time to grow.", "Basalt cooled quickly at the surface, so the crystals are small."]}, {"q": "Describe how sedimentary rock forms.", "m": 3, "ms": ["Rocks are weathered and eroded into small pieces.", "Rivers deposit the sediment in layers.", "Layers are compacted and cemented together over millions of years."]}, {"q": "Describe how a piece of sedimentary rock could become igneous rock, naming the processes.", "m": 4, "ms": ["It is buried deep underground.", "Heat and pressure may change it into metamorphic rock.", "Deeper still it melts to form magma.", "The magma cools and solidifies to form igneous rock."]}]}}, {"id": "y9-unit-10", "year": 9, "number": 10, "title": "The Universe", "skills": ["space", "orbits", "moon"], "test": {"mcq": [{"q": "The Earth orbits the Sun once every…", "opts": ["day.", "month.", "year (about 365 days)."], "a": 2, "why": "One orbit is one year."}, {"q": "A light year is a unit of…", "opts": ["speed.", "distance.", "time."], "a": 1, "why": "The distance light travels in a year."}, {"q": "A lunar eclipse happens when…", "opts": ["Earth’s shadow falls on the Moon.", "the Moon blocks the Sun.", "the Moon is new."], "a": 0, "why": "Earth is between the Sun and Moon."}], "parts": [{"q": "Put in order of size, smallest first: star, planet, galaxy, Universe.", "m": 2, "ms": ["Planet, star.", "Galaxy, Universe."]}, {"q": "Explain what causes day and night.", "m": 3, "ms": ["The Earth spins on its axis.", "One spin takes about 24 hours.", "The side facing the Sun has day; the side facing away has night."]}, {"q": "Explain why the UK has longer days in summer than in winter.", "m": 3, "ms": ["The Earth’s axis is tilted.", "In summer the northern hemisphere is tilted towards the Sun.", "So the UK spends more of each spin in sunlight."]}, {"q": "Explain why we see different phases of the Moon over a month.", "m": 4, "ms": ["The Moon does not make its own light; it reflects sunlight.", "The Sun always lights half of the Moon.", "As the Moon orbits Earth, we see different amounts of the lit half.", "This changes from new Moon to full Moon and back in about 28 days."]}]}}, {"id": "y9-unit-11", "year": 9, "number": 11, "title": "Contact forces", "skills": ["friction", "spring", "moments"], "test": {"mcq": [{"q": "Friction acts…", "opts": ["against the direction of motion.", "in the direction of motion.", "only upwards."], "a": 0, "why": "It opposes sliding."}, {"q": "A spring is 10 cm long and 16 cm when stretched. The extension is…", "opts": ["26 cm.", "16 cm.", "6 cm."], "a": 2, "why": "16 − 10."}, {"q": "Streamlining a car reduces…", "opts": ["mass.", "air resistance (drag).", "weight."], "a": 1, "why": "A smooth shape cuts drag."}], "parts": [{"q": "Give one useful and one unwanted effect of friction.", "m": 2, "ms": ["Useful: grip / brakes / walking.", "Unwanted: wear / wasted energy as heat."]}, {"q": "A spring extends 2 cm for every 1 N. Calculate the extension for 4.5 N and state Hooke’s law.", "m": 3, "ms": ["4.5 × 2 = 9 cm.", "Extension is proportional to force…", "… up to the limit of proportionality."]}, {"q": "Explain why a cyclist crouches low when riding fast.", "m": 3, "ms": ["Crouching reduces the area facing the air.", "This reduces air resistance (drag).", "So less energy is wasted and the cyclist can go faster."]}, {"q": "Describe how to investigate the relationship between force and extension for a spring.", "m": 4, "ms": ["Hang the spring from a clamp next to a vertical ruler and record its original length.", "Add 1 N weights one at a time, recording the new length each time.", "Calculate extension = new length − original length.", "Plot force against extension; a straight line through the origin shows Hooke’s law."]}]}}, {"id": "y9-unit-12", "year": 9, "number": 12, "title": "Pressure", "skills": ["pressure", "gas", "liquid-pressure"], "test": {"mcq": [{"q": "Pressure is calculated by…", "opts": ["force ÷ area.", "force × area.", "area ÷ force."], "a": 0, "why": "P = F ÷ A."}, {"q": "Water pressure increases with…", "opts": ["height above the water.", "the width of the container.", "depth."], "a": 2, "why": "More water above presses down."}, {"q": "Heating a gas in a sealed container makes its pressure…", "opts": ["stay the same.", "increase.", "decrease."], "a": 1, "why": "Particles hit the walls harder."}], "parts": [{"q": "A 900 N force acts on an area of 3 m². Calculate the pressure and give the unit.", "m": 2, "ms": ["900 ÷ 3 = 300.", "Pascals (Pa) / N/m²."]}, {"q": "A 600 N person stands on snow. Calculate the pressure with shoes of total area 0.04 m² and with skis of area 0.3 m².", "m": 3, "ms": ["Shoes: 600 ÷ 0.04 = 15 000 Pa.", "Skis: 600 ÷ 0.3 = 2000 Pa.", "The skis give a smaller pressure, so they sink less."]}, {"q": "Explain why a dam is built thicker at the bottom than at the top.", "m": 3, "ms": ["Water pressure increases with depth.", "The force on the bottom of the dam is greatest.", "A thicker base is needed to withstand it."]}, {"q": "Use the particle model to explain why a football gets harder when you pump in more air.", "m": 4, "ms": ["Air pressure is caused by particles hitting the inside walls.", "Pumping adds more particles in the same volume.", "The particles collide with the walls more often.", "So the pressure inside increases and the ball feels harder."]}]}}], "lessons": [{"key": "safety", "title": "Staying safe in the lab", "notes": ["A hazard is something that could hurt you. A risk is the chance of being hurt and how serious it could be. Follow your teacher's instructions in the lab.", "Wear goggles when liquids could splash. Use a measuring cylinder to measure liquid volume. Read the bottom of the water curve at eye level.", "Hazard symbols warn you about a danger, such as flammable or corrosive. A risk assessment lists the hazards, how likely harm is, and how to reduce it. Tie back long hair and stand up when heating."], "worked": "Hot glass can burn skin. Leave it to cool before touching it. Use a heatproof mat to protect the bench.", "question": "How would you measure 25 cm³ of water? Give one way to protect your eyes from splashes.", "scheme": ["Use a measuring cylinder with a clear scale.", "Read the bottom of the water curve at eye level.", "Wear safety goggles."], "mistake": "Saying “be careful” is not enough. Say what you would do to stay safe.", "model": null, "id": "y7-unit-01-safety", "unit": "y7-unit-01", "year": 7, "number": 1, "marks": 3, "cards": [{"term": "Hazard", "definition": "Something that could cause harm."}, {"term": "Risk", "definition": "The chance of harm and how serious it could be."}], "quiz": {"q": "Which action protects your eyes from splashes?", "opts": ["Take no measurements.", "Wear safety goggles.", "Only write “be careful”."], "a": 1, "why": "Goggles help stop splashes reaching your eyes."}, "misconception": {"q": "Which action protects your eyes from splashes? Sam answers: “Only write “be careful”.” Explain why this is wrong.", "m": 2, "ms": ["Wear safety goggles.", "Goggles help stop splashes reaching your eyes."]}, "more": [{"q": "Which symbol warns that a substance can burn skin?", "opts": ["Corrosive.", "Flammable.", "Harmful to the environment."], "a": 0, "why": "Corrosive substances can damage skin and eyes on contact."}, {"q": "What should you do first if a chemical splashes in your eye?", "opts": ["Rub your eye hard.", "Wait until the lesson ends.", "Rinse it with lots of clean water and tell your teacher."], "a": 2, "why": "Rinsing quickly washes the chemical away before it does more damage."}, {"q": "Why should you stand up during practical work with a Bunsen burner?", "opts": ["Because chairs are flammable.", "So you can move away quickly if something spills or catches fire.", "So you can see the board better."], "a": 1, "why": "Standing lets you step back from hot spills or flames."}, {"q": "A risk assessment is written…", "opts": ["before you start the practical.", "after the practical is finished.", "only if something goes wrong."], "a": 0, "why": "You plan how to stay safe before you begin."}], "ladder": [{"q": "What is a hazard?", "m": 1, "ms": ["Something that could cause harm."], "step": "Remember"}, {"q": "Give two safety rules for heating a liquid in a test tube.", "m": 2, "ms": ["Wear safety goggles.", "Point the test tube away from people / heat gently / use a test-tube holder."], "step": "Apply"}, {"q": "Explain how a risk assessment helps keep a practical safe.", "m": 3, "ms": ["It identifies the hazards.", "It judges how likely and how serious harm could be.", "It sets out precautions to reduce the risk."], "step": "Explain"}]}, {"key": "variables", "title": "Questions, predictions and variables", "notes": ["A variable is something that can change in an experiment. The independent variable is the one you change. The dependent variable is the one you measure.", "Keep control variables the same to make the test fair. A prediction says what you think will happen. Use a science idea to explain your prediction.", "A fair test changes only one variable at a time. If two things change at once, you cannot tell which one caused the result. A good question links the independent and dependent variables."], "worked": "To test how temperature affects sugar dissolving, change the water temperature. Measure the time taken for the sugar to dissolve. Keep the sugar mass and water volume the same.", "question": "Test how light affects pondweed. Name what you change, what you measure and two things you keep the same.", "scheme": ["Change light level, for example by moving the lamp.", "Measure oxygen made in a set time.", "Keep water temperature and carbon dioxide supply the same."], "mistake": "A fair test changes one variable at a time.", "model": null, "id": "y7-unit-01-variables", "unit": "y7-unit-01", "year": 7, "number": 2, "marks": 3, "cards": [{"term": "Independent variable", "definition": "The thing you choose to change in a test."}, {"term": "Dependent variable", "definition": "The thing you measure in a test."}, {"term": "Control variable", "definition": "Something you keep the same to make a test fair."}], "quiz": {"q": "In a test of temperature and dissolving time, what do you measure?", "opts": ["Time taken for the solid to dissolve.", "The temperature you choose.", "The label on the beaker."], "a": 0, "why": "You change the temperature and measure the time taken to dissolve."}, "misconception": {"q": "In a test of temperature and dissolving time, what do you measure? Sam answers: “The temperature you choose.” Explain why this is wrong.", "m": 2, "ms": ["Time taken for the solid to dissolve.", "You change the temperature and measure the time taken to dissolve."]}, "more": [{"q": "You test how the height of a ramp affects the speed of a car. What is the independent variable?", "opts": ["Speed of the car.", "Mass of the car.", "Height of the ramp."], "a": 2, "why": "You choose and change the ramp height."}, {"q": "Which is a control variable in that test?", "opts": ["The height of the ramp.", "The same car is used each time.", "The speed of the car."], "a": 1, "why": "Keeping the car the same makes the test fair."}, {"q": "Which prediction is testable?", "opts": ["The higher the ramp, the faster the car will go.", "Cars are interesting.", "The ramp is red."], "a": 0, "why": "A testable prediction says how one variable affects another."}, {"q": "Why change only one variable at a time?", "opts": ["To make the test quicker.", "So you need less equipment.", "So you know what caused any change in results."], "a": 2, "why": "If two things change, you cannot tell which caused the effect."}], "ladder": [{"q": "What is the dependent variable?", "m": 1, "ms": ["The variable you measure."], "step": "Remember"}, {"q": "Lia tests how temperature affects how fast sugar dissolves. Name the independent variable and one control variable.", "m": 2, "ms": ["Independent: temperature of the water.", "Control: mass of sugar / volume of water / stirring."], "step": "Apply"}, {"q": "Explain why Lia must keep the volume of water the same.", "m": 3, "ms": ["Volume of water could also change the dissolving time.", "If it changed, she could not tell whether temperature caused the effect.", "Keeping it the same makes it a fair test."], "step": "Explain"}]}, {"key": "planning", "title": "Planning tests and taking measurements", "notes": ["Write steps that someone else could follow. Say what to measure and which units to use. Choose equipment that can measure the small changes you expect.", "Check that your equipment reads zero before you start. Repeat each measurement to spot results that do not fit. Calculate a mean by adding the readings and dividing by their number.", "Choose a sensible range and interval, such as 20 °C to 60 °C in steps of 10 °C. Repeat readings and calculate a mean. Write a method in numbered steps."], "worked": "Suppose ten pendulum swings take 12 seconds. One swing takes 12 ÷ 10 = 1.2 seconds. Timing several swings reduces the effect of your reaction time.", "question": "How could you improve the time measurement for one pendulum swing? Give two ideas and explain one.", "scheme": ["Time several swings, then divide by the number of swings.", "Repeat the measurement and calculate a mean.", "Use the same point to start and stop timing."], "mistake": "Repeating readings will not fix a clock that always reads too high.", "model": null, "id": "y7-unit-01-planning", "unit": "y7-unit-01", "year": 7, "number": 3, "marks": 3, "cards": [{"term": "Resolution", "definition": "The smallest change a measuring instrument can show."}, {"term": "Repeatability", "definition": "Getting similar results when the same person repeats the same test."}], "quiz": {"q": "Why time ten swings instead of one?", "opts": ["It makes the clock perfect.", "It reduces the effect of your reaction time on each swing's time.", "It fixes every equipment error."], "a": 1, "why": "Divide the longer total time by ten. Your reaction time then has a smaller effect on each swing's time."}, "misconception": {"q": "Why time ten swings instead of one? Sam answers: “It fixes every equipment error.” Explain why this is wrong.", "m": 2, "ms": ["It reduces the effect of your reaction time on each swing's time.", "Divide the longer total time by ten. Your reaction time then has a smaller effect on each swing's time."]}, "more": [{"q": "Which instrument best measures 25 cm³ of water?", "opts": ["A measuring cylinder.", "A beaker.", "A thermometer."], "a": 0, "why": "A measuring cylinder has a scale for volume."}, {"q": "How do you calculate a mean of three repeats?", "opts": ["Choose the middle value only.", "Subtract the smallest from the largest.", "Add the three values and divide by 3."], "a": 2, "why": "Mean = total ÷ number of values."}, {"q": "A ruler marked in mm has a resolution of…", "opts": ["1 m.", "1 mm.", "1 cm."], "a": 1, "why": "It can show changes as small as 1 mm."}, {"q": "Why should you repeat measurements?", "opts": ["To spot anomalies and get a more reliable mean.", "To make the test unfair.", "Because the first result is always wrong."], "a": 0, "why": "Repeats show whether results agree."}], "ladder": [{"q": "What is meant by the resolution of an instrument?", "m": 1, "ms": ["The smallest change it can show."], "step": "Remember"}, {"q": "Times measured: 12.1 s, 12.5 s, 12.3 s. Calculate the mean time.", "m": 2, "ms": ["12.1 + 12.5 + 12.3 = 36.9 s.", "36.9 ÷ 3 = 12.3 s."], "step": "Apply"}, {"q": "Explain why a stopwatch is better than counting seconds aloud.", "m": 3, "ms": ["A stopwatch has a better resolution / reads to 0.01 s.", "Counting aloud is less precise and varies between people.", "So the times are more accurate and repeatable."], "step": "Explain"}]}, {"key": "burner", "title": "Using a Bunsen burner", "notes": ["A Bunsen burner burns gas to heat things. Burning is called combustion. The gas needs oxygen from the air to burn.", "A closed air hole gives a yellow safety flame. An open air hole gives a hotter blue heating flame. Only change the air hole when your teacher tells you to.", "Light the burner with the air hole closed so you get the yellow safety flame. Open the air hole to get a blue roaring flame for heating. Never leave a lit burner unattended."], "worked": "More air means more oxygen can mix with the gas. The gas can burn more completely. Tie back long hair and keep flammable items away.", "question": "Why does opening the air hole change the flame? Give one safety rule for heating.", "scheme": ["More air and oxygen can reach the gas.", "More complete burning produces a blue heating flame.", "Tie back hair, wear goggles or give another suitable safety rule."], "mistake": "The yellow safety flame is still hot enough to burn you.", "model": null, "id": "y7-unit-01-burner", "unit": "y7-unit-01", "year": 7, "number": 4, "marks": 3, "cards": [{"term": "Combustion", "definition": "Burning: a reaction with oxygen that transfers energy to the surroundings."}, {"term": "Safety flame", "definition": "The visible yellow Bunsen flame used when you are not heating."}], "quiz": {"q": "What does opening a Bunsen burner's air hole change?", "opts": ["The mass of the burner.", "The amount of air and oxygen entering.", "The type of gas fuel."], "a": 1, "why": "More oxygen helps the gas burn more completely, making a blue heating flame."}, "misconception": {"q": "What does opening a Bunsen burner's air hole change? Sam answers: “The type of gas fuel.” Explain why this is wrong.", "m": 2, "ms": ["The amount of air and oxygen entering.", "More oxygen helps the gas burn more completely, making a blue heating flame."]}, "more": [{"q": "Which flame should be used when the burner is lit but not heating anything?", "opts": ["The yellow safety flame.", "The blue roaring flame.", "No flame."], "a": 0, "why": "The yellow flame is easy to see, so it is safer."}, {"q": "Why is the blue flame hotter?", "opts": ["It uses a different gas.", "Blue things are always hot.", "More oxygen mixes with the gas, so it burns more completely."], "a": 2, "why": "Complete combustion transfers more energy."}, {"q": "What should you place under the Bunsen burner?", "opts": ["A plastic tray.", "A heatproof mat.", "A sheet of paper."], "a": 1, "why": "A heatproof mat protects the bench."}, {"q": "Which leaves soot on glassware?", "opts": ["The yellow flame.", "The blue flame.", "An electric heater."], "a": 0, "why": "Incomplete combustion in the yellow flame makes soot."}], "ladder": [{"q": "What colour is the safety flame?", "m": 1, "ms": ["Yellow."], "step": "Remember"}, {"q": "Give two steps to light a Bunsen burner safely.", "m": 2, "ms": ["Close the air hole and put on goggles.", "Light the splint/lighter first, then turn on the gas."], "step": "Apply"}, {"q": "Explain why the blue flame is better for heating than the yellow flame.", "m": 3, "ms": ["The air hole is open, so more oxygen is mixed in.", "The gas burns more completely.", "It is hotter and does not leave soot."], "step": "Explain"}]}, {"key": "data", "title": "Tables, graphs and conclusions", "notes": ["Put measurements in a results table. Label each column with the quantity and its unit. A graph helps you spot a pattern.", "Use a line graph for measurements such as time and temperature. Use a bar chart for separate groups, such as different materials. A conclusion answers your question using your results.", "Plot the independent variable on the x-axis and the dependent variable on the y-axis. Draw a line or curve of best fit through the points. Do not join the dots with a ruler."], "worked": "Suppose sugar dissolves in 40 seconds in cool water and 20 seconds in warm water. The warmer water gave a shorter dissolving time. Use these numbers as evidence in your conclusion.", "question": "What graph would show water temperature and sugar dissolving time? How would you write a good conclusion?", "scheme": ["Use a line or scatter graph with temperature on the horizontal axis.", "Put dissolving time on the vertical axis and label both units.", "Describe the pattern and use numbers from the results."], "mistake": "A conclusion needs evidence. Do not just say your prediction was right.", "model": null, "id": "y7-unit-01-data", "unit": "y7-unit-01", "year": 7, "number": 5, "marks": 3, "cards": [{"term": "Continuous data", "definition": "Measurements with values anywhere within a range, such as height."}, {"term": "Discrete data", "definition": "Separate counts or values, such as the number of leaves."}, {"term": "Conclusion", "definition": "An answer to your test question, supported by your results."}], "quiz": {"q": "What makes a good conclusion?", "opts": ["Choose your favourite result and ignore the others.", "Leave units off the graph.", "Describe a pattern and use numbers from the results."], "a": 2, "why": "Numbers from the results give evidence for the pattern you describe."}, "misconception": {"q": "What makes a good conclusion? Sam answers: “Choose your favourite result and ignore the others.” Explain why this is wrong.", "m": 2, "ms": ["Describe a pattern and use numbers from the results.", "Numbers from the results give evidence for the pattern you describe."]}, "more": [{"q": "Which axis should show the independent variable?", "opts": ["Either axis, it does not matter.", "The x-axis (horizontal).", "The y-axis (vertical)."], "a": 1, "why": "By convention, the variable you change goes along the bottom."}, {"q": "What is a line of best fit?", "opts": ["A smooth line or curve that passes close to most points.", "A line joining every point dot-to-dot.", "A line through the first and last points only."], "a": 0, "why": "It shows the overall pattern."}, {"q": "Which graph type suits \"number of students with each eye colour\"?", "opts": ["Line graph.", "Scatter graph with a curve.", "Bar chart."], "a": 2, "why": "Eye colour is a category, so use a bar chart."}, {"q": "A table heading should include…", "opts": ["nothing; numbers are enough.", "the quantity and its unit, e.g. Time (s).", "only the unit."], "a": 1, "why": "Units belong in the heading, not after each number."}], "ladder": [{"q": "What does a line of best fit show?", "m": 1, "ms": ["The overall pattern/trend in the results."], "step": "Remember"}, {"q": "A table has the heading \"Temperature\" and values 20, 40, 60. Give two ways to improve it.", "m": 2, "ms": ["Add the unit to the heading, e.g. Temperature (°C).", "Add a column for the measured (dependent) variable / repeats and a mean."], "step": "Apply"}, {"q": "Explain how to plot a line graph of time against temperature.", "m": 3, "ms": ["Put temperature (independent) on the x-axis and time on the y-axis.", "Choose even scales that use most of the grid and label axes with units.", "Plot points accurately and draw a smooth line of best fit."], "step": "Explain"}]}, {"key": "evaluate", "title": "Spotting errors and improving tests", "notes": ["Measurements can change slightly when you repeat them. These unpredictable changes are called random errors. An unusual result that does not fit the pattern is an anomaly.", "A systematic error makes readings wrong in the same way each time. Check equipment for a zero error before measuring. Choose an improvement that tackles the actual problem.", "A result is repeatable if you get similar results when you repeat it. It is reproducible if someone else gets similar results with different equipment. Improve a test by reducing errors, for example by using a data logger."], "worked": "A balance shows 2 g when nothing is on it. Every mass reading will be 2 g too high. Set it to zero before taking new readings.", "question": "A thermometer always reads 2°C too high. Name the error and explain why repeating readings will not fix it.", "scheme": ["This is a systematic error.", "Every reading is too high by the same amount.", "A mean of repeated readings will still be too high."], "mistake": "More repeats help with random errors. They do not remove a fixed error in the equipment.", "model": null, "id": "y7-unit-01-evaluate", "unit": "y7-unit-01", "year": 7, "number": 6, "marks": 3, "cards": [{"term": "Random error", "definition": "An unpredictable change between repeated measurements."}, {"term": "Systematic error", "definition": "An error that makes readings wrong in the same way each time."}, {"term": "Anomaly", "definition": "A result that does not fit the pattern."}], "quiz": {"q": "A balance always reads 2 g too high. What should you do?", "opts": ["Call it a random error.", "Check and correct its zero or calibration.", "Just take a mean of more wrong readings."], "a": 1, "why": "A mean will still be too high. The balance needs correcting before new measurements are made."}, "misconception": {"q": "A balance always reads 2 g too high. What should you do? Sam answers: “Just take a mean of more wrong readings.” Explain why this is wrong.", "m": 2, "ms": ["Check and correct its zero or calibration.", "A mean will still be too high. The balance needs correcting before new measurements are made."]}, "more": [{"q": "A thermometer reads 1 °C too high every time. This is…", "opts": ["a systematic error.", "a random error.", "an anomaly."], "a": 0, "why": "The error is the same each time, so it is systematic."}, {"q": "What should you do with an anomalous result?", "opts": ["Always include it in the mean.", "Change the other results to match.", "Repeat it and leave it out of the mean if it is clearly wrong."], "a": 2, "why": "Anomalies can distort the mean."}, {"q": "Which makes results more precise?", "opts": ["Writing faster.", "Using an instrument with better resolution.", "Using a bigger beaker."], "a": 1, "why": "Better resolution shows smaller differences."}, {"q": "Results are reproducible when…", "opts": ["another person gets similar results.", "you get one result only.", "the results are all different."], "a": 0, "why": "Reproducible means others can repeat it and agree."}], "ladder": [{"q": "What is an anomaly?", "m": 1, "ms": ["A result that does not fit the pattern."], "step": "Remember"}, {"q": "Repeat times were 5.2 s, 5.4 s and 8.9 s. Identify the anomaly and calculate the mean without it.", "m": 2, "ms": ["8.9 s is the anomaly.", "(5.2 + 5.4) ÷ 2 = 5.3 s."], "step": "Apply"}, {"q": "Suggest and explain one improvement to an experiment timed with a hand-held stopwatch.", "m": 3, "ms": ["Use light gates / a data logger / film it.", "This removes human reaction time.", "So the timing is more accurate and repeatable."], "step": "Explain"}]}, {"key": "microscope", "title": "Using a microscope", "notes": ["A microscope makes tiny objects look bigger. Start with the lowest-power lens. Adjust the focus until the image is clear.", "Total magnification = eyepiece magnification × objective magnification. Use the same units when comparing image size and actual size. Draw clear outlines and use straight label lines.", "Put the slide on the stage and use the coarse focus with the lowest-power lens first. Then use the fine focus for a sharp image. Stains, such as iodine, make cell parts easier to see."], "worked": "A ×10 eyepiece and a ×40 objective give 10 × 40 = ×400 magnification. The image looks 400 times bigger than the object. Magnification does not tell you how much detail is clear.", "question": "A microscope has a ×10 eyepiece and ×20 objective. Find total magnification. Why must image and actual sizes use the same units?", "scheme": ["Multiply 10 × 20.", "Total magnification is ×200.", "Matching units makes the size comparison correct."], "mistake": "A bigger image is not always a clearer image.", "model": "cell", "id": "y7-unit-02-microscope", "unit": "y7-unit-02", "year": 7, "number": 1, "marks": 3, "cards": [{"term": "Magnification", "definition": "How many times bigger an image is than the real object."}, {"term": "Resolution", "definition": "How well an image shows two close details separately."}], "quiz": {"q": "What is the total magnification with a ×10 eyepiece and ×40 objective?", "opts": ["×400.", "×50.", "×4."], "a": 0, "why": "Multiply the lens magnifications: 10 × 40 = 400."}, "misconception": {"q": "What is the total magnification with a ×10 eyepiece and ×40 objective? Sam answers: “×50.” Explain why this is wrong.", "m": 2, "ms": ["×400.", "Multiply the lens magnifications: 10 × 40 = 400."]}, "more": [{"q": "Which lens should you use first?", "opts": ["The highest-power objective lens.", "Any lens.", "The lowest-power objective lens."], "a": 2, "why": "Low power makes it easier to find the specimen."}, {"q": "Eyepiece ×10 and objective ×10. What is the total magnification?", "opts": ["×1.", "×100.", "×20."], "a": 1, "why": "10 × 10 = 100."}, {"q": "Why is a stain added to cells?", "opts": ["To make cell parts easier to see.", "To kill the cells.", "To make the slide stick."], "a": 0, "why": "Stains add colour to parts such as the nucleus."}, {"q": "Which part do you turn to make the image sharp at high power?", "opts": ["The coarse focus.", "The mirror.", "The fine focus."], "a": 2, "why": "The fine focus makes small adjustments."}], "ladder": [{"q": "What does a microscope do?", "m": 1, "ms": ["Makes small objects look bigger (magnifies them)."], "step": "Remember"}, {"q": "An eyepiece is ×5 and the objective is ×40. Calculate the total magnification.", "m": 2, "ms": ["Total magnification = 5 × 40.", "= ×200."], "step": "Apply"}, {"q": "Describe how to prepare and view onion cells.", "m": 3, "ms": ["Peel a thin layer of onion skin and lay it flat on a slide.", "Add a drop of iodine and lower a cover slip without trapping bubbles.", "View on low power first, focus, then switch to higher power and use fine focus."], "step": "Explain"}]}, {"key": "cell", "title": "Plant and animal cells", "notes": ["Cells are the small building blocks of living things. Plant and animal cells have a nucleus, cytoplasm and cell membrane. The nucleus contains genetic information.", "A plant cell also has a cell wall and a large permanent vacuole. Many leaf cells have chloroplasts that absorb light. Both plant and animal cells release energy by respiration. Cytoplasm is where many chemical reactions happen. The membrane controls what enters and leaves. Mitochondria are where aerobic respiration happens. Ribosomes make proteins. A cell wall supports a plant cell, and its vacuole contains cell sap.", "Mitochondria are where most respiration happens, releasing energy. Ribosomes make proteins. The cell wall is made of cellulose and gives plant cells a fixed shape."], "worked": "A leaf cell uses chloroplasts for photosynthesis. A root cell usually has no chloroplasts because it gets little light. An animal cell has no cell wall.", "question": "Compare a leaf cell with an animal cell. Name one structure they share and two differences.", "scheme": ["Both have a nucleus, cytoplasm or cell membrane.", "A leaf cell has a cell wall but an animal cell does not.", "A leaf cell has chloroplasts or a large permanent vacuole, unlike a typical animal cell."], "mistake": "Not every plant cell has chloroplasts. Root cells usually do not.", "model": "cell", "id": "y7-unit-02-cell", "unit": "y7-unit-02", "year": 7, "number": 2, "marks": 3, "cards": [{"term": "Nucleus", "definition": "The cell part containing genetic information."}, {"term": "Cell membrane", "definition": "A thin boundary that controls what enters and leaves a cell."}, {"term": "Chloroplast", "definition": "A cell part containing chlorophyll, which absorbs light for photosynthesis."}], "quiz": {"q": "Which statement about plant cells is correct?", "opts": ["Every plant cell has chloroplasts.", "Plant cells do not respire.", "Most root cells have no chloroplasts."], "a": 2, "why": "Most root cells receive little light and do not carry out photosynthesis."}, "misconception": {"q": "Which statement about plant cells is correct? Sam answers: “Every plant cell has chloroplasts.” Explain why this is wrong.", "m": 2, "ms": ["Most root cells have no chloroplasts.", "Most root cells receive little light and do not carry out photosynthesis."]}, "more": [{"q": "Where does most respiration happen in a cell?", "opts": ["Cell wall.", "Mitochondria.", "Nucleus."], "a": 1, "why": "Mitochondria release energy from glucose."}, {"q": "Which part is found in plant cells but not animal cells?", "opts": ["Cell wall.", "Cell membrane.", "Cytoplasm."], "a": 0, "why": "Only plant cells have a cellulose cell wall."}, {"q": "What does the cell membrane do?", "opts": ["Makes food by photosynthesis.", "Gives the cell a fixed shape.", "Controls what enters and leaves the cell."], "a": 2, "why": "The membrane is a barrier with control."}, {"q": "Where do most chemical reactions take place in a cell?", "opts": ["Cell wall.", "Cytoplasm.", "Vacuole."], "a": 1, "why": "The cytoplasm is a jelly where reactions happen."}], "ladder": [{"q": "Name the part of the cell that contains genetic information.", "m": 1, "ms": ["Nucleus."], "step": "Remember"}, {"q": "Name two parts found in plant cells but not animal cells.", "m": 2, "ms": ["Cell wall / chloroplasts / permanent vacuole.", "Any second correct part."], "step": "Apply"}, {"q": "A cell has a nucleus, a cell wall and chloroplasts. Explain whether it is a plant or animal cell.", "m": 3, "ms": ["It is a plant cell.", "Animal cells do not have a cell wall.", "Chloroplasts are only found in plant (and algae) cells."], "step": "Explain"}]}, {"key": "specialised", "title": "Cells with special jobs", "notes": ["A specialised cell has features that help it do a particular job. A red blood cell carries oxygen. A root hair cell takes water and minerals into a plant.", "A root hair cell has a long, thin part that reaches into the soil. This gives it a large surface area for taking substances in. A unicellular organism is a living thing made of just one cell. A thin cell wall gives water a short distance to travel.", "A sperm cell has a tail to swim and lots of mitochondria for energy. A nerve cell is long to carry signals around the body. Many leaf cells are packed with chloroplasts for photosynthesis."], "worked": "The long part of a root hair cell touches more soil water. More water and dissolved minerals can enter the cell. The whole plant depends on these substances.", "question": "Describe two features of a root hair cell. Explain how they help it absorb water or minerals.", "scheme": ["Its long extension gives a large surface area.", "The large surface area helps water and minerals enter.", "A thin cell wall gives water a short distance to travel."], "mistake": "A specialised cell is still a cell. Its features help it do its job.", "model": null, "id": "y7-unit-02-specialised", "unit": "y7-unit-02", "year": 7, "number": 3, "marks": 3, "cards": [{"term": "Specialised cell", "definition": "A cell with features that help it do a particular job."}, {"term": "Unicellular organism", "definition": "A living thing made of one cell."}], "quiz": {"q": "Why does a root hair cell have a long, thin extension?", "opts": ["It turns it into an animal cell.", "It makes sunlight.", "It gives a bigger surface area for taking in water and minerals."], "a": 2, "why": "More surface area means more contact with the water around soil particles."}, "misconception": {"q": "Why does a root hair cell have a long, thin extension? Sam answers: “It turns it into an animal cell.” Explain why this is wrong.", "m": 2, "ms": ["It gives a bigger surface area for taking in water and minerals.", "More surface area means more contact with the water around soil particles."]}, "more": [{"q": "Why does a red blood cell have no nucleus?", "opts": ["So it can photosynthesise.", "There is more space to carry oxygen.", "So it can swim."], "a": 1, "why": "No nucleus means more room for haemoglobin."}, {"q": "Which cell has a tail?", "opts": ["Sperm cell.", "Red blood cell.", "Root hair cell."], "a": 0, "why": "The tail helps the sperm swim to the egg."}, {"q": "Why is a nerve cell long?", "opts": ["To store water.", "To absorb light.", "To carry signals over long distances."], "a": 2, "why": "Long fibres link distant parts of the body."}, {"q": "Why do root hair cells have no chloroplasts?", "opts": ["They are dead.", "They are underground, with no light.", "They are too small."], "a": 1, "why": "Without light, chloroplasts would be useless."}], "ladder": [{"q": "What is a specialised cell?", "m": 1, "ms": ["A cell with features that help it do a particular job."], "step": "Remember"}, {"q": "Describe two adaptations of a sperm cell.", "m": 2, "ms": ["A tail for swimming.", "Many mitochondria to release energy / a head with enzymes."], "step": "Apply"}, {"q": "Explain how the shape of a root hair cell helps the plant.", "m": 3, "ms": ["It has a long, thin extension.", "This gives a large surface area.", "So it can absorb more water and minerals from the soil."], "step": "Explain"}]}, {"key": "diffusion", "title": "How particles spread out: diffusion", "notes": ["Particles in liquids and gases keep moving. They spread from a crowded area to a less crowded area. This spreading is called diffusion.", "Concentration means how much of a substance is in a space. More particles move away from a high concentration than towards it. Particles still move when they are evenly spread. A larger concentration difference can make diffusion faster. A higher temperature usually makes particles move faster.", "Diffusion is faster when it is warmer, because particles move faster. It is also faster when the concentration difference is bigger. Oxygen diffuses into cells and carbon dioxide diffuses out."], "worked": "A cell uses oxygen during respiration. There is then less oxygen inside the cell than outside. Oxygen diffuses into the cell through its membrane.", "question": "A cell uses oxygen in respiration. Explain why oxygen moves into it by diffusion.", "scheme": ["The cell uses up oxygen.", "Oxygen concentration is higher outside than inside.", "More oxygen particles move into the cell than out."], "mistake": "Particles do not stop moving when they are evenly spread.", "model": "diffusion", "id": "y7-unit-02-diffusion", "unit": "y7-unit-02", "year": 7, "number": 4, "marks": 3, "cards": [{"term": "Diffusion", "definition": "Particles spreading from a higher concentration to a lower concentration."}, {"term": "Concentration gradient", "definition": "A difference in concentration between two places."}], "quiz": {"q": "What happens when diffusing particles are evenly spread?", "opts": ["They only move towards the most crowded area.", "They keep moving in both directions.", "They all stop moving."], "a": 1, "why": "Particles keep moving, but equal amounts move each way overall."}, "misconception": {"q": "What happens when diffusing particles are evenly spread? Sam answers: “They all stop moving.” Explain why this is wrong.", "m": 2, "ms": ["They keep moving in both directions.", "Particles keep moving, but equal amounts move each way overall."]}, "more": [{"q": "Which makes diffusion faster?", "opts": ["A higher temperature.", "A lower temperature.", "A smaller concentration difference."], "a": 0, "why": "Warmer particles move faster."}, {"q": "Perfume spreads across a room by…", "opts": ["filtration.", "condensation.", "diffusion."], "a": 2, "why": "Perfume particles spread from high to low concentration."}, {"q": "In which state is diffusion slowest?", "opts": ["Liquid.", "Solid.", "Gas."], "a": 1, "why": "Particles in solids cannot move from place to place."}, {"q": "Oxygen moves into a cell because…", "opts": ["there is more oxygen outside than inside.", "cells push it in.", "oxygen is heavier."], "a": 0, "why": "Particles diffuse from high to low concentration."}], "ladder": [{"q": "What is diffusion?", "m": 1, "ms": ["The spreading of particles from a high concentration to a low concentration."], "step": "Remember"}, {"q": "A tea bag is put in hot water and another in cold water. Predict which colours the water faster and why.", "m": 2, "ms": ["Hot water colours faster.", "Particles move faster at a higher temperature."], "step": "Apply"}, {"q": "Explain how oxygen gets from the air in your lungs into your blood.", "m": 3, "ms": ["There is a higher concentration of oxygen in the air sacs than in the blood.", "Oxygen particles diffuse from high to low concentration.", "They pass through the thin walls into the blood."], "step": "Explain"}]}, {"key": "organisation", "title": "Cells, organs and joints", "notes": ["Cells with similar jobs work together as a tissue. Different tissues work together to make an organ. Organs work together in an organ system.", "Your skeleton supports your body and protects organs. Joints are places where bones meet. Muscles pull on bones to move them.", "The order of organisation is cells → tissues → organs → organ systems → organism. The heart is an organ made of muscle tissue and other tissues. The skeleton also makes blood cells in bone marrow."], "worked": "Cartilage makes smooth surfaces at the ends of bones. Ligaments hold bones together at a joint. Tendons join muscles to bones.", "question": "What do cartilage, ligaments and tendons do at a joint?", "scheme": ["Cartilage reduces rubbing between the ends of bones.", "Ligaments join bone to bone.", "Tendons join muscle to bone."], "mistake": "Ligaments and tendons have different jobs. Do not swap their names.", "model": null, "id": "y7-unit-03-organisation", "unit": "y7-unit-03", "year": 7, "number": 1, "marks": 3, "cards": [{"term": "Tissue", "definition": "A group of cells working together to do a job."}, {"term": "Organ", "definition": "A body part made of different tissues working together."}, {"term": "Ligament", "definition": "A strong band joining bone to bone."}], "quiz": {"q": "What joins a muscle to a bone?", "opts": ["A tendon.", "A ligament.", "Only cartilage."], "a": 0, "why": "Tendons join muscle to bone. Ligaments join bone to bone."}, "misconception": {"q": "What joins a muscle to a bone? Sam answers: “A ligament.” Explain why this is wrong.", "m": 2, "ms": ["A tendon.", "Tendons join muscle to bone. Ligaments join bone to bone."]}, "more": [{"q": "Which is the correct order?", "opts": ["Organ, cell, tissue, system.", "Tissue, cell, organ, system.", "Cell, tissue, organ, organ system."], "a": 2, "why": "Each level is made from the one before."}, {"q": "The stomach is an example of…", "opts": ["a tissue.", "an organ.", "a cell."], "a": 1, "why": "It is made of several tissues working together."}, {"q": "Which is NOT a job of the skeleton?", "opts": ["Digesting food.", "Support.", "Protecting organs."], "a": 0, "why": "Digestion is done by the digestive system."}, {"q": "Which bone protects the brain?", "opts": ["Ribs.", "Femur.", "Skull."], "a": 2, "why": "The skull surrounds the brain."}], "ladder": [{"q": "What is a tissue?", "m": 1, "ms": ["A group of similar cells working together to do a job."], "step": "Remember"}, {"q": "Give two jobs of the skeleton.", "m": 2, "ms": ["Support / shape.", "Protection / movement / making blood cells."], "step": "Apply"}, {"q": "Explain the difference between a tissue, an organ and an organ system.", "m": 3, "ms": ["A tissue is a group of similar cells.", "An organ is made of different tissues working together.", "An organ system is a group of organs working together, e.g. the digestive system."], "step": "Explain"}]}, {"key": "muscles", "title": "How muscles move bones", "notes": ["Muscles pull on bones to make them move. A contracting muscle develops a pulling force. Muscles cannot actively push bones back.", "Muscles often work in pairs. One pulls a joint one way and the other pulls it back. This is called an antagonistic pair.", "The biceps bends the arm at the elbow and the triceps straightens it. Tendons join muscles to bones. Ligaments join bones to other bones at a joint."], "worked": "To bend your elbow, your biceps contracts and your triceps relaxes. To straighten it, your triceps contracts and your biceps relaxes. The muscles pull in opposite directions.", "question": "Why do you need two opposing muscles to bend and straighten an elbow?", "scheme": ["Muscles move bones by pulling, not pushing.", "One muscle contracts to bend the elbow.", "The opposing muscle contracts to straighten it."], "mistake": "A relaxed muscle does not push a bone back into place.", "model": null, "id": "y7-unit-03-muscles", "unit": "y7-unit-03", "year": 7, "number": 2, "marks": 3, "cards": [{"term": "Antagonistic pair", "definition": "Two muscles that pull a joint in opposite directions."}, {"term": "Contraction", "definition": "When a muscle develops a pulling force, often becoming shorter."}], "quiz": {"q": "Why do two muscles work as an opposing pair at the elbow?", "opts": ["The bones contract.", "Muscles pull bones but cannot actively push them back.", "A relaxed muscle pushes the bone back."], "a": 1, "why": "One muscle pulls to bend the joint and the other pulls to straighten it."}, "misconception": {"q": "Why do two muscles work as an opposing pair at the elbow? Sam answers: “A relaxed muscle pushes the bone back.” Explain why this is wrong.", "m": 2, "ms": ["Muscles pull bones but cannot actively push them back.", "One muscle pulls to bend the joint and the other pulls to straighten it."]}, "more": [{"q": "Which muscle contracts to bend your arm?", "opts": ["Biceps.", "Triceps.", "Diaphragm."], "a": 0, "why": "The biceps pulls the forearm up."}, {"q": "What joins a muscle to a bone?", "opts": ["Ligament.", "Cartilage.", "Tendon."], "a": 2, "why": "Tendons are tough cords linking muscle to bone."}, {"q": "Why do muscles work in pairs?", "opts": ["Because bones push muscles.", "Muscles can only pull, not push.", "So one can rest."], "a": 1, "why": "One pulls each way."}, {"q": "When the triceps contracts, the biceps…", "opts": ["relaxes.", "also contracts.", "pushes the arm."], "a": 0, "why": "Antagonistic pairs work opposite each other."}], "ladder": [{"q": "What is an antagonistic pair?", "m": 1, "ms": ["Two muscles that work in opposite directions at a joint."], "step": "Remember"}, {"q": "Describe what happens to the biceps and triceps when you straighten your arm.", "m": 2, "ms": ["The triceps contracts.", "The biceps relaxes."], "step": "Apply"}, {"q": "Explain why the elbow needs two muscles to move both ways.", "m": 3, "ms": ["Muscles can only pull when they contract.", "The biceps pulls the forearm up to bend the arm.", "The triceps is needed to pull it back down / straighten it."], "step": "Explain"}]}, {"key": "planning", "title": "Planning tests and taking measurements", "notes": ["Write steps that someone else could follow. Say what to measure and which units to use. Choose equipment that can measure the small changes you expect.", "Check that your equipment reads zero before you start. Repeat each measurement to spot results that do not fit. Calculate a mean by adding the readings and dividing by their number.", "Choose a sensible range and interval, such as 20 °C to 60 °C in steps of 10 °C. Repeat readings and calculate a mean. Write a method in numbered steps."], "worked": "Suppose ten pendulum swings take 12 seconds. One swing takes 12 ÷ 10 = 1.2 seconds. Timing several swings reduces the effect of your reaction time.", "question": "How could you improve the time measurement for one pendulum swing? Give two ideas and explain one.", "scheme": ["Time several swings, then divide by the number of swings.", "Repeat the measurement and calculate a mean.", "Use the same point to start and stop timing."], "mistake": "Repeating readings will not fix a clock that always reads too high.", "model": null, "id": "y7-unit-03-planning", "unit": "y7-unit-03", "year": 7, "number": 3, "marks": 3, "cards": [{"term": "Resolution", "definition": "The smallest change a measuring instrument can show."}, {"term": "Repeatability", "definition": "Getting similar results when the same person repeats the same test."}], "quiz": {"q": "Why time ten swings instead of one?", "opts": ["It reduces the effect of your reaction time on each swing's time.", "It fixes every equipment error.", "It makes the clock perfect."], "a": 0, "why": "Divide the longer total time by ten. Your reaction time then has a smaller effect on each swing's time."}, "misconception": {"q": "Why time ten swings instead of one? Sam answers: “It fixes every equipment error.” Explain why this is wrong.", "m": 2, "ms": ["It reduces the effect of your reaction time on each swing's time.", "Divide the longer total time by ten. Your reaction time then has a smaller effect on each swing's time."]}, "more": [{"q": "Which instrument best measures 25 cm³ of water?", "opts": ["A beaker.", "A thermometer.", "A measuring cylinder."], "a": 2, "why": "A measuring cylinder has a scale for volume."}, {"q": "How do you calculate a mean of three repeats?", "opts": ["Subtract the smallest from the largest.", "Add the three values and divide by 3.", "Choose the middle value only."], "a": 1, "why": "Mean = total ÷ number of values."}, {"q": "A ruler marked in mm has a resolution of…", "opts": ["1 mm.", "1 cm.", "1 m."], "a": 0, "why": "It can show changes as small as 1 mm."}, {"q": "Why should you repeat measurements?", "opts": ["To make the test unfair.", "Because the first result is always wrong.", "To spot anomalies and get a more reliable mean."], "a": 2, "why": "Repeats show whether results agree."}], "ladder": [{"q": "What is meant by the resolution of an instrument?", "m": 1, "ms": ["The smallest change it can show."], "step": "Remember"}, {"q": "Times measured: 12.1 s, 12.5 s, 12.3 s. Calculate the mean time.", "m": 2, "ms": ["12.1 + 12.5 + 12.3 = 36.9 s.", "36.9 ÷ 3 = 12.3 s."], "step": "Apply"}, {"q": "Explain why a stopwatch is better than counting seconds aloud.", "m": 3, "ms": ["A stopwatch has a better resolution / reads to 0.01 s.", "Counting aloud is less precise and varies between people.", "So the times are more accurate and repeatable."], "step": "Explain"}]}, {"key": "particles", "title": "Solids, liquids and gases", "notes": ["Everything around you is made of tiny particles. In a solid, particles are close together and vibrate in fixed positions. In a liquid, particles stay close but move past each other.", "Gas particles are far apart and move freely. A gas spreads out to fill its container. A liquid keeps its volume but takes the container's shape.", "The particle model explains properties. Solids keep their shape because particles are held in place. Gases can be squashed because there are big spaces between particles."], "worked": "Push a syringe full of air and the air takes up less space. The gaps between gas particles get smaller. A syringe full of liquid is much harder to squeeze.", "question": "Why can you squeeze a gas into a smaller space much more easily than a liquid?", "scheme": ["Gas particles have large gaps between them.", "Squeezing brings the particles closer together.", "Liquid particles are already close together."], "mistake": "Squeezing a gas makes the gaps smaller. It does not make the particles smaller.", "model": "particles", "id": "y7-unit-04-particles", "unit": "y7-unit-04", "year": 7, "number": 1, "marks": 3, "cards": [{"term": "Solid", "definition": "A state with close particles vibrating in fixed positions."}, {"term": "Liquid", "definition": "A state with close particles that move past each other."}, {"term": "Gas", "definition": "A state with widely spaced particles moving freely."}], "quiz": {"q": "Why is a gas easy to squeeze into a smaller space?", "opts": ["The particles shrink.", "It contains no particles.", "There are large gaps between particles."], "a": 2, "why": "Squeezing a gas reduces the gaps between its particles."}, "misconception": {"q": "Why is a gas easy to squeeze into a smaller space? Sam answers: “The particles shrink.” Explain why this is wrong.", "m": 2, "ms": ["There are large gaps between particles.", "Squeezing a gas reduces the gaps between its particles."]}, "more": [{"q": "Why can a gas be compressed?", "opts": ["Its particles do not move.", "There are large spaces between its particles.", "Its particles are very small."], "a": 1, "why": "Pushing moves particles into the gaps."}, {"q": "Why does a liquid take the shape of its container?", "opts": ["Its particles can move past each other.", "Its particles are far apart.", "Its particles vibrate in fixed positions."], "a": 0, "why": "Particles slide around to fill the bottom of the container."}, {"q": "In which state are the particles most tightly packed?", "opts": ["Liquid.", "Gas.", "Solid."], "a": 2, "why": "Solid particles are close together in a regular pattern."}, {"q": "When a solid is heated, its particles…", "opts": ["stop moving.", "vibrate faster.", "get bigger."], "a": 1, "why": "Heating gives particles more energy, not more size."}], "ladder": [{"q": "Describe how particles are arranged in a gas.", "m": 1, "ms": ["Far apart and randomly arranged / moving quickly in all directions."], "step": "Remember"}, {"q": "Use the particle model to explain why solids cannot flow.", "m": 2, "ms": ["Particles are held in fixed positions.", "They can only vibrate, so they cannot move past each other."], "step": "Apply"}, {"q": "Explain why a syringe full of air can be pushed in, but a syringe full of water cannot.", "m": 3, "ms": ["Air is a gas with large spaces between particles.", "Pushing moves gas particles closer together.", "Water particles are already touching, so there is no space to squash them into."], "step": "Explain"}]}, {"key": "state", "title": "Melting, freezing, boiling and condensing", "notes": ["Melting changes a solid into a liquid. Freezing changes a liquid into a solid. These changes do not make a new substance.", "Evaporation happens at a liquid's surface, even below its boiling point. Boiling happens throughout a liquid at its boiling point. Condensation changes a gas into a liquid.", "The melting point is the temperature at which a solid melts. A pure substance melts and boils at fixed temperatures. Heating gives particles more energy to break away from each other."], "worked": "A puddle slowly dries on a cool day by evaporation. Water in a boiling kettle forms bubbles throughout the liquid. Both changes turn liquid water into water vapour.", "question": "How is evaporation different from boiling? Give three differences or linked facts.", "scheme": ["Evaporation happens at the surface.", "Evaporation can happen below the boiling point.", "Boiling happens throughout the liquid at its boiling point."], "mistake": "Steam that you can see is tiny water droplets. Water vapour itself is invisible.", "model": "particles", "id": "y7-unit-04-state", "unit": "y7-unit-04", "year": 7, "number": 2, "marks": 3, "cards": [{"term": "Melting", "definition": "Changing from a solid to a liquid."}, {"term": "Evaporation", "definition": "Particles leaving a liquid's surface as a gas."}, {"term": "Condensation", "definition": "Changing from a gas to a liquid."}], "quiz": {"q": "How is evaporation different from boiling?", "opts": ["It turns water into a different element.", "It must happen throughout the liquid.", "It can happen at the surface below the boiling point."], "a": 2, "why": "Evaporation happens at the surface. Boiling happens throughout the liquid at its boiling point."}, "misconception": {"q": "How is evaporation different from boiling? Sam answers: “It turns water into a different element.” Explain why this is wrong.", "m": 2, "ms": ["It can happen at the surface below the boiling point.", "Evaporation happens at the surface. Boiling happens throughout the liquid at its boiling point."]}, "more": [{"q": "What is condensing?", "opts": ["A solid turning into a liquid.", "A gas turning into a liquid.", "A liquid turning into a gas."], "a": 1, "why": "Water vapour condensing makes droplets on a cold window."}, {"q": "At what temperature does pure water boil at sea level?", "opts": ["100 °C.", "0 °C.", "50 °C."], "a": 0, "why": "Pure water boils at 100 °C at normal pressure."}, {"q": "A puddle dries up on a warm day. This is…", "opts": ["boiling.", "freezing.", "evaporation."], "a": 2, "why": "Evaporation happens at the surface below the boiling point."}, {"q": "During melting, the temperature of ice…", "opts": ["falls.", "stays the same until it has all melted.", "keeps rising steadily."], "a": 1, "why": "Energy is used to break the solid apart."}], "ladder": [{"q": "Name the change of state from liquid to solid.", "m": 1, "ms": ["Freezing."], "step": "Remember"}, {"q": "Describe two differences between evaporation and boiling.", "m": 2, "ms": ["Evaporation only happens at the surface; boiling happens throughout the liquid.", "Evaporation happens at any temperature; boiling happens at the boiling point."], "step": "Apply"}, {"q": "Explain, using particles, what happens when ice melts.", "m": 3, "ms": ["Heating transfers energy to the particles.", "The particles vibrate more strongly.", "They break free of their fixed positions and can move past each other."], "step": "Explain"}]}, {"key": "diffusion", "title": "How particles spread out: diffusion", "notes": ["Particles in liquids and gases keep moving. They spread from a crowded area to a less crowded area. This spreading is called diffusion.", "Concentration means how much of a substance is in a space. More particles move away from a high concentration than towards it. Particles still move when they are evenly spread. A larger concentration difference can make diffusion faster. A higher temperature usually makes particles move faster.", "Diffusion is faster when it is warmer, because particles move faster. It is also faster when the concentration difference is bigger. Oxygen diffuses into cells and carbon dioxide diffuses out."], "worked": "A cell uses oxygen during respiration. There is then less oxygen inside the cell than outside. Oxygen diffuses into the cell through its membrane.", "question": "A cell uses oxygen in respiration. Explain why oxygen moves into it by diffusion.", "scheme": ["The cell uses up oxygen.", "Oxygen concentration is higher outside than inside.", "More oxygen particles move into the cell than out."], "mistake": "Particles do not stop moving when they are evenly spread.", "model": "diffusion", "id": "y7-unit-04-diffusion", "unit": "y7-unit-04", "year": 7, "number": 3, "marks": 3, "cards": [{"term": "Diffusion", "definition": "Particles spreading from a higher concentration to a lower concentration."}, {"term": "Concentration gradient", "definition": "A difference in concentration between two places."}], "quiz": {"q": "What happens when diffusing particles are evenly spread?", "opts": ["They keep moving in both directions.", "They all stop moving.", "They only move towards the most crowded area."], "a": 0, "why": "Particles keep moving, but equal amounts move each way overall."}, "misconception": {"q": "What happens when diffusing particles are evenly spread? Sam answers: “They all stop moving.” Explain why this is wrong.", "m": 2, "ms": ["They keep moving in both directions.", "Particles keep moving, but equal amounts move each way overall."]}, "more": [{"q": "Which makes diffusion faster?", "opts": ["A lower temperature.", "A smaller concentration difference.", "A higher temperature."], "a": 2, "why": "Warmer particles move faster."}, {"q": "Perfume spreads across a room by…", "opts": ["condensation.", "diffusion.", "filtration."], "a": 1, "why": "Perfume particles spread from high to low concentration."}, {"q": "In which state is diffusion slowest?", "opts": ["Solid.", "Gas.", "Liquid."], "a": 0, "why": "Particles in solids cannot move from place to place."}, {"q": "Oxygen moves into a cell because…", "opts": ["cells push it in.", "oxygen is heavier.", "there is more oxygen outside than inside."], "a": 2, "why": "Particles diffuse from high to low concentration."}], "ladder": [{"q": "What is diffusion?", "m": 1, "ms": ["The spreading of particles from a high concentration to a low concentration."], "step": "Remember"}, {"q": "A tea bag is put in hot water and another in cold water. Predict which colours the water faster and why.", "m": 2, "ms": ["Hot water colours faster.", "Particles move faster at a higher temperature."], "step": "Apply"}, {"q": "Explain how oxygen gets from the air in your lungs into your blood.", "m": 3, "ms": ["There is a higher concentration of oxygen in the air sacs than in the blood.", "Oxygen particles diffuse from high to low concentration.", "They pass through the thin walls into the blood."], "step": "Explain"}]}, {"key": "gas", "title": "Gas pressure", "notes": ["Gas particles move in all directions. They hit the walls of their container. These hits cause gas pressure.", "Squeezing a gas puts the particles in a smaller space. They hit the walls more often. This increases pressure if the temperature stays the same.", "Heating a gas makes its particles move faster. They hit the walls harder and more often, so pressure rises. Air pressure acts on us all the time because air particles hit us from every direction."], "worked": "Seal the end of a syringe containing air. Push the plunger in to reduce the space. The trapped air pushes back more strongly.", "question": "Why does squeezing the air in a sealed syringe increase its pressure?", "scheme": ["The same gas is in a smaller volume.", "Particles hit the walls more often.", "More frequent hits increase pressure."], "mistake": "Pressure comes from particles hitting a surface. Particles do not grow when heated.", "model": "particles", "id": "y7-unit-04-gas", "unit": "y7-unit-04", "year": 7, "number": 4, "marks": 3, "cards": [{"term": "Gas pressure", "definition": "The force on each unit area caused by gas particles hitting a surface."}, {"term": "Compression", "definition": "Squeezing something into a smaller volume."}], "quiz": {"q": "What happens when you heat gas in a sealed container that cannot expand?", "opts": ["Its particles stop hitting the walls.", "Its pressure rises.", "Its number of particles falls."], "a": 1, "why": "The particles move faster and hit the walls more often and harder."}, "misconception": {"q": "What happens when you heat gas in a sealed container that cannot expand? Sam answers: “Its number of particles falls.” Explain why this is wrong.", "m": 2, "ms": ["Its pressure rises.", "The particles move faster and hit the walls more often and harder."]}, "more": [{"q": "What happens to gas pressure if the gas is heated in a sealed can?", "opts": ["It increases.", "It decreases.", "It stays the same."], "a": 0, "why": "Faster particles hit the walls harder and more often."}, {"q": "What causes gas pressure?", "opts": ["Particles getting bigger.", "Particles sticking together.", "Particles hitting the walls of the container."], "a": 2, "why": "Each collision pushes on the wall."}, {"q": "A balloon is squashed to half its size. The pressure inside…", "opts": ["becomes zero.", "increases.", "decreases."], "a": 1, "why": "Particles hit the walls more often in a smaller space."}, {"q": "Why does a crisp packet puff up at the top of a mountain?", "opts": ["Air pressure outside is lower.", "The air inside gets colder.", "The crisps expand."], "a": 0, "why": "Less pressure outside lets the gas inside push outwards."}], "ladder": [{"q": "What causes the pressure of a gas?", "m": 1, "ms": ["Gas particles colliding with the walls of the container."], "step": "Remember"}, {"q": "Explain why you should not heat a sealed can.", "m": 2, "ms": ["The gas particles move faster and hit the walls harder/more often.", "The pressure could rise enough to burst the can."], "step": "Apply"}, {"q": "A football is pumped up with more air. Explain why it feels harder.", "m": 3, "ms": ["More particles are inside the same space.", "They hit the inside walls more often.", "So the pressure increases."], "step": "Explain"}]}, {"key": "atoms", "title": "Atoms, elements, compounds and mixtures", "notes": ["An atom is a tiny building block of matter. An element contains only one type of atom. Iron and oxygen are elements.", "A compound has different elements chemically joined together. A mixture contains substances that are not chemically joined to each other. Mixtures can often be separated using physical methods.", "Chemical formulae show which atoms are joined, for example H₂O has two hydrogen atoms and one oxygen atom. A compound's properties can be very different from its elements. Mixtures can be separated by physical methods."], "worked": "Water is a compound of hydrogen and oxygen. Salt water is a mixture of salt and water. You can collect the water from salt water by distillation.", "question": "Use water and salt water to explain the difference between a compound and a mixture.", "scheme": ["Water contains hydrogen and oxygen chemically joined.", "Salt water contains salt mixed with water without a new compound forming.", "The substances in salt water can be separated by physical methods."], "mistake": "A mixture is not the same as a compound.", "model": null, "id": "y7-unit-04-atoms", "unit": "y7-unit-04", "year": 7, "number": 5, "marks": 3, "cards": [{"term": "Element", "definition": "A substance containing just one type of atom."}, {"term": "Compound", "definition": "A substance with different elements chemically joined in a fixed ratio."}, {"term": "Mixture", "definition": "Substances together without being chemically joined to each other."}], "quiz": {"q": "Which substance is a compound?", "opts": ["Pure water.", "Air.", "Iron."], "a": 0, "why": "Water contains hydrogen and oxygen atoms chemically joined together."}, "misconception": {"q": "Which substance is a compound? Sam answers: “Air.” Explain why this is wrong.", "m": 2, "ms": ["Pure water.", "Water contains hydrogen and oxygen atoms chemically joined together."]}, "more": [{"q": "Which is a compound?", "opts": ["Oxygen, O₂.", "Iron, Fe.", "Water, H₂O."], "a": 2, "why": "Water has two different elements chemically joined."}, {"q": "Air is…", "opts": ["a compound.", "a mixture.", "an element."], "a": 1, "why": "Air contains different gases that are not joined."}, {"q": "How many atoms are in CO₂?", "opts": ["3.", "2.", "1."], "a": 0, "why": "One carbon atom and two oxygen atoms."}, {"q": "Sodium is a reactive metal and chlorine is a toxic gas. Sodium chloride is…", "opts": ["also a toxic gas.", "a mixture of the two.", "table salt, which is safe to eat in small amounts."], "a": 2, "why": "A compound can have very different properties from its elements."}], "ladder": [{"q": "What is an element?", "m": 1, "ms": ["A substance made of only one type of atom."], "step": "Remember"}, {"q": "State the number of each type of atom in H₂SO₄.", "m": 2, "ms": ["2 hydrogen and 1 sulfur.", "4 oxygen."], "step": "Apply"}, {"q": "Explain the difference between a mixture of iron and sulfur and the compound iron sulfide.", "m": 3, "ms": ["In the mixture the atoms are not chemically joined.", "The mixture can be separated, e.g. with a magnet.", "In iron sulfide they are chemically joined, so a magnet cannot separate them."], "step": "Explain"}]}, {"key": "atoms", "title": "Atoms, elements, compounds and mixtures", "notes": ["An atom is a tiny building block of matter. An element contains only one type of atom. Iron and oxygen are elements.", "A compound has different elements chemically joined together. A mixture contains substances that are not chemically joined to each other. Mixtures can often be separated using physical methods.", "Chemical formulae show which atoms are joined, for example H₂O has two hydrogen atoms and one oxygen atom. A compound's properties can be very different from its elements. Mixtures can be separated by physical methods."], "worked": "Water is a compound of hydrogen and oxygen. Salt water is a mixture of salt and water. You can collect the water from salt water by distillation.", "question": "Use water and salt water to explain the difference between a compound and a mixture.", "scheme": ["Water contains hydrogen and oxygen chemically joined.", "Salt water contains salt mixed with water without a new compound forming.", "The substances in salt water can be separated by physical methods."], "mistake": "A mixture is not the same as a compound.", "model": null, "id": "y7-unit-05-atoms", "unit": "y7-unit-05", "year": 7, "number": 1, "marks": 3, "cards": [{"term": "Element", "definition": "A substance containing just one type of atom."}, {"term": "Compound", "definition": "A substance with different elements chemically joined in a fixed ratio."}, {"term": "Mixture", "definition": "Substances together without being chemically joined to each other."}], "quiz": {"q": "Which substance is a compound?", "opts": ["Air.", "Iron.", "Pure water."], "a": 2, "why": "Water contains hydrogen and oxygen atoms chemically joined together."}, "misconception": {"q": "Which substance is a compound? Sam answers: “Air.” Explain why this is wrong.", "m": 2, "ms": ["Pure water.", "Water contains hydrogen and oxygen atoms chemically joined together."]}, "more": [{"q": "Which is a compound?", "opts": ["Iron, Fe.", "Water, H₂O.", "Oxygen, O₂."], "a": 1, "why": "Water has two different elements chemically joined."}, {"q": "Air is…", "opts": ["a mixture.", "an element.", "a compound."], "a": 0, "why": "Air contains different gases that are not joined."}, {"q": "How many atoms are in CO₂?", "opts": ["2.", "1.", "3."], "a": 2, "why": "One carbon atom and two oxygen atoms."}, {"q": "Sodium is a reactive metal and chlorine is a toxic gas. Sodium chloride is…", "opts": ["a mixture of the two.", "table salt, which is safe to eat in small amounts.", "also a toxic gas."], "a": 1, "why": "A compound can have very different properties from its elements."}], "ladder": [{"q": "What is an element?", "m": 1, "ms": ["A substance made of only one type of atom."], "step": "Remember"}, {"q": "State the number of each type of atom in H₂SO₄.", "m": 2, "ms": ["2 hydrogen and 1 sulfur.", "4 oxygen."], "step": "Apply"}, {"q": "Explain the difference between a mixture of iron and sulfur and the compound iron sulfide.", "m": 3, "ms": ["In the mixture the atoms are not chemically joined.", "The mixture can be separated, e.g. with a magnet.", "In iron sulfide they are chemically joined, so a magnet cannot separate them."], "step": "Explain"}]}, {"key": "solution", "title": "Dissolving and solutions", "notes": ["A solute is the substance that dissolves. A solvent is the liquid it dissolves in. Together they make a solution.", "Stirring can make a solid dissolve faster. Solubility is how much can dissolve at a given temperature. A saturated solution cannot dissolve any more solute at that temperature.", "Particles of the solute spread out between solvent particles. The mass is conserved: mass of solute + mass of solvent = mass of solution. Most solids dissolve better in warmer water."], "worked": "Sugar is the solute when you dissolve it in water. The water is the solvent. Stirring helps the sugar dissolve more quickly.", "question": "Why can stirring make sugar dissolve faster without changing how much can dissolve at that temperature?", "scheme": ["Stirring brings fresh water into contact with the sugar.", "The sugar dissolves more quickly.", "The maximum amount that can dissolve at that temperature stays the same."], "mistake": "Dissolving faster does not always mean that more can dissolve.", "model": null, "id": "y7-unit-05-solution", "unit": "y7-unit-05", "year": 7, "number": 2, "marks": 3, "cards": [{"term": "Solute", "definition": "A substance that dissolves in a solvent."}, {"term": "Solvent", "definition": "A liquid that dissolves a solute."}, {"term": "Saturated solution", "definition": "A solution that cannot dissolve more solute at that temperature."}], "quiz": {"q": "What does stirring usually increase?", "opts": ["How quickly a solid dissolves.", "How much can dissolve at a fixed temperature.", "The number of atoms in the solid."], "a": 0, "why": "Stirring brings fresh solvent to the solid. It helps dissolving happen faster."}, "misconception": {"q": "What does stirring usually increase? Sam answers: “How much can dissolve at a fixed temperature.” Explain why this is wrong.", "m": 2, "ms": ["How quickly a solid dissolves.", "Stirring brings fresh solvent to the solid. It helps dissolving happen faster."]}, "more": [{"q": "20 g of salt dissolves in 100 g of water. What is the mass of the solution?", "opts": ["100 g.", "80 g.", "120 g."], "a": 2, "why": "Mass is conserved when dissolving."}, {"q": "In salty water, the solvent is…", "opts": ["salty water.", "water.", "salt."], "a": 1, "why": "The solvent is the liquid that dissolves the solute."}, {"q": "Which usually lets more sugar dissolve?", "opts": ["Warmer water.", "Colder water.", "Less stirring."], "a": 0, "why": "Solubility of most solids increases with temperature."}, {"q": "A substance that does not dissolve is…", "opts": ["soluble.", "saturated.", "insoluble."], "a": 2, "why": "Sand is insoluble in water."}], "ladder": [{"q": "What is a solute?", "m": 1, "ms": ["The substance that dissolves."], "step": "Remember"}, {"q": "15 g of sugar is dissolved in 85 g of water. Calculate the mass of the solution and explain your answer.", "m": 2, "ms": ["15 + 85 = 100 g.", "No particles are lost when dissolving, so mass is conserved."], "step": "Apply"}, {"q": "Explain what happens to the particles when sugar dissolves in water.", "m": 3, "ms": ["The sugar particles separate from each other.", "Water particles surround them.", "The sugar particles spread out between the water particles, so they are too small to see."], "step": "Explain"}]}, {"key": "filter", "title": "Filtering and making crystals", "notes": ["Filtering separates an insoluble solid from a liquid. Insoluble means it does not dissolve. Filter paper lets the liquid through but traps the solid.", "The trapped solid is called the residue. The liquid that passes through is the filtrate. Crystallisation makes solid crystals from a solution.", "Evaporating all the water quickly leaves small crystals. Letting it evaporate slowly makes larger crystals. Rock salt can be purified by dissolving, filtering and then evaporating."], "worked": "Add water to a dry mixture of sand and salt. Filter out the sand because it does not dissolve. Evaporate some water, then leave the salt solution to cool and form crystals.", "question": "How would you separate a dry mixture of sand and salt?", "scheme": ["Add water to dissolve the salt.", "Filter the mixture to remove sand.", "Evaporate some water and leave the solution to form salt crystals."], "mistake": "Ordinary filter paper does not trap salt that is dissolved in water.", "model": null, "id": "y7-unit-05-filter", "unit": "y7-unit-05", "year": 7, "number": 3, "marks": 3, "cards": [{"term": "Residue", "definition": "The solid left on filter paper."}, {"term": "Filtrate", "definition": "The liquid that passes through filter paper."}, {"term": "Crystallisation", "definition": "Making solid crystals from a solution."}], "quiz": {"q": "Can ordinary filter paper remove dissolved salt from water?", "opts": ["Yes. It traps all the dissolved salt.", "Yes. It turns the salt into sand.", "No. Dissolved salt passes through with the water."], "a": 2, "why": "Filtering traps insoluble solids, such as sand. It does not trap dissolved salt."}, "misconception": {"q": "Can ordinary filter paper remove dissolved salt from water? Sam answers: “Yes. It traps all the dissolved salt.” Explain why this is wrong.", "m": 2, "ms": ["No. Dissolved salt passes through with the water.", "Filtering traps insoluble solids, such as sand. It does not trap dissolved salt."]}, "more": [{"q": "What is left on the filter paper?", "opts": ["The solvent.", "The residue.", "The filtrate."], "a": 1, "why": "The insoluble solid is trapped as residue."}, {"q": "Which mixture can be separated by filtering?", "opts": ["Sand and water.", "Salt and water.", "Ink and water."], "a": 0, "why": "Sand is insoluble, so it is trapped."}, {"q": "Slow evaporation gives…", "opts": ["smaller crystals.", "no crystals.", "larger crystals."], "a": 2, "why": "Crystals have more time to grow."}, {"q": "Why is rock salt dissolved in water before filtering?", "opts": ["To melt the rock.", "To separate the soluble salt from insoluble sand and grit.", "To make the salt heavier."], "a": 1, "why": "Only dissolved salt passes through the paper."}], "ladder": [{"q": "What is the filtrate?", "m": 1, "ms": ["The liquid that passes through the filter paper."], "step": "Remember"}, {"q": "Describe how to get dry sand from a mixture of sand and water.", "m": 2, "ms": ["Filter the mixture.", "Leave the sand (residue) to dry / dry it in a warm place."], "step": "Apply"}, {"q": "Explain how to get pure salt crystals from rock salt.", "m": 3, "ms": ["Dissolve the rock salt in warm water and stir.", "Filter to remove the insoluble sand and grit.", "Evaporate some water and leave the filtrate to crystallise."], "step": "Explain"}]}, {"key": "distil", "title": "Distillation and chromatography", "notes": ["Distillation separates and collects a liquid from a mixture. Heat the mixture so the liquid evaporates. Cool the vapour so it condenses back into a liquid.", "The condenser is the part that cools the vapour. Chromatography separates dissolved substances, such as colours in ink. Different substances travel different distances along the paper.", "Pure water can be made from sea water by distillation. In chromatography, the solvent moves up the paper and carries dissolved dyes different distances. Draw the start line in pencil, because pencil does not dissolve."], "worked": "Heat salt water to make water vapour. Cool the vapour in a condenser and collect liquid water. The salt stays behind because it does not evaporate with the water.", "question": "How does distillation collect pure water from salt water?", "scheme": ["Heat the salt water so water evaporates.", "Cool the water vapour so it condenses.", "Collect the liquid water, leaving the salt behind."], "mistake": "Evaporating water without collecting the vapour will not give you the water back.", "model": null, "id": "y7-unit-05-distil", "unit": "y7-unit-05", "year": 7, "number": 4, "marks": 3, "cards": [{"term": "Distillation", "definition": "Separating a liquid by evaporating it and then condensing its vapour."}, {"term": "Chromatography", "definition": "Separating dissolved substances because they travel different distances in a solvent."}], "quiz": {"q": "What does a condenser do during distillation?", "opts": ["Filters salt from water.", "Makes new water molecules.", "Cools vapour so it becomes liquid."], "a": 2, "why": "Cooling turns the vapour back into liquid so you can collect it."}, "misconception": {"q": "What does a condenser do during distillation? Sam answers: “Filters salt from water.” Explain why this is wrong.", "m": 2, "ms": ["Cools vapour so it becomes liquid.", "Cooling turns the vapour back into liquid so you can collect it."]}, "more": [{"q": "Which method gets pure water from sea water?", "opts": ["Chromatography.", "Distillation.", "Filtration."], "a": 1, "why": "Water evaporates and condenses; salt stays behind."}, {"q": "Why is the start line drawn in pencil in chromatography?", "opts": ["Pencil does not dissolve in the solvent.", "Pencil is easier to rub out.", "Ink is too expensive."], "a": 0, "why": "An ink line would move with the solvent."}, {"q": "What does the condenser do?", "opts": ["Heats the mixture.", "Filters the liquid.", "Cools vapour back into a liquid."], "a": 2, "why": "Cold water around it cools the vapour."}, {"q": "A black ink separates into three spots. This shows that the ink…", "opts": ["is insoluble.", "is a mixture of at least three dyes.", "is a pure substance."], "a": 1, "why": "Each spot is a different dye."}], "ladder": [{"q": "What does chromatography separate?", "m": 1, "ms": ["Dissolved substances, such as dyes in an ink."], "step": "Remember"}, {"q": "Describe how distillation separates water from salty water.", "m": 2, "ms": ["Heat the salty water so the water evaporates.", "The vapour is cooled in a condenser and collected as pure water."], "step": "Apply"}, {"q": "Explain why the dyes in an ink move different distances up the paper.", "m": 3, "ms": ["The solvent moves up the paper, carrying the dyes.", "Different dyes dissolve in the solvent and stick to the paper by different amounts.", "Dyes that are more soluble move further."], "step": "Explain"}]}, {"key": "energy", "title": "Energy stores and transfers", "notes": ["Energy can be stored in different ways. A moving object has a kinetic energy store. A battery has a chemical energy store.", "Energy can move between stores by heating, waves, electricity or forces. Energy is conserved: it cannot be created or destroyed. Energy often spreads into the surroundings and becomes less useful.", "Other energy stores include gravitational potential (raised objects), elastic (stretched springs) and thermal (hot objects). A falling ball transfers energy from its gravitational store to its kinetic store. Some energy is usually wasted by heating the surroundings."], "worked": "A battery-powered lamp transfers energy electrically from the battery. Light carries energy away and warms objects that absorb it. The lamp also heats the air around it.", "question": "Describe the energy changes when a battery-powered lamp lights a room.", "scheme": ["Energy starts in the battery's chemical store.", "It is transferred electrically to the lamp.", "Light and heating transfer energy to the room and its contents."], "mistake": "“Wasted” energy has not disappeared. It has spread to less useful places.", "model": null, "id": "y7-unit-06-energy", "unit": "y7-unit-06", "year": 7, "number": 1, "marks": 3, "cards": [{"term": "Energy store", "definition": "A way energy is held, such as in a moving object or a battery."}, {"term": "Dissipation", "definition": "Energy spreading into the surroundings and becoming less useful."}], "quiz": {"q": "What happens to energy we call “wasted”?", "opts": ["It stops being conserved.", "It spreads into less useful stores, often in the surroundings.", "It is destroyed."], "a": 1, "why": "The energy still exists, but it is less useful for the job we wanted."}, "misconception": {"q": "What happens to energy we call “wasted”? Sam answers: “It is destroyed.” Explain why this is wrong.", "m": 2, "ms": ["It spreads into less useful stores, often in the surroundings.", "The energy still exists, but it is less useful for the job we wanted."]}, "more": [{"q": "A stretched spring has energy in which store?", "opts": ["Elastic potential.", "Kinetic.", "Chemical."], "a": 0, "why": "Stretching or squashing stores elastic energy."}, {"q": "As a ball falls, energy transfers from…", "opts": ["kinetic to chemical.", "elastic to nuclear.", "gravitational potential to kinetic."], "a": 2, "why": "It loses height and gains speed."}, {"q": "A torch transfers energy from a battery to…", "opts": ["nuclear energy.", "light and the thermal store of the surroundings.", "the battery’s kinetic store."], "a": 1, "why": "Light is useful; heating is wasted."}, {"q": "Energy cannot be…", "opts": ["created or destroyed.", "transferred.", "stored."], "a": 0, "why": "This is the law of conservation of energy."}], "ladder": [{"q": "Name the energy store of a hot cup of tea.", "m": 1, "ms": ["Thermal store."], "step": "Remember"}, {"q": "Describe the energy transfer when a car brakes to a stop.", "m": 2, "ms": ["The kinetic store of the car decreases.", "Energy is transferred to the thermal store of the brakes/surroundings."], "step": "Apply"}, {"q": "A ball is dropped and bounces lower each time. Explain where the energy goes.", "m": 3, "ms": ["Energy is not destroyed.", "Some is transferred to the thermal store of the ball, floor and air.", "Some is carried away by sound, so less is left for the next bounce."], "step": "Explain"}]}, {"key": "food-energy", "title": "Comparing energy in foods", "notes": ["Food has a chemical energy store. Burning a food sample can heat water. A larger water temperature rise can suggest more energy was transferred.", "Compare energy for the same mass of food, such as one gram. Some energy heats the air and equipment instead of the water. Only use your teacher's method for burning foods.", "Food labels show energy in kilojoules (kJ). An active teenager needs more energy each day than someone who is less active. Eating more energy than you use is stored, often as fat."], "worked": "Two food samples may have different masses. A bigger sample could heat more water even if it gives less energy per gram. Divide the energy by the mass to compare them fairly.", "question": "Give two problems with comparing foods by burning them below water. Explain how one affects the result.", "scheme": ["Some energy heats the air or the equipment rather than the water.", "The food may not burn completely.", "These effects make the measured energy lower than the energy available in the food."], "mistake": "The temperature rise alone is not the total energy in the food.", "model": null, "id": "y7-unit-06-food-energy", "unit": "y7-unit-06", "year": 7, "number": 2, "marks": 3, "cards": [{"term": "Chemical energy store", "definition": "Energy stored in substances such as food, fuels and batteries."}, {"term": "Energy per gram", "definition": "The energy for each gram of a substance."}], "quiz": {"q": "Why compare food energy per gram?", "opts": ["A water temperature rise measures all the food's energy perfectly.", "Every food contains the same energy.", "The food samples might have different masses."], "a": 2, "why": "Comparing equal masses makes the comparison fairer."}, "misconception": {"q": "Why compare food energy per gram? Sam answers: “A water temperature rise measures all the food's energy perfectly.” Explain why this is wrong.", "m": 2, "ms": ["The food samples might have different masses.", "Comparing equal masses makes the comparison fairer."]}, "more": [{"q": "Food energy on labels is usually given in…", "opts": ["watts (W).", "kilojoules (kJ).", "newtons (N)."], "a": 1, "why": "1 kJ = 1000 J."}, {"q": "Who needs the most energy each day?", "opts": ["An active teenager who plays lots of sport.", "A sleeping adult.", "A small child resting."], "a": 0, "why": "Activity and growth need more energy."}, {"q": "Why compare foods using the same mass?", "opts": ["To make the food burn.", "To change the dependent variable.", "To make the test fair."], "a": 2, "why": "Different masses would hold different amounts of energy."}, {"q": "In the burning food test, why might results be too low?", "opts": ["The food has too much energy.", "Energy heats the air and equipment, not just the water.", "The water is too clean."], "a": 1, "why": "Not all energy reaches the water."}], "ladder": [{"q": "In which store is energy kept in food?", "m": 1, "ms": ["Chemical store."], "step": "Remember"}, {"q": "A crisp raises the water temperature by 15 °C and a peanut by 25 °C. Which transferred more energy, and how can you tell?", "m": 2, "ms": ["The peanut.", "It caused a bigger temperature rise in the same water."], "step": "Apply"}, {"q": "Explain one way to improve the burning-food experiment.", "m": 3, "ms": ["Use the same mass of each food / insulate the tube / keep the food close to the tube.", "This reduces energy lost to the surroundings or makes the test fair.", "So the temperature rise better represents the energy in the food."], "step": "Explain"}]}, {"key": "resources", "title": "Energy resources", "notes": ["Renewable resources are replaced naturally as we use them. Wind, sunlight and moving water are examples. Fossil fuels will run out because they form much more slowly than we use them.", "Burning fossil fuels releases carbon dioxide. Wind turbines make electricity without burning fuel. Wind output changes because the wind does not always blow. Nuclear fuel is non-renewable and produces radioactive waste. Nuclear power gives little carbon dioxide during electricity generation, but costs and waste still matter.", "Non-renewable resources include coal, oil, gas and nuclear fuel. Renewable resources include wind, solar, hydroelectric, tidal and biomass. Each resource has advantages and disadvantages, such as cost, reliability and pollution."], "worked": "A wind farm can reduce the fossil fuel used for electricity. On a calm day it produces little electricity. Other supplies or energy storage are then needed.", "question": "Give one advantage and one drawback of wind power compared with fossil-fuel power. Explain one.", "scheme": ["Wind is renewable and does not need burning fuel.", "It produces no carbon dioxide from burning fuel while operating.", "Output falls when there is little wind, so backup or storage is needed."], "mistake": "Renewable does not mean that an energy source is available all the time.", "model": null, "id": "y7-unit-06-resources", "unit": "y7-unit-06", "year": 7, "number": 3, "marks": 3, "cards": [{"term": "Renewable resource", "definition": "An energy resource that nature replaces as we use it."}, {"term": "Non-renewable resource", "definition": "An energy resource used faster than nature replaces it."}], "quiz": {"q": "Which is a renewable energy resource?", "opts": ["Natural gas.", "Uranium fuel.", "Wind."], "a": 2, "why": "Wind is replaced naturally, although it does not blow all the time."}, "misconception": {"q": "Which is a renewable energy resource? Sam answers: “Natural gas.” Explain why this is wrong.", "m": 2, "ms": ["Wind.", "Wind is replaced naturally, although it does not blow all the time."]}, "more": [{"q": "Which is a renewable energy resource?", "opts": ["Natural gas.", "Solar power.", "Coal."], "a": 1, "why": "Sunlight will not run out."}, {"q": "Why are fossil fuels non-renewable?", "opts": ["They take millions of years to form.", "They are found underground.", "They are expensive."], "a": 0, "why": "We use them much faster than they form."}, {"q": "A disadvantage of wind power is that…", "opts": ["it releases carbon dioxide.", "it will run out.", "it does not work when the wind is not blowing."], "a": 2, "why": "Supply depends on the weather."}, {"q": "Burning fossil fuels adds which gas to the air?", "opts": ["Nitrogen.", "Carbon dioxide.", "Oxygen."], "a": 1, "why": "Carbon dioxide adds to the greenhouse effect."}], "ladder": [{"q": "Name one non-renewable energy resource.", "m": 1, "ms": ["Coal / oil / natural gas / nuclear fuel."], "step": "Remember"}, {"q": "Give one advantage and one disadvantage of solar panels.", "m": 2, "ms": ["Advantage: renewable / no carbon dioxide while running.", "Disadvantage: no electricity at night / less on cloudy days / takes up space."], "step": "Apply"}, {"q": "Explain why many countries are building more wind and solar farms.", "m": 3, "ms": ["Fossil fuels will run out.", "Burning them releases carbon dioxide, which adds to climate change.", "Wind and solar are renewable and do not release carbon dioxide when generating electricity."], "step": "Explain"}]}, {"key": "power", "title": "Power, energy and electricity bills", "notes": ["Power tells you how quickly energy is transferred. Power is measured in watts, W. A kilowatt, kW, is 1000 watts.", "Electricity bills measure energy in kilowatt-hours, kWh. Energy in kWh = power in kW × time in hours. Cost = energy used × price per kWh.", "Devices with a higher power rating use energy faster. A 3 kW kettle transfers energy faster than a 0.1 kW TV. You can save money by using lower-power devices or using devices for less time."], "worked": "A 500 W device has a power of 0.5 kW. Used for 3 hours, it transfers 0.5 × 3 = 1.5 kWh. At 20 p per kWh, it costs 1.5 × 20 = 30 p.", "question": "A 500 W device runs for 3 hours. Electricity costs 20 p per kWh. Find the energy used and the cost.", "scheme": ["500 W = 0.5 kW.", "Energy used = 0.5 × 3 = 1.5 kWh.", "Cost = 1.5 × 20 = 30 p."], "mistake": "kW measures power. kWh measures energy.", "model": "bill", "id": "y7-unit-06-power", "unit": "y7-unit-06", "year": 7, "number": 4, "marks": 3, "cards": [{"term": "Power", "definition": "Energy transferred each second."}, {"term": "Kilowatt-hour", "definition": "The energy transferred by a 1 kW device in one hour."}], "quiz": {"q": "What is measured in kilowatt-hours, kWh?", "opts": ["Energy.", "Power.", "Current."], "a": 0, "why": "Power × time gives energy. A kilowatt alone measures power."}, "misconception": {"q": "What is measured in kilowatt-hours, kWh? Sam answers: “Power.” Explain why this is wrong.", "m": 2, "ms": ["Energy.", "Power × time gives energy. A kilowatt alone measures power."]}, "more": [{"q": "A 2 kW heater is on for 3 hours. How much energy does it use?", "opts": ["5 kWh.", "1.5 kWh.", "6 kWh."], "a": 2, "why": "2 × 3 = 6 kWh."}, {"q": "Energy costs 30p per kWh. What does 4 kWh cost?", "opts": ["7.5p.", "120p (£1.20).", "34p."], "a": 1, "why": "4 × 30 = 120p."}, {"q": "Which device has the highest power?", "opts": ["A 3 kW kettle.", "A 100 W TV.", "A 10 W phone charger."], "a": 0, "why": "3 kW = 3000 W."}, {"q": "What is 500 W in kilowatts?", "opts": ["5 kW.", "50 kW.", "0.5 kW."], "a": 2, "why": "Divide by 1000."}], "ladder": [{"q": "What unit is power measured in?", "m": 1, "ms": ["Watts (W)."], "step": "Remember"}, {"q": "A 1.5 kW microwave is used for 2 hours. Electricity costs 25p per kWh. Calculate the cost.", "m": 2, "ms": ["Energy = 1.5 × 2 = 3 kWh.", "Cost = 3 × 25 = 75p."], "step": "Apply"}, {"q": "Suggest and explain two ways a family could reduce their electricity bill.", "m": 3, "ms": ["Use lower-power appliances, e.g. LED bulbs.", "Use appliances for less time / switch off standby.", "Both reduce the number of kWh used, so the cost is lower."], "step": "Explain"}]}, {"key": "energy", "title": "Energy stores and transfers", "notes": ["Energy can be stored in different ways. A moving object has a kinetic energy store. A battery has a chemical energy store.", "Energy can move between stores by heating, waves, electricity or forces. Energy is conserved: it cannot be created or destroyed. Energy often spreads into the surroundings and becomes less useful.", "Other energy stores include gravitational potential (raised objects), elastic (stretched springs) and thermal (hot objects). A falling ball transfers energy from its gravitational store to its kinetic store. Some energy is usually wasted by heating the surroundings."], "worked": "A battery-powered lamp transfers energy electrically from the battery. Light carries energy away and warms objects that absorb it. The lamp also heats the air around it.", "question": "Describe the energy changes when a battery-powered lamp lights a room.", "scheme": ["Energy starts in the battery's chemical store.", "It is transferred electrically to the lamp.", "Light and heating transfer energy to the room and its contents."], "mistake": "“Wasted” energy has not disappeared. It has spread to less useful places.", "model": null, "id": "y7-unit-07-energy", "unit": "y7-unit-07", "year": 7, "number": 1, "marks": 3, "cards": [{"term": "Energy store", "definition": "A way energy is held, such as in a moving object or a battery."}, {"term": "Dissipation", "definition": "Energy spreading into the surroundings and becoming less useful."}], "quiz": {"q": "What happens to energy we call “wasted”?", "opts": ["It spreads into less useful stores, often in the surroundings.", "It is destroyed.", "It stops being conserved."], "a": 0, "why": "The energy still exists, but it is less useful for the job we wanted."}, "misconception": {"q": "What happens to energy we call “wasted”? Sam answers: “It is destroyed.” Explain why this is wrong.", "m": 2, "ms": ["It spreads into less useful stores, often in the surroundings.", "The energy still exists, but it is less useful for the job we wanted."]}, "more": [{"q": "A stretched spring has energy in which store?", "opts": ["Kinetic.", "Chemical.", "Elastic potential."], "a": 2, "why": "Stretching or squashing stores elastic energy."}, {"q": "As a ball falls, energy transfers from…", "opts": ["elastic to nuclear.", "gravitational potential to kinetic.", "kinetic to chemical."], "a": 1, "why": "It loses height and gains speed."}, {"q": "A torch transfers energy from a battery to…", "opts": ["light and the thermal store of the surroundings.", "the battery’s kinetic store.", "nuclear energy."], "a": 0, "why": "Light is useful; heating is wasted."}, {"q": "Energy cannot be…", "opts": ["transferred.", "stored.", "created or destroyed."], "a": 2, "why": "This is the law of conservation of energy."}], "ladder": [{"q": "Name the energy store of a hot cup of tea.", "m": 1, "ms": ["Thermal store."], "step": "Remember"}, {"q": "Describe the energy transfer when a car brakes to a stop.", "m": 2, "ms": ["The kinetic store of the car decreases.", "Energy is transferred to the thermal store of the brakes/surroundings."], "step": "Apply"}, {"q": "A ball is dropped and bounces lower each time. Explain where the energy goes.", "m": 3, "ms": ["Energy is not destroyed.", "Some is transferred to the thermal store of the ball, floor and air.", "Some is carried away by sound, so less is left for the next bounce."], "step": "Explain"}]}, {"key": "efficiency", "title": "Useful and wasted energy", "notes": ["A device transfers energy in useful and unwanted ways. An efficient device transfers a larger share in the useful way. Efficiency cannot be more than 100%.", "Efficiency = useful energy out ÷ total energy in. Multiply by 100 to give a percentage. A Sankey diagram uses arrow widths to show how much energy goes each way.", "Wasted energy usually heats the surroundings. LED bulbs are more efficient than filament bulbs because they waste less energy as heat. Insulation and lubrication can reduce wasted energy."], "worked": "A motor takes in 600 J and gives 450 J of useful movement. Efficiency = 450 ÷ 600 × 100 = 75%. The other 150 J is transferred in unwanted ways, such as heating.", "question": "A motor takes in 600 J and gives 450 J of useful movement. Find its efficiency and the unwanted energy transfer.", "scheme": ["Efficiency = 450 ÷ 600.", "Efficiency = 75%.", "Unwanted transfer = 600 − 450 = 150 J."], "mistake": "Even a very efficient machine cannot give out more energy than it takes in.", "model": "bill", "id": "y7-unit-07-efficiency", "unit": "y7-unit-07", "year": 7, "number": 2, "marks": 3, "cards": [{"term": "Efficiency", "definition": "The useful energy output divided by the total energy input."}, {"term": "Sankey diagram", "definition": "A diagram with arrow widths showing amounts of energy transferred."}], "quiz": {"q": "A device gives 20 J of useful energy from 100 J input. What is its efficiency?", "opts": ["500%.", "20%.", "80%."], "a": 1, "why": "20 ÷ 100 × 100 = 20%."}, "misconception": {"q": "A device gives 20 J of useful energy from 100 J input. What is its efficiency? Sam answers: “80%.” Explain why this is wrong.", "m": 2, "ms": ["20%.", "20 ÷ 100 × 100 = 20%."]}, "more": [{"q": "A bulb transfers 100 J; 20 J is light. What is its efficiency?", "opts": ["20%.", "80%.", "120%."], "a": 0, "why": "20 ÷ 100 × 100 = 20%."}, {"q": "Where does most wasted energy end up?", "opts": ["Back in the battery.", "It disappears.", "The thermal store of the surroundings."], "a": 2, "why": "Energy spreads out as heat."}, {"q": "Which bulb is more efficient?", "opts": ["They are always equal.", "An LED bulb.", "A filament bulb."], "a": 1, "why": "LEDs waste less energy by heating."}, {"q": "Oil on a bike chain improves efficiency by…", "opts": ["reducing friction.", "adding energy.", "making it heavier."], "a": 0, "why": "Less friction means less wasted heating."}], "ladder": [{"q": "What does efficiency tell you?", "m": 1, "ms": ["The fraction/percentage of energy transferred usefully."], "step": "Remember"}, {"q": "A motor uses 500 J and transfers 400 J usefully. Calculate its efficiency.", "m": 2, "ms": ["400 ÷ 500 = 0.8.", "0.8 × 100 = 80%."], "step": "Apply"}, {"q": "Explain why no device can be 100% efficient.", "m": 3, "ms": ["Energy is always transferred to unwanted stores.", "Friction and electrical resistance heat the device and surroundings.", "So the useful energy out is always less than the energy in."], "step": "Explain"}]}, {"key": "variation", "title": "Differences between living things", "notes": ["Variation means differences between living things of the same species. Some differences come from genes passed on by parents. Others come from surroundings and experiences.", "Height is continuous variation: people can have many values within a range. Blood group is discontinuous variation: people fit into separate groups. Many features depend on both genes and the environment.", "Some features depend on both genes and environment, such as height and weight. Variation within a species can be shown on a graph. Continuous variation makes a bell-shaped curve, while discontinuous variation is shown on a bar chart."], "worked": "Arm span is measured on a scale with many possible values. ABO blood group has the groups A, B, AB and O. A scar is an example of a difference caused by experience.", "question": "Compare continuous and discontinuous variation. Give an example of each.", "scheme": ["Continuous variation has values across a range, such as arm span.", "Discontinuous variation has separate groups, such as ABO blood group.", "A measurement can have values between two others, but the blood groups are separate categories."], "mistake": "Most features are not caused by genes alone or the environment alone.", "model": null, "id": "y7-unit-08-variation", "unit": "y7-unit-08", "year": 7, "number": 1, "marks": 3, "cards": [{"term": "Variation", "definition": "Differences between living things of the same species."}, {"term": "Continuous variation", "definition": "Differences with values across a range, such as height."}, {"term": "Discontinuous variation", "definition": "Differences in separate groups, such as ABO blood group."}], "quiz": {"q": "Which shows continuous variation?", "opts": ["Whether a feature is present or absent.", "Arm span.", "ABO blood group."], "a": 1, "why": "Arm span can have many measured values within a range."}, "misconception": {"q": "Which shows continuous variation? Sam answers: “ABO blood group.” Explain why this is wrong.", "m": 2, "ms": ["Arm span.", "Arm span can have many measured values within a range."]}, "more": [{"q": "Which is discontinuous variation?", "opts": ["Blood group.", "Height.", "Mass."], "a": 0, "why": "Blood group has only a few separate types."}, {"q": "Which feature is caused only by the environment?", "opts": ["Natural eye colour.", "Blood group.", "A scar."], "a": 2, "why": "A scar comes from an injury, not genes."}, {"q": "Which graph suits continuous variation?", "opts": ["A bar chart of categories.", "A histogram or line graph showing a range.", "A pie chart only."], "a": 1, "why": "Continuous data has values across a range."}, {"q": "Identical twins have different weights. This is mainly due to…", "opts": ["the environment, such as diet and exercise.", "different genes.", "different blood groups."], "a": 0, "why": "Identical twins share the same genes."}], "ladder": [{"q": "What is variation?", "m": 1, "ms": ["Differences between living things of the same species."], "step": "Remember"}, {"q": "Give one example of continuous and one of discontinuous variation in humans.", "m": 2, "ms": ["Continuous: height / mass / hand span.", "Discontinuous: blood group / tongue rolling / natural eye colour."], "step": "Apply"}, {"q": "Explain why identical twins can still look different as adults.", "m": 3, "ms": ["Identical twins have the same genes.", "Differences come from their environment.", "For example, diet, exercise, sun exposure or injuries."], "step": "Explain"}]}, {"key": "adaptation", "title": "Adaptations for survival", "notes": ["An adaptation is a feature that helps a living thing survive and reproduce. Inherited adaptations can be passed on to offspring. Different environments favour different features.", "Thick fur helps a mammal keep warm. A cactus has features that reduce water loss. A useful feature in one place may be unhelpful somewhere else.", "Animals in cold places often have thick fur, fat and small ears to reduce heat loss. Desert plants have small leaves or spines and deep roots. Predators often have forward-facing eyes; prey animals often have eyes on the sides of their heads."], "worked": "Thick fur traps air near an animal's skin. This slows energy transfer to cold surroundings. In a hot place, thick fur could make cooling down harder.", "question": "How does thick fur help a mammal in a cold place? Why might it be less helpful in a hot place?", "scheme": ["Fur traps air and reduces heat loss.", "This helps the mammal stay warm in the cold.", "In hot conditions it can make losing unwanted heat harder."], "mistake": "Living things do not choose a new inherited feature because they need it.", "model": null, "id": "y7-unit-08-adaptation", "unit": "y7-unit-08", "year": 7, "number": 2, "marks": 3, "cards": [{"term": "Adaptation", "definition": "An inherited feature that helps a living thing survive and reproduce in its environment."}, {"term": "Selection pressure", "definition": "Something in the environment that affects which organisms survive and reproduce."}], "quiz": {"q": "Which statement about inherited adaptations is correct?", "opts": ["They can become more common over generations.", "An animal chooses a new gene when it needs one.", "They are helpful in every environment."], "a": 0, "why": "A helpful inherited feature can be passed on by survivors to their offspring."}, "misconception": {"q": "Which statement about inherited adaptations is correct? Sam answers: “An animal chooses a new gene when it needs one.” Explain why this is wrong.", "m": 2, "ms": ["They can become more common over generations.", "A helpful inherited feature can be passed on by survivors to their offspring."]}, "more": [{"q": "Why does a polar bear have small ears?", "opts": ["To hear better.", "To swim faster.", "To reduce heat loss."], "a": 2, "why": "Small ears have less surface area to lose heat."}, {"q": "Why does a cactus have spines instead of leaves?", "opts": ["To make more food.", "To reduce water loss.", "To catch insects."], "a": 1, "why": "Smaller surface area loses less water."}, {"q": "Prey animals often have eyes on the sides of their heads to…", "opts": ["see predators coming from many directions.", "judge distance precisely.", "see in the dark."], "a": 0, "why": "A wide field of view helps them spot danger."}, {"q": "Which is a behavioural adaptation?", "opts": ["Thick fur.", "Sharp teeth.", "Birds migrating to warmer places in winter."], "a": 2, "why": "Behaviour is something the animal does."}], "ladder": [{"q": "What is an adaptation?", "m": 1, "ms": ["A feature that helps a living thing survive and reproduce in its environment."], "step": "Remember"}, {"q": "Give two adaptations of a camel to life in the desert.", "m": 2, "ms": ["Hump stores fat / wide feet for walking on sand.", "Long eyelashes keep out sand / loses little water."], "step": "Apply"}, {"q": "Explain how a thick layer of fat helps a seal survive in cold water.", "m": 3, "ms": ["Fat is a good insulator.", "It reduces energy transfer from the body to the cold water.", "So the seal keeps warm and can survive."], "step": "Explain"}]}, {"key": "data", "title": "Tables, graphs and conclusions", "notes": ["Put measurements in a results table. Label each column with the quantity and its unit. A graph helps you spot a pattern.", "Use a line graph for measurements such as time and temperature. Use a bar chart for separate groups, such as different materials. A conclusion answers your question using your results.", "Plot the independent variable on the x-axis and the dependent variable on the y-axis. Draw a line or curve of best fit through the points. Do not join the dots with a ruler."], "worked": "Suppose sugar dissolves in 40 seconds in cool water and 20 seconds in warm water. The warmer water gave a shorter dissolving time. Use these numbers as evidence in your conclusion.", "question": "What graph would show water temperature and sugar dissolving time? How would you write a good conclusion?", "scheme": ["Use a line or scatter graph with temperature on the horizontal axis.", "Put dissolving time on the vertical axis and label both units.", "Describe the pattern and use numbers from the results."], "mistake": "A conclusion needs evidence. Do not just say your prediction was right.", "model": null, "id": "y7-unit-08-data", "unit": "y7-unit-08", "year": 7, "number": 3, "marks": 3, "cards": [{"term": "Continuous data", "definition": "Measurements with values anywhere within a range, such as height."}, {"term": "Discrete data", "definition": "Separate counts or values, such as the number of leaves."}, {"term": "Conclusion", "definition": "An answer to your test question, supported by your results."}], "quiz": {"q": "What makes a good conclusion?", "opts": ["Choose your favourite result and ignore the others.", "Leave units off the graph.", "Describe a pattern and use numbers from the results."], "a": 2, "why": "Numbers from the results give evidence for the pattern you describe."}, "misconception": {"q": "What makes a good conclusion? Sam answers: “Choose your favourite result and ignore the others.” Explain why this is wrong.", "m": 2, "ms": ["Describe a pattern and use numbers from the results.", "Numbers from the results give evidence for the pattern you describe."]}, "more": [{"q": "Which axis should show the independent variable?", "opts": ["Either axis, it does not matter.", "The x-axis (horizontal).", "The y-axis (vertical)."], "a": 1, "why": "By convention, the variable you change goes along the bottom."}, {"q": "What is a line of best fit?", "opts": ["A smooth line or curve that passes close to most points.", "A line joining every point dot-to-dot.", "A line through the first and last points only."], "a": 0, "why": "It shows the overall pattern."}, {"q": "Which graph type suits \"number of students with each eye colour\"?", "opts": ["Line graph.", "Scatter graph with a curve.", "Bar chart."], "a": 2, "why": "Eye colour is a category, so use a bar chart."}, {"q": "A table heading should include…", "opts": ["nothing; numbers are enough.", "the quantity and its unit, e.g. Time (s).", "only the unit."], "a": 1, "why": "Units belong in the heading, not after each number."}], "ladder": [{"q": "What does a line of best fit show?", "m": 1, "ms": ["The overall pattern/trend in the results."], "step": "Remember"}, {"q": "A table has the heading \"Temperature\" and values 20, 40, 60. Give two ways to improve it.", "m": 2, "ms": ["Add the unit to the heading, e.g. Temperature (°C).", "Add a column for the measured (dependent) variable / repeats and a mean."], "step": "Apply"}, {"q": "Explain how to plot a line graph of time against temperature.", "m": 3, "ms": ["Put temperature (independent) on the x-axis and time on the y-axis.", "Choose even scales that use most of the grid and label axes with units.", "Plot points accurately and draw a smooth line of best fit."], "step": "Explain"}]}, {"key": "puberty", "title": "Puberty and reproductive organs", "notes": ["Puberty is when a child's body develops towards an adult body. Chemical messages called hormones control these changes. The timing is different for different people.", "Testes produce sperm cells. Ovaries produce egg cells. A baby develops in the uterus, also called the womb. Sperm ducts carry sperm, and the penis delivers semen. Oviducts carry eggs, and the vagina connects the uterus to the outside of the body. Adolescence also includes emotional and social changes.", "In boys, testosterone from the testes causes changes such as a deeper voice and facial hair. In girls, oestrogen from the ovaries causes changes such as breasts developing and periods starting. Both may grow quickly and get body hair."], "worked": "Sperm and eggs are sex cells, called gametes. A sperm cell can join with an egg cell at fertilisation. The resulting embryo can later grow in the uterus.", "question": "What are the jobs of the testes, ovaries and uterus?", "scheme": ["Testes produce sperm.", "Ovaries produce egg cells.", "The uterus is where an embryo can develop into a baby."], "mistake": "Puberty does not happen at exactly the same age for everyone.", "model": null, "id": "y7-unit-09-puberty", "unit": "y7-unit-09", "year": 7, "number": 1, "marks": 3, "cards": [{"term": "Puberty", "definition": "Body changes that prepare a child for adulthood and reproduction."}, {"term": "Gamete", "definition": "A sex cell, such as a sperm or egg, with half the usual chromosome number."}], "quiz": {"q": "Where are sperm produced?", "opts": ["In the oviducts.", "In the testes.", "In the uterus."], "a": 1, "why": "Testes produce sperm and ovaries produce egg cells."}, "misconception": {"q": "Where are sperm produced? Sam answers: “In the uterus.” Explain why this is wrong.", "m": 2, "ms": ["In the testes.", "Testes produce sperm and ovaries produce egg cells."]}, "more": [{"q": "Which hormone causes most changes in boys during puberty?", "opts": ["Testosterone.", "Oestrogen.", "Insulin."], "a": 0, "why": "Testosterone is made in the testes."}, {"q": "Where are egg cells made?", "opts": ["Uterus.", "Testes.", "Ovaries."], "a": 2, "why": "Ovaries release an egg about once a month."}, {"q": "Which change happens to both boys and girls?", "opts": ["Voice deepens a lot.", "Growth of pubic and underarm hair.", "Periods start."], "a": 1, "why": "Some changes happen to everyone."}, {"q": "What are hormones?", "opts": ["Chemical messengers carried in the blood.", "Types of cell.", "Bones."], "a": 0, "why": "Hormones travel in the blood to target organs."}], "ladder": [{"q": "What is puberty?", "m": 1, "ms": ["The time when a child’s body develops into an adult body."], "step": "Remember"}, {"q": "Name the male and female sex hormones.", "m": 2, "ms": ["Testosterone (male).", "Oestrogen (female)."], "step": "Apply"}, {"q": "Explain why puberty starts at different ages for different people.", "m": 3, "ms": ["Puberty is controlled by hormones.", "Hormones start being made at different times in different bodies.", "Genes, diet and health can affect the timing."], "step": "Explain"}]}, {"key": "cycle", "title": "The menstrual cycle", "notes": ["The menstrual cycle prepares the uterus for a possible pregnancy. The lining of the uterus thickens. Ovulation is the release of an egg from an ovary.", "If pregnancy does not happen, the lining breaks down. The lining and blood leave through the vagina during a period. This is called menstruation.", "The menstrual cycle lasts about 28 days. Ovulation usually happens around day 14. Hormones control when the uterus lining builds up and when it breaks down."], "worked": "Diagrams often show a 28-day cycle. Real cycles can be shorter or longer. The timing of ovulation can also change.", "question": "What are menstruation and ovulation? Why does a 28-day diagram not describe every cycle?", "scheme": ["Menstruation is when the uterus lining leaves the body during a period.", "Ovulation is the release of an egg from an ovary.", "Cycle length and ovulation timing vary between people and cycles."], "mistake": "Ovulation and a period are different events.", "model": null, "id": "y7-unit-09-cycle", "unit": "y7-unit-09", "year": 7, "number": 2, "marks": 3, "cards": [{"term": "Menstruation", "definition": "When the uterus lining leaves the body during a period."}, {"term": "Ovulation", "definition": "The release of an egg from an ovary."}], "quiz": {"q": "Why does a 28-day diagram not describe every menstrual cycle?", "opts": ["Every cycle is exactly 28 days.", "Ovulation is the same as a period.", "Cycle length and the timing of ovulation vary."], "a": 2, "why": "A diagram shows a typical pattern. Real cycles can be shorter or longer."}, "misconception": {"q": "Why does a 28-day diagram not describe every menstrual cycle? Sam answers: “Every cycle is exactly 28 days.” Explain why this is wrong.", "m": 2, "ms": ["Cycle length and the timing of ovulation vary.", "A diagram shows a typical pattern. Real cycles can be shorter or longer."]}, "more": [{"q": "About how long is a typical menstrual cycle?", "opts": ["1 year.", "28 days.", "7 days."], "a": 1, "why": "It varies, but about 28 days is typical."}, {"q": "What is ovulation?", "opts": ["The release of an egg from an ovary.", "The lining breaking down.", "Sperm meeting an egg."], "a": 0, "why": "An egg is released about once a month."}, {"q": "Why does the uterus lining thicken?", "opts": ["To store food for the mother.", "To make eggs.", "To be ready for an embryo to implant."], "a": 2, "why": "A thick lining can support a pregnancy."}, {"q": "A period happens when…", "opts": ["ovulation starts.", "an egg is not fertilised and the lining breaks down.", "an egg is fertilised."], "a": 1, "why": "The lining leaves the body through the vagina."}], "ladder": [{"q": "About which day of a 28-day cycle does ovulation happen?", "m": 1, "ms": ["Day 14."], "step": "Remember"}, {"q": "Describe what happens to the uterus lining during the cycle.", "m": 2, "ms": ["It thickens/builds up to prepare for pregnancy.", "If no egg is fertilised, it breaks down and leaves the body (a period)."], "step": "Apply"}, {"q": "Explain why a period stops if a woman becomes pregnant.", "m": 3, "ms": ["The embryo implants in the thick lining.", "Hormones keep the lining in place.", "The lining is needed to support the growing baby, so it is not lost."], "step": "Explain"}]}, {"key": "pregnancy", "title": "Fertilisation and pregnancy", "notes": ["Fertilisation happens when the nuclei of a sperm and an egg join. It usually happens in an oviduct, also called a fallopian tube. The fertilised egg starts dividing to form an embryo.", "The embryo travels to the uterus. It attaches to the uterus lining: this is implantation. The placenta exchanges substances between the mother and developing baby.", "The placenta lets food and oxygen pass from the mother's blood to the fetus, and waste pass back. The umbilical cord connects the fetus to the placenta. Pregnancy lasts about 40 weeks."], "worked": "Oxygen and nutrients pass towards the baby through the placenta. Waste substances pass away from the baby. The mother's blood and the baby's blood do not normally mix directly.", "question": "How are fertilisation and implantation different? Give one job of the placenta.", "scheme": ["Fertilisation joins sperm and egg nuclei, usually in an oviduct.", "Implantation is the embryo attaching to the uterus lining.", "The placenta passes oxygen or nutrients to the baby, or removes waste."], "mistake": "Fertilisation happens before implantation.", "model": null, "id": "y7-unit-09-pregnancy", "unit": "y7-unit-09", "year": 7, "number": 3, "marks": 3, "cards": [{"term": "Fertilisation", "definition": "The joining of a sperm-cell nucleus and an egg-cell nucleus."}, {"term": "Implantation", "definition": "An embryo attaching to the uterus lining."}, {"term": "Placenta", "definition": "An organ that exchanges nutrients, oxygen and waste between the mother and developing baby."}], "quiz": {"q": "Where does fertilisation usually happen in humans?", "opts": ["In the uterus lining during implantation.", "In the placenta.", "In an oviduct, also called a fallopian tube."], "a": 2, "why": "The embryo travels to the uterus and implants there after fertilisation."}, "misconception": {"q": "Where does fertilisation usually happen in humans? Sam answers: “In the uterus lining during implantation.” Explain why this is wrong.", "m": 2, "ms": ["In an oviduct, also called a fallopian tube.", "The embryo travels to the uterus and implants there after fertilisation."]}, "more": [{"q": "Where does fertilisation usually happen?", "opts": ["In the vagina.", "In the oviduct (fallopian tube).", "In the ovary."], "a": 1, "why": "The sperm meets the egg in the oviduct."}, {"q": "What does the placenta do?", "opts": ["Passes food and oxygen to the fetus and removes waste.", "Makes sperm.", "Releases eggs."], "a": 0, "why": "It is the exchange organ between mother and fetus."}, {"q": "About how long does a human pregnancy last?", "opts": ["12 weeks.", "2 years.", "40 weeks."], "a": 2, "why": "About nine months."}, {"q": "Why should pregnant women avoid smoking and alcohol?", "opts": ["They stop periods.", "Harmful substances can cross the placenta to the fetus.", "They make the baby bigger."], "a": 1, "why": "The placenta does not block all harmful chemicals."}], "ladder": [{"q": "What is fertilisation?", "m": 1, "ms": ["When the nucleus of a sperm joins with the nucleus of an egg."], "step": "Remember"}, {"q": "Name the organ that supplies the fetus with oxygen and describe how it is connected.", "m": 2, "ms": ["The placenta.", "It is connected to the fetus by the umbilical cord."], "step": "Apply"}, {"q": "Explain why smoking during pregnancy can harm the baby.", "m": 3, "ms": ["Chemicals such as nicotine and carbon monoxide cross the placenta.", "Carbon monoxide reduces the oxygen reaching the fetus.", "This can slow growth and lead to a low birth weight."], "step": "Explain"}]}, {"key": "flower", "title": "Flowers and pollination", "notes": ["Flowers contain the parts needed for plant reproduction. Anthers make pollen. The stigma is the surface that receives pollen.", "Pollination moves pollen from an anther to a stigma. Insects can carry pollen between flowers. Wind can also carry pollen.", "The male parts are the stamens: anther and filament. The female parts are the carpel: stigma, style and ovary. Insect-pollinated flowers have bright petals, scent and nectar; wind-pollinated flowers have feathery stigmas and lots of light pollen."], "worked": "Insect-pollinated flowers often have bright petals, scent and nectar. These attract insects that carry pollen. Wind-pollinated flowers often release lots of small, light pollen grains.", "question": "Give one feature of a wind-pollinated flower and one of an insect-pollinated flower. Explain how a feature helps.", "scheme": ["Wind-pollinated flowers may produce lots of light pollen.", "Insect-pollinated flowers may have bright petals, nectar or scent.", "The feature helps wind or insects carry pollen to a stigma."], "mistake": "Pollination is moving pollen. Fertilisation happens later.", "model": null, "id": "y7-unit-10-flower", "unit": "y7-unit-10", "year": 7, "number": 1, "marks": 3, "cards": [{"term": "Pollination", "definition": "Moving pollen from an anther to a stigma."}, {"term": "Anther", "definition": "The part of a flower that makes pollen."}, {"term": "Stigma", "definition": "The flower surface that receives pollen."}], "quiz": {"q": "Which example is pollination?", "opts": ["A seed starting to grow.", "Pollen landing on a suitable stigma.", "Sperm and egg nuclei joining."], "a": 1, "why": "Pollination is moving pollen. Fertilisation is joining sex-cell nuclei later."}, "misconception": {"q": "Which example is pollination? Sam answers: “Sperm and egg nuclei joining.” Explain why this is wrong.", "m": 2, "ms": ["Pollen landing on a suitable stigma.", "Pollination is moving pollen. Fertilisation is joining sex-cell nuclei later."]}, "more": [{"q": "Which part of a flower makes pollen?", "opts": ["Anther.", "Stigma.", "Ovary."], "a": 0, "why": "The anther is part of the stamen."}, {"q": "Which feature suits a wind-pollinated flower?", "opts": ["Bright petals.", "Sweet scent.", "Feathery stigma hanging outside the flower."], "a": 2, "why": "A feathery stigma catches pollen blowing past."}, {"q": "Why do some flowers make nectar?", "opts": ["To catch wind.", "To attract insects.", "To make seeds heavier."], "a": 1, "why": "Insects visit for nectar and carry pollen."}, {"q": "Where are the ovules found?", "opts": ["In the ovary.", "In the anther.", "On the petals."], "a": 0, "why": "Ovules contain the female sex cells."}], "ladder": [{"q": "What is pollination?", "m": 1, "ms": ["The transfer of pollen from an anther to a stigma."], "step": "Remember"}, {"q": "Name two female parts of a flower.", "m": 2, "ms": ["Stigma / style.", "Ovary / ovule."], "step": "Apply"}, {"q": "Explain how the features of an insect-pollinated flower help pollination.", "m": 3, "ms": ["Bright petals and scent attract insects.", "Insects collect nectar and pollen sticks to them.", "They carry the pollen to the sticky stigma of another flower."], "step": "Explain"}]}, {"key": "seed", "title": "Making and spreading seeds", "notes": ["After pollination, a pollen tube grows towards an ovule. A male sex-cell nucleus travels down the tube. It joins the egg-cell nucleus at fertilisation.", "A fertilised ovule can develop into a seed. The ovary often develops into a fruit. Seeds can be spread by wind, water or animals.", "Seeds and fruits are dispersed so new plants do not compete with the parent for light, water and minerals. Methods include wind (sycamore), animals (berries, burrs), water (coconut) and explosion (pea pods)."], "worked": "A dandelion seed has a light parachute-like structure. Wind carries it away from the parent plant. The new plant then has less competition with its parent.", "question": "Describe the steps from pollination to a seed forming.", "scheme": ["Pollen reaches the stigma.", "A pollen tube grows and a male nucleus joins the egg nucleus.", "The fertilised ovule develops into a seed."], "mistake": "A seed develops from an ovule, not from a petal.", "model": null, "id": "y7-unit-10-seed", "unit": "y7-unit-10", "year": 7, "number": 2, "marks": 3, "cards": [{"term": "Seed dispersal", "definition": "Spreading seeds away from the parent plant."}, {"term": "Ovule", "definition": "A part inside the flower's ovary that can become a seed after fertilisation."}], "quiz": {"q": "Which flower part develops into a seed after fertilisation?", "opts": ["The whole anther.", "A petal.", "An ovule."], "a": 2, "why": "A fertilised ovule becomes a seed. The ovary often becomes a fruit."}, "misconception": {"q": "Which flower part develops into a seed after fertilisation? Sam answers: “The whole anther.” Explain why this is wrong.", "m": 2, "ms": ["An ovule.", "A fertilised ovule becomes a seed. The ovary often becomes a fruit."]}, "more": [{"q": "Why are seeds dispersed away from the parent plant?", "opts": ["So they can be pollinated.", "To reduce competition for light, water and minerals.", "To keep them warm."], "a": 1, "why": "Young plants grow better with less competition."}, {"q": "A dandelion seed has a parachute of hairs. It is dispersed by…", "opts": ["wind.", "animals eating it.", "explosion."], "a": 0, "why": "The hairs catch the wind."}, {"q": "After fertilisation, the ovary becomes the…", "opts": ["flower.", "pollen.", "fruit."], "a": 2, "why": "The fruit surrounds and protects seeds."}, {"q": "Which seed is dispersed by animals eating the fruit?", "opts": ["Dandelion.", "Blackberry.", "Sycamore."], "a": 1, "why": "Seeds pass through the animal and are dropped elsewhere."}], "ladder": [{"q": "What develops from a fertilised ovule?", "m": 1, "ms": ["A seed."], "step": "Remember"}, {"q": "Describe two ways seeds are dispersed, with an example of each.", "m": 2, "ms": ["Wind, e.g. dandelion or sycamore.", "Animals, e.g. berries eaten or burrs on fur / explosion, e.g. pea pods."], "step": "Apply"}, {"q": "Explain why a sycamore seed with wings can land further from the tree.", "m": 3, "ms": ["The wings make the seed spin as it falls.", "This increases air resistance so it falls slowly.", "The wind has more time to carry it further away."], "step": "Explain"}]}, {"key": "germination", "title": "When seeds start to grow", "notes": ["Germination is when a seed starts growing. Most seeds need water, oxygen and a suitable temperature. They use stored food to start with.", "Water starts processes inside the seed. Oxygen is needed for aerobic respiration. Respiration releases energy for growth.", "Seeds do not need light to germinate, because they use their stored food. Once leaves grow, the plant needs light for photosynthesis. You can test what seeds need by changing one condition at a time."], "worked": "A seed can start growing on damp cotton wool. It does not need soil as its first food supply. Many seeds can germinate without light.", "question": "Why does a seed need water and oxygen to germinate?", "scheme": ["Water allows processes inside the seed to start.", "Oxygen is used in aerobic respiration.", "Respiration releases energy needed for growth."], "mistake": "Most seeds use stored food at first. Soil is not their food.", "model": null, "id": "y7-unit-10-germination", "unit": "y7-unit-10", "year": 7, "number": 3, "marks": 3, "cards": [{"term": "Germination", "definition": "When a seed starts to grow into a seedling."}, {"term": "Control group", "definition": "A comparison group used to help find the effect of the thing being tested."}], "quiz": {"q": "What do most seeds need to germinate?", "opts": ["Light in every case.", "Soil as their food supply.", "Water, oxygen and a suitable temperature."], "a": 2, "why": "Seeds use stored food at first. Many can germinate without light."}, "misconception": {"q": "What do most seeds need to germinate? Sam answers: “Light in every case.” Explain why this is wrong.", "m": 2, "ms": ["Water, oxygen and a suitable temperature.", "Seeds use stored food at first. Many can germinate without light."]}, "more": [{"q": "Which is NOT needed for most seeds to germinate?", "opts": ["Oxygen.", "Light.", "Water."], "a": 1, "why": "Stored food provides energy until leaves grow."}, {"q": "Seeds kept in a fridge germinate slowly because…", "opts": ["it is too cold for enzymes to work quickly.", "there is too much light.", "there is too much oxygen."], "a": 0, "why": "Low temperature slows reactions in the seed."}, {"q": "Why do germinating seeds need oxygen?", "opts": ["To make chlorophyll.", "To stay dry.", "For aerobic respiration to release energy."], "a": 2, "why": "Respiration releases energy for growth."}, {"q": "In a germination test, the control dish should…", "opts": ["have no water and no air.", "have all the conditions: water, air and warmth.", "have no seeds."], "a": 1, "why": "The control shows normal germination."}], "ladder": [{"q": "What is germination?", "m": 1, "ms": ["When a seed starts to grow."], "step": "Remember"}, {"q": "Plan a test to find out whether seeds need water to germinate.", "m": 2, "ms": ["Set up two dishes of seeds, one with damp cotton wool and one with dry cotton wool.", "Keep all other conditions the same and compare after a few days."], "step": "Apply"}, {"q": "Explain why a seed can germinate in the dark but the young plant will not keep growing well without light.", "m": 3, "ms": ["The seed uses its stored food for energy at first.", "Once the store runs out, the plant needs to make food by photosynthesis.", "Photosynthesis needs light."], "step": "Explain"}]}, {"key": "reaction", "title": "Chemical reactions and physical changes", "notes": ["A chemical reaction makes one or more new substances. The starting substances are reactants. The new substances are products.", "A physical change does not make a new substance. Melting and freezing are physical changes. Bubbles or a colour change can be clues to a reaction, but check the evidence.", "Signs of a chemical reaction include a colour change, fizzing, a temperature change or a precipitate forming. Chemical changes are usually hard to reverse. Word equations show the reactants and products."], "worked": "Burning magnesium makes a new substance, magnesium oxide. Melting ice still leaves you with water. Boiling water makes bubbles without a chemical reaction.", "question": "Give one chemical reaction and one physical change. Explain the difference.", "scheme": ["Give a reaction that makes a new substance, such as burning magnesium.", "Give a physical change, such as melting ice.", "A physical change does not make a new substance."], "mistake": "Bubbles alone do not prove that a chemical reaction happened.", "model": null, "id": "y7-unit-11-reaction", "unit": "y7-unit-11", "year": 7, "number": 1, "marks": 3, "cards": [{"term": "Reactant", "definition": "A starting substance in a chemical reaction."}, {"term": "Product", "definition": "A new substance made in a chemical reaction."}, {"term": "Physical change", "definition": "A change that does not make a new substance."}], "quiz": {"q": "Which observation alone does not prove a chemical reaction?", "opts": ["Bubbles appearing.", "Clear evidence of a new substance forming.", "A test confirming a different chemical substance."], "a": 0, "why": "Boiling water also makes bubbles, without making a new substance."}, "misconception": {"q": "Which observation alone does not prove a chemical reaction? Sam answers: “Clear evidence of a new substance forming.” Explain why this is wrong.", "m": 2, "ms": ["Bubbles appearing.", "Boiling water also makes bubbles, without making a new substance."]}, "more": [{"q": "Which is a chemical change?", "opts": ["Melting ice.", "Dissolving sugar.", "Burning wood."], "a": 2, "why": "Burning makes new substances such as ash and carbon dioxide."}, {"q": "Which is a sign of a chemical reaction?", "opts": ["Something being cut into pieces.", "A gas being given off (fizzing).", "A change in shape."], "a": 1, "why": "Fizzing shows a new substance, a gas, is made."}, {"q": "In \"magnesium + oxygen → magnesium oxide\", the product is…", "opts": ["magnesium oxide.", "magnesium.", "oxygen."], "a": 0, "why": "Products are on the right of the arrow."}, {"q": "Which change is easy to reverse?", "opts": ["Cooking an egg.", "Rusting.", "Water freezing."], "a": 2, "why": "Freezing is a physical change."}], "ladder": [{"q": "What is a product?", "m": 1, "ms": ["A new substance made in a chemical reaction."], "step": "Remember"}, {"q": "Give two observations that show a chemical reaction has happened.", "m": 2, "ms": ["Colour change / fizzing (gas given off).", "Temperature change / a solid (precipitate) forms / light given out."], "step": "Apply"}, {"q": "Explain why melting chocolate is a physical change but toasting bread is a chemical change.", "m": 3, "ms": ["Melting chocolate does not make a new substance and can be reversed by cooling.", "Toasting bread makes new substances (the brown, burnt layer).", "It cannot be reversed."], "step": "Explain"}]}, {"key": "acid", "title": "Acids, alkalis and pH", "notes": ["Acids have a pH below 7. Alkalis have a pH above 7. A neutral solution has a pH of 7 at room temperature.", "An indicator changes colour to show pH. Concentrated means a lot of dissolved substance in a given volume. Dilute means less dissolved substance in the same volume.", "Acids in everyday life include vinegar and citrus fruits; alkalis include soap and oven cleaner. Strong acids and alkalis are corrosive, so wear goggles. Red litmus turns blue in alkali; blue litmus turns red in acid."], "worked": "Strength and concentration mean different things. Acid strength describes how much the acid splits into charged particles in water. A strong acid can still be dilute if it contains lots of water.", "question": "A pupil says “concentrated” and “strong” mean the same thing for acids. Explain the difference.", "scheme": ["Concentration describes how much acid is in a given volume of solution.", "Strength describes how much the acid splits into charged particles in water.", "A strong acid can be dilute, so the words do not mean the same thing."], "mistake": "A concentrated acid is not always a strong acid.", "model": "ph", "id": "y7-unit-11-acid", "unit": "y7-unit-11", "year": 7, "number": 2, "marks": 3, "cards": [{"term": "Acid", "definition": "A substance that gives a solution with pH below 7 in water."}, {"term": "Alkali", "definition": "A base that dissolves in water."}, {"term": "Concentration", "definition": "How much dissolved substance there is in a given volume of solution."}], "quiz": {"q": "What does “concentrated” tell you about an acid solution?", "opts": ["How much acid there is in a given volume of solution.", "How much of the acid splits into charged particles.", "That the acid must be strong."], "a": 0, "why": "Concentration describes the amount of acid. Strength describes a different property of the acid."}, "misconception": {"q": "What does “concentrated” tell you about an acid solution? Sam answers: “How much of the acid splits into charged particles.” Explain why this is wrong.", "m": 2, "ms": ["How much acid there is in a given volume of solution.", "Concentration describes the amount of acid. Strength describes a different property of the acid."]}, "more": [{"q": "What colour does universal indicator turn in a strong acid?", "opts": ["Green.", "Purple.", "Red."], "a": 2, "why": "Strong acids have a low pH and turn it red."}, {"q": "A solution has a pH of 12. It is…", "opts": ["neutral.", "alkaline.", "acidic."], "a": 1, "why": "Above 7 is alkaline."}, {"q": "Which is acidic?", "opts": ["Lemon juice.", "Soap.", "Pure water."], "a": 0, "why": "Lemon juice contains citric acid."}, {"q": "Blue litmus paper turns red in…", "opts": ["alkali.", "pure water.", "acid."], "a": 2, "why": "Acids turn blue litmus red."}], "ladder": [{"q": "What pH is neutral?", "m": 1, "ms": ["7."], "step": "Remember"}, {"q": "A solution turns universal indicator dark blue. Give its approximate pH and whether it is acidic or alkaline.", "m": 2, "ms": ["About pH 10–12.", "Alkaline."], "step": "Apply"}, {"q": "Explain why universal indicator is more useful than litmus paper.", "m": 3, "ms": ["Litmus only shows whether something is acidic or alkaline.", "Universal indicator shows a range of colours.", "So it shows the pH and how strongly acidic or alkaline it is."], "step": "Explain"}]}, {"key": "neutral", "title": "Neutralisation and salts", "notes": ["An acid reacts with a base in a neutralisation reaction. An alkali is a base that dissolves in water. Acid + metal oxide → salt + water.", "The acid helps decide the salt's name. Hydrochloric acid makes chlorides. Sulfuric acid makes sulfates and nitric acid makes nitrates.", "Neutralisation is useful: indigestion tablets neutralise extra stomach acid, and farmers use lime to neutralise acidic soil. You can follow neutralisation with an indicator. Acid + alkali → salt + water."], "worked": "Magnesium oxide reacts with hydrochloric acid. The products are magnesium chloride and water. The acid and base have made a salt.", "question": "Magnesium oxide reacts with hydrochloric acid. Name the salt and the other product.", "scheme": ["The salt contains magnesium.", "The salt is magnesium chloride.", "The other product is water."], "mistake": "A salt does not always mean the table salt you put on food.", "model": "ph", "id": "y7-unit-11-neutral", "unit": "y7-unit-11", "year": 7, "number": 3, "marks": 3, "cards": [{"term": "Neutralisation", "definition": "A reaction between an acid and a base."}, {"term": "Salt", "definition": "A type of compound made in reactions such as acid reacting with a metal oxide."}], "quiz": {"q": "What type of salt does hydrochloric acid make?", "opts": ["A nitrate.", "A chloride.", "A sulfate."], "a": 1, "why": "Hydrochloric acid makes chlorides. Sulfuric acid makes sulfates."}, "misconception": {"q": "What type of salt does hydrochloric acid make? Sam answers: “A sulfate.” Explain why this is wrong.", "m": 2, "ms": ["A chloride.", "Hydrochloric acid makes chlorides. Sulfuric acid makes sulfates."]}, "more": [{"q": "What are the products when an acid reacts with an alkali?", "opts": ["A salt and water.", "Hydrogen and oxygen.", "Only water."], "a": 0, "why": "This is neutralisation."}, {"q": "Which salt does hydrochloric acid make?", "opts": ["A sulfate.", "A nitrate.", "A chloride."], "a": 2, "why": "Hydrochloric acid makes chlorides."}, {"q": "Why do farmers add lime to fields?", "opts": ["To kill insects.", "To neutralise acidic soil.", "To make the soil more acidic."], "a": 1, "why": "Many crops grow better near pH 7."}, {"q": "Indigestion tablets work because they are…", "opts": ["bases that neutralise stomach acid.", "acids.", "salts that add acid."], "a": 0, "why": "They reduce excess acid."}], "ladder": [{"q": "What is neutralisation?", "m": 1, "ms": ["A reaction between an acid and a base that makes a salt and water."], "step": "Remember"}, {"q": "Name the salt made when sodium hydroxide reacts with sulfuric acid, and the other product.", "m": 2, "ms": ["Sodium sulfate.", "Water."], "step": "Apply"}, {"q": "Explain how you could show that an acid has been neutralised by an alkali.", "m": 3, "ms": ["Add universal indicator to the acid.", "Add the alkali a little at a time, stirring.", "When the indicator turns green, the solution is neutral (pH 7)."], "step": "Explain"}]}, {"key": "metals", "title": "Metals and reactivity", "notes": ["Metals usually conduct heat and electricity well. Many metals react with oxygen to make metal oxides. Gaining oxygen is called oxidation.", "Some metals react more easily than others. A more reactive metal can replace a less reactive metal in a compound. This is called displacement. Most metals can be shaped without breaking. Some non-metals are exceptions to the usual rules: graphite conducts electricity.", "The reactivity series lists metals from most to least reactive, for example potassium, sodium, calcium, magnesium, zinc, iron, copper, gold. Iron rusts when it reacts with oxygen and water. Gold does not react, so it stays shiny."], "worked": "Zinc is more reactive than copper. Zinc placed in copper sulfate solution can form zinc sulfate. Copper is left as a solid.", "question": "Zinc is more reactive than copper. What happens when zinc is put in copper sulfate solution? Explain why.", "scheme": ["Zinc displaces copper.", "Zinc sulfate and copper form.", "Zinc replaces copper because it is more reactive."], "mistake": "A less reactive metal cannot simply displace a more reactive one.", "model": null, "id": "y7-unit-12-metals", "unit": "y7-unit-12", "year": 7, "number": 1, "marks": 3, "cards": [{"term": "Displacement", "definition": "A more reactive element replacing a less reactive element in a compound."}, {"term": "Oxidation", "definition": "A reaction in which a substance gains oxygen, in these examples."}], "quiz": {"q": "Iron is more reactive than copper. Can copper displace iron from iron sulfate?", "opts": ["No.", "Yes, because all metals displace each other.", "Yes, because copper is coloured."], "a": 0, "why": "The more reactive metal displaces the less reactive metal, not the other way around."}, "misconception": {"q": "Iron is more reactive than copper. Can copper displace iron from iron sulfate? Sam answers: “Yes, because all metals displace each other.” Explain why this is wrong.", "m": 2, "ms": ["No.", "The more reactive metal displaces the less reactive metal, not the other way around."]}, "more": [{"q": "Which metal is most reactive?", "opts": ["Iron.", "Gold.", "Potassium."], "a": 2, "why": "Potassium is at the top of the reactivity series."}, {"q": "What two things does iron need to rust?", "opts": ["Light and heat.", "Oxygen and water.", "Hydrogen and salt."], "a": 1, "why": "Rust forms when iron reacts with both."}, {"q": "Why is gold used for jewellery?", "opts": ["It is unreactive, so it does not tarnish.", "It is very reactive.", "It is magnetic."], "a": 0, "why": "Gold stays shiny for a long time."}, {"q": "Magnesium burns in oxygen to make…", "opts": ["magnesium chloride.", "hydrogen.", "magnesium oxide."], "a": 2, "why": "Metal + oxygen → metal oxide."}], "ladder": [{"q": "Name the product when copper reacts with oxygen.", "m": 1, "ms": ["Copper oxide."], "step": "Remember"}, {"q": "Give two properties that most metals share.", "m": 2, "ms": ["Good conductors of heat and electricity.", "Shiny / malleable / high melting point / strong."], "step": "Apply"}, {"q": "Explain two ways to stop an iron gate rusting.", "m": 3, "ms": ["Paint it / cover it in oil or grease / galvanise it with zinc.", "This keeps out oxygen and water.", "Without both, iron cannot rust."], "step": "Explain"}]}, {"key": "metal-acid", "title": "Metals reacting with acids", "notes": ["Many metals react with dilute acids. These reactions make a salt and hydrogen gas. More reactive metals usually react faster under the same conditions.", "The acid helps decide which salt forms. Hydrochloric acid makes a chloride. Sulfuric acid makes a sulfate.", "The test for hydrogen is a lit splint, which goes out with a squeaky pop. Very reactive metals such as sodium are not added to acids because the reaction is dangerous. Copper does not react with dilute acids."], "worked": "Magnesium and dilute sulfuric acid make magnesium sulfate and hydrogen. A small sample of hydrogen makes a squeaky pop with a lighted splint. Only test gases using your teacher's safety instructions.", "question": "What forms when magnesium reacts with dilute sulfuric acid? How would you test the gas safely in the lab?", "scheme": ["Magnesium sulfate forms.", "Hydrogen gas forms.", "A teacher-supervised test with a lighted splint gives a squeaky pop."], "mistake": "The salt name depends on the acid, not just the metal.", "model": null, "id": "y7-unit-12-metal-acid", "unit": "y7-unit-12", "year": 7, "number": 2, "marks": 3, "cards": [{"term": "Reactivity series", "definition": "A list of metals ordered by how readily they react."}, {"term": "Hydrogen test", "definition": "A small gas sample makes a squeaky pop with a lighted splint in a teacher-supervised test."}], "quiz": {"q": "What forms when magnesium reacts with dilute hydrochloric acid?", "opts": ["Only water.", "Magnesium chloride and hydrogen.", "Magnesium sulfate and oxygen."], "a": 1, "why": "A suitable metal and dilute acid make a salt and hydrogen gas."}, "misconception": {"q": "What forms when magnesium reacts with dilute hydrochloric acid? Sam answers: “Magnesium sulfate and oxygen.” Explain why this is wrong.", "m": 2, "ms": ["Magnesium chloride and hydrogen.", "A suitable metal and dilute acid make a salt and hydrogen gas."]}, "more": [{"q": "Which gas is made when magnesium reacts with hydrochloric acid?", "opts": ["Hydrogen.", "Oxygen.", "Carbon dioxide."], "a": 0, "why": "Metal + acid → salt + hydrogen."}, {"q": "What is the test for hydrogen?", "opts": ["It relights a glowing splint.", "It turns limewater milky.", "A lit splint gives a squeaky pop."], "a": 2, "why": "Hydrogen burns rapidly with a pop."}, {"q": "Which metal does NOT react with dilute acid?", "opts": ["Zinc.", "Copper.", "Magnesium."], "a": 1, "why": "Copper is below hydrogen in reactivity."}, {"q": "Zinc + sulfuric acid → ?", "opts": ["Zinc sulfate + hydrogen.", "Zinc chloride + water.", "Zinc oxide + hydrogen."], "a": 0, "why": "Sulfuric acid makes sulfates."}], "ladder": [{"q": "Name the salt made when magnesium reacts with hydrochloric acid.", "m": 1, "ms": ["Magnesium chloride."], "step": "Remember"}, {"q": "Complete the word equation: iron + hydrochloric acid → … + …", "m": 2, "ms": ["Iron chloride.", "Hydrogen."], "step": "Apply"}, {"q": "Describe how you could use acid to put magnesium, zinc and iron in order of reactivity.", "m": 3, "ms": ["Add the same mass/size of each metal to the same volume and concentration of acid.", "Observe or count the bubbles of hydrogen.", "The more quickly it fizzes, the more reactive the metal."], "step": "Explain"}]}, {"key": "charge", "title": "Static electricity", "notes": ["Electrons are tiny particles with a negative charge. Rubbing some materials moves electrons from one surface to another. An object that gains electrons becomes negatively charged.", "An object that loses electrons becomes positively charged. Like charges repel: they push apart. Opposite charges attract: they pull together.", "Like charges repel and opposite charges attract. A charged balloon can stick to a wall or attract small bits of paper. Static charge can build up and cause a spark when it jumps to a conductor."], "worked": "Two plastic rods both gain electrons when rubbed. Both rods are negatively charged. They repel because their charges are alike.", "question": "Two rods both gain electrons. Explain why they push away from each other.", "scheme": ["Electrons carry negative charge.", "Both rods become negatively charged.", "Like charges repel."], "mistake": "In these examples, electrons move. Positive charge does not move from one rod to another.", "model": null, "id": "y7-unit-13-charge", "unit": "y7-unit-13", "year": 7, "number": 1, "marks": 3, "cards": [{"term": "Electron", "definition": "A tiny particle with a negative electric charge."}, {"term": "Static charge", "definition": "A build-up of electric charge on an object."}], "quiz": {"q": "An insulating rod gains electrons. What charge does it have?", "opts": ["Always zero.", "Negative.", "Positive."], "a": 1, "why": "Electrons are negative, so gaining extra electrons makes the rod negatively charged."}, "misconception": {"q": "An insulating rod gains electrons. What charge does it have? Sam answers: “Positive.” Explain why this is wrong.", "m": 2, "ms": ["Negative.", "Electrons are negative, so gaining extra electrons makes the rod negatively charged."]}, "more": [{"q": "Two negatively charged balloons will…", "opts": ["repel each other.", "attract each other.", "do nothing."], "a": 0, "why": "Like charges repel."}, {"q": "When a rod becomes negative after rubbing, it has…", "opts": ["lost electrons.", "gained protons.", "gained electrons."], "a": 2, "why": "Only electrons move."}, {"q": "A positive and a negative charge will…", "opts": ["cancel and disappear.", "attract.", "repel."], "a": 1, "why": "Opposite charges attract."}, {"q": "Why do you sometimes get a small shock from a car door?", "opts": ["Static charge has built up and jumps as a spark.", "The car battery is leaking.", "The door is magnetic."], "a": 0, "why": "Charge flows to earth through you."}], "ladder": [{"q": "What type of charge does an electron have?", "m": 1, "ms": ["Negative."], "step": "Remember"}, {"q": "A balloon rubbed on hair becomes negative. Explain what happened to the hair.", "m": 2, "ms": ["Electrons moved from the hair to the balloon.", "The hair lost electrons, so it became positively charged."], "step": "Apply"}, {"q": "Explain why a charged balloon sticks to a wall.", "m": 3, "ms": ["The balloon is negatively charged.", "It repels electrons in the wall, leaving the wall surface positive.", "Opposite charges attract, so the balloon sticks."], "step": "Explain"}]}, {"key": "current", "title": "Electric current and circuits", "notes": ["An electric current is a flow of charge. A complete circuit is needed for a steady current. An ammeter measures current in amperes, A.", "Connect an ammeter in series: in the same path as the current. Current is the same all around a single series loop. At a junction, the current splits between branches. Circuit diagrams use standard symbols to show how parts are connected.", "In a series circuit, there is only one path, so the current is the same everywhere. In a parallel circuit, the current splits between branches. Adding more bulbs in series makes each one dimmer."], "worked": "Two parallel branches carry 0.4 A and 0.6 A. The current before the split is 0.4 + 0.6 = 1.0 A. The same total current returns after the branches join.", "question": "Two parallel branches carry 0.4 A and 0.6 A. Find the supply current and explain your method.", "scheme": ["Add the branch currents.", "0.4 + 0.6 = 1.0 A.", "The total current into a junction equals the total current out."], "mistake": "Current is not used up by a bulb.", "model": "circuit", "id": "y7-unit-13-current", "unit": "y7-unit-13", "year": 7, "number": 2, "marks": 3, "cards": [{"term": "Current", "definition": "The amount of electric charge flowing each second."}, {"term": "Ammeter", "definition": "An instrument connected in series to measure current."}], "quiz": {"q": "What happens to current at a junction?", "opts": ["Current is used up.", "Each branch always gets all the supply current.", "Total current in equals total current out."], "a": 2, "why": "Charge does not disappear. The branch currents add to the current before the split."}, "misconception": {"q": "What happens to current at a junction? Sam answers: “Current is used up.” Explain why this is wrong.", "m": 2, "ms": ["Total current in equals total current out.", "Charge does not disappear. The branch currents add to the current before the split."]}, "more": [{"q": "What does an ammeter measure?", "opts": ["Resistance.", "Current.", "Voltage."], "a": 1, "why": "Current is measured in amps."}, {"q": "In a series circuit, the current is…", "opts": ["the same everywhere.", "biggest near the battery.", "zero after each bulb."], "a": 0, "why": "There is only one path."}, {"q": "Why do bulbs in parallel stay bright when one breaks?", "opts": ["The current stops everywhere.", "Parallel bulbs have no current.", "Each branch is a separate complete path."], "a": 2, "why": "Other branches are still complete loops."}, {"q": "What happens when you add a second bulb in series?", "opts": ["Nothing changes.", "Both bulbs are dimmer.", "Both are brighter."], "a": 1, "why": "The total resistance increases, so current falls."}], "ladder": [{"q": "What is an electric current?", "m": 1, "ms": ["A flow of charge."], "step": "Remember"}, {"q": "A series circuit has a cell, a switch and two bulbs. Describe what happens when the switch is opened.", "m": 2, "ms": ["The circuit is broken/incomplete.", "No current flows, so both bulbs go out."], "step": "Apply"}, {"q": "Explain why the lights in a house are wired in parallel rather than series.", "m": 3, "ms": ["In parallel each light has its own complete path.", "One light can be switched off or fail without the others going out.", "Each light gets the full voltage, so it is bright."], "step": "Explain"}]}, {"key": "voltage", "title": "Voltage and resistance", "notes": ["Potential difference is also called voltage. It tells us the energy transferred by each coulomb of charge. Voltage is measured in volts, V.", "A voltmeter measures voltage across a component. Resistance describes how much a component limits the current. Resistance = voltage ÷ current, measured in ohms, Ω. A coulomb is a unit of electric charge. Voltages across parts of a series circuit add up to the supply voltage. Parallel branches across the same two points have the same voltage.", "A voltmeter is connected in parallel across a component. Resistance is measured in ohms, Ω. A bigger resistance means a smaller current for the same voltage: current = voltage ÷ resistance."], "worked": "A resistor has 12 V across it and a current of 2 A. Its resistance is 12 ÷ 2 = 6 Ω. Connect the voltmeter across the resistor, in parallel.", "question": "A resistor has 12 V across it and carries 2 A. Find its resistance. How should the voltmeter be connected?", "scheme": ["Use resistance = voltage ÷ current.", "12 ÷ 2 = 6 Ω.", "Connect the voltmeter in parallel across the resistor."], "mistake": "A voltmeter goes across a component, not in the same path as an ammeter.", "model": "circuit", "id": "y7-unit-14-voltage", "unit": "y7-unit-14", "year": 7, "number": 1, "marks": 3, "cards": [{"term": "Potential difference", "definition": "Energy transferred per coulomb (a unit of charge), also called voltage."}, {"term": "Resistance", "definition": "How much a component limits current; calculated as voltage divided by current."}, {"term": "Voltmeter", "definition": "An instrument connected across a component to measure voltage."}], "quiz": {"q": "How should you connect a voltmeter?", "opts": ["With only one lead connected.", "In parallel across a component.", "In series in place of a wire."], "a": 1, "why": "Voltage is measured between two points, so the voltmeter goes across the component."}, "misconception": {"q": "How should you connect a voltmeter? Sam answers: “In series in place of a wire.” Explain why this is wrong.", "m": 2, "ms": ["In parallel across a component.", "Voltage is measured between two points, so the voltmeter goes across the component."]}, "more": [{"q": "How is a voltmeter connected?", "opts": ["In parallel across the component.", "In series with the component.", "Across the switch only."], "a": 0, "why": "It compares energy on each side."}, {"q": "What is the unit of resistance?", "opts": ["Amp (A).", "Volt (V).", "Ohm (Ω)."], "a": 2, "why": "Resistance is measured in ohms."}, {"q": "A 6 V cell drives a current through a 3 Ω resistor. What is the current?", "opts": ["0.5 A.", "2 A.", "18 A."], "a": 1, "why": "I = V ÷ R = 6 ÷ 3."}, {"q": "Adding more cells in series increases the…", "opts": ["voltage.", "resistance.", "number of paths."], "a": 0, "why": "Each cell adds its voltage."}], "ladder": [{"q": "What unit is potential difference measured in?", "m": 1, "ms": ["Volts (V)."], "step": "Remember"}, {"q": "A 12 V battery is connected to a 4 Ω resistor. Calculate the current.", "m": 2, "ms": ["I = V ÷ R = 12 ÷ 4.", "= 3 A."], "step": "Apply"}, {"q": "Explain why a long thin wire has more resistance than a short thick one.", "m": 3, "ms": ["Resistance is opposition to the flow of charge.", "A longer wire gives electrons further to travel through the material.", "A thinner wire gives less space for electrons to flow, so there are more collisions."], "step": "Explain"}]}, {"key": "current", "title": "Electric current and circuits", "notes": ["An electric current is a flow of charge. A complete circuit is needed for a steady current. An ammeter measures current in amperes, A.", "Connect an ammeter in series: in the same path as the current. Current is the same all around a single series loop. At a junction, the current splits between branches. Circuit diagrams use standard symbols to show how parts are connected.", "In a series circuit, there is only one path, so the current is the same everywhere. In a parallel circuit, the current splits between branches. Adding more bulbs in series makes each one dimmer."], "worked": "Two parallel branches carry 0.4 A and 0.6 A. The current before the split is 0.4 + 0.6 = 1.0 A. The same total current returns after the branches join.", "question": "Two parallel branches carry 0.4 A and 0.6 A. Find the supply current and explain your method.", "scheme": ["Add the branch currents.", "0.4 + 0.6 = 1.0 A.", "The total current into a junction equals the total current out."], "mistake": "Current is not used up by a bulb.", "model": "circuit", "id": "y7-unit-14-current", "unit": "y7-unit-14", "year": 7, "number": 2, "marks": 3, "cards": [{"term": "Current", "definition": "The amount of electric charge flowing each second."}, {"term": "Ammeter", "definition": "An instrument connected in series to measure current."}], "quiz": {"q": "What happens to current at a junction?", "opts": ["Current is used up.", "Each branch always gets all the supply current.", "Total current in equals total current out."], "a": 2, "why": "Charge does not disappear. The branch currents add to the current before the split."}, "misconception": {"q": "What happens to current at a junction? Sam answers: “Current is used up.” Explain why this is wrong.", "m": 2, "ms": ["Total current in equals total current out.", "Charge does not disappear. The branch currents add to the current before the split."]}, "more": [{"q": "What does an ammeter measure?", "opts": ["Resistance.", "Current.", "Voltage."], "a": 1, "why": "Current is measured in amps."}, {"q": "In a series circuit, the current is…", "opts": ["the same everywhere.", "biggest near the battery.", "zero after each bulb."], "a": 0, "why": "There is only one path."}, {"q": "Why do bulbs in parallel stay bright when one breaks?", "opts": ["The current stops everywhere.", "Parallel bulbs have no current.", "Each branch is a separate complete path."], "a": 2, "why": "Other branches are still complete loops."}, {"q": "What happens when you add a second bulb in series?", "opts": ["Nothing changes.", "Both bulbs are dimmer.", "Both are brighter."], "a": 1, "why": "The total resistance increases, so current falls."}], "ladder": [{"q": "What is an electric current?", "m": 1, "ms": ["A flow of charge."], "step": "Remember"}, {"q": "A series circuit has a cell, a switch and two bulbs. Describe what happens when the switch is opened.", "m": 2, "ms": ["The circuit is broken/incomplete.", "No current flows, so both bulbs go out."], "step": "Apply"}, {"q": "Explain why the lights in a house are wired in parallel rather than series.", "m": 3, "ms": ["In parallel each light has its own complete path.", "One light can be switched off or fail without the others going out.", "Each light gets the full voltage, so it is bright."], "step": "Explain"}]}, {"key": "foodweb", "title": "Food chains and food webs", "notes": ["A food chain shows what eats what. A producer, such as a green plant, makes its own food. A consumer gets food by eating other living things.", "Arrows point from the food towards the eater. They show the direction energy is transferred. Several linked food chains make a food web. Other food sources and competition can change the outcome in a real food web.", "A food web shows many linked food chains. If one population changes, others in the web are affected. Toxic chemicals can build up along a food chain, harming top predators most."], "worked": "Consider algae → water flea → small fish. Fewer water fleas may mean less algae is eaten. Small fish may have less food and their numbers may fall.", "question": "In algae → water flea → small fish, what might happen to algae and fish if water flea numbers fall?", "scheme": ["Less algae may be eaten, so algae may increase.", "Fish have fewer water fleas to eat.", "Fish numbers may fall if they cannot find enough other food."], "mistake": "An arrow points towards the animal eating the food, not towards its food.", "model": "populations", "id": "y8-unit-01-foodweb", "unit": "y8-unit-01", "year": 8, "number": 1, "marks": 3, "cards": [{"term": "Producer", "definition": "A living thing that makes its own food, usually by photosynthesis."}, {"term": "Consumer", "definition": "A living thing that gets food by eating other living things."}, {"term": "Food web", "definition": "Several food chains linked together."}], "quiz": {"q": "Which way does an arrow point in a food chain?", "opts": ["From the eater towards its food.", "Always towards the producer.", "From the food towards the eater."], "a": 2, "why": "Arrows show the direction that energy passes through the chain."}, "misconception": {"q": "Which way does an arrow point in a food chain? Sam answers: “From the eater towards its food.” Explain why this is wrong.", "m": 2, "ms": ["From the food towards the eater.", "Arrows show the direction that energy passes through the chain."]}, "more": [{"q": "In the chain grass → rabbit → fox, the producer is…", "opts": ["fox.", "grass.", "rabbit."], "a": 1, "why": "Producers make their own food."}, {"q": "If foxes are removed, what will happen to rabbits at first?", "opts": ["Their number will increase.", "Their number will decrease.", "No change."], "a": 0, "why": "Fewer predators means more rabbits survive."}, {"q": "What do arrows in a food chain show?", "opts": ["Which animal is biggest.", "Where animals live.", "The direction energy (food) moves."], "a": 2, "why": "The arrow points to the eater."}, {"q": "A herbivore eats…", "opts": ["plants and animals.", "only plants.", "only animals."], "a": 1, "why": "Herbivores are primary consumers."}], "ladder": [{"q": "What is a consumer?", "m": 1, "ms": ["A living thing that gets its food by eating other living things."], "step": "Remember"}, {"q": "In grass → rabbit → fox, name the primary consumer and the top predator.", "m": 2, "ms": ["Primary consumer: rabbit.", "Top predator: fox."], "step": "Apply"}, {"q": "A disease kills most of the rabbits. Explain the effect on the grass and the foxes.", "m": 3, "ms": ["Fewer rabbits eat the grass, so the grass increases.", "Foxes have less food.", "So the fox population decreases (or foxes eat other prey)."], "step": "Explain"}]}, {"key": "ecosystem", "title": "Habitats, competition and quadrats", "notes": ["An ecosystem includes living things and their surroundings. Living things compete when they need the same limited resource. Plants may compete for light, water and space.", "A quadrat is a square frame used to count plants in a small area. Place it at random points so you do not choose only plant-rich patches. Use several samples to make a better estimate.", "A quadrat is a square frame used to count plants in an area. Placing quadrats randomly avoids choosing only the best spots. Multiply the mean number per quadrat to estimate the whole population."], "worked": "Five 1 m² quadrats contain 25 daisies in total. The mean is 25 ÷ 5 = 5 daisies per m². For a similar 100 m² field, estimate 5 × 100 = 500 daisies.", "question": "How could you use quadrats to estimate the number of daisies in a field?", "scheme": ["Place equal-sized quadrats at random points.", "Count daisies and calculate the mean number per square metre.", "Multiply by field area and say the answer is an estimate."], "mistake": "Choosing only places with lots of daisies will give an unfair estimate.", "model": "populations", "id": "y8-unit-01-ecosystem", "unit": "y8-unit-01", "year": 8, "number": 2, "marks": 3, "cards": [{"term": "Ecosystem", "definition": "Living things in an area and the surroundings they interact with."}, {"term": "Competition", "definition": "Living things needing the same limited resource."}, {"term": "Quadrat", "definition": "A frame marking a known area for counting plants or other organisms."}], "quiz": {"q": "Why place quadrats at random points?", "opts": ["To remove the need for repeats.", "To avoid choosing only patches that support your prediction.", "To make every count identical."], "a": 1, "why": "Random points reduce the effect of the person choosing where to count."}, "misconception": {"q": "Why place quadrats at random points? Sam answers: “To make every count identical.” Explain why this is wrong.", "m": 2, "ms": ["To avoid choosing only patches that support your prediction.", "Random points reduce the effect of the person choosing where to count."]}, "more": [{"q": "What do animals often compete for?", "opts": ["Food, water, space and mates.", "Light only.", "Carbon dioxide."], "a": 0, "why": "These resources are limited."}, {"q": "Why should quadrats be placed randomly?", "opts": ["To make the counting faster.", "So all quadrats land on plants.", "To avoid bias in choosing where to sample."], "a": 2, "why": "Random placement gives a fair sample."}, {"q": "A field is 100 m². Mean daisies per 1 m² quadrat is 4. Estimated daisies in the field?", "opts": ["25.", "400.", "104."], "a": 1, "why": "4 × 100 = 400."}, {"q": "What do plants compete for?", "opts": ["Light, water, space and minerals.", "Food from animals.", "Mates."], "a": 0, "why": "Plants make their own food but need these resources."}], "ladder": [{"q": "What is an ecosystem?", "m": 1, "ms": ["All the living things in an area and their surroundings."], "step": "Remember"}, {"q": "Quadrat counts of buttercups were 3, 5 and 4. The field is 50 m² and each quadrat is 1 m². Estimate the buttercup population.", "m": 2, "ms": ["Mean = (3 + 5 + 4) ÷ 3 = 4 per m².", "4 × 50 = 200 buttercups."], "step": "Apply"}, {"q": "Explain why weeds can reduce the growth of crop plants.", "m": 3, "ms": ["Weeds compete with the crop for the same resources.", "They take light, water, space and minerals.", "So less is available for the crop, which grows less."], "step": "Explain"}]}, {"key": "speed", "title": "Measuring and calculating speed", "notes": ["Speed tells you how far something travels each second. Average speed = total distance ÷ total time. Use metres and seconds to get metres per second, m/s.", "Measure a known distance and time the journey. Repeat the test and compare the readings. Electronic timing can reduce errors caused by reaction time.", "Speed can be measured in other units, such as km/h or mph. Typical speeds: walking about 1.5 m/s, cycling about 6 m/s, a car on a motorway about 30 m/s. To find the distance, use distance = speed × time."], "worked": "A trolley travels 1.8 m in 3 seconds. Average speed = 1.8 ÷ 3 = 0.6 m/s. This does not mean it had exactly that speed at every moment.", "question": "A trolley travels 2.4 m in 4 seconds. Find its average speed and suggest a way to improve timing.", "scheme": ["Use average speed = distance ÷ time.", "2.4 ÷ 4 = 0.6 m/s.", "Use electronic timing or time a longer distance to reduce the effect of reaction time."], "mistake": "Average speed describes the whole journey, not every moment of it.", "model": "race", "id": "y8-unit-02-speed", "unit": "y8-unit-02", "year": 8, "number": 1, "marks": 3, "cards": [{"term": "Average speed", "definition": "Total distance travelled divided by total time."}, {"term": "Repeat", "definition": "Taking another measurement using the same chosen conditions."}], "quiz": {"q": "A trolley travels 6 m in 3 seconds. What is its average speed?", "opts": ["2 m/s.", "18 m/s.", "0.5 m/s."], "a": 0, "why": "Average speed = 6 ÷ 3 = 2 m/s."}, "misconception": {"q": "A trolley travels 6 m in 3 seconds. What is its average speed? Sam answers: “18 m/s.” Explain why this is wrong.", "m": 2, "ms": ["2 m/s.", "Average speed = 6 ÷ 3 = 2 m/s."]}, "more": [{"q": "A car travels 200 m in 10 s. What is its average speed?", "opts": ["2000 m/s.", "0.05 m/s.", "20 m/s."], "a": 2, "why": "200 ÷ 10 = 20 m/s."}, {"q": "Which is a typical walking speed?", "opts": ["150 m/s.", "1.5 m/s.", "15 m/s."], "a": 1, "why": "People walk about 1–2 m/s."}, {"q": "A cyclist moves at 5 m/s for 60 s. How far does she travel?", "opts": ["300 m.", "12 m.", "65 m."], "a": 0, "why": "5 × 60 = 300 m."}, {"q": "Why is it called average speed?", "opts": ["It is always the top speed.", "It ignores distance.", "Speed can change during the journey."], "a": 2, "why": "It is the overall speed for the whole trip."}], "ladder": [{"q": "Write the equation linking speed, distance and time.", "m": 1, "ms": ["Speed = distance ÷ time."], "step": "Remember"}, {"q": "A runner covers 400 m in 80 s. Calculate her average speed.", "m": 2, "ms": ["400 ÷ 80.", "= 5 m/s."], "step": "Apply"}, {"q": "Describe how to measure the average speed of a toy car rolling across the floor.", "m": 3, "ms": ["Measure the distance between two marks with a metre ruler/tape.", "Time how long the car takes to travel between the marks with a stopwatch.", "Divide distance by time, and repeat to find a mean."], "step": "Explain"}]}, {"key": "dt", "title": "Distance–time graphs", "notes": ["A distance–time graph shows how far an object has travelled. Time goes on the horizontal axis. Distance goes on the vertical axis.", "A horizontal line means the object has stopped. A steeper straight line means a greater speed. Speed = change in distance ÷ change in time.", "The steeper the line on a distance–time graph, the faster the object is moving. A straight sloping line means a steady speed. Speed = distance ÷ time, so you can read both values from the graph."], "worked": "A line goes from 3 m at 2 s to 15 m at 8 s. The changes are 12 m and 6 s. Speed = 12 ÷ 6 = 2 m/s.", "question": "A graph line goes from 10 m at 5 s to 40 m at 15 s. Find the speed.", "scheme": ["Distance change = 40 − 10 = 30 m.", "Time change = 15 − 5 = 10 s.", "Speed = 30 ÷ 10 = 3 m/s."], "mistake": "A graph line is not the shape of the road. A rising line can show a steady speed.", "model": "race", "id": "y8-unit-02-dt", "unit": "y8-unit-02", "year": 8, "number": 2, "marks": 3, "cards": [{"term": "Gradient", "definition": "The steepness of a graph line, found from vertical change divided by horizontal change."}, {"term": "Distance–time graph", "definition": "A graph showing distance travelled as time passes."}], "quiz": {"q": "What does a horizontal distance–time line show?", "opts": ["The object is stationary.", "The object is speeding up.", "The object is travelling uphill."], "a": 0, "why": "Time passes but distance does not change, so the object is not moving."}, "misconception": {"q": "What does a horizontal distance–time line show? Sam answers: “The object is speeding up.” Explain why this is wrong.", "m": 2, "ms": ["The object is stationary.", "Time passes but distance does not change, so the object is not moving."]}, "more": [{"q": "A horizontal line on a distance–time graph shows the object is…", "opts": ["moving at a steady speed.", "speeding up.", "stationary (not moving)."], "a": 2, "why": "Distance is not changing."}, {"q": "A steeper line means…", "opts": ["the object is stopped.", "a faster speed.", "a slower speed."], "a": 1, "why": "More distance in the same time."}, {"q": "A straight line goes from 0 m to 60 m in 12 s. What is the speed?", "opts": ["5 m/s.", "720 m/s.", "0.2 m/s."], "a": 0, "why": "60 ÷ 12 = 5 m/s."}, {"q": "A curved line getting steeper shows the object is…", "opts": ["slowing down.", "at rest.", "speeding up."], "a": 2, "why": "Speed increases as the slope increases."}], "ladder": [{"q": "What does the gradient (slope) of a distance–time graph show?", "m": 1, "ms": ["The speed."], "step": "Remember"}, {"q": "A graph shows 100 m travelled in 20 s, then a flat line for 10 s. Describe the motion.", "m": 2, "ms": ["First it moves at a steady speed of 100 ÷ 20 = 5 m/s.", "Then it stops (stationary) for 10 s."], "step": "Apply"}, {"q": "Two cyclists’ lines start at the origin; line A is steeper than line B. Explain what this tells you.", "m": 3, "ms": ["Cyclist A covers more distance in the same time.", "So A is moving faster than B.", "Both are moving at a steady speed because the lines are straight."], "step": "Explain"}]}, {"key": "data", "title": "Tables, graphs and conclusions", "notes": ["Put measurements in a results table. Label each column with the quantity and its unit. A graph helps you spot a pattern.", "Use a line graph for measurements such as time and temperature. Use a bar chart for separate groups, such as different materials. A conclusion answers your question using your results.", "Plot the independent variable on the x-axis and the dependent variable on the y-axis. Draw a line or curve of best fit through the points. Do not join the dots with a ruler."], "worked": "Suppose sugar dissolves in 40 seconds in cool water and 20 seconds in warm water. The warmer water gave a shorter dissolving time. Use these numbers as evidence in your conclusion.", "question": "What graph would show water temperature and sugar dissolving time? How would you write a good conclusion?", "scheme": ["Use a line or scatter graph with temperature on the horizontal axis.", "Put dissolving time on the vertical axis and label both units.", "Describe the pattern and use numbers from the results."], "mistake": "A conclusion needs evidence. Do not just say your prediction was right.", "model": null, "id": "y8-unit-02-data", "unit": "y8-unit-02", "year": 8, "number": 3, "marks": 3, "cards": [{"term": "Continuous data", "definition": "Measurements with values anywhere within a range, such as height."}, {"term": "Discrete data", "definition": "Separate counts or values, such as the number of leaves."}, {"term": "Conclusion", "definition": "An answer to your test question, supported by your results."}], "quiz": {"q": "What makes a good conclusion?", "opts": ["Describe a pattern and use numbers from the results.", "Choose your favourite result and ignore the others.", "Leave units off the graph."], "a": 0, "why": "Numbers from the results give evidence for the pattern you describe."}, "misconception": {"q": "What makes a good conclusion? Sam answers: “Choose your favourite result and ignore the others.” Explain why this is wrong.", "m": 2, "ms": ["Describe a pattern and use numbers from the results.", "Numbers from the results give evidence for the pattern you describe."]}, "more": [{"q": "Which axis should show the independent variable?", "opts": ["The y-axis (vertical).", "Either axis, it does not matter.", "The x-axis (horizontal)."], "a": 2, "why": "By convention, the variable you change goes along the bottom."}, {"q": "What is a line of best fit?", "opts": ["A line through the first and last points only.", "A smooth line or curve that passes close to most points.", "A line joining every point dot-to-dot."], "a": 1, "why": "It shows the overall pattern."}, {"q": "Which graph type suits \"number of students with each eye colour\"?", "opts": ["Bar chart.", "Line graph.", "Scatter graph with a curve."], "a": 0, "why": "Eye colour is a category, so use a bar chart."}, {"q": "A table heading should include…", "opts": ["only the unit.", "nothing; numbers are enough.", "the quantity and its unit, e.g. Time (s)."], "a": 2, "why": "Units belong in the heading, not after each number."}], "ladder": [{"q": "What does a line of best fit show?", "m": 1, "ms": ["The overall pattern/trend in the results."], "step": "Remember"}, {"q": "A table has the heading \"Temperature\" and values 20, 40, 60. Give two ways to improve it.", "m": 2, "ms": ["Add the unit to the heading, e.g. Temperature (°C).", "Add a column for the measured (dependent) variable / repeats and a mean."], "step": "Apply"}, {"q": "Explain how to plot a line graph of time against temperature.", "m": 3, "ms": ["Put temperature (independent) on the x-axis and time on the y-axis.", "Choose even scales that use most of the grid and label axes with units.", "Plot points accurately and draw a smooth line of best fit."], "step": "Explain"}]}, {"key": "force", "title": "Forces and movement", "notes": ["A force is a push or pull, measured in newtons, N. Friction is a contact force. Gravity acts without objects touching.", "The resultant force is the overall force after combining all the forces. Balanced forces do not change an object's speed or direction. Unbalanced forces change speed, direction or both. An increase in speed is called acceleration.", "Balanced forces mean the resultant force is zero: a still object stays still and a moving object keeps the same speed. Unbalanced forces change speed or direction. Force arrows show size and direction."], "worked": "A trolley has a 9 N push right and a 4 N force left. The resultant is 9 − 4 = 5 N right. With balanced forces, it could stay still or move steadily.", "question": "A boat has a 120 N push forwards and 80 N drag backwards. Find the resultant and describe its effect.", "scheme": ["120 − 80 = 40 N.", "The resultant acts forwards.", "The boat accelerates forwards."], "mistake": "An object can move at a steady speed while forces are balanced.", "model": null, "id": "y8-unit-03-force", "unit": "y8-unit-03", "year": 8, "number": 1, "marks": 3, "cards": [{"term": "Resultant force", "definition": "The overall force after combining all forces and their directions."}, {"term": "Balanced forces", "definition": "Forces that cancel out to give zero overall force."}], "quiz": {"q": "What can an object do when its forces are balanced?", "opts": ["Stay still or move steadily in a straight line.", "Always speed up.", "Only stay still."], "a": 0, "why": "Balanced forces do not change speed or direction. An object can already be moving."}, "misconception": {"q": "What can an object do when its forces are balanced? Sam answers: “Always speed up.” Explain why this is wrong.", "m": 2, "ms": ["Stay still or move steadily in a straight line.", "Balanced forces do not change speed or direction. An object can already be moving."]}, "more": [{"q": "Forces of 10 N right and 4 N left act on a box. What is the resultant force?", "opts": ["14 N to the right.", "6 N to the left.", "6 N to the right."], "a": 2, "why": "10 − 4 = 6 N towards the bigger force."}, {"q": "If forces on a moving object are balanced, it…", "opts": ["speeds up.", "keeps moving at the same speed.", "stops immediately."], "a": 1, "why": "Zero resultant force means no change in motion."}, {"q": "Which is a non-contact force?", "opts": ["Gravity.", "Friction.", "Air resistance."], "a": 0, "why": "Gravity acts at a distance."}, {"q": "What is the unit of force?", "opts": ["Kilogram (kg).", "Joule (J).", "Newton (N)."], "a": 2, "why": "Forces are measured in newtons."}], "ladder": [{"q": "What is the resultant force?", "m": 1, "ms": ["The overall force when all the forces are combined."], "step": "Remember"}, {"q": "A rocket has 5000 N thrust upwards and 3000 N weight. Calculate the resultant force and state what happens.", "m": 2, "ms": ["5000 − 3000 = 2000 N upwards.", "The rocket speeds up upwards."], "step": "Apply"}, {"q": "A car moves at a steady 30 m/s on a straight road. Explain what this tells you about the forces on it.", "m": 3, "ms": ["The car’s speed and direction are not changing.", "So the forces are balanced.", "The driving force equals the friction and air resistance."], "step": "Explain"}]}, {"key": "gravity", "title": "Mass, weight and falling", "notes": ["Mass is the amount of matter in an object, measured in kilograms. Weight is the force of gravity on an object, measured in newtons. Mass stays the same on different planets, but weight can change.", "A falling object's weight acts downwards. Air resistance, also called drag, acts upwards. Drag increases as the object falls faster.", "Weight = mass × gravitational field strength. On Earth, g is about 10 N/kg. On the Moon g is about 1.6 N/kg, so you weigh less but your mass is the same."], "worked": "A skydiver speeds up just after jumping. As drag grows, it can become equal to weight. The balanced forces give a steady falling speed, called terminal velocity.", "question": "Why can a falling skydiver reach a steady speed?", "scheme": ["Weight acts downwards and drag acts upwards.", "Drag grows until it equals weight.", "The forces balance, so the skydiver stops speeding up."], "mistake": "Steady falling speed does not mean there are no forces.", "model": null, "id": "y8-unit-03-gravity", "unit": "y8-unit-03", "year": 8, "number": 2, "marks": 3, "cards": [{"term": "Mass", "definition": "The amount of matter in an object, measured in kilograms."}, {"term": "Weight", "definition": "The force of gravity on an object, measured in newtons."}, {"term": "Terminal velocity", "definition": "Steady falling speed reached when weight and drag balance."}], "quiz": {"q": "At terminal velocity, how do drag and weight compare?", "opts": ["Drag is zero.", "Weight has disappeared.", "They are equal in size and opposite in direction."], "a": 2, "why": "Balanced forces mean the falling object stops speeding up."}, "misconception": {"q": "At terminal velocity, how do drag and weight compare? Sam answers: “Drag is zero.” Explain why this is wrong.", "m": 2, "ms": ["They are equal in size and opposite in direction.", "Balanced forces mean the falling object stops speeding up."]}, "more": [{"q": "A 50 kg student on Earth (g = 10 N/kg) has a weight of…", "opts": ["5 N.", "500 N.", "50 N."], "a": 1, "why": "W = 50 × 10."}, {"q": "On the Moon, your mass would…", "opts": ["stay the same.", "decrease.", "increase."], "a": 0, "why": "Mass is the amount of matter."}, {"q": "Weight is measured with…", "opts": ["a balance in kg.", "a ruler.", "a newtonmeter (force meter)."], "a": 2, "why": "Weight is a force."}, {"q": "Why do you weigh less on the Moon?", "opts": ["There is no air.", "The Moon’s gravitational field strength is smaller.", "You lose mass in space."], "a": 1, "why": "g on the Moon is about 1.6 N/kg."}], "ladder": [{"q": "What is weight?", "m": 1, "ms": ["The force of gravity on an object."], "step": "Remember"}, {"q": "An astronaut has a mass of 80 kg. Calculate her weight on the Moon, where g = 1.6 N/kg.", "m": 2, "ms": ["W = m × g = 80 × 1.6.", "= 128 N."], "step": "Apply"}, {"q": "Explain why a bag of sugar has the same mass on Earth and the Moon but a different weight.", "m": 3, "ms": ["Mass is the amount of matter, which does not change.", "Weight depends on the gravitational field strength.", "The Moon’s field is weaker, so the weight is smaller."], "step": "Explain"}]}, {"key": "crater", "title": "Investigating craters", "notes": ["A dropped ball can make a crater in a tray of flour. The crater models a mark made by an object hitting a surface. A model helps us test an idea, but it is not an exact copy.", "Change one thing, such as drop height. Measure crater width. Keep the ball and the depth and type of flour the same.", "Dropping a ball from a greater height gives it more kinetic energy when it lands. It usually makes a wider, deeper crater. Real meteorite craters are much bigger because meteorites travel very fast."], "worked": "Drop the same ball from several measured heights. Level the flour between drops and repeat each height. Compare the mean crater width for each height.", "question": "For a ball-and-flour crater test, name what you change and measure. Give one way it differs from a real impact.", "scheme": ["Change drop height and measure crater width.", "Keep the ball or flour conditions the same.", "A classroom ball and flour do not exactly match a fast space rock and a planet's surface."], "mistake": "A model can be useful without matching every part of a real event.", "model": null, "id": "y8-unit-03-crater", "unit": "y8-unit-03", "year": 8, "number": 3, "marks": 3, "cards": [{"term": "Model", "definition": "A simpler version of something, used to explore an idea."}, {"term": "Control variable", "definition": "Something kept the same to make a test fair."}], "quiz": {"q": "When testing drop height and crater size, what should stay the same?", "opts": ["Nothing.", "The ball and the type and depth of the surface material.", "Drop height."], "a": 1, "why": "Keeping the ball and surface the same helps show the effect of drop height."}, "misconception": {"q": "When testing drop height and crater size, what should stay the same? Sam answers: “Drop height.” Explain why this is wrong.", "m": 2, "ms": ["The ball and the type and depth of the surface material.", "Keeping the ball and surface the same helps show the effect of drop height."]}, "more": [{"q": "In the crater test, what is the independent variable if you change the drop height?", "opts": ["Drop height.", "Crater width.", "Mass of flour."], "a": 0, "why": "You choose the height."}, {"q": "Dropping from higher usually makes the crater…", "opts": ["smaller.", "disappear.", "wider."], "a": 2, "why": "The ball has more energy when it lands."}, {"q": "Why use the same ball each time?", "opts": ["To change the results.", "To keep its mass and size the same (fair test).", "To make it bounce."], "a": 1, "why": "Changing the ball adds another variable."}, {"q": "Why is flour a model for the Moon’s surface?", "opts": ["It is soft and shows marks clearly.", "It is made of moon rock.", "It is the same colour as space."], "a": 0, "why": "A model is simpler and safe to use."}], "ladder": [{"q": "What is a model in science?", "m": 1, "ms": ["A simpler version of something real used to test or explain ideas."], "step": "Remember"}, {"q": "Give two control variables in the crater experiment.", "m": 2, "ms": ["Same ball (mass/size).", "Same depth and type of flour / smoothing the surface the same way each time."], "step": "Apply"}, {"q": "Explain why the crater gets bigger when the ball is dropped from higher.", "m": 3, "ms": ["The ball gains more speed as it falls further.", "It has more kinetic energy when it hits the flour.", "More energy pushes more flour aside, making a bigger crater."], "step": "Explain"}]}, {"key": "atoms", "title": "Atoms, elements, compounds and mixtures", "notes": ["An atom is a tiny building block of matter. An element contains only one type of atom. Iron and oxygen are elements.", "A compound has different elements chemically joined together. A mixture contains substances that are not chemically joined to each other. Mixtures can often be separated using physical methods.", "Chemical formulae show which atoms are joined, for example H₂O has two hydrogen atoms and one oxygen atom. A compound's properties can be very different from its elements. Mixtures can be separated by physical methods."], "worked": "Water is a compound of hydrogen and oxygen. Salt water is a mixture of salt and water. You can collect the water from salt water by distillation.", "question": "Use water and salt water to explain the difference between a compound and a mixture.", "scheme": ["Water contains hydrogen and oxygen chemically joined.", "Salt water contains salt mixed with water without a new compound forming.", "The substances in salt water can be separated by physical methods."], "mistake": "A mixture is not the same as a compound.", "model": null, "id": "y8-unit-04-atoms", "unit": "y8-unit-04", "year": 8, "number": 1, "marks": 3, "cards": [{"term": "Element", "definition": "A substance containing just one type of atom."}, {"term": "Compound", "definition": "A substance with different elements chemically joined in a fixed ratio."}, {"term": "Mixture", "definition": "Substances together without being chemically joined to each other."}], "quiz": {"q": "Which substance is a compound?", "opts": ["Air.", "Iron.", "Pure water."], "a": 2, "why": "Water contains hydrogen and oxygen atoms chemically joined together."}, "misconception": {"q": "Which substance is a compound? Sam answers: “Air.” Explain why this is wrong.", "m": 2, "ms": ["Pure water.", "Water contains hydrogen and oxygen atoms chemically joined together."]}, "more": [{"q": "Which is a compound?", "opts": ["Iron, Fe.", "Water, H₂O.", "Oxygen, O₂."], "a": 1, "why": "Water has two different elements chemically joined."}, {"q": "Air is…", "opts": ["a mixture.", "an element.", "a compound."], "a": 0, "why": "Air contains different gases that are not joined."}, {"q": "How many atoms are in CO₂?", "opts": ["2.", "1.", "3."], "a": 2, "why": "One carbon atom and two oxygen atoms."}, {"q": "Sodium is a reactive metal and chlorine is a toxic gas. Sodium chloride is…", "opts": ["a mixture of the two.", "table salt, which is safe to eat in small amounts.", "also a toxic gas."], "a": 1, "why": "A compound can have very different properties from its elements."}], "ladder": [{"q": "What is an element?", "m": 1, "ms": ["A substance made of only one type of atom."], "step": "Remember"}, {"q": "State the number of each type of atom in H₂SO₄.", "m": 2, "ms": ["2 hydrogen and 1 sulfur.", "4 oxygen."], "step": "Apply"}, {"q": "Explain the difference between a mixture of iron and sulfur and the compound iron sulfide.", "m": 3, "ms": ["In the mixture the atoms are not chemically joined.", "The mixture can be separated, e.g. with a magnet.", "In iron sulfide they are chemically joined, so a magnet cannot separate them."], "step": "Explain"}]}, {"key": "elements", "title": "Symbols and chemical formulae", "notes": ["Each element has a chemical symbol, such as O for oxygen. The first letter is a capital. Some symbols have a second, lower-case letter, such as Mg.", "A chemical formula shows which atoms make up a substance. Small numbers show how many atoms of an element are present. No small number means one atom.", "Chemical formulae use small numbers after a symbol to show how many atoms there are, as in CO₂. Some elements exist as molecules, like O₂. There are about 118 known elements."], "worked": "CO₂ means one carbon atom joined to two oxygen atoms. It is the formula for carbon dioxide. A mixture of carbon and oxygen is different because they are not joined in this way.", "question": "What does CO₂ mean? How is it different from a mixture of carbon and oxygen?", "scheme": ["CO₂ has one carbon atom and two oxygen atoms in each molecule.", "These atoms are chemically joined.", "In a mixture, carbon and oxygen are not joined to each other as carbon dioxide."], "mistake": "Co and CO are different. Capital letters matter in chemical symbols.", "model": null, "id": "y8-unit-04-elements", "unit": "y8-unit-04", "year": 8, "number": 2, "marks": 3, "cards": [{"term": "Chemical symbol", "definition": "The one- or two-letter label for an element."}, {"term": "Chemical formula", "definition": "Symbols and numbers showing the atoms in a substance."}], "quiz": {"q": "What does CO₂ show?", "opts": ["A mixture of separate carbon and oxygen.", "One carbon atom joined to two oxygen atoms.", "Two carbon atoms joined to one oxygen atom."], "a": 1, "why": "The small 2 refers to oxygen. No number after C means one carbon atom."}, "misconception": {"q": "What does CO₂ show? Sam answers: “Two carbon atoms joined to one oxygen atom.” Explain why this is wrong.", "m": 2, "ms": ["One carbon atom joined to two oxygen atoms.", "The small 2 refers to oxygen. No number after C means one carbon atom."]}, "more": [{"q": "What is the symbol for sodium?", "opts": ["Na.", "So.", "S."], "a": 0, "why": "It comes from the Latin name natrium."}, {"q": "How many oxygen atoms are in CO₂?", "opts": ["1.", "3.", "2."], "a": 2, "why": "The small 2 is after O."}, {"q": "Which is correctly written?", "opts": ["mg.", "Mg.", "MG."], "a": 1, "why": "First letter capital, second lower case."}, {"q": "What does the formula NaCl show?", "opts": ["One sodium atom joined to one chlorine atom.", "Two sodium atoms.", "A mixture of nitrogen and chlorine."], "a": 0, "why": "It is sodium chloride."}], "ladder": [{"q": "What is the chemical symbol for iron?", "m": 1, "ms": ["Fe."], "step": "Remember"}, {"q": "Name the elements in CaCO₃ and how many atoms of each.", "m": 2, "ms": ["Calcium 1, carbon 1.", "Oxygen 3."], "step": "Apply"}, {"q": "Explain the difference between O₂ and 2O.", "m": 3, "ms": ["O₂ is one molecule of two oxygen atoms joined together.", "2O means two separate oxygen atoms.", "In O₂ the atoms are chemically bonded; in 2O they are not."], "step": "Explain"}]}, {"key": "metals", "title": "Metals and reactivity", "notes": ["Metals usually conduct heat and electricity well. Many metals react with oxygen to make metal oxides. Gaining oxygen is called oxidation.", "Some metals react more easily than others. A more reactive metal can replace a less reactive metal in a compound. This is called displacement. Most metals can be shaped without breaking. Some non-metals are exceptions to the usual rules: graphite conducts electricity.", "The reactivity series lists metals from most to least reactive, for example potassium, sodium, calcium, magnesium, zinc, iron, copper, gold. Iron rusts when it reacts with oxygen and water. Gold does not react, so it stays shiny."], "worked": "Zinc is more reactive than copper. Zinc placed in copper sulfate solution can form zinc sulfate. Copper is left as a solid.", "question": "Zinc is more reactive than copper. What happens when zinc is put in copper sulfate solution? Explain why.", "scheme": ["Zinc displaces copper.", "Zinc sulfate and copper form.", "Zinc replaces copper because it is more reactive."], "mistake": "A less reactive metal cannot simply displace a more reactive one.", "model": null, "id": "y8-unit-04-metals", "unit": "y8-unit-04", "year": 8, "number": 3, "marks": 3, "cards": [{"term": "Displacement", "definition": "A more reactive element replacing a less reactive element in a compound."}, {"term": "Oxidation", "definition": "A reaction in which a substance gains oxygen, in these examples."}], "quiz": {"q": "Iron is more reactive than copper. Can copper displace iron from iron sulfate?", "opts": ["Yes, because copper is coloured.", "No.", "Yes, because all metals displace each other."], "a": 1, "why": "The more reactive metal displaces the less reactive metal, not the other way around."}, "misconception": {"q": "Iron is more reactive than copper. Can copper displace iron from iron sulfate? Sam answers: “Yes, because all metals displace each other.” Explain why this is wrong.", "m": 2, "ms": ["No.", "The more reactive metal displaces the less reactive metal, not the other way around."]}, "more": [{"q": "Which metal is most reactive?", "opts": ["Potassium.", "Iron.", "Gold."], "a": 0, "why": "Potassium is at the top of the reactivity series."}, {"q": "What two things does iron need to rust?", "opts": ["Hydrogen and salt.", "Light and heat.", "Oxygen and water."], "a": 2, "why": "Rust forms when iron reacts with both."}, {"q": "Why is gold used for jewellery?", "opts": ["It is magnetic.", "It is unreactive, so it does not tarnish.", "It is very reactive."], "a": 1, "why": "Gold stays shiny for a long time."}, {"q": "Magnesium burns in oxygen to make…", "opts": ["magnesium oxide.", "magnesium chloride.", "hydrogen."], "a": 0, "why": "Metal + oxygen → metal oxide."}], "ladder": [{"q": "Name the product when copper reacts with oxygen.", "m": 1, "ms": ["Copper oxide."], "step": "Remember"}, {"q": "Give two properties that most metals share.", "m": 2, "ms": ["Good conductors of heat and electricity.", "Shiny / malleable / high melting point / strong."], "step": "Apply"}, {"q": "Explain two ways to stop an iron gate rusting.", "m": 3, "ms": ["Paint it / cover it in oil or grease / galvanise it with zinc.", "This keeps out oxygen and water.", "Without both, iron cannot rust."], "step": "Explain"}]}, {"key": "polymer", "title": "Polymers and useful materials", "notes": ["A polymer has very long molecules made from repeating small parts. Many plastics are polymers. Different polymers have different useful properties.", "Choose a material to suit the job. A cable coating must be flexible and an electrical insulator. Think about waste, reuse and recycling as well as usefulness. Starch and cellulose are natural polymers. A polymer is not automatically biodegradable or easy to recycle.", "Natural polymers include cotton, wool and rubber. Synthetic polymers such as polythene are made in factories. Ceramics are hard and heatproof; composites combine materials, like carbon fibre, to get better properties."], "worked": "A plastic coating stops your hand touching the conducting wire. It bends with the cable. If it is not recycled, it may remain as waste for a long time.", "question": "Give a useful polymer property for a cable coating and explain it. Give one environmental problem to consider.", "scheme": ["It should be an electrical insulator or flexible.", "Insulation protects users, or flexibility lets the cable bend.", "Some plastics are difficult to recycle or break down very slowly."], "mistake": "Not all polymers have the same properties or can be recycled in the same way.", "model": null, "id": "y8-unit-04-polymer", "unit": "y8-unit-04", "year": 8, "number": 4, "marks": 3, "cards": [{"term": "Polymer", "definition": "A substance made of long molecules with repeating small parts."}, {"term": "Biodegradable", "definition": "Able to be broken down by living things such as microorganisms in suitable conditions."}], "quiz": {"q": "Which statement about polymers is correct?", "opts": ["Different polymers have different useful properties.", "Every polymer is the same material.", "Every polymer breaks down quickly in soil."], "a": 0, "why": "Choose a polymer whose properties suit the job, such as a flexible electrical insulator."}, "misconception": {"q": "Which statement about polymers is correct? Sam answers: “Every polymer is the same material.” Explain why this is wrong.", "m": 2, "ms": ["Different polymers have different useful properties.", "Choose a polymer whose properties suit the job, such as a flexible electrical insulator."]}, "more": [{"q": "Which is a natural polymer?", "opts": ["Polythene.", "PVC.", "Wool."], "a": 2, "why": "Wool comes from sheep."}, {"q": "Why are plastics used for electrical cable covers?", "opts": ["They are magnetic.", "They are good electrical insulators.", "They conduct electricity well."], "a": 1, "why": "Insulators stop current reaching your hand."}, {"q": "A problem with many plastics is that they…", "opts": ["do not rot easily and cause litter.", "are too heavy.", "dissolve in rain."], "a": 0, "why": "Most are not biodegradable."}, {"q": "Which material is a ceramic?", "opts": ["A plastic bag.", "A copper wire.", "A china plate."], "a": 2, "why": "Ceramics are hard, brittle and heat-resistant."}], "ladder": [{"q": "What is a polymer?", "m": 1, "ms": ["A substance with very long molecules made from many repeating units."], "step": "Remember"}, {"q": "Give two useful properties of plastics.", "m": 2, "ms": ["Light / flexible / easy to shape.", "Waterproof / electrical insulator / strong."], "step": "Apply"}, {"q": "Explain why a bike frame might be made from carbon fibre rather than steel.", "m": 3, "ms": ["Carbon fibre is a composite.", "It is very strong but much lighter than steel.", "A lighter bike needs less energy to ride fast."], "step": "Explain"}]}, {"key": "periodic", "title": "Using the periodic table", "notes": ["The periodic table organises the elements. Each box gives an element's symbol. A group is a vertical column.", "A period is a horizontal row. Elements in a group often have similar chemical properties. These patterns help us predict how an element may react. Elements are ordered by atomic number: the number of protons in each atom. Metals are mostly on the left and centre, and non-metals mostly on the right.", "Metals are on the left and in the middle of the periodic table; non-metals are on the right. Elements in the same group react in similar ways. Atomic number tells you the order of the elements."], "worked": "Lithium and sodium are both in Group 1. Both react with water to make hydrogen. Their shared group helps us spot a pattern.", "question": "What is a group in the periodic table? Why is grouping elements useful?", "scheme": ["A group is a vertical column.", "Elements in a group often have similar chemical properties.", "You can use the pattern to predict reactions or properties."], "mistake": "Elements in a group are similar, but they are not identical.", "model": null, "id": "y8-unit-05-periodic", "unit": "y8-unit-05", "year": 8, "number": 1, "marks": 3, "cards": [{"term": "Group", "definition": "A vertical column of the periodic table."}, {"term": "Period", "definition": "A horizontal row of the periodic table."}], "quiz": {"q": "Why is a periodic-table group useful?", "opts": ["Every element in it has exactly the same mass.", "Its elements are all the same substance.", "Its elements often have similar chemical properties."], "a": 2, "why": "Group patterns help predict properties and reactions."}, "misconception": {"q": "Why is a periodic-table group useful? Sam answers: “Every element in it has exactly the same mass.” Explain why this is wrong.", "m": 2, "ms": ["Its elements often have similar chemical properties.", "Group patterns help predict properties and reactions."]}, "more": [{"q": "Where are most metals found in the periodic table?", "opts": ["Only in the top row.", "On the left and in the middle.", "On the far right."], "a": 1, "why": "Non-metals are on the right."}, {"q": "A vertical column is called…", "opts": ["a group.", "a period.", "a block."], "a": 0, "why": "Groups have similar properties."}, {"q": "Elements in the same group…", "opts": ["are always gases.", "have the same mass.", "have similar chemical properties."], "a": 2, "why": "They react in similar ways."}, {"q": "Which element is a non-metal?", "opts": ["Iron.", "Sulfur.", "Sodium."], "a": 1, "why": "Sulfur is on the right of the table."}], "ladder": [{"q": "What is a period in the periodic table?", "m": 1, "ms": ["A horizontal row."], "step": "Remember"}, {"q": "Lithium and potassium are in Group 1. Predict one way potassium reacts like lithium.", "m": 2, "ms": ["It reacts with water.", "It makes an alkaline solution and hydrogen / fizzes and moves on the surface."], "step": "Apply"}, {"q": "Explain how the periodic table helps scientists predict properties of an element.", "m": 3, "ms": ["Elements in the same group have similar properties.", "Metals and non-metals are in different areas.", "So the position tells you whether it is likely to be a reactive metal, a non-metal, etc."], "step": "Explain"}]}, {"key": "groups", "title": "Groups 1, 7 and 0", "notes": ["Group 1 contains reactive metals such as lithium and sodium. Group 7 contains non-metals called halogens. Group 0 contains noble gases that rarely react.", "Group 1 metals get more reactive down the group. Group 7 halogens get less reactive down the group. A more reactive halogen can displace a less reactive one from a compound.", "Group 1 metals get more reactive going down the group. Group 7 halogens get less reactive going down. Group 0 noble gases are unreactive, which is why helium is used in balloons and argon in light bulbs."], "worked": "Chlorine is more reactive than iodine. Chlorine reacts with potassium iodide solution. Potassium chloride and iodine form.", "question": "Chlorine is more reactive than iodine. What happens when chlorine is added to potassium iodide solution?", "scheme": ["Chlorine displaces iodine.", "Potassium chloride forms.", "Iodine is produced because chlorine is more reactive."], "mistake": "The reactivity trend in Group 7 goes the opposite way to Group 1.", "model": null, "id": "y8-unit-05-groups", "unit": "y8-unit-05", "year": 8, "number": 2, "marks": 3, "cards": [{"term": "Halogen", "definition": "A reactive non-metal in Group 7, also numbered Group 17."}, {"term": "Noble gas", "definition": "A Group 0 element that rarely reacts, also numbered Group 18."}], "quiz": {"q": "How does reactivity change down Group 1?", "opts": ["Every element is unreactive.", "It generally increases.", "It generally decreases."], "a": 1, "why": "The lower Group 1 metals generally react more readily."}, "misconception": {"q": "How does reactivity change down Group 1? Sam answers: “It generally decreases.” Explain why this is wrong.", "m": 2, "ms": ["It generally increases.", "The lower Group 1 metals generally react more readily."]}, "more": [{"q": "Which Group 1 metal is most reactive?", "opts": ["Potassium (lowest of Li, Na, K).", "Lithium.", "Sodium."], "a": 0, "why": "Reactivity increases down Group 1."}, {"q": "Group 1 metals react with water to make…", "opts": ["an acid and oxygen.", "salt only.", "an alkaline solution and hydrogen."], "a": 2, "why": "They are called the alkali metals."}, {"q": "Why is helium used in party balloons?", "opts": ["It is coloured.", "It is less dense than air and unreactive.", "It is reactive."], "a": 1, "why": "Noble gases do not burn."}, {"q": "Which halogen is most reactive?", "opts": ["Fluorine.", "Iodine.", "Bromine."], "a": 0, "why": "Reactivity decreases down Group 7."}], "ladder": [{"q": "What name is given to Group 7 elements?", "m": 1, "ms": ["Halogens."], "step": "Remember"}, {"q": "Describe what you would see when sodium is added to water.", "m": 2, "ms": ["It fizzes and floats/moves around on the surface.", "It melts into a ball and gets smaller until it disappears."], "step": "Apply"}, {"q": "Explain why noble gases are used in light bulbs and balloons.", "m": 3, "ms": ["Noble gases are very unreactive.", "They do not react with the hot filament or burn.", "This makes them safe to use."], "step": "Explain"}]}, {"key": "transition", "title": "Useful metals in the middle of the table", "notes": ["Many familiar metals are in the middle of the periodic table. Iron and copper are examples. Many are strong and conduct heat and electricity well.", "Copper is useful for wires because it conducts electricity. Iron is used to make strong steel. Some of these metals also speed up chemical reactions as catalysts.", "Transition metals often form coloured compounds, such as blue copper sulfate. Many are used as catalysts, such as iron in making ammonia. They are usually hard, dense and have high melting points."], "worked": "Copper wire carries current through a circuit. Steel beams support buildings. Each material is chosen because its properties suit the job.", "question": "Give two uses of these metals and explain which property makes each useful.", "scheme": ["Give a use such as copper in wires or iron in steel.", "Link copper wiring to good electrical conduction.", "Link steel structures to strength, or give another correct use and property."], "mistake": "Name a property and explain why it helps with the particular job.", "model": null, "id": "y8-unit-05-transition", "unit": "y8-unit-05", "year": 8, "number": 3, "marks": 3, "cards": [{"term": "Catalyst", "definition": "A substance that speeds up a reaction without being used up overall."}, {"term": "Transition metal", "definition": "A metal in the central part of the periodic table, such as iron or copper in school examples."}], "quiz": {"q": "Why is copper useful for electric wires?", "opts": ["It is an electrical insulator.", "It is a gas at room temperature.", "It conducts electricity well."], "a": 2, "why": "Copper lets charge flow easily through a wire."}, "misconception": {"q": "Why is copper useful for electric wires? Sam answers: “It is an electrical insulator.” Explain why this is wrong.", "m": 2, "ms": ["It conducts electricity well.", "Copper lets charge flow easily through a wire."]}, "more": [{"q": "Which is a transition metal?", "opts": ["Calcium.", "Copper.", "Sodium."], "a": 1, "why": "Copper is in the middle block."}, {"q": "Copper sulfate solution is…", "opts": ["blue.", "colourless.", "orange."], "a": 0, "why": "Transition metal compounds are often coloured."}, {"q": "Why is copper used for electrical wires?", "opts": ["It is magnetic.", "It is very reactive.", "It is a very good electrical conductor and easy to bend."], "a": 2, "why": "It conducts well and is ductile."}, {"q": "Compared with Group 1 metals, transition metals are…", "opts": ["all gases.", "harder and less reactive.", "softer and more reactive."], "a": 1, "why": "They are tough and stable."}], "ladder": [{"q": "Give one use of a transition metal.", "m": 1, "ms": ["E.g. iron for buildings/bridges, copper for wires/pipes, gold for jewellery."], "step": "Remember"}, {"q": "Give two properties of transition metals.", "m": 2, "ms": ["Hard/strong / high melting point / dense.", "Form coloured compounds / good catalysts / conduct electricity."], "step": "Apply"}, {"q": "Explain why iron rather than sodium is used to build bridges.", "m": 3, "ms": ["Iron is hard and strong.", "Sodium is soft and reacts violently with water.", "So a sodium bridge would be weak and dangerous."], "step": "Explain"}]}, {"key": "lungs", "title": "Breathing and gas exchange", "notes": ["Breathing moves air into and out of your lungs. Air reaches tiny air sacs called alveoli. Oxygen passes from the alveoli into the blood.", "Carbon dioxide passes from the blood into the alveoli. Thin walls and a large surface area help gases move quickly. The diaphragm is a sheet of muscle below the lungs. Air travels down the windpipe, or trachea, through bronchi and bronchioles to reach the alveoli. A good blood supply carries gases to and from the alveoli. During breathing out, the chest gets smaller and air is pushed out.", "When you breathe in, the intercostal muscles move the ribs up and out and the diaphragm flattens. The chest volume increases, pressure falls, and air rushes in. Alveoli have thin walls, a big surface area and a good blood supply."], "worked": "When you breathe in, the diaphragm contracts and moves down. The space inside the chest gets larger and the pressure falls. Air moves into the lungs.", "question": "How does the diaphragm help you breathe in?", "scheme": ["It contracts and moves downwards.", "Chest volume increases and air pressure inside falls.", "Air moves into the lungs from outside."], "mistake": "Breathing moves air. Respiration is a chemical process inside cells.", "model": "breathing", "id": "y8-unit-06-lungs", "unit": "y8-unit-06", "year": 8, "number": 1, "marks": 3, "cards": [{"term": "Ventilation", "definition": "Moving air into and out of the lungs."}, {"term": "Alveolus", "definition": "A tiny air sac in the lungs where gases move between air and blood."}, {"term": "Diaphragm", "definition": "A sheet of muscle below the lungs that helps breathing."}], "quiz": {"q": "What happens when you breathe in normally?", "opts": ["Air is pushed out of the lungs.", "The diaphragm contracts and moves down.", "The diaphragm moves up and chest space gets smaller."], "a": 1, "why": "The chest space gets larger, pressure falls and air moves in."}, "misconception": {"q": "What happens when you breathe in normally? Sam answers: “The diaphragm moves up and chest space gets smaller.” Explain why this is wrong.", "m": 2, "ms": ["The diaphragm contracts and moves down.", "The chest space gets larger, pressure falls and air moves in."]}, "more": [{"q": "What happens to the diaphragm when you breathe in?", "opts": ["It contracts and flattens.", "It relaxes and moves up.", "It does not move."], "a": 0, "why": "This increases the chest volume."}, {"q": "Which gas diffuses from the blood into the alveoli?", "opts": ["Oxygen.", "Nitrogen.", "Carbon dioxide."], "a": 2, "why": "It is then breathed out."}, {"q": "Why do alveoli have very thin walls?", "opts": ["To stop air escaping.", "To give a short distance for diffusion.", "To make them strong."], "a": 1, "why": "Gases cross quickly."}, {"q": "When you breathe in, the pressure inside your chest…", "opts": ["decreases.", "increases.", "stays the same."], "a": 0, "why": "Bigger volume means lower pressure, so air moves in."}], "ladder": [{"q": "What are alveoli?", "m": 1, "ms": ["Tiny air sacs in the lungs where gas exchange happens."], "step": "Remember"}, {"q": "Describe what happens to the ribs and diaphragm when you breathe in.", "m": 2, "ms": ["Intercostal muscles contract, moving the ribs up and out.", "The diaphragm contracts and flattens."], "step": "Apply"}, {"q": "Explain how the structure of the alveoli makes gas exchange efficient.", "m": 3, "ms": ["There are millions of alveoli, giving a large surface area.", "Walls are one cell thick, so there is a short diffusion distance.", "A good blood supply keeps a high concentration difference."], "step": "Explain"}]}, {"key": "drugs", "title": "Smoking, vaping, alcohol and drugs", "notes": ["A drug changes how the body works. Some drugs are medicines and others can cause harm. Nicotine can make people dependent, so stopping is difficult.", "Cigarette smoke contains harmful substances. Tar damages the lungs and carbon monoxide reduces oxygen carried by the blood. Vaping is not harmless and is unsuitable for children and non-smokers. Alcohol affects the nervous system and can slow reactions and affect judgement. Smoke damages tiny hairs called cilia that help clean the airways.", "Smoking damages the cilia that clean the airways and can cause lung cancer and heart disease. Alcohol slows reactions and can damage the liver. Vapes still contain nicotine, which is addictive and especially harmful for young people."], "worked": "Damaged air sacs make gas exchange harder. Carbon monoxide attaches to haemoglobin, which normally carries oxygen. Both effects can reduce oxygen reaching body cells.", "question": "Give two ways cigarette smoke reduces the oxygen reaching body cells. Explain one.", "scheme": ["Tar can damage air sacs and reduce gas exchange.", "Carbon monoxide reduces the blood's ability to carry oxygen.", "Less oxygen then reaches cells for aerobic respiration."], "mistake": "Less harmful than smoking does not mean harmless. Young people should not start vaping.", "model": null, "id": "y8-unit-06-drugs", "unit": "y8-unit-06", "year": 8, "number": 2, "marks": 3, "cards": [{"term": "Drug", "definition": "A substance that changes how the body works."}, {"term": "Dependence", "definition": "Finding it difficult to stop using a substance, sometimes with withdrawal effects."}], "quiz": {"q": "Which statement about nicotine vaping is correct?", "opts": ["It is harmless for all young people.", "Everyone who does not smoke should start vaping.", "It is not harmless and nicotine can cause dependence."], "a": 2, "why": "Vaping is unsuitable for children and non-smokers. Nicotine can make stopping difficult."}, "misconception": {"q": "Which statement about nicotine vaping is correct? Sam answers: “It is harmless for all young people.” Explain why this is wrong.", "m": 2, "ms": ["It is not harmless and nicotine can cause dependence.", "Vaping is unsuitable for children and non-smokers. Nicotine can make stopping difficult."]}, "more": [{"q": "Which substance in cigarettes is addictive?", "opts": ["Oxygen.", "Nicotine.", "Tar."], "a": 1, "why": "Nicotine causes dependence."}, {"q": "Which disease is strongly linked to smoking?", "opts": ["Lung cancer.", "Chickenpox.", "Food poisoning."], "a": 0, "why": "Tar contains cancer-causing chemicals."}, {"q": "Alcohol is a depressant, which means it…", "opts": ["speeds up the heart a lot.", "improves judgement.", "slows down reactions."], "a": 2, "why": "It slows the nervous system."}, {"q": "Why are vapes not safe for young people?", "opts": ["They clean the lungs.", "Most contain nicotine, which is addictive and affects brain development.", "They contain no chemicals."], "a": 1, "why": "Vapes are only for helping adults stop smoking."}], "ladder": [{"q": "What is a drug?", "m": 1, "ms": ["A chemical that changes the way the body works."], "step": "Remember"}, {"q": "Give two harmful effects of smoking.", "m": 2, "ms": ["Lung cancer / heart disease / emphysema.", "Damaged cilia, causing coughs and chest infections / lower birth weight in pregnancy."], "step": "Apply"}, {"q": "Explain why people find it difficult to stop smoking.", "m": 3, "ms": ["Cigarettes contain nicotine.", "Nicotine is addictive, so the body becomes dependent.", "Stopping causes withdrawal symptoms, such as cravings and bad mood."], "step": "Explain"}]}, {"key": "nutrition", "title": "Nutrients and a balanced diet", "notes": ["A balanced diet gives the body the nutrients it needs. Carbohydrates and fats provide energy. Protein is needed for growth and repair.", "Vitamins and minerals are needed in small amounts. Fibre helps food move through the gut. A deficiency means you are not getting enough of a nutrient. Water is needed for transport and many processes inside cells. The amount of food needed depends on factors such as activity and growth.", "Fibre keeps food moving through the gut and water is needed for all chemical reactions. Too little food can cause starvation; too much can cause obesity. A lack of a vitamin or mineral causes a deficiency disease, such as scurvy from too little vitamin C."], "worked": "Iron helps make haemoglobin in red blood cells. Haemoglobin carries oxygen. Too little iron can cause tiredness because less oxygen reaches cells.", "question": "What are the jobs of protein, fibre and iron?", "scheme": ["Protein is used for growth and repair.", "Fibre helps food move through the gut.", "Iron is needed to make haemoglobin for carrying oxygen."], "mistake": "A balanced diet means a useful mix of nutrients, not equal amounts of every food.", "model": null, "id": "y8-unit-07-nutrition", "unit": "y8-unit-07", "year": 8, "number": 1, "marks": 3, "cards": [{"term": "Nutrient", "definition": "A substance needed for energy, growth, repair or health."}, {"term": "Deficiency", "definition": "Not getting enough of a needed nutrient."}, {"term": "Fibre", "definition": "Material in food that we do not digest and that helps food move through the gut."}], "quiz": {"q": "Why do you need iron in your diet?", "opts": ["To replace all the water in the body.", "To digest fibre into glucose.", "To make haemoglobin for carrying oxygen in blood."], "a": 2, "why": "Haemoglobin in red blood cells needs iron to carry oxygen."}, "misconception": {"q": "Why do you need iron in your diet? Sam answers: “To replace all the water in the body.” Explain why this is wrong.", "m": 2, "ms": ["To make haemoglobin for carrying oxygen in blood.", "Haemoglobin in red blood cells needs iron to carry oxygen."]}, "more": [{"q": "Which nutrient is mainly for growth and repair?", "opts": ["Fat.", "Protein.", "Carbohydrate."], "a": 1, "why": "Protein builds new cells."}, {"q": "What does fibre do?", "opts": ["Helps food move through the gut.", "Gives lots of energy.", "Builds muscles."], "a": 0, "why": "It prevents constipation."}, {"q": "A lack of vitamin C causes…", "opts": ["rickets.", "anaemia.", "scurvy."], "a": 2, "why": "Scurvy causes bleeding gums."}, {"q": "Which food is a good source of carbohydrate?", "opts": ["Butter.", "Pasta.", "Chicken."], "a": 1, "why": "Starch is a carbohydrate."}], "ladder": [{"q": "Name the nutrient that provides the most energy per gram.", "m": 1, "ms": ["Fat (lipid)."], "step": "Remember"}, {"q": "Give two reasons why a diet high in sugar and fat can be harmful.", "m": 2, "ms": ["It can lead to obesity / weight gain.", "It increases the risk of heart disease / type 2 diabetes / tooth decay."], "step": "Apply"}, {"q": "Explain why an athlete in training needs more carbohydrate and protein than an office worker.", "m": 3, "ms": ["The athlete is more active, so uses more energy.", "Carbohydrates release that energy in respiration.", "Protein is needed to repair and build muscle tissue."], "step": "Explain"}]}, {"key": "food-tests", "title": "Testing foods", "notes": ["Food tests help identify nutrients in a sample. Iodine solution tests for starch. A blue-black colour is a positive starch result.", "Benedict's solution tests for some sugars when heated safely. The biuret test identifies protein. Use separate samples and follow your teacher's safety instructions.", "Benedict's solution turns from blue to brick-red when heated with sugar. Biuret solution turns purple with protein. Fats leave a translucent mark on paper or make a cloudy emulsion with ethanol and water."], "worked": "Add iodine to a food sample. If it stays orange-brown, starch has not been detected. Other carbohydrates, such as sugars, could still be present.", "question": "Describe a positive iodine test. Why does a negative result not show that all carbohydrates are missing?", "scheme": ["Iodine turns blue-black if starch is detected.", "A negative result only means starch was not detected.", "Other carbohydrates, such as sugars, may still be present."], "mistake": "A test for one nutrient cannot tell you that every other nutrient is absent.", "model": null, "id": "y8-unit-07-food-tests", "unit": "y8-unit-07", "year": 8, "number": 2, "marks": 3, "cards": [{"term": "Positive test", "definition": "A result showing that the substance being tested for was detected."}, {"term": "Reducing sugar", "definition": "A type of sugar, such as glucose, detected by Benedict's test with heating."}], "quiz": {"q": "What is a positive iodine test for starch?", "opts": ["Bubbles prove starch is present.", "The sample turns blue-black.", "The sample stays orange-brown."], "a": 1, "why": "Iodine turns blue-black when starch is detected."}, "misconception": {"q": "What is a positive iodine test for starch? Sam answers: “The sample stays orange-brown.” Explain why this is wrong.", "m": 2, "ms": ["The sample turns blue-black.", "Iodine turns blue-black when starch is detected."]}, "more": [{"q": "Which reagent tests for starch?", "opts": ["Iodine solution.", "Biuret solution.", "Benedict’s solution."], "a": 0, "why": "Iodine turns blue-black with starch."}, {"q": "A positive Benedict’s test turns…", "opts": ["blue-black.", "purple.", "brick-red/orange."], "a": 2, "why": "Sugar reacts when heated."}, {"q": "Biuret solution turns purple with…", "opts": ["fat.", "protein.", "starch."], "a": 1, "why": "Biuret is the protein test."}, {"q": "What must you do in the Benedict’s test?", "opts": ["Heat the mixture in a water bath.", "Add iodine.", "Freeze the sample."], "a": 0, "why": "Benedict’s needs heat to work."}], "ladder": [{"q": "What colour does iodine turn if starch is present?", "m": 1, "ms": ["Blue-black."], "step": "Remember"}, {"q": "A food turns Biuret purple and iodine stays orange-brown. What does it contain and not contain?", "m": 2, "ms": ["It contains protein.", "It does not contain starch."], "step": "Apply"}, {"q": "Describe how to test a food for sugar safely.", "m": 3, "ms": ["Mix the food with water and add Benedict’s solution.", "Heat in a hot water bath (not a flame) wearing goggles.", "A colour change from blue to green/orange/brick-red shows sugar is present."], "step": "Explain"}]}, {"key": "digestion", "title": "Digestion, enzymes and absorption", "notes": ["Digestion breaks large food molecules into small ones. The small molecules can dissolve and pass into the blood. Enzymes speed up the chemical breakdown of food.", "The small intestine has many tiny folds called villi. These give a large surface area for absorption. Absorption is the movement of digested nutrients through the gut wall. Amylase breaks down starch, protease breaks down proteins and lipase breaks down fats. Bile breaks fat into small droplets and helps neutralise acid from the stomach. Bile is not an enzyme. The stomach mixes food, and the small intestine does most absorption. The large intestine absorbs water.", "Carbohydrase breaks starch into sugars, protease breaks proteins into amino acids, and lipase breaks fats into fatty acids and glycerol. Small molecules are absorbed through the wall of the small intestine. Villi give the small intestine a huge surface area."], "worked": "An enzyme breaks starch into smaller sugar molecules. The sugars pass through the wall of the small intestine. Blood carries them to body cells.", "question": "How do enzymes and villi help nutrients get from food into the blood?", "scheme": ["Enzymes break large food molecules into small soluble molecules.", "Villi give a large surface area for absorption.", "Small nutrients pass through the gut wall into the blood."], "mistake": "Food does not simply fall through holes into the blood. It must be digested and absorbed.", "model": null, "id": "y8-unit-07-digestion", "unit": "y8-unit-07", "year": 8, "number": 3, "marks": 3, "cards": [{"term": "Digestion", "definition": "Breaking large food molecules into small molecules that can dissolve."}, {"term": "Enzyme", "definition": "A substance made by living things that speeds up a chemical reaction."}, {"term": "Absorption", "definition": "Digested nutrients passing through the gut wall."}], "quiz": {"q": "How do villi help absorption?", "opts": ["They stop nutrients reaching the blood.", "They provide a larger surface area.", "They make the intestine waterproof."], "a": 1, "why": "More surface area lets nutrients pass into the body more quickly."}, "misconception": {"q": "How do villi help absorption? Sam answers: “They make the intestine waterproof.” Explain why this is wrong.", "m": 2, "ms": ["They provide a larger surface area.", "More surface area lets nutrients pass into the body more quickly."]}, "more": [{"q": "Which enzyme breaks down protein?", "opts": ["Protease.", "Lipase.", "Carbohydrase."], "a": 0, "why": "Protease → amino acids."}, {"q": "Where are most digested food molecules absorbed into the blood?", "opts": ["Stomach.", "Large intestine.", "Small intestine."], "a": 2, "why": "Villi absorb small molecules."}, {"q": "Why do villi help absorption?", "opts": ["They produce acid.", "They increase the surface area.", "They make food move faster."], "a": 1, "why": "More surface means faster absorption."}, {"q": "What is the main job of the large intestine?", "opts": ["Absorbing water.", "Digesting protein.", "Making bile."], "a": 0, "why": "Water is taken back into the body."}], "ladder": [{"q": "What does an enzyme do in digestion?", "m": 1, "ms": ["Speeds up the breakdown of large food molecules into small ones."], "step": "Remember"}, {"q": "Name the products when fats are digested.", "m": 2, "ms": ["Fatty acids.", "Glycerol."], "step": "Apply"}, {"q": "Explain why starch must be digested before it can be used by the body.", "m": 3, "ms": ["Starch molecules are too large to pass through the gut wall.", "Carbohydrase breaks them into small sugar molecules.", "Sugars dissolve and are absorbed into the blood."], "step": "Explain"}]}, {"key": "sound", "title": "Sound waves, loudness and pitch", "notes": ["Sound is made by vibrations. It travels through solids, liquids or gases. Particles pass the vibration from place to place.", "Amplitude is the size of a vibration. A larger amplitude usually makes a louder sound. Frequency is vibrations per second: a higher frequency gives a higher pitch. Sound cannot cross a vacuum because there are no particles to pass on the vibration.", "Sound travels fastest in solids and cannot travel through a vacuum. Frequency is the number of vibrations per second, measured in hertz, Hz. Higher frequency gives a higher pitch; bigger amplitude gives a louder sound."], "worked": "A guitar string can vibrate with a large or small amplitude. Plucking harder usually makes it louder. Changing how often it vibrates changes the pitch.", "question": "How is increasing amplitude different from increasing frequency for a sound?", "scheme": ["Increasing amplitude usually increases loudness.", "Increasing frequency increases pitch.", "Loudness and pitch can change separately."], "mistake": "Louder does not always mean higher-pitched.", "model": "wave", "id": "y8-unit-08-sound", "unit": "y8-unit-08", "year": 8, "number": 1, "marks": 3, "cards": [{"term": "Amplitude", "definition": "The greatest distance a vibrating part moves from its resting position."}, {"term": "Frequency", "definition": "The number of complete vibrations each second."}, {"term": "Longitudinal wave", "definition": "A wave whose vibrations are along the direction it travels."}], "quiz": {"q": "What changes when a sound has a higher pitch?", "opts": ["It must travel faster.", "Its frequency is higher.", "Its amplitude must be larger."], "a": 1, "why": "Pitch depends on frequency. Amplitude is linked to loudness."}, "misconception": {"q": "What changes when a sound has a higher pitch? Sam answers: “Its amplitude must be larger.” Explain why this is wrong.", "m": 2, "ms": ["Its frequency is higher.", "Pitch depends on frequency. Amplitude is linked to loudness."]}, "more": [{"q": "Why can sound not travel through space?", "opts": ["There are no particles to pass on the vibrations.", "It is too cold.", "Space is too dark."], "a": 0, "why": "Sound needs a medium."}, {"q": "A higher frequency sound has a…", "opts": ["lower pitch.", "quieter volume.", "higher pitch."], "a": 2, "why": "Pitch depends on frequency."}, {"q": "A bigger amplitude makes a sound…", "opts": ["faster.", "louder.", "higher."], "a": 1, "why": "Amplitude relates to loudness."}, {"q": "In which material does sound usually travel fastest?", "opts": ["Steel (a solid).", "Air (a gas).", "Water (a liquid)."], "a": 0, "why": "Particles in solids are close together."}], "ladder": [{"q": "What is the unit of frequency?", "m": 1, "ms": ["Hertz (Hz)."], "step": "Remember"}, {"q": "A guitar string is plucked harder. Describe what happens to the wave and the sound.", "m": 2, "ms": ["The amplitude of the vibration increases.", "The sound is louder (pitch stays the same)."], "step": "Apply"}, {"q": "Explain why an astronaut on a spacewalk cannot hear a nearby explosion.", "m": 3, "ms": ["Sound is passed on by vibrating particles.", "Space is a vacuum with almost no particles.", "So the vibrations cannot travel to the astronaut."], "step": "Explain"}]}, {"key": "ear", "title": "Hearing and echoes", "notes": ["Sound makes the eardrum vibrate. Small bones pass the vibrations towards the inner ear. The cochlea changes vibrations into nerve signals for the brain.", "An echo is a sound that reflects from a surface. The sound travels to the surface and back. Divide the total travel distance by two to find the distance to the surface.", "Humans hear frequencies from about 20 Hz to 20,000 Hz. Loud sounds can damage the tiny hairs in the cochlea, causing hearing loss. An echo is a reflected sound; echoes can be used to measure distance."], "worked": "An echo takes 0.2 seconds to return. At 340 m/s, sound travels 340 × 0.2 = 68 m in total. The wall is 68 ÷ 2 = 34 m away.", "question": "An echo returns after 0.2 seconds. Sound travels at 340 m/s. How far away is the wall?", "scheme": ["Total distance = 340 × 0.2 = 68 m.", "Divide by two because the sound travels there and back.", "Wall distance = 34 m."], "mistake": "The echo time includes both journeys, not just the journey to the wall.", "model": null, "id": "y8-unit-08-ear", "unit": "y8-unit-08", "year": 8, "number": 2, "marks": 3, "cards": [{"term": "Echo", "definition": "A sound that reflects from a surface."}, {"term": "Cochlea", "definition": "The inner-ear part that turns vibrations into nerve signals."}], "quiz": {"q": "Why divide speed × echo time by two to find a wall's distance?", "opts": ["Sound only travels half the time.", "The wall absorbs exactly half the sound.", "The sound travels to the wall and back."], "a": 2, "why": "The calculation first gives the total length of both journeys."}, "misconception": {"q": "Why divide speed × echo time by two to find a wall's distance? Sam answers: “Sound only travels half the time.” Explain why this is wrong.", "m": 2, "ms": ["The sound travels to the wall and back.", "The calculation first gives the total length of both journeys."]}, "more": [{"q": "Which part of the ear first vibrates when sound arrives?", "opts": ["Auditory nerve.", "Eardrum.", "Cochlea."], "a": 1, "why": "The eardrum is at the end of the ear canal."}, {"q": "What is the normal human hearing range?", "opts": ["About 20 Hz to 20,000 Hz.", "About 1 Hz to 100 Hz.", "Above 50,000 Hz only."], "a": 0, "why": "Ultrasound is above 20,000 Hz."}, {"q": "What is an echo?", "opts": ["A very quiet sound.", "A sound in a vacuum.", "A reflected sound."], "a": 2, "why": "Sound bounces off hard surfaces."}, {"q": "Why should you wear ear defenders near loud machines?", "opts": ["They make sounds louder.", "Loud sounds can damage hair cells in the cochlea.", "They keep your ears warm."], "a": 1, "why": "Damage can cause permanent hearing loss."}], "ladder": [{"q": "What does the cochlea do?", "m": 1, "ms": ["Changes vibrations into electrical signals (nerve impulses) for the brain."], "step": "Remember"}, {"q": "A clap echoes from a wall 85 m away after 0.5 s. Calculate the speed of sound.", "m": 2, "ms": ["Distance travelled = 2 × 85 = 170 m.", "Speed = 170 ÷ 0.5 = 340 m/s."], "step": "Apply"}, {"q": "Describe the path of a sound from outside the ear to the brain.", "m": 3, "ms": ["The outer ear funnels sound down the ear canal to the eardrum, which vibrates.", "The ossicles pass on and amplify the vibrations to the cochlea.", "The cochlea makes nerve impulses that travel along the auditory nerve to the brain."], "step": "Explain"}]}, {"key": "light", "title": "Reflection and refraction", "notes": ["Light travels in straight lines through a uniform material. Reflection is light bouncing off a surface. Refraction is light changing direction as its speed changes between materials.", "Draw the normal at right angles to the surface. Measure ray angles from the normal. For reflection, the incoming angle equals the reflected angle. Light bends towards the normal when it enters glass from air at an angle.", "The angle of incidence equals the angle of reflection, measured from the normal. Light slows down when it enters glass and bends towards the normal. Light travels at about 300,000 km/s, much faster than sound."], "worked": "A ray hits a mirror at 40° to the normal. It reflects at 40° to the normal. It makes 90 − 40 = 50° with the mirror surface.", "question": "A ray hits a plane mirror at 40° to the normal. Find the reflection angle and the angle to the mirror surface.", "scheme": ["The reflection angle is 40° to the normal.", "The normal is at 90° to the mirror.", "The reflected ray is at 50° to the mirror surface."], "mistake": "Angles are measured from the normal, not from the mirror surface.", "model": "rays", "id": "y8-unit-09-light", "unit": "y8-unit-09", "year": 8, "number": 1, "marks": 3, "cards": [{"term": "Normal", "definition": "A line drawn at right angles to a surface where a ray hits it."}, {"term": "Reflection", "definition": "A wave bouncing back from a surface."}, {"term": "Refraction", "definition": "A wave changing direction as its speed changes between materials."}], "quiz": {"q": "Where do you measure reflection angles from?", "opts": ["Any line on the page.", "The normal.", "The mirror surface."], "a": 1, "why": "The normal is at 90° to the surface. Both ray angles are measured from it."}, "misconception": {"q": "Where do you measure reflection angles from? Sam answers: “The mirror surface.” Explain why this is wrong.", "m": 2, "ms": ["The normal.", "The normal is at 90° to the surface. Both ray angles are measured from it."]}, "more": [{"q": "For a plane mirror, the angle of reflection is…", "opts": ["equal to the angle of incidence.", "always 90°.", "half the angle of incidence."], "a": 0, "why": "This is the law of reflection."}, {"q": "When light enters glass from air it bends…", "opts": ["away from the normal.", "not at all, at any angle.", "towards the normal."], "a": 2, "why": "It slows down in glass."}, {"q": "Why do you see lightning before you hear thunder?", "opts": ["Thunder happens later.", "Light travels much faster than sound.", "Sound travels faster."], "a": 1, "why": "Light reaches you almost instantly."}, {"q": "The normal is a line drawn…", "opts": ["at 90° to the surface.", "along the surface.", "at 45° to the surface."], "a": 0, "why": "Angles are measured from the normal."}], "ladder": [{"q": "What is refraction?", "m": 1, "ms": ["The change in direction of light as it passes from one material into another."], "step": "Remember"}, {"q": "A ray hits a mirror with an angle of incidence of 35°. State the angle of reflection and between which lines it is measured.", "m": 2, "ms": ["35°.", "Between the reflected ray and the normal."], "step": "Apply"}, {"q": "Explain why a straw looks bent in a glass of water.", "m": 3, "ms": ["Light from the straw refracts as it leaves the water into the air.", "It changes direction at the surface.", "Your brain assumes light travels in straight lines, so the straw appears in a different place."], "step": "Explain"}]}, {"key": "colour", "title": "Colours, lenses and light waves", "notes": ["White light is a mixture of colours. An object looks coloured because it reflects some colours and absorbs others. A filter lets some colours through and absorbs others.", "A red object reflects red light well. Under blue light it may look dark because little blue is reflected. A convex lens brings parallel light rays together.", "A red object looks red because it reflects red light and absorbs other colours. A red filter only lets red light through. A convex lens focuses light to a point; the eye uses a lens to focus light onto the retina."], "worked": "Put a red card under white light and it looks red. Shine only blue light on it and there is no red light to reflect. It may then look very dark.", "question": "Why can a red object look dark when only blue light shines on it?", "scheme": ["A red object mainly reflects red light.", "Blue light contains no red light for it to reflect.", "The object absorbs much of the blue light, so little reaches the eye."], "mistake": "An object cannot reflect a colour that is missing from the light shining on it.", "model": "rays", "id": "y8-unit-09-colour", "unit": "y8-unit-09", "year": 8, "number": 2, "marks": 3, "cards": [{"term": "Filter", "definition": "A material that lets some colours of light through and absorbs others."}, {"term": "Convex lens", "definition": "A lens that can bring parallel light rays together."}, {"term": "Spectrum", "definition": "A range of waves arranged by wavelength or frequency."}], "quiz": {"q": "Why can a red object look dark in blue light?", "opts": ["There is no red light to reflect and it absorbs much of the blue.", "It creates black light.", "It must turn into a blue material."], "a": 0, "why": "An object can only reflect colours that are present in the light reaching it."}, "misconception": {"q": "Why can a red object look dark in blue light? Sam answers: “It creates black light.” Explain why this is wrong.", "m": 2, "ms": ["There is no red light to reflect and it absorbs much of the blue.", "An object can only reflect colours that are present in the light reaching it."]}, "more": [{"q": "What colour does a blue shirt look in red light?", "opts": ["Blue.", "Red.", "Black."], "a": 2, "why": "It absorbs red and there is no blue light to reflect."}, {"q": "White light can be split into colours by…", "opts": ["a filter only.", "a prism.", "a mirror."], "a": 1, "why": "Different colours refract by different amounts."}, {"q": "A green filter lets through…", "opts": ["green light only.", "all colours except green.", "red light only."], "a": 0, "why": "Filters transmit their own colour."}, {"q": "Which type of lens brings light rays together?", "opts": ["Concave.", "Flat.", "Convex."], "a": 2, "why": "Convex lenses focus light."}], "ladder": [{"q": "What is dispersion?", "m": 1, "ms": ["The splitting of white light into a spectrum of colours."], "step": "Remember"}, {"q": "White light shines through a red filter onto a green apple. State and explain the colour the apple appears.", "m": 2, "ms": ["Black.", "Only red light reaches it and a green apple absorbs red light, reflecting none."], "step": "Apply"}, {"q": "Explain why grass looks green in sunlight.", "m": 3, "ms": ["Sunlight contains all colours.", "Grass absorbs most colours.", "It reflects green light into our eyes."], "step": "Explain"}]}, {"key": "reaction", "title": "Chemical reactions and physical changes", "notes": ["A chemical reaction makes one or more new substances. The starting substances are reactants. The new substances are products.", "A physical change does not make a new substance. Melting and freezing are physical changes. Bubbles or a colour change can be clues to a reaction, but check the evidence.", "Signs of a chemical reaction include a colour change, fizzing, a temperature change or a precipitate forming. Chemical changes are usually hard to reverse. Word equations show the reactants and products."], "worked": "Burning magnesium makes a new substance, magnesium oxide. Melting ice still leaves you with water. Boiling water makes bubbles without a chemical reaction.", "question": "Give one chemical reaction and one physical change. Explain the difference.", "scheme": ["Give a reaction that makes a new substance, such as burning magnesium.", "Give a physical change, such as melting ice.", "A physical change does not make a new substance."], "mistake": "Bubbles alone do not prove that a chemical reaction happened.", "model": null, "id": "y8-unit-10-reaction", "unit": "y8-unit-10", "year": 8, "number": 1, "marks": 3, "cards": [{"term": "Reactant", "definition": "A starting substance in a chemical reaction."}, {"term": "Product", "definition": "A new substance made in a chemical reaction."}, {"term": "Physical change", "definition": "A change that does not make a new substance."}], "quiz": {"q": "Which observation alone does not prove a chemical reaction?", "opts": ["Bubbles appearing.", "Clear evidence of a new substance forming.", "A test confirming a different chemical substance."], "a": 0, "why": "Boiling water also makes bubbles, without making a new substance."}, "misconception": {"q": "Which observation alone does not prove a chemical reaction? Sam answers: “Clear evidence of a new substance forming.” Explain why this is wrong.", "m": 2, "ms": ["Bubbles appearing.", "Boiling water also makes bubbles, without making a new substance."]}, "more": [{"q": "Which is a chemical change?", "opts": ["Melting ice.", "Dissolving sugar.", "Burning wood."], "a": 2, "why": "Burning makes new substances such as ash and carbon dioxide."}, {"q": "Which is a sign of a chemical reaction?", "opts": ["Something being cut into pieces.", "A gas being given off (fizzing).", "A change in shape."], "a": 1, "why": "Fizzing shows a new substance, a gas, is made."}, {"q": "In \"magnesium + oxygen → magnesium oxide\", the product is…", "opts": ["magnesium oxide.", "magnesium.", "oxygen."], "a": 0, "why": "Products are on the right of the arrow."}, {"q": "Which change is easy to reverse?", "opts": ["Cooking an egg.", "Rusting.", "Water freezing."], "a": 2, "why": "Freezing is a physical change."}], "ladder": [{"q": "What is a product?", "m": 1, "ms": ["A new substance made in a chemical reaction."], "step": "Remember"}, {"q": "Give two observations that show a chemical reaction has happened.", "m": 2, "ms": ["Colour change / fizzing (gas given off).", "Temperature change / a solid (precipitate) forms / light given out."], "step": "Apply"}, {"q": "Explain why melting chocolate is a physical change but toasting bread is a chemical change.", "m": 3, "ms": ["Melting chocolate does not make a new substance and can be reversed by cooling.", "Toasting bread makes new substances (the brown, burnt layer).", "It cannot be reversed."], "step": "Explain"}]}, {"key": "combustion", "title": "Burning and breaking down compounds", "notes": ["Combustion is burning: a substance reacts with oxygen. Thermal decomposition is when heating breaks a compound into simpler substances. Both are chemical changes because new substances form.", "Melting is a physical change. The particles are still the same substance after melting. Use evidence of new substances to tell changes apart.", "Complete combustion of a fuel makes carbon dioxide and water. Limewater turns milky when carbon dioxide is bubbled through it. Heating copper carbonate breaks it down into copper oxide and carbon dioxide."], "worked": "Melting ice produces liquid water, so no new substance forms. Heating calcium carbonate makes calcium oxide and carbon dioxide. This is thermal decomposition because a compound breaks down when heated.", "question": "Is each change physical or chemical: melting ice, and heating calcium carbonate to make calcium oxide and carbon dioxide? Explain.", "scheme": ["Melting ice is physical because it is still water.", "Heating calcium carbonate is chemical because new substances form.", "The chemical change is thermal decomposition."], "mistake": "Not every change caused by heating is a chemical reaction.", "model": null, "id": "y8-unit-10-combustion", "unit": "y8-unit-10", "year": 8, "number": 2, "marks": 3, "cards": [{"term": "Thermal decomposition", "definition": "Breaking a compound into simpler substances by heating it."}, {"term": "Complete combustion", "definition": "A fuel burning fully with enough oxygen."}], "quiz": {"q": "Which is thermal decomposition?", "opts": ["Heating calcium carbonate to make calcium oxide and carbon dioxide.", "Melting ice.", "Filtering sand from water."], "a": 0, "why": "A compound breaks down into new substances when heated."}, "misconception": {"q": "Which is thermal decomposition? Sam answers: “Melting ice.” Explain why this is wrong.", "m": 2, "ms": ["Heating calcium carbonate to make calcium oxide and carbon dioxide.", "A compound breaks down into new substances when heated."]}, "more": [{"q": "What is made when methane burns completely in oxygen?", "opts": ["Carbon monoxide only.", "Hydrogen and oxygen.", "Carbon dioxide and water."], "a": 2, "why": "Fuel + oxygen → CO₂ + H₂O."}, {"q": "What is the test for carbon dioxide?", "opts": ["It gives a squeaky pop.", "It turns limewater milky.", "It relights a glowing splint."], "a": 1, "why": "Limewater goes cloudy."}, {"q": "Thermal decomposition means…", "opts": ["breaking down a substance using heat.", "burning in oxygen.", "dissolving in water."], "a": 0, "why": "One reactant breaks into two or more products."}, {"q": "Which three things does a fire need?", "opts": ["Water, fuel and light.", "Oxygen, water and heat.", "Fuel, oxygen and heat."], "a": 2, "why": "This is the fire triangle."}], "ladder": [{"q": "What gas is needed for combustion?", "m": 1, "ms": ["Oxygen."], "step": "Remember"}, {"q": "Write the word equation for heating copper carbonate.", "m": 2, "ms": ["Copper carbonate → copper oxide…", "… + carbon dioxide."], "step": "Apply"}, {"q": "Explain how a fire blanket puts out a small fire.", "m": 3, "ms": ["A fire needs fuel, heat and oxygen.", "The blanket covers the fire and stops oxygen reaching it.", "Without oxygen the fire goes out."], "step": "Explain"}]}, {"key": "mass", "title": "Where does the mass go?", "notes": ["Atoms are rearranged in a chemical reaction. They are not created or destroyed. Total mass stays the same if you count everything.", "A gas can enter or leave an open container. This can make the measured mass change. A closed container keeps all the reacting matter inside.", "When magnesium burns, the product is heavier because oxygen atoms from the air join it. When a gas escapes from an open flask, the mass seems to decrease. In a sealed container, the total mass stays exactly the same."], "worked": "Magnesium burns by joining with oxygen from the air. The magnesium oxide includes the added oxygen. Its mass is greater than the starting magnesium alone.", "question": "Why does magnesium gain mass when it burns in air?", "scheme": ["Magnesium reacts with oxygen.", "Oxygen atoms join the magnesium to make magnesium oxide.", "The added oxygen makes the product heavier than the magnesium alone."], "mistake": "A lower reading after a reaction does not mean mass was destroyed. A gas may have escaped.", "model": null, "id": "y8-unit-10-mass", "unit": "y8-unit-10", "year": 8, "number": 3, "marks": 3, "cards": [{"term": "Closed system", "definition": "A setup where no matter can enter or leave."}, {"term": "Conservation of mass", "definition": "Total mass stays the same in a reaction when all matter is counted."}], "quiz": {"q": "Why can an open flask lose measured mass during a reaction?", "opts": ["Mass stops existing.", "A gas leaves the flask.", "Atoms are destroyed."], "a": 1, "why": "The gas still exists outside the flask. Counting it would keep the total mass unchanged."}, "misconception": {"q": "Why can an open flask lose measured mass during a reaction? Sam answers: “Atoms are destroyed.” Explain why this is wrong.", "m": 2, "ms": ["A gas leaves the flask.", "The gas still exists outside the flask. Counting it would keep the total mass unchanged."]}, "more": [{"q": "Why does mass increase when magnesium burns in air?", "opts": ["Oxygen from the air combines with it.", "Atoms are created.", "Magnesium gets hotter."], "a": 0, "why": "The product includes the added oxygen."}, {"q": "In an open flask, marble chips react with acid and the mass goes down because…", "opts": ["atoms are destroyed.", "the acid evaporates instantly.", "carbon dioxide gas escapes."], "a": 2, "why": "The gas leaves the container."}, {"q": "What happens to total mass in a sealed container during a reaction?", "opts": ["It decreases.", "It stays the same.", "It increases."], "a": 1, "why": "No atoms can enter or leave."}, {"q": "Conservation of mass means…", "opts": ["atoms are not created or destroyed in reactions.", "mass always increases.", "gases have no mass."], "a": 0, "why": "Atoms are just rearranged."}], "ladder": [{"q": "What is the law of conservation of mass?", "m": 1, "ms": ["Mass is not created or destroyed in a chemical reaction."], "step": "Remember"}, {"q": "24 g of magnesium reacts with 16 g of oxygen. Calculate the mass of magnesium oxide and explain how you know.", "m": 2, "ms": ["24 + 16 = 40 g.", "All the atoms from the reactants end up in the product, so mass is conserved."], "step": "Apply"}, {"q": "Explain why the mass in an open beaker decreases when an acid reacts with a carbonate.", "m": 3, "ms": ["The reaction makes carbon dioxide gas.", "The gas escapes into the air.", "Its mass is no longer measured, but the total mass of all substances is still conserved."], "step": "Explain"}]}, {"key": "chemical-energy", "title": "Reactions that heat or cool", "notes": ["An exothermic reaction transfers energy to the surroundings. The surroundings usually get warmer. An endothermic reaction takes energy from the surroundings, which usually cool down.", "Bonds are links between atoms. Breaking bonds takes in energy. Making new bonds releases energy. A lid and insulation reduce unwanted energy transfer in temperature-change tests. Keep starting temperatures and amounts the same for a fair comparison.", "Burning, neutralisation and hand warmers are exothermic. Thermal decomposition and dissolving some salts, like in cold packs, are endothermic. A thermometer shows whether the temperature rises or falls."], "worked": "In an exothermic reaction, making new bonds releases more energy than breaking old bonds takes in. The extra energy heats the surroundings. A thermometer can show the temperature rise.", "question": "Why can an exothermic reaction warm its surroundings? Use the ideas of breaking and making bonds.", "scheme": ["Breaking old bonds takes in energy.", "Making new bonds releases more energy than was taken in.", "The extra energy is transferred to the surroundings, warming them."], "mistake": "Breaking a bond takes energy. It does not release energy by itself.", "model": "rate", "id": "y8-unit-11-chemical-energy", "unit": "y8-unit-11", "year": 8, "number": 1, "marks": 3, "cards": [{"term": "Exothermic", "definition": "Transferring energy to the surroundings overall, usually warming them."}, {"term": "Endothermic", "definition": "Taking energy from the surroundings overall, usually cooling them."}, {"term": "Bond", "definition": "A chemical link between atoms."}], "quiz": {"q": "Which statement about bonds is correct?", "opts": ["Breaking bonds takes in energy and making bonds releases energy.", "Breaking bonds always releases energy.", "Making bonds always needs energy with none released."], "a": 0, "why": "Compare the energy taken in and released to decide whether the reaction heats or cools its surroundings."}, "misconception": {"q": "Which statement about bonds is correct? Sam answers: “Breaking bonds always releases energy.” Explain why this is wrong.", "m": 2, "ms": ["Breaking bonds takes in energy and making bonds releases energy.", "Compare the energy taken in and released to decide whether the reaction heats or cools its surroundings."]}, "more": [{"q": "A reaction makes the test tube feel hot. It is…", "opts": ["endothermic.", "neutral.", "exothermic."], "a": 2, "why": "Energy is given out to the surroundings."}, {"q": "Which is an endothermic process?", "opts": ["A hand warmer.", "An instant cold pack.", "Burning wood."], "a": 1, "why": "Cold packs take in energy."}, {"q": "How can you measure whether a reaction is exo- or endothermic?", "opts": ["Measure the temperature change with a thermometer.", "Weigh the beaker.", "Look at the colour only."], "a": 0, "why": "Temperature rise = exothermic; fall = endothermic."}, {"q": "Combustion is…", "opts": ["endothermic.", "not a chemical reaction.", "exothermic."], "a": 2, "why": "Burning releases energy as heat and light."}], "ladder": [{"q": "What is an endothermic reaction?", "m": 1, "ms": ["A reaction that takes in energy from the surroundings, so they get colder."], "step": "Remember"}, {"q": "Acid and alkali are mixed; the temperature rises from 20 °C to 27 °C. State the temperature change and the type of reaction.", "m": 2, "ms": ["A rise of 7 °C.", "Exothermic."], "step": "Apply"}, {"q": "Explain why a polystyrene cup is used when measuring the temperature change of a reaction.", "m": 3, "ms": ["Polystyrene is a good thermal insulator.", "It reduces energy transfer to or from the surroundings.", "So the measured temperature change is more accurate."], "step": "Explain"}]}, {"key": "catalyst", "title": "Catalysts and enzymes", "notes": ["A catalyst makes a reaction happen faster. It is not used up overall in the reaction. An enzyme is a catalyst made by a living thing.", "A catalyst can help the reaction finish sooner. It does not necessarily make more product in total. Enzymes work best within suitable temperature and pH ranges.", "Enzymes work best at a certain temperature, often body temperature. High temperatures can denature an enzyme so it stops working. Catalysts save energy in industry because reactions can happen at lower temperatures."], "worked": "Two tests start with the same amounts of reactants. The one with a catalyst produces gas more quickly. Both can still finish with the same gas volume.", "question": "Why can a reaction make gas faster but still produce the same final gas volume?", "scheme": ["A catalyst speeds up the reaction.", "The same starting amounts can make the same total product.", "The gas is made sooner, rather than extra gas being made."], "mistake": "A faster reaction does not always make more product in total.", "model": "rate", "id": "y8-unit-11-catalyst", "unit": "y8-unit-11", "year": 8, "number": 2, "marks": 3, "cards": [{"term": "Activation energy", "definition": "The energy needed to get a reaction started."}, {"term": "Catalyst", "definition": "A substance that speeds up a reaction without being used up overall."}], "quiz": {"q": "What can a catalyst change when reactant amounts stay the same?", "opts": ["The total number of starting atoms.", "Whether atoms are conserved.", "How quickly the products form."], "a": 2, "why": "A catalyst can make the same amount of product form sooner."}, "misconception": {"q": "What can a catalyst change when reactant amounts stay the same? Sam answers: “The total number of starting atoms.” Explain why this is wrong.", "m": 2, "ms": ["How quickly the products form.", "A catalyst can make the same amount of product form sooner."]}, "more": [{"q": "A catalyst…", "opts": ["is a product of the reaction.", "speeds up a reaction and is not used up.", "slows down a reaction."], "a": 1, "why": "It can be reused."}, {"q": "An enzyme is…", "opts": ["a biological catalyst.", "a type of acid.", "a fat."], "a": 0, "why": "Enzymes are proteins made by living things."}, {"q": "Why do enzymes stop working at high temperatures?", "opts": ["They melt into water.", "They become catalysts.", "Their shape changes (they are denatured)."], "a": 2, "why": "The active site no longer fits."}, {"q": "Which change increases the rate of most reactions?", "opts": ["Diluting the acid.", "Increasing the temperature.", "Using larger lumps."], "a": 1, "why": "Particles move faster and collide more."}], "ladder": [{"q": "What is a catalyst?", "m": 1, "ms": ["A substance that speeds up a reaction without being used up."], "step": "Remember"}, {"q": "Give two ways, other than a catalyst, to speed up a reaction between marble chips and acid.", "m": 2, "ms": ["Increase the temperature / use more concentrated acid.", "Use smaller pieces (powder) for a bigger surface area."], "step": "Apply"}, {"q": "Explain why using a catalyst in a factory is good for the environment and for costs.", "m": 3, "ms": ["The reaction can happen at a lower temperature.", "Less fuel is burned, so less energy is used and less carbon dioxide released.", "The catalyst is not used up, so it can be reused, saving money."], "step": "Explain"}]}, {"key": "respiration", "title": "Aerobic respiration and exercise", "notes": ["Respiration is a chemical process inside living cells. It releases energy from food. Aerobic respiration uses oxygen.", "The word equation is glucose + oxygen → carbon dioxide + water. Plants and animals both respire. Breathing brings air to the lungs; it is not the same as respiration.", "Respiration happens in mitochondria in every living cell, all the time. During exercise, you breathe faster and your heart beats faster to supply more oxygen and glucose. Respiration is not the same as breathing."], "worked": "Muscles need more energy during exercise. They use more glucose and oxygen for respiration. Breathing faster helps supply oxygen and remove carbon dioxide.", "question": "Why does breathing rate usually increase during exercise?", "scheme": ["Working muscles need more energy.", "They carry out more aerobic respiration and need more oxygen.", "Faster breathing supplies oxygen and removes extra carbon dioxide."], "mistake": "Plants respire in the light and in the dark.", "model": null, "id": "y8-unit-12-respiration", "unit": "y8-unit-12", "year": 8, "number": 1, "marks": 3, "cards": [{"term": "Aerobic respiration", "definition": "Releasing energy from glucose in cells using oxygen."}, {"term": "Respiration", "definition": "Chemical processes in cells that release energy from food."}], "quiz": {"q": "Which living things respire?", "opts": ["Only animals.", "Only things that have lungs.", "Plants and animals."], "a": 2, "why": "Plants and animals need energy for cell processes, so both respire."}, "misconception": {"q": "Which living things respire? Sam answers: “Only animals.” Explain why this is wrong.", "m": 2, "ms": ["Plants and animals.", "Plants and animals need energy for cell processes, so both respire."]}, "more": [{"q": "Where does aerobic respiration happen?", "opts": ["Nucleus.", "Mitochondria.", "Lungs only."], "a": 1, "why": "Mitochondria release energy in cells."}, {"q": "What are the products of aerobic respiration?", "opts": ["Carbon dioxide and water.", "Glucose and oxygen.", "Lactic acid only."], "a": 0, "why": "Glucose + oxygen → carbon dioxide + water."}, {"q": "Why does your heart rate increase during exercise?", "opts": ["To cool you down.", "To make lactic acid.", "To deliver more oxygen and glucose to muscles."], "a": 2, "why": "Muscles respire faster."}, {"q": "Respiration happens in…", "opts": ["only lung cells.", "all living cells.", "only animal cells."], "a": 1, "why": "Plants and animals respire."}], "ladder": [{"q": "Write the word equation for aerobic respiration.", "m": 1, "ms": ["Glucose + oxygen → carbon dioxide + water (+ energy released)."], "step": "Remember"}, {"q": "Give two changes in the body during exercise and why they happen.", "m": 2, "ms": ["Breathing rate increases / heart rate increases.", "To supply more oxygen and remove more carbon dioxide from respiring muscles."], "step": "Apply"}, {"q": "Explain the difference between breathing and respiration.", "m": 3, "ms": ["Breathing is moving air into and out of the lungs.", "Respiration is a chemical reaction in cells.", "Respiration releases energy from glucose; breathing supplies the oxygen."], "step": "Explain"}]}, {"key": "anaerobic", "title": "Respiration without oxygen", "notes": ["Anaerobic respiration releases energy without using oxygen. It releases less energy from each glucose molecule than aerobic respiration. Different organisms can make different products.", "Yeast makes ethanol and carbon dioxide from glucose without oxygen. This process is called fermentation. It is used in bread making and some drinks production.", "In muscles during hard exercise, anaerobic respiration makes lactic acid, which causes fatigue. Afterwards you keep breathing hard to repay the oxygen debt. Yeast respires anaerobically to make ethanol and carbon dioxide, used in baking and brewing."], "worked": "Yeast in bread dough produces carbon dioxide. The gas makes bubbles that cause the dough to rise. Ethanol is also formed and mostly evaporates during baking.", "question": "What are the products of anaerobic respiration in yeast? Explain how one helps make bread.", "scheme": ["Yeast produces ethanol.", "It also produces carbon dioxide.", "Carbon dioxide bubbles make the dough rise."], "mistake": "Anaerobic respiration is not “no respiration”. It still releases energy.", "model": null, "id": "y8-unit-12-anaerobic", "unit": "y8-unit-12", "year": 8, "number": 2, "marks": 3, "cards": [{"term": "Anaerobic respiration", "definition": "Releasing energy from glucose without using oxygen."}, {"term": "Fermentation", "definition": "Anaerobic respiration in yeast that makes ethanol and carbon dioxide."}], "quiz": {"q": "Which gas makes bread dough rise?", "opts": ["Carbon dioxide.", "Oxygen.", "Nitrogen."], "a": 0, "why": "Yeast makes carbon dioxide bubbles that expand the dough."}, "misconception": {"q": "Which gas makes bread dough rise? Sam answers: “Oxygen.” Explain why this is wrong.", "m": 2, "ms": ["Carbon dioxide.", "Yeast makes carbon dioxide bubbles that expand the dough."]}, "more": [{"q": "What is made in human muscles during anaerobic respiration?", "opts": ["Ethanol.", "Oxygen.", "Lactic acid."], "a": 2, "why": "Glucose → lactic acid."}, {"q": "What does yeast make in anaerobic respiration?", "opts": ["Oxygen and water.", "Ethanol and carbon dioxide.", "Lactic acid only."], "a": 1, "why": "This is fermentation."}, {"q": "Why does bread rise?", "opts": ["Yeast makes carbon dioxide bubbles.", "Yeast makes oxygen.", "The flour melts."], "a": 0, "why": "The gas gets trapped in the dough."}, {"q": "Compared with aerobic, anaerobic respiration releases…", "opts": ["more energy per glucose.", "the same energy.", "less energy per glucose."], "a": 2, "why": "Glucose is not fully broken down."}], "ladder": [{"q": "When does anaerobic respiration happen in muscles?", "m": 1, "ms": ["When there is not enough oxygen, e.g. during hard exercise."], "step": "Remember"}, {"q": "Write the word equation for anaerobic respiration in yeast.", "m": 2, "ms": ["Glucose → ethanol…", "… + carbon dioxide (+ energy released)."], "step": "Apply"}, {"q": "Explain why a sprinter keeps breathing hard after finishing a race.", "m": 3, "ms": ["During the sprint muscles respired anaerobically, making lactic acid.", "Extra oxygen is needed to break down the lactic acid.", "This is the oxygen debt, so breathing stays fast until it is repaid."], "step": "Explain"}]}, {"key": "planning", "title": "Planning tests and taking measurements", "notes": ["Write steps that someone else could follow. Say what to measure and which units to use. Choose equipment that can measure the small changes you expect.", "Check that your equipment reads zero before you start. Repeat each measurement to spot results that do not fit. Calculate a mean by adding the readings and dividing by their number.", "Choose a sensible range and interval, such as 20 °C to 60 °C in steps of 10 °C. Repeat readings and calculate a mean. Write a method in numbered steps."], "worked": "Suppose ten pendulum swings take 12 seconds. One swing takes 12 ÷ 10 = 1.2 seconds. Timing several swings reduces the effect of your reaction time.", "question": "How could you improve the time measurement for one pendulum swing? Give two ideas and explain one.", "scheme": ["Time several swings, then divide by the number of swings.", "Repeat the measurement and calculate a mean.", "Use the same point to start and stop timing."], "mistake": "Repeating readings will not fix a clock that always reads too high.", "model": null, "id": "y8-unit-12-planning", "unit": "y8-unit-12", "year": 8, "number": 3, "marks": 3, "cards": [{"term": "Resolution", "definition": "The smallest change a measuring instrument can show."}, {"term": "Repeatability", "definition": "Getting similar results when the same person repeats the same test."}], "quiz": {"q": "Why time ten swings instead of one?", "opts": ["It fixes every equipment error.", "It makes the clock perfect.", "It reduces the effect of your reaction time on each swing's time."], "a": 2, "why": "Divide the longer total time by ten. Your reaction time then has a smaller effect on each swing's time."}, "misconception": {"q": "Why time ten swings instead of one? Sam answers: “It fixes every equipment error.” Explain why this is wrong.", "m": 2, "ms": ["It reduces the effect of your reaction time on each swing's time.", "Divide the longer total time by ten. Your reaction time then has a smaller effect on each swing's time."]}, "more": [{"q": "Which instrument best measures 25 cm³ of water?", "opts": ["A thermometer.", "A measuring cylinder.", "A beaker."], "a": 1, "why": "A measuring cylinder has a scale for volume."}, {"q": "How do you calculate a mean of three repeats?", "opts": ["Add the three values and divide by 3.", "Choose the middle value only.", "Subtract the smallest from the largest."], "a": 0, "why": "Mean = total ÷ number of values."}, {"q": "A ruler marked in mm has a resolution of…", "opts": ["1 cm.", "1 m.", "1 mm."], "a": 2, "why": "It can show changes as small as 1 mm."}, {"q": "Why should you repeat measurements?", "opts": ["Because the first result is always wrong.", "To spot anomalies and get a more reliable mean.", "To make the test unfair."], "a": 1, "why": "Repeats show whether results agree."}], "ladder": [{"q": "What is meant by the resolution of an instrument?", "m": 1, "ms": ["The smallest change it can show."], "step": "Remember"}, {"q": "Times measured: 12.1 s, 12.5 s, 12.3 s. Calculate the mean time.", "m": 2, "ms": ["12.1 + 12.5 + 12.3 = 36.9 s.", "36.9 ÷ 3 = 12.3 s."], "step": "Apply"}, {"q": "Explain why a stopwatch is better than counting seconds aloud.", "m": 3, "ms": ["A stopwatch has a better resolution / reads to 0.01 s.", "Counting aloud is less precise and varies between people.", "So the times are more accurate and repeatable."], "step": "Explain"}]}, {"key": "photosynthesis", "title": "Photosynthesis and plant food", "notes": ["Plants make glucose using light energy. This process is called photosynthesis. Carbon dioxide + water → glucose + oxygen.", "Chlorophyll is the green substance that absorbs light. Plants use glucose for respiration and growth. They can store extra glucose as starch.", "Plants use glucose for respiration, to make starch for storage, and to make cellulose for cell walls. The rate of photosynthesis increases with more light, more carbon dioxide or a warmer temperature, up to a limit. Photosynthesis happens in chloroplasts."], "worked": "Carbon dioxide enters a leaf from the air. Roots take in water and light is absorbed in the leaf. The glucose made can be used to build cellulose for cell walls.", "question": "Write the photosynthesis word equation. Give two uses of the glucose made.", "scheme": ["Carbon dioxide + water → glucose + oxygen, using light.", "Glucose can be used in respiration.", "It can also be stored as starch or used to make cellulose for growth."], "mistake": "Plants make their food by photosynthesis. They do not get their food from soil.", "model": "photosynthesis", "id": "y8-unit-13-photosynthesis", "unit": "y8-unit-13", "year": 8, "number": 1, "marks": 3, "cards": [{"term": "Photosynthesis", "definition": "Using light to make glucose from carbon dioxide and water, releasing oxygen."}, {"term": "Chlorophyll", "definition": "The green substance that absorbs light for photosynthesis."}], "quiz": {"q": "Where does the carbon used to build much of a plant come from?", "opts": ["The light itself.", "Carbon dioxide in the air.", "Only minerals in the soil."], "a": 1, "why": "Photosynthesis uses carbon dioxide to make glucose that can be used for growth."}, "misconception": {"q": "Where does the carbon used to build much of a plant come from? Sam answers: “Only minerals in the soil.” Explain why this is wrong.", "m": 2, "ms": ["Carbon dioxide in the air.", "Photosynthesis uses carbon dioxide to make glucose that can be used for growth."]}, "more": [{"q": "Where in a plant cell does photosynthesis happen?", "opts": ["Chloroplasts.", "Mitochondria.", "Nucleus."], "a": 0, "why": "Chloroplasts contain chlorophyll."}, {"q": "Which gas is released by photosynthesis?", "opts": ["Carbon dioxide.", "Nitrogen.", "Oxygen."], "a": 2, "why": "Oxygen is a product."}, {"q": "Which increases the rate of photosynthesis (up to a limit)?", "opts": ["Less water.", "More light.", "Less carbon dioxide."], "a": 1, "why": "Light provides the energy."}, {"q": "Plants store glucose as…", "opts": ["starch.", "fat only.", "protein."], "a": 0, "why": "Starch is insoluble, so it is good for storage."}], "ladder": [{"q": "Write the word equation for photosynthesis.", "m": 1, "ms": ["Carbon dioxide + water → glucose + oxygen (using light energy)."], "step": "Remember"}, {"q": "Give two uses of the glucose made in photosynthesis.", "m": 2, "ms": ["Respiration to release energy / stored as starch.", "Making cellulose for cell walls / making proteins or fats."], "step": "Apply"}, {"q": "Explain why a plant in a dark cupboard eventually dies.", "m": 3, "ms": ["Without light it cannot photosynthesise.", "So it cannot make glucose.", "It uses up its stored food in respiration and runs out of energy."], "step": "Explain"}]}, {"key": "leaf", "title": "Leaves and plant growth", "notes": ["Leaves are broad, so they absorb lots of light. They are thin, so gases have a short distance to travel. Small pores called stomata let gases move in and out.", "A limiting factor is something in short supply that slows a process. Too little light or carbon dioxide can slow photosynthesis. An unsuitable temperature can also slow it. Many cells near the top of a leaf contain lots of chloroplasts. Veins carry water to the leaf and sugars away. Plants need nitrates to make proteins and magnesium to make chlorophyll.", "Inside the leaf, palisade cells near the top are packed with chloroplasts. Air spaces in the spongy layer let gases diffuse. Guard cells open and close stomata to control gas exchange and water loss."], "worked": "At first, brighter light can make photosynthesis faster. Eventually there may not be enough carbon dioxide to go faster. Adding more light alone then makes little difference.", "question": "Why might extra light eventually stop making photosynthesis faster?", "scheme": ["Light was in short supply at first.", "Another factor, such as carbon dioxide, is now in short supply.", "More light cannot solve the shortage of that other factor."], "mistake": "A limiting factor is the factor holding back the rate at that moment.", "model": "photosynthesis", "id": "y8-unit-13-leaf", "unit": "y8-unit-13", "year": 8, "number": 2, "marks": 3, "cards": [{"term": "Stoma", "definition": "A tiny pore in a leaf that lets gases pass in and out."}, {"term": "Limiting factor", "definition": "The thing in short supply that is holding back the rate."}], "quiz": {"q": "Why can extra light stop making photosynthesis faster?", "opts": ["Light has turned into soil minerals.", "Another factor, such as carbon dioxide, is now in short supply.", "The plant has stopped needing all energy."], "a": 1, "why": "Extra light does not fix a shortage of carbon dioxide or an unsuitable temperature."}, "misconception": {"q": "Why can extra light stop making photosynthesis faster? Sam answers: “The plant has stopped needing all energy.” Explain why this is wrong.", "m": 2, "ms": ["Another factor, such as carbon dioxide, is now in short supply.", "Extra light does not fix a shortage of carbon dioxide or an unsuitable temperature."]}, "more": [{"q": "Why are leaves thin?", "opts": ["Gases only have a short distance to diffuse.", "To make them heavy.", "To store water."], "a": 0, "why": "Short distance = faster diffusion."}, {"q": "What are stomata?", "opts": ["Roots in the soil.", "Seeds.", "Tiny pores that let gases in and out of the leaf."], "a": 2, "why": "Usually on the underside of the leaf."}, {"q": "Which cells contain the most chloroplasts?", "opts": ["Guard cells only.", "Palisade cells.", "Root hair cells."], "a": 1, "why": "They are near the top where light is strongest."}, {"q": "Why are leaves broad and flat?", "opts": ["To absorb as much light as possible.", "To lose water faster.", "To catch rain."], "a": 0, "why": "A large surface area captures more light."}], "ladder": [{"q": "What do guard cells do?", "m": 1, "ms": ["Open and close the stomata."], "step": "Remember"}, {"q": "Name the gas that enters the leaf for photosynthesis and how it gets in.", "m": 2, "ms": ["Carbon dioxide.", "It diffuses in through the stomata."], "step": "Apply"}, {"q": "Explain two ways a leaf is adapted for photosynthesis.", "m": 3, "ms": ["Broad and flat to absorb lots of light.", "Thin, with stomata and air spaces, so carbon dioxide diffuses in quickly.", "Palisade cells packed with chloroplasts near the upper surface."], "step": "Explain"}]}, {"key": "plant-practical", "title": "Investigating photosynthesis", "notes": ["Pondweed gives off oxygen during photosynthesis. You can compare oxygen made at different light levels. Keep temperature, time and carbon dioxide supply the same.", "Count bubbles for a simple estimate. Collecting gas volume can be better because bubbles have different sizes. Repeat measurements before comparing results.", "Move the lamp to different distances and count bubbles per minute. A glass tank of water between the lamp and the plant stops the lamp heating the water. The closer the lamp, the brighter the light and the more bubbles, up to a limit."], "worked": "Move a lamp closer to pondweed and count bubbles for one minute. Use a ruler to set each lamp distance. Watch for lamp heating, which could change the water temperature.", "question": "Give two problems with counting pondweed bubbles. Suggest one improvement.", "scheme": ["Bubbles can have different sizes.", "Some bubbles may be missed or gas may dissolve in the water.", "Collect gas volume over a set time and repeat readings."], "mistake": "A bubble count is an estimate of gas production, not an exact oxygen volume.", "model": null, "id": "y8-unit-13-plant-practical", "unit": "y8-unit-13", "year": 8, "number": 3, "marks": 3, "cards": [{"term": "Proxy", "definition": "A measurement used to estimate something else."}, {"term": "Destarching", "definition": "Keeping a plant in the dark long enough for stored starch to be used up."}], "quiz": {"q": "Why can gas volume be better than a bubble count?", "opts": ["Every bubble has the same volume.", "Bubble counts measure every oxygen molecule.", "Bubbles can have different sizes."], "a": 2, "why": "Counting ten large bubbles and ten small bubbles does not give the same gas volume."}, "misconception": {"q": "Why can gas volume be better than a bubble count? Sam answers: “Every bubble has the same volume.” Explain why this is wrong.", "m": 2, "ms": ["Bubbles can have different sizes.", "Counting ten large bubbles and ten small bubbles does not give the same gas volume."]}, "more": [{"q": "In the pondweed test, what is the independent variable?", "opts": ["Type of water.", "Light intensity (distance of the lamp).", "Number of bubbles."], "a": 1, "why": "You change the lamp distance."}, {"q": "What is the dependent variable?", "opts": ["Number of bubbles (or volume of oxygen) per minute.", "Distance of the lamp.", "Temperature."], "a": 0, "why": "You measure the bubbles."}, {"q": "Why might a heat shield be placed between the lamp and the plant?", "opts": ["To make the light brighter.", "To add carbon dioxide.", "To stop the lamp changing the water temperature."], "a": 2, "why": "Temperature is a control variable."}, {"q": "As the lamp moves closer, the bubble rate usually…", "opts": ["stays zero.", "increases.", "decreases."], "a": 1, "why": "More light, more photosynthesis."}], "ladder": [{"q": "Which gas is in the bubbles from the pondweed?", "m": 1, "ms": ["Oxygen."], "step": "Remember"}, {"q": "Give two control variables in the pondweed investigation.", "m": 2, "ms": ["Temperature of the water.", "Same pondweed / same amount of carbon dioxide (sodium hydrogencarbonate) / same time for counting."], "step": "Apply"}, {"q": "Explain why counting bubbles may not be an accurate way to measure the rate of photosynthesis.", "m": 3, "ms": ["Bubbles can be different sizes.", "Some oxygen dissolves in the water instead of forming bubbles.", "Collecting the gas in a measuring cylinder or syringe would be more accurate."], "step": "Explain"}]}, {"key": "investigate-candle", "title": "Testing a candle under a container", "notes": ["A candle needs oxygen to keep burning. Covering it limits the supply of fresh air. Only do a real candle test with teacher supervision.", "Change the container volume and measure burning time. Keep the candle, starting conditions and timing rule the same. The flame can go out before every bit of oxygen has been used.", "Use containers of different volumes and time how long the candle burns. A bigger container holds more air, so more oxygen. Plot volume on the x-axis and burning time on the y-axis."], "worked": "Use the same candle and containers of different measured volumes. Start timing when the container covers the candle. Stop when the flame goes out.", "question": "For a test of container volume and candle burning time, name what you change, what you measure and one control.", "scheme": ["Change the volume of the container.", "Measure the time until the flame goes out.", "Keep the candle or starting conditions the same."], "mistake": "Do not assume the candle uses up all the oxygen before it goes out.", "model": null, "id": "y8-unit-14-investigate-candle", "unit": "y8-unit-14", "year": 8, "number": 1, "marks": 3, "cards": [{"term": "Independent variable", "definition": "The thing you choose to change in a test."}, {"term": "Endpoint", "definition": "The clear event that tells you when to stop measuring."}], "quiz": {"q": "What should stay the same in a candle and container-volume test?", "opts": ["The candle and the rule for when timing stops.", "The container volume.", "Nothing."], "a": 0, "why": "Keep other things the same so you can compare the effect of container volume."}, "misconception": {"q": "What should stay the same in a candle and container-volume test? Sam answers: “The container volume.” Explain why this is wrong.", "m": 2, "ms": ["The candle and the rule for when timing stops.", "Keep other things the same so you can compare the effect of container volume."]}, "more": [{"q": "What is the independent variable?", "opts": ["Burning time.", "Candle colour.", "Volume of the container."], "a": 2, "why": "You choose the container."}, {"q": "Why does the candle go out?", "opts": ["The container gets cold.", "It uses up the oxygen in the container.", "The wax runs out at once."], "a": 1, "why": "Combustion needs oxygen."}, {"q": "A bigger container usually makes the candle burn…", "opts": ["for longer.", "for a shorter time.", "brighter but shorter."], "a": 0, "why": "More air means more oxygen."}, {"q": "Which is a control variable?", "opts": ["The burning time.", "The container volume.", "Using the same type and size of candle."], "a": 2, "why": "Different candles would be unfair."}], "ladder": [{"q": "What does a candle need to keep burning?", "m": 1, "ms": ["Oxygen (from the air)."], "step": "Remember"}, {"q": "Suggest two safety precautions for the candle investigation.", "m": 2, "ms": ["Use a heatproof mat and keep hair/paper away.", "Do not touch the hot container; work with teacher supervision."], "step": "Apply"}, {"q": "Explain why the burning time should be measured several times for each container.", "m": 3, "ms": ["Results can vary because of random errors, e.g. reaction time.", "Repeats let you spot anomalies.", "A mean of repeats is more reliable."], "step": "Explain"}]}, {"key": "investigate-bounce", "title": "Testing bouncing balls", "notes": ["A dropped ball transfers energy as it falls and bounces. Some energy heats the ball, floor and air. Some is carried away by sound.", "The ball usually rises to a lower height after the bounce. Compare balls using the same drop height and surface. Release each ball without pushing it.", "Drop the ball from different heights and measure the bounce height with a metre ruler held upright. Look at the bottom of the ball at eye level to avoid parallax error. The bounce height is usually less than the drop height."], "worked": "Drop two balls from the same measured height. Record the highest point after the first bounce. Repeat and compare their mean rebound heights.", "question": "Why does a ball usually bounce lower than its drop height? How would you compare two balls fairly?", "scheme": ["Some energy transfers to heating and sound.", "Less remains for the ball to rise again.", "Use the same drop height and surface, and release without pushing."], "mistake": "Energy has not vanished when the bounce is lower. Some has moved to the surroundings.", "model": null, "id": "y8-unit-14-investigate-bounce", "unit": "y8-unit-14", "year": 8, "number": 2, "marks": 3, "cards": [{"term": "Rebound height", "definition": "The highest point a ball reaches after a bounce."}, {"term": "Dissipation", "definition": "Energy spreading to the surroundings and becoming less useful."}], "quiz": {"q": "Why does a ball usually bounce lower than its drop height?", "opts": ["Energy is destroyed.", "Gravity switches off during the bounce.", "Some energy transfers to heating and sound."], "a": 2, "why": "Less energy remains for lifting the ball, but total energy is still conserved."}, "misconception": {"q": "Why does a ball usually bounce lower than its drop height? Sam answers: “Energy is destroyed.” Explain why this is wrong.", "m": 2, "ms": ["Some energy transfers to heating and sound.", "Less energy remains for lifting the ball, but total energy is still conserved."]}, "more": [{"q": "Why does a ball not bounce back to its starting height?", "opts": ["Gravity switches off.", "Some energy is transferred to heating and sound.", "Energy is destroyed."], "a": 1, "why": "Energy is dissipated to the surroundings."}, {"q": "How can you measure bounce height more accurately?", "opts": ["Film it in slow motion next to a ruler.", "Guess by eye from far away.", "Use a bathroom scale."], "a": 0, "why": "Video lets you pause at the top."}, {"q": "Which is the independent variable if you change the drop height?", "opts": ["Bounce height.", "Type of floor.", "Drop height."], "a": 2, "why": "You choose the drop height."}, {"q": "Reading the ruler at eye level avoids…", "opts": ["anomalies in mass.", "parallax error.", "random error from temperature."], "a": 1, "why": "Viewing at an angle misreads the scale."}], "ladder": [{"q": "Which energy store decreases as the ball falls?", "m": 1, "ms": ["Gravitational potential energy store."], "step": "Remember"}, {"q": "A ball is dropped from 100 cm and bounces to 60 cm. Calculate the bounce height as a percentage of the drop height.", "m": 2, "ms": ["60 ÷ 100 = 0.6.", "0.6 × 100 = 60%."], "step": "Apply"}, {"q": "Explain why a ball bounces lower on carpet than on a hard floor.", "m": 3, "ms": ["Carpet squashes more when the ball lands.", "More energy is transferred to the thermal store of the carpet (and sound).", "So less energy is returned to the ball’s kinetic and gravitational stores."], "step": "Explain"}]}, {"key": "investigate-bungee", "title": "Testing a stretchy cord", "notes": ["A stretched cord becomes longer. Extension is the extra length, not the total length. Extension = stretched length − original length.", "Change the load and measure the extension. Use the same cord and allow it to settle. Use small safe loads and keep the landing space clear.", "Add equal masses one at a time and measure the length each time. Calculate the extension by subtracting the original length. Plot load against extension to see the pattern."], "worked": "A cord starts at 20 cm and stretches to 28 cm. Its extension is 28 − 20 = 8 cm. Check that a test load will not reach the floor.", "question": "How do you find a cord's extension? Give two things to keep the same when testing loads.", "scheme": ["Subtract original length from stretched length.", "Keep the same cord and its starting length.", "Keep the measuring method and settling time the same."], "mistake": "Use a small model. Do not test a homemade bungee with a person.", "model": null, "id": "y8-unit-14-investigate-bungee", "unit": "y8-unit-14", "year": 8, "number": 3, "marks": 3, "cards": [{"term": "Extension", "definition": "Stretched length minus original length."}, {"term": "Elastic deformation", "definition": "A change of shape that reverses when the force is removed."}], "quiz": {"q": "A cord stretches from 20 cm to 28 cm. What is its extension?", "opts": ["8 cm.", "28 cm.", "48 cm."], "a": 0, "why": "Extension is the extra length: 28 − 20 = 8 cm."}, "misconception": {"q": "A cord stretches from 20 cm to 28 cm. What is its extension? Sam answers: “28 cm.” Explain why this is wrong.", "m": 2, "ms": ["8 cm.", "Extension is the extra length: 28 − 20 = 8 cm."]}, "more": [{"q": "A cord is 20 cm long and stretches to 26 cm. What is the extension?", "opts": ["26 cm.", "46 cm.", "6 cm."], "a": 2, "why": "26 − 20 = 6 cm."}, {"q": "What is the independent variable?", "opts": ["The colour of the cord.", "The load (weight) added.", "The extension."], "a": 1, "why": "You choose the load."}, {"q": "Why should you wear goggles?", "opts": ["The cord could snap and flick up.", "To see the ruler better.", "Because of chemicals."], "a": 0, "why": "A stretched cord stores energy."}, {"q": "If the cord does not return to its original length, it has been…", "opts": ["measured wrongly.", "heated.", "stretched beyond its elastic limit."], "a": 2, "why": "It is permanently deformed."}], "ladder": [{"q": "What is extension?", "m": 1, "ms": ["The extra length when something is stretched (stretched length − original length)."], "step": "Remember"}, {"q": "A cord’s extension is 4 cm with 2 N. Predict the extension with 4 N if it stretches evenly, and explain.", "m": 2, "ms": ["8 cm.", "Doubling the force doubles the extension (they are proportional)."], "step": "Apply"}, {"q": "Explain why the bungee cord in a real bungee jump must be tested carefully.", "m": 3, "ms": ["The cord must stretch enough to slow the jumper gently.", "It must not stretch so far that the jumper hits the ground.", "It must not go past its elastic limit or snap."], "step": "Explain"}]}, {"key": "investigate-conduction", "title": "Comparing heat transfer through metals", "notes": ["Conduction transfers energy through a material. Metals are usually good thermal conductors. A fair comparison changes the metal, not several other things.", "Use rods with the same length and thickness. Heat them in the same way for the same time. Use the same test for deciding how fast energy reaches the end.", "Fix rods of different metals to a heat source with wax or a temperature sensor at the far end. Time how long it takes for the wax to melt. The rods must be the same length and thickness."], "worked": "Two rods have matching sizes and start at the same temperature. One end of each receives the same heating. Compare what happens at the other ends.", "question": "Give two things to keep the same when comparing heat transfer through metal rods. Explain one.", "scheme": ["Use rods with the same length and thickness.", "Use the same heating and starting temperature.", "These controls stop size or heating differences from causing the result."], "mistake": "A thicker or shorter rod could change the result even if the metal stayed the same.", "model": null, "id": "y8-unit-14-investigate-conduction", "unit": "y8-unit-14", "year": 8, "number": 4, "marks": 3, "cards": [{"term": "Thermal conductor", "definition": "A material that transfers energy easily by conduction."}, {"term": "Fair comparison", "definition": "A test keeping other factors the same so one change can be compared."}], "quiz": {"q": "What must you control when comparing metal rods?", "opts": ["Rod size and the heating method.", "Nothing.", "Only the colour of the table."], "a": 0, "why": "A size or heating difference could change the result, even without changing the metal."}, "misconception": {"q": "What must you control when comparing metal rods? Sam answers: “Nothing.” Explain why this is wrong.", "m": 2, "ms": ["Rod size and the heating method.", "A size or heating difference could change the result, even without changing the metal."]}, "more": [{"q": "Which metal is usually the best thermal conductor?", "opts": ["Iron.", "Steel.", "Copper."], "a": 2, "why": "Copper conducts heat very well."}, {"q": "Why must all the rods be the same thickness?", "opts": ["So they melt.", "To make it a fair test.", "So they are heavier."], "a": 1, "why": "Thickness affects heat transfer."}, {"q": "What is the dependent variable?", "opts": ["Time for the wax to melt.", "Type of metal.", "Length of rod."], "a": 0, "why": "You measure the time."}, {"q": "Why are saucepan handles made of plastic or wood?", "opts": ["They are good conductors.", "They are cheap metals.", "They are poor conductors (insulators)."], "a": 2, "why": "They stop heat reaching your hand."}], "ladder": [{"q": "What is conduction?", "m": 1, "ms": ["Transfer of energy through a material by vibrating particles."], "step": "Remember"}, {"q": "Wax melts after 30 s on copper and 90 s on steel. Which is the better conductor and why?", "m": 2, "ms": ["Copper.", "Energy reached the end faster, so the wax melted sooner."], "step": "Apply"}, {"q": "Explain how energy is transferred along a metal rod.", "m": 3, "ms": ["Particles at the hot end vibrate more.", "They pass energy to neighbouring particles as they collide.", "In metals, free electrons also carry energy quickly along the rod."], "step": "Explain"}]}, {"key": "investigate-cupcake", "title": "Testing falling paper cases", "notes": ["A falling paper case has weight downwards and air resistance upwards. Air resistance increases as it speeds up. At terminal velocity these forces balance and its speed stays steady.", "Measure time over a known falling distance. Distance ÷ time gives average speed. One average cannot show whether speed stayed steady throughout.", "Drop paper cases from the same height and time the fall. Stack cases to change the mass without changing the shape. Heavier stacks usually reach a higher terminal velocity and land sooner."], "worked": "Time a case over two equal sections of its fall. Similar times suggest a similar speed in those sections. Repeat before deciding whether it reached a steady speed.", "question": "Why does one average speed not prove a falling paper case reached terminal velocity?", "scheme": ["Average speed covers the whole timed section.", "The case could have changed speed during that section.", "Compare speeds in separate sections to check whether it became steady."], "mistake": "Terminal velocity means steady speed with balanced forces, not the highest speed in every fall.", "model": null, "id": "y8-unit-14-investigate-cupcake", "unit": "y8-unit-14", "year": 8, "number": 5, "marks": 3, "cards": [{"term": "Drag", "definition": "A force that opposes movement through air or water."}, {"term": "Terminal velocity", "definition": "Steady falling speed when weight and drag balance."}], "quiz": {"q": "Does one average falling speed prove terminal velocity was reached?", "opts": ["No. Speed could have changed during the timed part.", "Yes, every average is a terminal velocity.", "Yes, if the object is made of paper."], "a": 0, "why": "Compare speeds in different parts of the fall to check whether speed became steady."}, "misconception": {"q": "Does one average falling speed prove terminal velocity was reached? Sam answers: “Yes, every average is a terminal velocity.” Explain why this is wrong.", "m": 2, "ms": ["No. Speed could have changed during the timed part.", "Compare speeds in different parts of the fall to check whether speed became steady."]}, "more": [{"q": "When a falling case reaches terminal velocity, the forces are…", "opts": ["unbalanced downwards.", "zero in total because weight disappears.", "balanced."], "a": 2, "why": "Air resistance equals weight."}, {"q": "Why stack cases to increase the mass?", "opts": ["So they fall slower.", "The shape stays the same, so it is a fair test.", "To make them bounce."], "a": 1, "why": "Only mass changes."}, {"q": "Air resistance increases when the case…", "opts": ["moves faster.", "stops.", "gets lighter."], "a": 0, "why": "Faster objects hit more air particles."}, {"q": "Which forces act on a falling paper case?", "opts": ["Friction and thrust.", "Upthrust and magnetism.", "Weight down and air resistance up."], "a": 2, "why": "Two main forces act."}], "ladder": [{"q": "What is terminal velocity?", "m": 1, "ms": ["The steady top speed reached when air resistance equals weight."], "step": "Remember"}, {"q": "Describe how the speed of a dropped paper case changes as it falls.", "m": 2, "ms": ["It speeds up at first because weight is greater than air resistance.", "Air resistance increases until it equals weight, then it falls at a steady speed."], "step": "Apply"}, {"q": "Explain why a stack of four cases lands sooner than one case.", "m": 3, "ms": ["The stack has more weight but the same shape.", "It must fall faster before air resistance balances its weight.", "So its terminal velocity is higher and it lands sooner."], "step": "Explain"}]}, {"key": "investigate-salt", "title": "Testing how quickly salt dissolves", "notes": ["Salt dissolves in water to make a solution. Dissolving time is the time until the solid has dissolved. Keep stirring, water volume and temperature the same.", "A saturated solution cannot dissolve more salt at that temperature. Extra salt then remains as solid. That makes a “time until all dissolved” test impossible to finish.", "Measure the time for a fixed mass of salt to dissolve in water at different temperatures. Stir the same way each time, or not at all. Warmer water usually dissolves salt faster."], "worked": "Add a small measured salt mass and time it. Repeat with other masses using fresh water each time. Stop increasing the mass before the solution becomes saturated.", "question": "Why is a dissolving-time test difficult once the solution is saturated?", "scheme": ["The solution cannot dissolve any more salt at that temperature.", "Some solid salt remains.", "There is no finishing time when “all the salt has dissolved”."], "mistake": "Faster dissolving and greater solubility are different ideas.", "model": null, "id": "y8-unit-14-investigate-salt", "unit": "y8-unit-14", "year": 8, "number": 6, "marks": 3, "cards": [{"term": "Solubility", "definition": "The maximum amount that dissolves in a given amount of solvent at a set temperature."}, {"term": "Dissolving rate", "definition": "How quickly a substance dissolves."}], "quiz": {"q": "What happens if extra salt is added to a saturated solution?", "opts": ["The salt becomes a different element.", "Some salt remains undissolved.", "All extra salt dissolves instantly."], "a": 1, "why": "No more can dissolve at that temperature, so some stays as a solid."}, "misconception": {"q": "What happens if extra salt is added to a saturated solution? Sam answers: “All extra salt dissolves instantly.” Explain why this is wrong.", "m": 2, "ms": ["Some salt remains undissolved.", "No more can dissolve at that temperature, so some stays as a solid."]}, "more": [{"q": "What is the independent variable if you change water temperature?", "opts": ["Temperature of the water.", "Dissolving time.", "Mass of salt."], "a": 0, "why": "You choose the temperature."}, {"q": "Why does salt dissolve faster in warm water?", "opts": ["Warm water is heavier.", "Salt melts.", "Water particles move faster and break up the solid more quickly."], "a": 2, "why": "Faster particles collide more."}, {"q": "Which is a control variable?", "opts": ["Water temperature.", "Mass of salt.", "Dissolving time."], "a": 1, "why": "Keep it the same."}, {"q": "Stirring makes salt dissolve…", "opts": ["faster.", "slower.", "not at all."], "a": 0, "why": "Stirring brings fresh water to the salt."}], "ladder": [{"q": "What does soluble mean?", "m": 1, "ms": ["Able to dissolve in a liquid."], "step": "Remember"}, {"q": "Times to dissolve: 20 °C = 60 s, 40 °C = 35 s, 60 °C = 20 s. Describe the pattern.", "m": 2, "ms": ["As temperature increases, the dissolving time decreases.", "So salt dissolves faster in warmer water."], "step": "Apply"}, {"q": "Explain why it is hard to decide exactly when the salt has finished dissolving, and how to improve this.", "m": 3, "ms": ["It is difficult to see the last tiny grains.", "Different people judge the end point differently.", "Use a black background/light or a conductivity meter to judge the end point consistently."], "step": "Explain"}]}, {"key": "investigate-diffusion", "title": "Testing how colour spreads in water", "notes": ["Dissolved colour particles spread by diffusion. Particles usually move faster in warmer water. Moving currents in the water can also carry the colour.", "Use the same dye amount and water volume. Use matching containers and do not stir. Let the water settle before adding the dye.", "Add one drop of food colouring to still water at different temperatures and time how long it takes to spread evenly. Do not stir or move the beaker. Warmer water spreads colour faster."], "worked": "Put the same dye drop into warm and cool water. Compare how far the colour spreads after the same time. Remember that warm water currents may also move it.", "question": "Give two controls for comparing dye in warm and cool water. Give one reason the test is not a perfect measure of diffusion.", "scheme": ["Keep dye amount and water volume the same.", "Use matching containers and no stirring.", "Convection currents can also carry the colour, so not all spreading is due to diffusion."], "mistake": "Water moving as a whole is convection, not just diffusion.", "model": null, "id": "y8-unit-14-investigate-diffusion", "unit": "y8-unit-14", "year": 8, "number": 7, "marks": 3, "cards": [{"term": "Diffusion", "definition": "Particles spreading from higher to lower concentration."}, {"term": "Convection", "definition": "Energy transfer as a liquid or gas moves from place to place."}], "quiz": {"q": "What else can spread dye in a warm-water test besides diffusion?", "opts": ["The dye turning into light.", "The water particles becoming larger.", "Convection currents moving the coloured water."], "a": 2, "why": "Moving water carries dye with it, so the test does not show diffusion alone."}, "misconception": {"q": "What else can spread dye in a warm-water test besides diffusion? Sam answers: “The dye turning into light.” Explain why this is wrong.", "m": 2, "ms": ["Convection currents moving the coloured water.", "Moving water carries dye with it, so the test does not show diffusion alone."]}, "more": [{"q": "Why does colour spread faster in warm water?", "opts": ["Particles get bigger.", "The particles move faster.", "Warm water is a different colour."], "a": 1, "why": "Faster particles mix more quickly."}, {"q": "Why should you not stir the water?", "opts": ["Stirring would mix it, not diffusion.", "Stirring cools it.", "It is unsafe."], "a": 0, "why": "You want to measure diffusion only."}, {"q": "What is the dependent variable?", "opts": ["Water temperature.", "Size of beaker.", "Time for the colour to spread evenly."], "a": 2, "why": "You measure the time."}, {"q": "Diffusion happens from…", "opts": ["top to bottom only.", "high concentration to low concentration.", "low to high concentration."], "a": 1, "why": "Particles spread out."}], "ladder": [{"q": "What is diffusion?", "m": 1, "ms": ["The spreading of particles from high to low concentration."], "step": "Remember"}, {"q": "Give two control variables in the food colouring investigation.", "m": 2, "ms": ["Volume of water / size of beaker.", "Number of drops / type of food colouring / no stirring."], "step": "Apply"}, {"q": "Explain, using particles, why the colour spreads out even though nobody stirs the water.", "m": 3, "ms": ["All particles in a liquid are always moving randomly.", "Colour particles collide with water particles and move in all directions.", "Overall they spread from where there are many to where there are few."], "step": "Explain"}]}, {"key": "magnet", "title": "Magnets and magnetic fields", "notes": ["Magnets have a north pole and a south pole. Like poles repel and opposite poles attract. A magnetic field is the region where magnetic forces act.", "A compass needle is a small magnet. It turns to line up with the field. Outside a bar magnet, field arrows run from north to south.", "Magnetic materials include iron, nickel and cobalt. Field lines go from the north pole to the south pole, and lines close together show a stronger field. A compass needle is a small magnet that points along the field."], "worked": "A magnet attracts an unmagnetised iron nail. The nail does not have to be a permanent magnet. Repulsion gives stronger evidence that an object is itself a magnet.", "question": "Why does attraction alone not prove that a metal object is a permanent magnet?", "scheme": ["A magnet can attract unmagnetised iron.", "The iron can become temporarily magnetic near the magnet.", "Repulsion between like poles is better evidence that the object is a magnet."], "mistake": "Not every metal is attracted to a magnet.", "model": "electromagnet", "id": "y9-unit-01-magnet", "unit": "y9-unit-01", "year": 9, "number": 1, "marks": 3, "cards": [{"term": "Magnetic field", "definition": "The region where magnetic forces act."}, {"term": "Induced magnet", "definition": "A material that becomes magnetic near another magnet."}], "quiz": {"q": "Which is better evidence that an object is a magnet?", "opts": ["It is attracted to a magnet.", "It looks shiny.", "It repels one pole of a known magnet."], "a": 2, "why": "Unmagnetised iron can be attracted, but repulsion shows the object has a like magnetic pole."}, "misconception": {"q": "Which is better evidence that an object is a magnet? Sam answers: “It is attracted to a magnet.” Explain why this is wrong.", "m": 2, "ms": ["It repels one pole of a known magnet.", "Unmagnetised iron can be attracted, but repulsion shows the object has a like magnetic pole."]}, "more": [{"q": "Which metal is magnetic?", "opts": ["Aluminium.", "Iron.", "Copper."], "a": 1, "why": "Iron, nickel and cobalt are magnetic."}, {"q": "Two north poles placed together will…", "opts": ["repel.", "attract.", "do nothing."], "a": 0, "why": "Like poles repel."}, {"q": "Magnetic field lines point from…", "opts": ["south to north.", "the middle outwards only.", "north to south."], "a": 2, "why": "By convention, N to S outside the magnet."}, {"q": "Where is a bar magnet’s field strongest?", "opts": ["Far away from it.", "At the poles.", "In the middle."], "a": 1, "why": "Field lines are closest at the poles."}], "ladder": [{"q": "Name a magnetic material.", "m": 1, "ms": ["Iron / nickel / cobalt / steel."], "step": "Remember"}, {"q": "Describe how to show the shape of a bar magnet’s field.", "m": 2, "ms": ["Place a plotting compass near the magnet and mark where the needle points.", "Move it along and join the marks with lines (or sprinkle iron filings on paper over the magnet)."], "step": "Apply"}, {"q": "Explain why a compass needle points north on Earth.", "m": 3, "ms": ["The needle is a small magnet.", "Earth has a magnetic field, like a giant bar magnet.", "The needle lines up with Earth’s field, pointing towards the magnetic pole in the north."], "step": "Explain"}]}, {"key": "electromagnet", "title": "Making an electromagnet", "notes": ["Current in a wire produces a magnetic field. Coiling the wire makes a stronger field. An iron core can make the electromagnet stronger still.", "More coil turns can make it stronger at the same current. A larger current can also make it stronger. Switching the current off lets you control the magnet.", "Electromagnets can be turned on and off, which is why they are used in scrapyard cranes, door locks and electric bells. Reversing the current reverses the poles. The field of a coil looks like a bar magnet's field."], "worked": "To test coil turns fairly, keep the current the same. Use the same iron core each time. A relay uses an electromagnet to operate a switch.", "question": "Give two ways to strengthen an electromagnet. Name one control for testing the number of turns.", "scheme": ["Increase the current.", "Add more coil turns or an iron core.", "Keep current and the core the same when comparing coil turns."], "mistake": "Do not assume the current stays the same when you change the coil.", "model": "electromagnet", "id": "y9-unit-01-electromagnet", "unit": "y9-unit-01", "year": 9, "number": 2, "marks": 3, "cards": [{"term": "Electromagnet", "definition": "A magnet made by an electric current in a coil."}, {"term": "Relay", "definition": "A switch operated by an electromagnet."}], "quiz": {"q": "How can you make an electromagnet stronger?", "opts": ["Remove all the turns.", "Switch the current off.", "Increase current or add more turns under fair conditions."], "a": 2, "why": "More current and more coil turns can make a stronger field. Control other factors when testing one change."}, "misconception": {"q": "How can you make an electromagnet stronger? Sam answers: “Remove all the turns.” Explain why this is wrong.", "m": 2, "ms": ["Increase current or add more turns under fair conditions.", "More current and more coil turns can make a stronger field. Control other factors when testing one change."]}, "more": [{"q": "Give one way to make an electromagnet stronger.", "opts": ["Reduce the current.", "Add more turns of wire.", "Use a plastic core."], "a": 1, "why": "More coils give a stronger field."}, {"q": "Why are electromagnets used in scrapyard cranes?", "opts": ["They can be switched off to drop the metal.", "They are permanent magnets.", "They do not need electricity."], "a": 0, "why": "Switching off releases the load."}, {"q": "Reversing the current in an electromagnet…", "opts": ["makes it stronger.", "turns it into copper.", "swaps the north and south poles."], "a": 2, "why": "Field direction depends on current direction."}, {"q": "Which core makes an electromagnet strongest?", "opts": ["Plastic.", "Iron.", "Wood."], "a": 1, "why": "Iron is magnetic and concentrates the field."}], "ladder": [{"q": "What is an electromagnet?", "m": 1, "ms": ["A coil of wire that becomes magnetic when a current flows through it."], "step": "Remember"}, {"q": "Give two ways to increase the strength of an electromagnet.", "m": 2, "ms": ["More turns (coils) of wire.", "A larger current / an iron core."], "step": "Apply"}, {"q": "Explain why an electromagnet is more useful than a permanent magnet in an electric door lock.", "m": 3, "ms": ["The electromagnet can be turned on and off with a switch.", "When on it holds the door locked; when off it releases.", "A permanent magnet cannot be switched off."], "step": "Explain"}]}, {"key": "planning", "title": "Planning tests and taking measurements", "notes": ["Write steps that someone else could follow. Say what to measure and which units to use. Choose equipment that can measure the small changes you expect.", "Check that your equipment reads zero before you start. Repeat each measurement to spot results that do not fit. Calculate a mean by adding the readings and dividing by their number.", "Choose a sensible range and interval, such as 20 °C to 60 °C in steps of 10 °C. Repeat readings and calculate a mean. Write a method in numbered steps."], "worked": "Suppose ten pendulum swings take 12 seconds. One swing takes 12 ÷ 10 = 1.2 seconds. Timing several swings reduces the effect of your reaction time.", "question": "How could you improve the time measurement for one pendulum swing? Give two ideas and explain one.", "scheme": ["Time several swings, then divide by the number of swings.", "Repeat the measurement and calculate a mean.", "Use the same point to start and stop timing."], "mistake": "Repeating readings will not fix a clock that always reads too high.", "model": null, "id": "y9-unit-01-planning", "unit": "y9-unit-01", "year": 9, "number": 3, "marks": 3, "cards": [{"term": "Resolution", "definition": "The smallest change a measuring instrument can show."}, {"term": "Repeatability", "definition": "Getting similar results when the same person repeats the same test."}], "quiz": {"q": "Why time ten swings instead of one?", "opts": ["It reduces the effect of your reaction time on each swing's time.", "It fixes every equipment error.", "It makes the clock perfect."], "a": 0, "why": "Divide the longer total time by ten. Your reaction time then has a smaller effect on each swing's time."}, "misconception": {"q": "Why time ten swings instead of one? Sam answers: “It fixes every equipment error.” Explain why this is wrong.", "m": 2, "ms": ["It reduces the effect of your reaction time on each swing's time.", "Divide the longer total time by ten. Your reaction time then has a smaller effect on each swing's time."]}, "more": [{"q": "Which instrument best measures 25 cm³ of water?", "opts": ["A beaker.", "A thermometer.", "A measuring cylinder."], "a": 2, "why": "A measuring cylinder has a scale for volume."}, {"q": "How do you calculate a mean of three repeats?", "opts": ["Subtract the smallest from the largest.", "Add the three values and divide by 3.", "Choose the middle value only."], "a": 1, "why": "Mean = total ÷ number of values."}, {"q": "A ruler marked in mm has a resolution of…", "opts": ["1 mm.", "1 cm.", "1 m."], "a": 0, "why": "It can show changes as small as 1 mm."}, {"q": "Why should you repeat measurements?", "opts": ["To make the test unfair.", "Because the first result is always wrong.", "To spot anomalies and get a more reliable mean."], "a": 2, "why": "Repeats show whether results agree."}], "ladder": [{"q": "What is meant by the resolution of an instrument?", "m": 1, "ms": ["The smallest change it can show."], "step": "Remember"}, {"q": "Times measured: 12.1 s, 12.5 s, 12.3 s. Calculate the mean time.", "m": 2, "ms": ["12.1 + 12.5 + 12.3 = 36.9 s.", "36.9 ÷ 3 = 12.3 s."], "step": "Apply"}, {"q": "Explain why a stopwatch is better than counting seconds aloud.", "m": 3, "ms": ["A stopwatch has a better resolution / reads to 0.01 s.", "Counting aloud is less precise and varies between people.", "So the times are more accurate and repeatable."], "step": "Explain"}]}, {"key": "work", "title": "Work done and simple machines", "notes": ["Work is done when a force moves an object. It transfers energy. Work done = force × distance moved in the force's direction.", "Work is measured in joules, J. A simple machine can reduce the force you need. You then have to move that force over a greater distance.", "Simple machines such as levers, ramps and pulleys make jobs easier by reducing the force needed. You must move the force through a bigger distance, so the work done is not reduced. 1 joule of work is done when a 1 N force moves 1 m."], "worked": "A 25 N force moves a load 4 m in its direction. Work done = 25 × 4 = 100 J. A pulley cannot create extra energy.", "question": "A 25 N force moves a load 4 m in its direction. Find the work done. Why can a machine not create extra energy?", "scheme": ["Work done = 25 × 4.", "Work done = 100 J.", "Energy is conserved: a smaller effort force must move further, and real machines also waste some energy."], "mistake": "Reducing the force with a machine does not give free energy.", "model": null, "id": "y9-unit-02-work", "unit": "y9-unit-02", "year": 9, "number": 1, "marks": 3, "cards": [{"term": "Work done", "definition": "Energy transferred when a force moves something through a distance."}, {"term": "Simple machine", "definition": "A device that can reduce a force by making it act over a greater distance."}], "quiz": {"q": "A perfect pulley halves the lifting force. What else changes?", "opts": ["The load has no weight.", "You pull the rope twice as far.", "You get twice as much energy for free."], "a": 1, "why": "A smaller force acts over a longer distance. The machine does not create energy."}, "misconception": {"q": "A perfect pulley halves the lifting force. What else changes? Sam answers: “You get twice as much energy for free.” Explain why this is wrong.", "m": 2, "ms": ["You pull the rope twice as far.", "A smaller force acts over a longer distance. The machine does not create energy."]}, "more": [{"q": "A 50 N force pushes a box 4 m. How much work is done?", "opts": ["200 J.", "54 J.", "12.5 J."], "a": 0, "why": "W = F × d = 50 × 4."}, {"q": "What is the unit of work done?", "opts": ["Newton (N).", "Watt (W).", "Joule (J)."], "a": 2, "why": "Work is energy transferred."}, {"q": "A ramp lets you lift a load using…", "opts": ["no force.", "a smaller force over a longer distance.", "a bigger force over a shorter distance."], "a": 1, "why": "Work done is about the same."}, {"q": "No work is done if…", "opts": ["the object does not move.", "the force is large.", "you push horizontally."], "a": 0, "why": "Distance moved is zero."}], "ladder": [{"q": "Write the equation for work done.", "m": 1, "ms": ["Work done = force × distance moved (in the direction of the force)."], "step": "Remember"}, {"q": "A crane lifts a 2000 N load through 15 m. Calculate the work done.", "m": 2, "ms": ["W = 2000 × 15.", "= 30 000 J."], "step": "Apply"}, {"q": "Explain why pushing a heavy box up a ramp is easier than lifting it straight up, even though the work done is about the same.", "m": 3, "ms": ["The ramp means you push the box over a longer distance.", "So a smaller force is needed.", "Work = force × distance, so a smaller force over a longer distance transfers about the same energy."], "step": "Explain"}]}, {"key": "food-energy", "title": "Comparing energy in foods", "notes": ["Food has a chemical energy store. Burning a food sample can heat water. A larger water temperature rise can suggest more energy was transferred.", "Compare energy for the same mass of food, such as one gram. Some energy heats the air and equipment instead of the water. Only use your teacher's method for burning foods.", "Food labels show energy in kilojoules (kJ). An active teenager needs more energy each day than someone who is less active. Eating more energy than you use is stored, often as fat."], "worked": "Two food samples may have different masses. A bigger sample could heat more water even if it gives less energy per gram. Divide the energy by the mass to compare them fairly.", "question": "Give two problems with comparing foods by burning them below water. Explain how one affects the result.", "scheme": ["Some energy heats the air or the equipment rather than the water.", "The food may not burn completely.", "These effects make the measured energy lower than the energy available in the food."], "mistake": "The temperature rise alone is not the total energy in the food.", "model": null, "id": "y9-unit-02-food-energy", "unit": "y9-unit-02", "year": 9, "number": 2, "marks": 3, "cards": [{"term": "Chemical energy store", "definition": "Energy stored in substances such as food, fuels and batteries."}, {"term": "Energy per gram", "definition": "The energy for each gram of a substance."}], "quiz": {"q": "Why compare food energy per gram?", "opts": ["Every food contains the same energy.", "The food samples might have different masses.", "A water temperature rise measures all the food's energy perfectly."], "a": 1, "why": "Comparing equal masses makes the comparison fairer."}, "misconception": {"q": "Why compare food energy per gram? Sam answers: “A water temperature rise measures all the food's energy perfectly.” Explain why this is wrong.", "m": 2, "ms": ["The food samples might have different masses.", "Comparing equal masses makes the comparison fairer."]}, "more": [{"q": "Food energy on labels is usually given in…", "opts": ["kilojoules (kJ).", "newtons (N).", "watts (W)."], "a": 0, "why": "1 kJ = 1000 J."}, {"q": "Who needs the most energy each day?", "opts": ["A sleeping adult.", "A small child resting.", "An active teenager who plays lots of sport."], "a": 2, "why": "Activity and growth need more energy."}, {"q": "Why compare foods using the same mass?", "opts": ["To change the dependent variable.", "To make the test fair.", "To make the food burn."], "a": 1, "why": "Different masses would hold different amounts of energy."}, {"q": "In the burning food test, why might results be too low?", "opts": ["Energy heats the air and equipment, not just the water.", "The water is too clean.", "The food has too much energy."], "a": 0, "why": "Not all energy reaches the water."}], "ladder": [{"q": "In which store is energy kept in food?", "m": 1, "ms": ["Chemical store."], "step": "Remember"}, {"q": "A crisp raises the water temperature by 15 °C and a peanut by 25 °C. Which transferred more energy, and how can you tell?", "m": 2, "ms": ["The peanut.", "It caused a bigger temperature rise in the same water."], "step": "Apply"}, {"q": "Explain one way to improve the burning-food experiment.", "m": 3, "ms": ["Use the same mass of each food / insulate the tube / keep the food close to the tube.", "This reduces energy lost to the surroundings or makes the test fair.", "So the temperature rise better represents the energy in the food."], "step": "Explain"}]}, {"key": "moments", "title": "Levers and turning forces", "notes": ["A force can turn an object around a pivot. The turning effect is called a moment. A pivot is the point the object turns about.", "Moment = force × perpendicular distance from the pivot. Perpendicular means at right angles to the force's line. A balanced lever has equal clockwise and anticlockwise moments.", "A lever can multiply force: a small force far from the pivot can balance a large force close to the pivot. When a seesaw balances, clockwise moments equal anticlockwise moments. Moment is measured in newton metres, N m."], "worked": "A 12 N force acts 0.5 m from a pivot. Its moment is 12 × 0.5 = 6 N m. A force on the other side at 0.3 m must be 6 ÷ 0.3 = 20 N.", "question": "A 12 N force acts 0.5 m from a pivot. What opposite turning force at 0.3 m will balance it?", "scheme": ["First moment = 12 × 0.5 = 6 N m.", "For balance, the other moment must also be 6 N m.", "Other force = 6 ÷ 0.3 = 20 N."], "mistake": "Use the right-angle distance to the force's line, not any distance from the pivot.", "model": "lever", "id": "y9-unit-02-moments", "unit": "y9-unit-02", "year": 9, "number": 3, "marks": 3, "cards": [{"term": "Moment", "definition": "The turning effect of a force around a pivot."}, {"term": "Pivot", "definition": "The point an object turns around."}], "quiz": {"q": "Which distance is used to calculate a moment?", "opts": ["The right-angle distance from the pivot to the force's line.", "Any sloping distance from the pivot.", "The total length of the object in every case."], "a": 0, "why": "Moment uses the perpendicular, or right-angle, distance."}, "misconception": {"q": "Which distance is used to calculate a moment? Sam answers: “Any sloping distance from the pivot.” Explain why this is wrong.", "m": 2, "ms": ["The right-angle distance from the pivot to the force's line.", "Moment uses the perpendicular, or right-angle, distance."]}, "more": [{"q": "A 20 N force acts 3 m from a pivot. What is the moment?", "opts": ["23 N m.", "6.7 N m.", "60 N m."], "a": 2, "why": "M = F × d."}, {"q": "What is the unit of moment?", "opts": ["Joule only.", "Newton metre (N m).", "Newton (N)."], "a": 1, "why": "Force × distance."}, {"q": "Why is a long spanner easier to use?", "opts": ["The bigger distance gives a bigger moment for the same force.", "It is heavier.", "It makes the nut smaller."], "a": 0, "why": "Moment = F × d."}, {"q": "A seesaw balances when…", "opts": ["both people weigh the same, always.", "the pivot moves.", "clockwise moments equal anticlockwise moments."], "a": 2, "why": "This is the principle of moments."}], "ladder": [{"q": "What is a pivot?", "m": 1, "ms": ["The point that an object turns about."], "step": "Remember"}, {"q": "A 300 N child sits 2 m from the pivot of a seesaw. How far from the pivot must a 400 N child sit on the other side to balance?", "m": 2, "ms": ["300 × 2 = 600 N m.", "600 ÷ 400 = 1.5 m."], "step": "Apply"}, {"q": "Explain why a door handle is placed far from the hinges.", "m": 3, "ms": ["The hinge is the pivot.", "A bigger distance from the pivot gives a bigger moment for the same force.", "So less force is needed to open the door."], "step": "Explain"}]}, {"key": "thermal", "title": "Temperature and heating", "notes": ["Temperature tells you how hot or cold something is. Heating transfers energy from a warmer object to a cooler one. A thermal energy store also depends on the amount and type of material.", "Conduction transfers energy through a material. Particles pass energy to nearby particles. Metals conduct well; many plastics and trapped air conduct poorly.", "Temperature is measured in degrees Celsius with a thermometer. The energy needed to heat something depends on its mass, the material and the temperature rise. Energy always flows from hot to cold until they reach the same temperature."], "worked": "A hot cup contains less water than a warm bath. Temperature alone cannot tell you which has the larger thermal energy store. You must also consider the mass and material.", "question": "Why can temperature alone not compare the thermal energy stores of a cup of water and a bath?", "scheme": ["Temperature shows how hot the water is.", "The amount of water also affects the energy store.", "A bath has much more water, so a cooler bath can have a larger store."], "mistake": "Temperature and the amount of stored energy are not the same quantity.", "model": null, "id": "y9-unit-03-thermal", "unit": "y9-unit-03", "year": 9, "number": 1, "marks": 3, "cards": [{"term": "Temperature", "definition": "A measure of how hot or cold something is."}, {"term": "Conduction", "definition": "Energy transfer through a material without the material flowing as a whole."}], "quiz": {"q": "Must a hot small cup have more thermal energy than a cooler bath?", "opts": ["Yes. Temperature is the only factor.", "Yes. Cups always hold more water than baths.", "No. The mass of water also matters."], "a": 2, "why": "A bath can have a larger energy store because it holds much more water."}, "misconception": {"q": "Must a hot small cup have more thermal energy than a cooler bath? Sam answers: “Yes. Temperature is the only factor.” Explain why this is wrong.", "m": 2, "ms": ["No. The mass of water also matters.", "A bath can have a larger energy store because it holds much more water."]}, "more": [{"q": "Energy flows from a hot cup of tea to…", "opts": ["nowhere.", "the cooler surroundings.", "the hotter surroundings."], "a": 1, "why": "Heat flows from hot to cold."}, {"q": "A bath of warm water has more thermal energy than a cup of boiling water because…", "opts": ["it has much more mass.", "it is hotter.", "it is a different liquid."], "a": 0, "why": "Thermal energy depends on mass too."}, {"q": "Which instrument measures temperature?", "opts": ["Newtonmeter.", "Ammeter.", "Thermometer."], "a": 2, "why": "Temperature is in °C."}, {"q": "Two objects at the same temperature…", "opts": ["are both cold.", "have no net energy transfer between them.", "always transfer energy."], "a": 1, "why": "This is thermal equilibrium."}], "ladder": [{"q": "What is the unit of temperature in school science?", "m": 1, "ms": ["Degrees Celsius (°C)."], "step": "Remember"}, {"q": "A drink cools from 70 °C to 25 °C in a 25 °C room. Describe what happens and why it stops cooling.", "m": 2, "ms": ["Energy transfers from the drink to the cooler room.", "It stops when the drink reaches room temperature (25 °C)."], "step": "Apply"}, {"q": "Explain why it takes longer to boil a full kettle than a half-full kettle.", "m": 3, "ms": ["A full kettle has a larger mass of water.", "More energy is needed to raise its temperature by the same amount.", "The kettle transfers energy at the same rate, so it takes longer."], "step": "Explain"}]}, {"key": "convection", "title": "Convection, radiation and insulation", "notes": ["In convection, warmer liquid or gas rises as cooler fluid sinks. This movement transfers energy. Thermal radiation transfers energy by infrared waves.", "Radiation can travel through empty space. Insulation slows unwanted energy transfer. Trapped air reduces conduction and stops large convection currents. A warmer liquid or gas expands and becomes less dense, so it rises.", "Shiny surfaces reflect infrared and dull black surfaces absorb and emit it best. Insulators such as foam, wool and trapped air reduce conduction and convection. Houses lose less energy with loft insulation, cavity wall insulation and double glazing."], "worked": "A coat traps layers of air close to your body. A shiny surface reflects much infrared radiation. Both can slow energy transfer to cooler surroundings.", "question": "How do trapped air and a shiny surface help keep something warm?", "scheme": ["Air is a poor conductor.", "Trapping it prevents large convection currents.", "A shiny surface reduces energy transfer by infrared radiation."], "mistake": "Heat is not a substance that rises. Warm fluids rise during convection.", "model": null, "id": "y9-unit-03-convection", "unit": "y9-unit-03", "year": 9, "number": 2, "marks": 3, "cards": [{"term": "Convection", "definition": "Energy transfer by the movement of a liquid or gas."}, {"term": "Thermal radiation", "definition": "Energy transfer by infrared waves."}, {"term": "Insulator", "definition": "A material or arrangement that slows energy transfer."}], "quiz": {"q": "Which method can transfer energy across empty space?", "opts": ["Convection.", "Conduction.", "Radiation."], "a": 2, "why": "Radiation needs no particles between objects. Conduction and convection do."}, "misconception": {"q": "Which method can transfer energy across empty space? Sam answers: “Convection.” Explain why this is wrong.", "m": 2, "ms": ["Radiation.", "Radiation needs no particles between objects. Conduction and convection do."]}, "more": [{"q": "Which surface is the best emitter of infrared?", "opts": ["White gloss.", "Dull black.", "Shiny silver."], "a": 1, "why": "Dark matt surfaces emit and absorb best."}, {"q": "Why is warm air in a room found near the ceiling?", "opts": ["Warm air is less dense, so it rises.", "Warm air is heavier.", "Ceilings attract heat."], "a": 0, "why": "This causes convection currents."}, {"q": "Loft insulation works mainly by…", "opts": ["reflecting sound.", "absorbing water.", "trapping air, which is a poor conductor."], "a": 2, "why": "Trapped air reduces conduction and convection."}, {"q": "Which energy transfer can happen through a vacuum?", "opts": ["Convection.", "Infrared radiation.", "Conduction."], "a": 1, "why": "Radiation does not need particles."}], "ladder": [{"q": "What is convection?", "m": 1, "ms": ["Energy transfer by a warm liquid or gas rising and cooler fluid sinking (a current)."], "step": "Remember"}, {"q": "Give two ways to reduce energy loss from a house.", "m": 2, "ms": ["Loft insulation / cavity wall insulation.", "Double glazing / draught excluders / carpets."], "step": "Apply"}, {"q": "Explain why a radiator heats the whole room even though it is only on one wall.", "m": 3, "ms": ["Air next to the radiator is heated and becomes less dense.", "The warm air rises and cooler air moves in to replace it.", "This sets up a convection current that carries energy around the room."], "step": "Explain"}]}, {"key": "atmosphere", "title": "The atmosphere and carbon cycle", "notes": ["The atmosphere is the layer of gases around Earth. Air is mainly nitrogen, with oxygen and small amounts of other gases. Carbon dioxide is one of those gases.", "Photosynthesis removes carbon dioxide from the air. Respiration and burning fuels add carbon dioxide. Carbon moves between air, living things, water and rocks in the carbon cycle.", "Air is about 78% nitrogen and 21% oxygen. Carbon moves between the air, living things and the oceans in the carbon cycle. Photosynthesis removes carbon dioxide; respiration, decay and burning release it."], "worked": "A tree takes carbon dioxide from the air as it grows. An animal eating plant food uses the carbon compounds. Respiration returns some carbon dioxide to the air.", "question": "Name two processes that add carbon dioxide to the air and one that removes it.", "scheme": ["Respiration adds carbon dioxide.", "Burning fuels adds carbon dioxide.", "Photosynthesis removes carbon dioxide."], "mistake": "Plants both photosynthesise and respire.", "model": null, "id": "y9-unit-04-atmosphere", "unit": "y9-unit-04", "year": 9, "number": 1, "marks": 3, "cards": [{"term": "Atmosphere", "definition": "The gases around a planet."}, {"term": "Carbon cycle", "definition": "Carbon moving between living things, air, water and rocks."}], "quiz": {"q": "Which process removes carbon dioxide from the air?", "opts": ["Photosynthesis.", "Burning fuels.", "Aerobic respiration."], "a": 0, "why": "Plants take in carbon dioxide and use it to make glucose."}, "misconception": {"q": "Which process removes carbon dioxide from the air? Sam answers: “Burning fuels.” Explain why this is wrong.", "m": 2, "ms": ["Photosynthesis.", "Plants take in carbon dioxide and use it to make glucose."]}, "more": [{"q": "Which gas makes up most of the air?", "opts": ["Oxygen.", "Carbon dioxide.", "Nitrogen."], "a": 2, "why": "About 78% nitrogen."}, {"q": "Which process removes carbon dioxide from the air?", "opts": ["Burning fossil fuels.", "Photosynthesis.", "Respiration."], "a": 1, "why": "Plants take in CO₂."}, {"q": "About what percentage of air is oxygen?", "opts": ["21%.", "78%.", "1%."], "a": 0, "why": "About one fifth."}, {"q": "Which process releases carbon dioxide?", "opts": ["Photosynthesis.", "Dissolving in rocks only.", "Decay by microorganisms."], "a": 2, "why": "Decomposers respire."}], "ladder": [{"q": "Name the process by which plants take carbon dioxide out of the air.", "m": 1, "ms": ["Photosynthesis."], "step": "Remember"}, {"q": "Give two processes that add carbon dioxide to the atmosphere.", "m": 2, "ms": ["Respiration / decay.", "Burning (combustion) of fossil fuels or wood."], "step": "Apply"}, {"q": "Explain how cutting down and burning forests affects the amount of carbon dioxide in the air.", "m": 3, "ms": ["Burning the trees releases carbon dioxide.", "Fewer trees means less photosynthesis.", "So less carbon dioxide is removed and its level in the air rises."], "step": "Explain"}]}, {"key": "climate", "title": "The greenhouse effect and climate", "notes": ["Climate describes weather patterns over many years. Greenhouse gases absorb infrared radiation leaving Earth. They send infrared radiation out in all directions, including back towards the surface.", "The natural greenhouse effect keeps Earth warmer. Human activities add extra greenhouse gases, including carbon dioxide. This strengthens warming and changes the climate.", "Burning fossil fuels and cutting down forests increase carbon dioxide levels. More greenhouse gases trap more energy, raising global temperatures. Effects include melting ice, rising sea levels and more extreme weather."], "worked": "Burning coal, oil and gas adds carbon dioxide to the air. More outgoing infrared radiation is absorbed. Earth warms until energy entering and leaving balance again.", "question": "How can adding carbon dioxide to the air cause global warming?", "scheme": ["Earth gives out infrared radiation.", "Extra carbon dioxide absorbs more of it and sends some back towards the surface.", "This changes the energy balance and warms Earth."], "mistake": "The greenhouse effect and the hole in the ozone layer are different issues.", "model": null, "id": "y9-unit-04-climate", "unit": "y9-unit-04", "year": 9, "number": 2, "marks": 3, "cards": [{"term": "Greenhouse gas", "definition": "A gas that absorbs infrared radiation and sends it out in all directions."}, {"term": "Climate", "definition": "The pattern of weather over many years."}], "quiz": {"q": "How do extra greenhouse gases increase warming?", "opts": ["They make a hole in the ozone layer as the main cause.", "They create sunlight.", "They absorb more outgoing infrared radiation and send some back towards the surface."], "a": 2, "why": "More energy is kept in Earth's surface and atmosphere until a new balance is reached."}, "misconception": {"q": "How do extra greenhouse gases increase warming? Sam answers: “They make a hole in the ozone layer as the main cause.” Explain why this is wrong.", "m": 2, "ms": ["They absorb more outgoing infrared radiation and send some back towards the surface.", "More energy is kept in Earth's surface and atmosphere until a new balance is reached."]}, "more": [{"q": "Which is a greenhouse gas?", "opts": ["Oxygen.", "Carbon dioxide.", "Nitrogen."], "a": 1, "why": "CO₂ absorbs infrared radiation."}, {"q": "What is a main cause of increasing carbon dioxide levels?", "opts": ["Burning fossil fuels.", "Planting trees.", "Using solar panels."], "a": 0, "why": "Combustion releases CO₂."}, {"q": "Which is an effect of global warming?", "opts": ["More ice at the poles.", "Colder summers everywhere.", "Rising sea levels."], "a": 2, "why": "Ice melts and water expands."}, {"q": "Weather is short-term; climate is…", "opts": ["one storm.", "the average weather over many years.", "tomorrow’s forecast."], "a": 1, "why": "Climate is long-term."}], "ladder": [{"q": "What is the greenhouse effect?", "m": 1, "ms": ["Gases in the atmosphere trapping energy and keeping Earth warm."], "step": "Remember"}, {"q": "Give two effects of climate change.", "m": 2, "ms": ["Rising sea levels / melting ice caps.", "More extreme weather / changes in where plants and animals can live."], "step": "Apply"}, {"q": "Explain how more carbon dioxide in the atmosphere leads to higher temperatures.", "m": 3, "ms": ["The Earth emits infrared radiation.", "Carbon dioxide absorbs it and sends some back towards the Earth.", "More carbon dioxide traps more energy, so the average temperature rises."], "step": "Explain"}]}, {"key": "extraction", "title": "Getting metals from rocks", "notes": ["An ore is rock containing enough useful material to make extraction worthwhile. Many ores contain metals joined to oxygen. Extraction separates the metal from its compound.", "Carbon can remove oxygen from oxides of metals less reactive than carbon. Removing oxygen is called reduction. More reactive metals may need electricity for extraction.", "Metals less reactive than carbon, such as iron, are extracted by heating the ore with carbon. Very reactive metals such as aluminium are extracted by electrolysis, which uses a lot of electricity. Gold is found as the pure metal because it is so unreactive."], "worked": "Iron is less reactive than carbon, so carbon can help extract it from iron oxide. Aluminium is more reactive than carbon. Aluminium is commonly extracted using electricity instead.", "question": "Why can carbon extract some metals from their oxides but is not normally used to extract aluminium?", "scheme": ["Carbon removes oxygen from oxides of metals less reactive than carbon.", "Aluminium is more reactive than carbon.", "Aluminium oxide therefore needs another method, usually electrolysis."], "mistake": "The extraction method depends on the metal's reactivity.", "model": null, "id": "y9-unit-05-extraction", "unit": "y9-unit-05", "year": 9, "number": 1, "marks": 3, "cards": [{"term": "Ore", "definition": "Rock containing enough useful material to make extraction worthwhile."}, {"term": "Reduction", "definition": "Removing oxygen from a metal oxide in these examples."}], "quiz": {"q": "Why is carbon not normally used to extract aluminium from its oxide?", "opts": ["Aluminium is less reactive than every metal.", "Carbon can extract every metal.", "Aluminium is more reactive than carbon."], "a": 2, "why": "Carbon cannot remove the oxygen from aluminium oxide by the usual carbon extraction method."}, "misconception": {"q": "Why is carbon not normally used to extract aluminium from its oxide? Sam answers: “Aluminium is less reactive than every metal.” Explain why this is wrong.", "m": 2, "ms": ["Aluminium is more reactive than carbon.", "Carbon cannot remove the oxygen from aluminium oxide by the usual carbon extraction method."]}, "more": [{"q": "How is iron extracted from its ore?", "opts": ["Dissolving in water.", "Heating with carbon.", "Electrolysis."], "a": 1, "why": "Carbon is more reactive than iron."}, {"q": "Why is gold found as the pure metal?", "opts": ["It is very unreactive.", "It is very reactive.", "It is magnetic."], "a": 0, "why": "It does not combine with oxygen."}, {"q": "Aluminium is extracted by electrolysis because…", "opts": ["it is less reactive than carbon.", "it is a gas.", "it is more reactive than carbon."], "a": 2, "why": "Carbon cannot take its oxygen."}, {"q": "What is an ore?", "opts": ["A type of fuel.", "A rock containing enough metal to be worth extracting.", "A pure metal."], "a": 1, "why": "Ores contain metal compounds."}], "ladder": [{"q": "What is an ore?", "m": 1, "ms": ["A rock containing enough metal (compound) to make extraction worthwhile."], "step": "Remember"}, {"q": "Complete the word equation: iron oxide + carbon → … + …", "m": 2, "ms": ["Iron.", "Carbon dioxide."], "step": "Apply"}, {"q": "Explain why copper can be extracted with carbon but aluminium cannot.", "m": 3, "ms": ["Carbon is more reactive than copper, so it can remove the oxygen from copper oxide.", "Aluminium is more reactive than carbon.", "So carbon cannot displace it, and electrolysis must be used."], "step": "Explain"}]}, {"key": "metals", "title": "Metals and reactivity", "notes": ["Metals usually conduct heat and electricity well. Many metals react with oxygen to make metal oxides. Gaining oxygen is called oxidation.", "Some metals react more easily than others. A more reactive metal can replace a less reactive metal in a compound. This is called displacement. Most metals can be shaped without breaking. Some non-metals are exceptions to the usual rules: graphite conducts electricity.", "The reactivity series lists metals from most to least reactive, for example potassium, sodium, calcium, magnesium, zinc, iron, copper, gold. Iron rusts when it reacts with oxygen and water. Gold does not react, so it stays shiny."], "worked": "Zinc is more reactive than copper. Zinc placed in copper sulfate solution can form zinc sulfate. Copper is left as a solid.", "question": "Zinc is more reactive than copper. What happens when zinc is put in copper sulfate solution? Explain why.", "scheme": ["Zinc displaces copper.", "Zinc sulfate and copper form.", "Zinc replaces copper because it is more reactive."], "mistake": "A less reactive metal cannot simply displace a more reactive one.", "model": null, "id": "y9-unit-05-metals", "unit": "y9-unit-05", "year": 9, "number": 2, "marks": 3, "cards": [{"term": "Displacement", "definition": "A more reactive element replacing a less reactive element in a compound."}, {"term": "Oxidation", "definition": "A reaction in which a substance gains oxygen, in these examples."}], "quiz": {"q": "Iron is more reactive than copper. Can copper displace iron from iron sulfate?", "opts": ["Yes, because all metals displace each other.", "Yes, because copper is coloured.", "No."], "a": 2, "why": "The more reactive metal displaces the less reactive metal, not the other way around."}, "misconception": {"q": "Iron is more reactive than copper. Can copper displace iron from iron sulfate? Sam answers: “Yes, because all metals displace each other.” Explain why this is wrong.", "m": 2, "ms": ["No.", "The more reactive metal displaces the less reactive metal, not the other way around."]}, "more": [{"q": "Which metal is most reactive?", "opts": ["Gold.", "Potassium.", "Iron."], "a": 1, "why": "Potassium is at the top of the reactivity series."}, {"q": "What two things does iron need to rust?", "opts": ["Oxygen and water.", "Hydrogen and salt.", "Light and heat."], "a": 0, "why": "Rust forms when iron reacts with both."}, {"q": "Why is gold used for jewellery?", "opts": ["It is very reactive.", "It is magnetic.", "It is unreactive, so it does not tarnish."], "a": 2, "why": "Gold stays shiny for a long time."}, {"q": "Magnesium burns in oxygen to make…", "opts": ["hydrogen.", "magnesium oxide.", "magnesium chloride."], "a": 1, "why": "Metal + oxygen → metal oxide."}], "ladder": [{"q": "Name the product when copper reacts with oxygen.", "m": 1, "ms": ["Copper oxide."], "step": "Remember"}, {"q": "Give two properties that most metals share.", "m": 2, "ms": ["Good conductors of heat and electricity.", "Shiny / malleable / high melting point / strong."], "step": "Apply"}, {"q": "Explain two ways to stop an iron gate rusting.", "m": 3, "ms": ["Paint it / cover it in oil or grease / galvanise it with zinc.", "This keeps out oxygen and water.", "Without both, iron cannot rust."], "step": "Explain"}]}, {"key": "recycle", "title": "Reusing and recycling metals", "notes": ["Reusing means using an item again. Recycling means processing waste material to make new products. Metals are often valuable to recycle.", "Recycling saves limited metal ores. It often uses less energy than extracting new metal. Collecting, sorting and processing waste still use energy and resources.", "Recycling metals uses less energy than extracting them from ores. It saves ores, which are finite, and reduces mining damage and landfill. Collecting and sorting waste does cost money and energy."], "worked": "An aluminium can can be collected and melted for new products. This reduces the need to mine more aluminium ore. The cans still need transport and sorting.", "question": "Give two benefits and one drawback of recycling metals.", "scheme": ["It saves limited metal ores.", "It often saves energy and reduces mining damage.", "Collection, transport and processing still use resources."], "mistake": "Recycling has costs and impacts, even when it is better than extracting new material.", "model": null, "id": "y9-unit-05-recycle", "unit": "y9-unit-05", "year": 9, "number": 3, "marks": 3, "cards": [{"term": "Reuse", "definition": "Using an item again."}, {"term": "Recycling", "definition": "Processing waste materials to make new products."}, {"term": "Life cycle", "definition": "The stages from getting raw materials to making, using and disposing of a product."}], "quiz": {"q": "Which statement about metal recycling is fair?", "opts": ["It has no benefits.", "It saves ores but collection and processing still use resources.", "It uses no energy at all."], "a": 1, "why": "Recycling can save ores and energy, but transport and processing still have costs."}, "misconception": {"q": "Which statement about metal recycling is fair? Sam answers: “It uses no energy at all.” Explain why this is wrong.", "m": 2, "ms": ["It saves ores but collection and processing still use resources.", "Recycling can save ores and energy, but transport and processing still have costs."]}, "more": [{"q": "Why is recycling aluminium cans useful?", "opts": ["It uses much less energy than extracting new aluminium.", "It makes cans heavier.", "It makes new ore."], "a": 0, "why": "Electrolysis uses lots of electricity."}, {"q": "Metal ores are a finite resource, which means they…", "opts": ["are renewable.", "grow back.", "will run out."], "a": 2, "why": "There is a limited amount."}, {"q": "A disadvantage of recycling is that…", "opts": ["it makes more landfill.", "collecting and sorting waste costs money and energy.", "it uses more ore."], "a": 1, "why": "Transport and sorting are needed."}, {"q": "Which is reusing rather than recycling?", "opts": ["Refilling a glass bottle.", "Melting cans to make new cans.", "Crushing cars for steel."], "a": 0, "why": "Reuse keeps the item as it is."}], "ladder": [{"q": "What is recycling?", "m": 1, "ms": ["Processing waste materials to make new products."], "step": "Remember"}, {"q": "Give two advantages of recycling steel.", "m": 2, "ms": ["Saves energy compared with extracting iron from ore.", "Saves iron ore / reduces mining / reduces landfill."], "step": "Apply"}, {"q": "Explain why recycling aluminium is especially good for the environment.", "m": 3, "ms": ["Extracting aluminium needs electrolysis, which uses a lot of electricity.", "Recycling uses only about 5% of that energy.", "Less electricity means less fossil fuel burned and less carbon dioxide released."], "step": "Explain"}]}, {"key": "selection", "title": "Evolution by natural selection", "notes": ["Living things in a species have inherited differences. Some differences help them survive in their environment. Survivors are more likely to reproduce and pass on their genes.", "Over many generations, a helpful inherited feature can become more common. This process is called natural selection. It acts on a population, not by changing one animal because it needs to adapt.", "Charles Darwin developed the theory of evolution by natural selection. Bacteria can become resistant to antibiotics by natural selection. Over many generations, a species changes as helpful features become more common."], "worked": "In a cold place, animals with thicker inherited fur may survive better. More of them reproduce and pass on genes for thicker fur. The feature may become more common over generations.", "question": "How can a helpful inherited feature become more common after the environment changes?", "scheme": ["Individuals already have inherited differences.", "Those with a helpful feature are more likely to survive and reproduce.", "They pass the feature on, so it becomes more common over generations."], "mistake": "An animal does not grow a new gene just because the environment changes.", "model": null, "id": "y9-unit-06-selection", "unit": "y9-unit-06", "year": 9, "number": 1, "marks": 3, "cards": [{"term": "Natural selection", "definition": "Helpful inherited features becoming more common through survival and reproduction over generations."}, {"term": "Inherited variation", "definition": "Differences passed on through genes from parents to offspring."}], "quiz": {"q": "What is needed for natural selection to change a population?", "opts": ["All individuals being exactly the same.", "Animals choosing new genes when needed.", "Inherited differences that affect survival and reproduction."], "a": 2, "why": "Survivors can pass helpful inherited features to their offspring."}, "misconception": {"q": "What is needed for natural selection to change a population? Sam answers: “All individuals being exactly the same.” Explain why this is wrong.", "m": 2, "ms": ["Inherited differences that affect survival and reproduction.", "Survivors can pass helpful inherited features to their offspring."]}, "more": [{"q": "Who proposed the theory of evolution by natural selection?", "opts": ["Marie Curie.", "Charles Darwin.", "Isaac Newton."], "a": 1, "why": "Darwin published in 1859."}, {"q": "In natural selection, which individuals are most likely to survive?", "opts": ["Those best adapted to the environment.", "The largest ones always.", "The youngest ones."], "a": 0, "why": "Helpful variations aid survival."}, {"q": "How do bacteria become resistant to antibiotics?", "opts": ["Antibiotics teach bacteria.", "Bacteria become larger.", "Resistant bacteria survive and reproduce."], "a": 2, "why": "Non-resistant ones are killed."}, {"q": "Why do helpful features become more common over time?", "opts": ["The environment creates new genes on purpose.", "Survivors pass on their genes to offspring.", "Animals choose to change."], "a": 1, "why": "Inherited features are passed on."}], "ladder": [{"q": "What is natural selection?", "m": 1, "ms": ["The process where individuals best suited to their environment survive and reproduce, passing on their genes."], "step": "Remember"}, {"q": "Give the two main steps after variation in natural selection.", "m": 2, "ms": ["Individuals with helpful features are more likely to survive (and reproduce).", "They pass on their genes, so the feature becomes more common."], "step": "Apply"}, {"q": "Explain how peppered moths became darker in polluted areas.", "m": 3, "ms": ["There was variation in colour; dark moths were camouflaged on sooty trees.", "Birds ate more pale moths, so more dark moths survived and reproduced.", "Dark moths passed on the gene, so dark moths became more common."], "step": "Explain"}]}, {"key": "evidence-evolution", "title": "Evidence for evolution", "notes": ["Evolution is change in inherited features over many generations. Fossils show that living things have changed over long periods. DNA similarities also help show how species are related.", "Darwin helped explain evolution by natural selection. Scientific explanations must be tested against evidence. A change during one lifetime is not always inherited.", "Fossils form when hard parts are replaced by minerals in rock over millions of years. Older rock layers usually contain simpler fossils. The fossil record is incomplete because most dead organisms decay before they can fossilise."], "worked": "Training can make a person's muscles larger. That does not mean their children inherit those larger trained muscles. Inherited evolution depends on genes passed between generations.", "question": "Why is building bigger muscles through training not the same as inherited evolution?", "scheme": ["Training changes an individual during their lifetime.", "The larger trained muscles are not directly passed on in genes.", "Inherited evolution involves changes passed on across generations."], "mistake": "A scientific theory is an explanation supported by evidence, not just a guess.", "model": null, "id": "y9-unit-06-evidence-evolution", "unit": "y9-unit-06", "year": 9, "number": 2, "marks": 3, "cards": [{"term": "Scientific theory", "definition": "An explanation supported by evidence and testing."}, {"term": "Acquired characteristic", "definition": "A feature gained during a lifetime, such as a scar."}], "quiz": {"q": "Why is muscle training not the same as inherited evolution?", "opts": ["The larger trained muscles are not directly passed on in genes.", "All exercise creates a new species.", "Children inherit every change their parents experience."], "a": 0, "why": "Training changes an individual. Inherited evolution involves changes passed on across generations."}, "misconception": {"q": "Why is muscle training not the same as inherited evolution? Sam answers: “All exercise creates a new species.” Explain why this is wrong.", "m": 2, "ms": ["The larger trained muscles are not directly passed on in genes.", "Training changes an individual. Inherited evolution involves changes passed on across generations."]}, "more": [{"q": "What is a fossil?", "opts": ["A living animal.", "A type of mineral.", "The remains or traces of an organism preserved in rock."], "a": 2, "why": "Bones and shells can be preserved."}, {"q": "Why is the fossil record incomplete?", "opts": ["All fossils have been found.", "Most organisms decay before they can fossilise.", "Fossils are too large."], "a": 1, "why": "Fossilisation needs special conditions."}, {"q": "Similar DNA in two species suggests…", "opts": ["they share a common ancestor.", "they are the same age.", "they live in the same place."], "a": 0, "why": "DNA similarity shows relatedness."}, {"q": "Lower rock layers are usually…", "opts": ["younger.", "the same age as the top.", "older."], "a": 2, "why": "Layers build up over time."}], "ladder": [{"q": "What is evolution?", "m": 1, "ms": ["A change in the inherited features of a species over many generations."], "step": "Remember"}, {"q": "Give two types of evidence for evolution.", "m": 2, "ms": ["Fossils.", "DNA similarities / antibiotic resistance in bacteria / comparing body structures."], "step": "Apply"}, {"q": "Explain why scientists cannot be completely sure how some species evolved.", "m": 3, "ms": ["The fossil record is incomplete.", "Soft-bodied organisms rarely fossilise.", "Many fossils have been destroyed by geological processes or not yet found."], "step": "Explain"}]}, {"key": "biodiversity", "title": "Protecting living things", "notes": ["Biodiversity means the variety of living things in an area or on Earth. A species becomes extinct when its last member dies. Habitat loss can put species at risk.", "Conservation protects living things and their habitats. Breeding programmes can help increase numbers of endangered animals. They also need suitable habitats and enough inherited variation.", "High biodiversity makes an ecosystem more stable, because species depend on each other. Seed banks, zoos, nature reserves and breeding programmes help protect species. Reducing pollution and habitat loss also protects biodiversity."], "worked": "A breeding programme may produce more animals. If the wild habitat is still destroyed, releasing them may fail. Protecting habitat tackles part of the original problem.", "question": "Give one way to protect a habitat. Why might breeding endangered animals alone not save a species?", "scheme": ["Protect or restore the habitat, for example with a nature reserve.", "Animals also need a safe place with food and space.", "Breeding alone cannot remove threats such as habitat loss or may leave too little inherited variation."], "mistake": "Increasing animal numbers is only part of conservation.", "model": null, "id": "y9-unit-06-biodiversity", "unit": "y9-unit-06", "year": 9, "number": 3, "marks": 3, "cards": [{"term": "Biodiversity", "definition": "The variety of living things, including different species and inherited differences."}, {"term": "Extinction", "definition": "When the last living member of a species dies."}, {"term": "Conservation", "definition": "Protecting living things and their habitats."}], "quiz": {"q": "Why might captive breeding alone fail to save a species?", "opts": ["The animals still need a safe, suitable wild habitat.", "Habitat never matters.", "All released animals are guaranteed to survive."], "a": 0, "why": "Breeding more animals cannot by itself fix habitat loss or other threats in the wild."}, "misconception": {"q": "Why might captive breeding alone fail to save a species? Sam answers: “Habitat never matters.” Explain why this is wrong.", "m": 2, "ms": ["The animals still need a safe, suitable wild habitat.", "Breeding more animals cannot by itself fix habitat loss or other threats in the wild."]}, "more": [{"q": "What does biodiversity mean?", "opts": ["The number of plants only.", "The size of an animal.", "The variety of living things in an area."], "a": 2, "why": "It includes all species."}, {"q": "What does a seed bank do?", "opts": ["Kills seeds.", "Stores seeds so plant species are not lost.", "Sells seeds for profit only."], "a": 1, "why": "Seeds can be planted in the future."}, {"q": "Which is a main cause of species becoming endangered?", "opts": ["Habitat loss.", "Too much rain.", "Seed banks."], "a": 0, "why": "Destroying habitats removes food and shelter."}, {"q": "Why is high biodiversity good for an ecosystem?", "opts": ["It makes animals bigger.", "It removes all predators.", "It is more stable if one species declines."], "a": 2, "why": "Food webs have more alternatives."}], "ladder": [{"q": "What does extinct mean?", "m": 1, "ms": ["No members of the species are left alive."], "step": "Remember"}, {"q": "Give two ways humans can protect endangered species.", "m": 2, "ms": ["Nature reserves / protecting habitats.", "Breeding programmes in zoos / seed banks / laws against hunting."], "step": "Apply"}, {"q": "Explain why losing one species can affect many others in a food web.", "m": 3, "ms": ["Species depend on each other for food.", "Predators lose a food source and may decline.", "Its prey may increase and over-eat plants, changing the whole ecosystem."], "step": "Explain"}]}, {"key": "inheritance", "title": "DNA, genes and chromosomes", "notes": ["DNA carries genetic information. Chromosomes are long, packaged DNA molecules found in a cell's nucleus. A gene is a section of DNA.", "Genes help control how a body grows and works. Different versions of a gene are called alleles. Offspring inherit genetic information from their parents.", "Human body cells have 46 chromosomes in 23 pairs; one of each pair comes from each parent. Sex cells (sperm and egg) have only 23 chromosomes. The double-helix structure of DNA was worked out by Watson, Crick, Franklin and Wilkins."], "worked": "Think of a chromosome as a long book of instructions. A gene is a section of those instructions. The comparison helps show the relationship, but real DNA is a molecule.", "question": "How are DNA, chromosomes and genes related?", "scheme": ["Chromosomes contain long DNA molecules.", "Genes are sections of DNA.", "Genes carry information that helps control features or how cells work."], "mistake": "A gene is part of DNA. It is not a tiny organism inside the nucleus.", "model": null, "id": "y9-unit-07-inheritance", "unit": "y9-unit-07", "year": 9, "number": 1, "marks": 3, "cards": [{"term": "Gene", "definition": "A section of DNA carrying information that helps control how cells work or features develop."}, {"term": "Allele", "definition": "A different version of a gene."}, {"term": "Chromosome", "definition": "A long, packaged DNA molecule."}], "quiz": {"q": "What is an allele?", "opts": ["A bone in a joint.", "A version of a gene.", "A whole animal cell."], "a": 1, "why": "A gene can have different versions called alleles."}, "misconception": {"q": "What is an allele? Sam answers: “A whole animal cell.” Explain why this is wrong.", "m": 2, "ms": ["A version of a gene.", "A gene can have different versions called alleles."]}, "more": [{"q": "How many chromosomes are in a normal human body cell?", "opts": ["46.", "23.", "92."], "a": 0, "why": "23 pairs."}, {"q": "How many chromosomes are in a human sperm cell?", "opts": ["46.", "12.", "23."], "a": 2, "why": "Sex cells have half."}, {"q": "What is a gene?", "opts": ["A type of protein.", "A section of DNA that codes for a characteristic.", "A whole cell."], "a": 1, "why": "Genes are on chromosomes."}, {"q": "Whose X-ray images helped show DNA is a double helix?", "opts": ["Rosalind Franklin.", "Charles Darwin.", "Isaac Newton."], "a": 0, "why": "Photo 51 was crucial."}], "ladder": [{"q": "Where in the cell are chromosomes found?", "m": 1, "ms": ["In the nucleus."], "step": "Remember"}, {"q": "Explain why a sperm cell has 23 chromosomes, not 46.", "m": 2, "ms": ["At fertilisation the sperm joins with an egg that also has 23.", "So the fertilised egg has 46, the normal number."], "step": "Apply"}, {"q": "Explain why children look a bit like both parents but not exactly like either.", "m": 3, "ms": ["Children get half their chromosomes from each parent.", "So they inherit a mixture of genes from both.", "Different combinations of alleles give different features."], "step": "Explain"}]}, {"key": "dna-practical", "title": "Extracting DNA", "notes": ["DNA carries genetic information in cells. A simple extraction can collect visible clumps containing DNA. The clumps contain many molecules, not one visible DNA strand.", "Detergent helps break open cell membranes. Salt helps the DNA clump together. Cold ethanol helps DNA come out of the liquid as a solid.", "Mash the fruit with washing-up liquid and salt to break open cells. Filter the mixture, then gently pour cold ethanol on top. White strands of DNA appear where the layers meet."], "worked": "Mash fruit to break up the tissue. Use the teacher's detergent and salt method, then add cold ethanol safely. Pale strands or clumps can appear.", "question": "What do detergent and ethanol do in a classroom DNA extraction?", "scheme": ["Detergent breaks open cell membranes.", "This releases DNA from cells.", "Ethanol makes DNA come out of the liquid so it can be collected."], "mistake": "The visible clumps are not a clear view of a single DNA double helix.", "model": null, "id": "y9-unit-07-dna-practical", "unit": "y9-unit-07", "year": 9, "number": 2, "marks": 3, "cards": [{"term": "DNA", "definition": "The molecule that carries genetic information."}, {"term": "Precipitate", "definition": "A solid that comes out of a solution."}], "quiz": {"q": "What are visible clumps in a classroom DNA extraction?", "opts": ["Many DNA molecules collected together, with possible other material.", "One clearly visible double helix.", "A complete living organism."], "a": 0, "why": "One DNA molecule is too small to see like this. Many collected molecules form the visible clumps."}, "misconception": {"q": "What are visible clumps in a classroom DNA extraction? Sam answers: “One clearly visible double helix.” Explain why this is wrong.", "m": 2, "ms": ["Many DNA molecules collected together, with possible other material.", "One DNA molecule is too small to see like this. Many collected molecules form the visible clumps."]}, "more": [{"q": "What does washing-up liquid do in DNA extraction?", "opts": ["Makes DNA visible as blue.", "Kills the fruit.", "Breaks down cell membranes."], "a": 2, "why": "Detergent breaks apart membranes."}, {"q": "Why is ice-cold ethanol used?", "opts": ["It colours the DNA.", "DNA does not dissolve in it, so it clumps and can be seen.", "It heats the mixture."], "a": 1, "why": "DNA comes out of solution."}, {"q": "Strawberries are good for this practical because…", "opts": ["they have many copies of their DNA in each cell.", "they have no DNA.", "they are red."], "a": 0, "why": "Lots of DNA makes it easier to see."}, {"q": "What do the white strands contain?", "opts": ["A single gene.", "Protein only.", "Many DNA molecules clumped together."], "a": 2, "why": "One DNA molecule is too small to see."}], "ladder": [{"q": "Where is DNA found in a cell?", "m": 1, "ms": ["In the nucleus (in chromosomes)."], "step": "Remember"}, {"q": "Give the purpose of two steps in extracting DNA.", "m": 2, "ms": ["Mashing with detergent breaks open the cells and nuclei.", "Adding cold ethanol makes the DNA come out of solution so it can be seen."], "step": "Apply"}, {"q": "Explain why you cannot see the double helix in the extracted strands.", "m": 3, "ms": ["Each DNA molecule is far too thin to see.", "The strands are millions of molecules tangled together.", "You would need very powerful methods to see the shape of one molecule."], "step": "Explain"}]}, {"key": "cross", "title": "Simple genetic crosses", "notes": ["Alleles are different versions of a gene. A genotype is the allele combination, such as Aa. A phenotype is the feature that results.", "In a simple dominant model, A shows its effect in AA and Aa. The recessive feature shows with aa. A genetic cross shows the chances for each offspring. A dominant allele can show its effect with one copy in this simple model.", "A dominant allele is shown with a capital letter, such as B; a recessive allele with a lower-case letter, such as b. A recessive feature only appears if both alleles are recessive (bb). A Punnett square shows the possible offspring."], "worked": "Cross Aa with aa and the possible combinations are Aa, Aa, aa and aa. Two of the four show the recessive feature. The chance is 2 out of 4, or 50%.", "question": "In a simple dominant model, cross Aa with aa. What is the chance of the recessive feature?", "scheme": ["One parent can pass on A or a and the other passes on a.", "The outcomes are Aa, Aa, aa and aa.", "The chance of aa is 2/4 = 50%."], "mistake": "A 50% chance does not promise exactly half of a small family will have a feature.", "model": "genetics", "id": "y9-unit-07-cross", "unit": "y9-unit-07", "year": 9, "number": 3, "marks": 3, "cards": [{"term": "Genotype", "definition": "The allele combination, such as Aa."}, {"term": "Phenotype", "definition": "The feature that results from genes and the environment."}, {"term": "Recessive allele", "definition": "An allele whose feature shows only with two copies in a simple dominant model."}], "quiz": {"q": "For Aa × Aa in a simple dominant model, what is the chance of aa?", "opts": ["1 in 2.", "Certain.", "1 in 4."], "a": 2, "why": "The four possible combinations are AA, Aa, Aa and aa."}, "misconception": {"q": "For Aa × Aa in a simple dominant model, what is the chance of aa? Sam answers: “1 in 2.” Explain why this is wrong.", "m": 2, "ms": ["1 in 4.", "The four possible combinations are AA, Aa, Aa and aa."]}, "more": [{"q": "If B (brown eyes) is dominant, what eye colour does Bb give?", "opts": ["Green.", "Brown.", "Blue."], "a": 1, "why": "One dominant allele is enough."}, {"q": "Which genotype shows the recessive feature?", "opts": ["bb.", "Bb.", "BB."], "a": 0, "why": "Both alleles must be recessive."}, {"q": "Two Bb parents have a child. What is the chance it is bb?", "opts": ["50%.", "75%.", "25%."], "a": 2, "why": "1 out of 4 boxes."}, {"q": "What is a phenotype?", "opts": ["A chromosome.", "The feature that shows, such as eye colour.", "The pair of alleles."], "a": 1, "why": "Phenotype is what you can see or measure."}], "ladder": [{"q": "What is an allele?", "m": 1, "ms": ["A different version of a gene."], "step": "Remember"}, {"q": "A homozygous dominant parent (BB) and a recessive parent (bb) have children. Give the possible genotype(s) and the phenotype.", "m": 2, "ms": ["All the children are Bb.", "They all show the dominant feature (e.g. brown eyes)."], "step": "Apply"}, {"q": "Two parents with brown eyes have a child with blue eyes. Explain how this is possible (B = brown, b = blue).", "m": 3, "ms": ["Both parents must be heterozygous, Bb.", "Each parent can pass on a b allele.", "The child inherits bb, so shows the recessive blue eyes (1 in 4 chance)."], "step": "Explain"}]}, {"key": "gm", "title": "Selective breeding and genetic modification", "notes": ["Selective breeding means choosing parents with useful inherited features. Breeders repeat this over generations. Genetic modification changes an organism's DNA using laboratory techniques.", "A gene can sometimes be moved from one organism into another. A new feature may be useful, but benefits and risks need checking. Different uses have different benefits and concerns.", "Selective breeding has produced crops with bigger yields and cows that make more milk. Genetic modification can make crops resistant to pests or add vitamins, like golden rice. Some people worry about effects on wildlife and human health."], "worked": "Bacteria can be genetically modified to make human insulin. The insulin is collected and used as a medicine. This is different from choosing parent animals for breeding.", "question": "How does genetic modification differ from selective breeding? Give a possible benefit of one named use.", "scheme": ["Genetic modification directly changes DNA using laboratory techniques.", "Selective breeding chooses parents and breeds them over generations.", "For example, modified bacteria can make insulin for medicine."], "mistake": "Genetic modification and selective breeding are different methods.", "model": null, "id": "y9-unit-07-gm", "unit": "y9-unit-07", "year": 9, "number": 4, "marks": 3, "cards": [{"term": "Genetic modification", "definition": "Changing DNA using laboratory techniques."}, {"term": "Selective breeding", "definition": "Choosing parents with useful inherited features and breeding them over generations."}], "quiz": {"q": "How is selective breeding different from genetic modification?", "opts": ["It needs no parents or offspring.", "It chooses parents instead of directly changing their DNA in a laboratory.", "It always moves a gene between unrelated species."], "a": 1, "why": "Breeders choose which organisms reproduce. Genetic modification directly changes genetic material."}, "misconception": {"q": "How is selective breeding different from genetic modification? Sam answers: “It always moves a gene between unrelated species.” Explain why this is wrong.", "m": 2, "ms": ["It chooses parents instead of directly changing their DNA in a laboratory.", "Breeders choose which organisms reproduce. Genetic modification directly changes genetic material."]}, "more": [{"q": "Choosing the best cows to breed for more milk is…", "opts": ["selective breeding.", "genetic modification.", "natural selection."], "a": 0, "why": "Humans choose the parents."}, {"q": "Golden rice has been modified to contain…", "opts": ["more protein.", "less water.", "more vitamin A (as beta-carotene)."], "a": 2, "why": "It helps prevent vitamin A deficiency."}, {"q": "A concern about selective breeding is…", "opts": ["it is too quick.", "reduced variation, making disease more damaging.", "animals become extinct immediately."], "a": 1, "why": "Inbreeding reduces genetic variety."}, {"q": "Genetic modification involves…", "opts": ["putting a gene from one organism into another.", "choosing parents over many years.", "feeding plants more."], "a": 0, "why": "Genes are moved directly."}], "ladder": [{"q": "What is selective breeding?", "m": 1, "ms": ["Humans choosing parents with useful features to breed over many generations."], "step": "Remember"}, {"q": "Give one benefit and one concern about GM crops.", "m": 2, "ms": ["Benefit: pest resistance / higher yield / added vitamins.", "Concern: effects on wildlife or food chains / possible health effects / genes spreading to wild plants."], "step": "Apply"}, {"q": "Describe how a farmer could breed sheep with thicker wool.", "m": 3, "ms": ["Choose the sheep with the thickest wool as parents.", "Breed them together and select the offspring with the thickest wool.", "Repeat over many generations."], "step": "Explain"}]}, {"key": "waves", "title": "Wave shapes and wave speed", "notes": ["Waves transfer energy from place to place. In a transverse wave, vibrations are across the direction the wave travels. In a longitudinal wave, vibrations are along the direction it travels.", "Wavelength is the distance between matching points, such as two neighbouring crests. Frequency is the number of complete waves each second. Wave speed = frequency × wavelength.", "Wave speed = frequency × wavelength. Wavelength is the distance from one peak to the next. Water waves and light are transverse; sound is longitudinal."], "worked": "A wave has frequency 4 Hz and wavelength 1.5 m. Speed = 4 × 1.5 = 6 m/s. Its period, the time for one wave, is 1 ÷ 4 = 0.25 s.", "question": "A wave has frequency 4 Hz and wavelength 1.5 m. Find its speed and the time for one wave.", "scheme": ["Speed = 4 × 1.5 = 6 m/s.", "Period = 1 ÷ frequency.", "Period = 0.25 s."], "mistake": "The wave travels along, but the material only vibrates near its own position.", "model": "wave", "id": "y9-unit-08-waves", "unit": "y9-unit-08", "year": 9, "number": 1, "marks": 3, "cards": [{"term": "Transverse wave", "definition": "A wave whose vibrations are across the direction it travels."}, {"term": "Wavelength", "definition": "The distance between matching points on neighbouring waves."}, {"term": "Period", "definition": "The time for one complete wave or vibration."}], "quiz": {"q": "A wave has frequency 3 Hz and wavelength 2 m. What is its speed?", "opts": ["5 m/s.", "6 m/s.", "1.5 m/s."], "a": 1, "why": "Wave speed = frequency × wavelength = 3 × 2 = 6 m/s."}, "misconception": {"q": "A wave has frequency 3 Hz and wavelength 2 m. What is its speed? Sam answers: “1.5 m/s.” Explain why this is wrong.", "m": 2, "ms": ["6 m/s.", "Wave speed = frequency × wavelength = 3 × 2 = 6 m/s."]}, "more": [{"q": "A wave has frequency 5 Hz and wavelength 2 m. What is its speed?", "opts": ["10 m/s.", "2.5 m/s.", "7 m/s."], "a": 0, "why": "v = f × λ."}, {"q": "What is the wavelength?", "opts": ["The height of a wave.", "The number of waves per second.", "The distance from one peak to the next peak."], "a": 2, "why": "Measured in metres."}, {"q": "Which is a longitudinal wave?", "opts": ["A water ripple.", "Sound.", "Light."], "a": 1, "why": "Vibrations are along the direction of travel."}, {"q": "What does a wave transfer?", "opts": ["Energy.", "Matter from place to place.", "Particles only."], "a": 0, "why": "The material stays roughly where it is."}], "ladder": [{"q": "What is the amplitude of a wave?", "m": 1, "ms": ["The maximum distance a point moves from its rest position (the height of a peak)."], "step": "Remember"}, {"q": "A sound wave has a frequency of 170 Hz and a wavelength of 2 m. Calculate its speed.", "m": 2, "ms": ["v = f × λ = 170 × 2.", "= 340 m/s."], "step": "Apply"}, {"q": "Explain the difference between a transverse and a longitudinal wave, with an example of each.", "m": 3, "ms": ["In a transverse wave the vibrations are at right angles to the direction of travel, e.g. light or water waves.", "In a longitudinal wave the vibrations are along the direction of travel, e.g. sound.", "Both transfer energy without transferring the material."], "step": "Explain"}]}, {"key": "ultrasound", "title": "Ultrasound and echoes", "notes": ["Ultrasound is sound above about 20,000 Hz. Most people cannot hear it. Like other sound, it needs a material to travel through.", "Ultrasound reflects when it meets some boundaries between materials. Scanners use the returning signals to build an image. Echo timing can also measure a distance.", "Ultrasound is used to scan unborn babies because it is safe and does not harm cells. Ships use sonar to measure sea depth from the time an echo takes to return. Bats and dolphins use ultrasound echoes to find food."], "worked": "Multiply sound speed by the time for the echo to return. This gives the distance there and back. Divide by two to find the distance to the reflecting surface.", "question": "Why must you divide speed × echo time by two when finding a distance with ultrasound?", "scheme": ["The time includes the outward and return journeys.", "Speed × time gives the total distance travelled.", "The reflecting surface is half that distance away."], "mistake": "Ultrasound is a sound wave, not an electromagnetic wave.", "model": null, "id": "y9-unit-08-ultrasound", "unit": "y9-unit-08", "year": 9, "number": 2, "marks": 3, "cards": [{"term": "Ultrasound", "definition": "Sound with a frequency above about 20,000 Hz."}, {"term": "Time of flight", "definition": "The time a signal takes to travel a particular distance."}], "quiz": {"q": "Can ultrasound travel across empty space?", "opts": ["Yes, because it is light.", "Yes, because it has a high pitch.", "No. Sound needs a material to travel through."], "a": 2, "why": "Ultrasound is still sound. It needs particles to pass on the vibrations."}, "misconception": {"q": "Can ultrasound travel across empty space? Sam answers: “Yes, because it is light.” Explain why this is wrong.", "m": 2, "ms": ["No. Sound needs a material to travel through.", "Ultrasound is still sound. It needs particles to pass on the vibrations."]}, "more": [{"q": "Ultrasound has a frequency…", "opts": ["of exactly 1000 Hz.", "above 20,000 Hz.", "below 20 Hz."], "a": 1, "why": "Too high for humans to hear."}, {"q": "Why is ultrasound used for pregnancy scans instead of X-rays?", "opts": ["It does not damage cells.", "It is cheaper only.", "It shows colours."], "a": 0, "why": "X-rays can harm the fetus."}, {"q": "A sonar pulse returns after 2 s. Sound in water travels 1500 m/s. How deep is the sea?", "opts": ["3000 m.", "750 m.", "1500 m."], "a": 2, "why": "Distance there and back = 3000 m, so depth = 1500 m."}, {"q": "Which animal uses ultrasound to hunt?", "opts": ["Snail.", "Bat.", "Cow."], "a": 1, "why": "Bats use echolocation."}], "ladder": [{"q": "What is ultrasound?", "m": 1, "ms": ["Sound with a frequency above about 20,000 Hz (too high for humans to hear)."], "step": "Remember"}, {"q": "A ship’s sonar pulse returns after 0.8 s. Sound travels at 1500 m/s in water. Calculate the depth.", "m": 2, "ms": ["Total distance = 1500 × 0.8 = 1200 m.", "Depth = 1200 ÷ 2 = 600 m."], "step": "Apply"}, {"q": "Explain how a bat uses ultrasound to find an insect.", "m": 3, "ms": ["The bat sends out ultrasound pulses.", "The pulses reflect off the insect as echoes.", "The time taken for the echo to return tells the bat how far away the insect is."], "step": "Explain"}]}, {"key": "em", "title": "The electromagnetic spectrum", "notes": ["The electromagnetic spectrum includes radio, microwave, infrared, visible, ultraviolet, X-ray and gamma waves. All can travel through empty space. They all have the same speed in a vacuum.", "Different waves have different uses. X-rays pass through soft tissue more easily than through bone. Some high-energy waves can damage cells, so exposure must be controlled.", "In order of increasing frequency: radio, microwave, infrared, visible light, ultraviolet, X-ray, gamma. Higher-frequency waves carry more energy and can be more harmful. All electromagnetic waves travel at the speed of light in a vacuum."], "worked": "An X-ray image shows differences in how much radiation tissues absorb. Bones usually appear clearly against softer tissue. The dose is kept as low as needed for a useful image.", "question": "Why are X-rays useful for images of bones? Why must exposure be controlled?", "scheme": ["Bone and soft tissue absorb X-rays differently.", "A detector records the differences to make an image.", "X-rays can damage cells, so unnecessary exposure is avoided."], "mistake": "Higher-frequency electromagnetic waves do not travel faster in a vacuum.", "model": null, "id": "y9-unit-08-em", "unit": "y9-unit-08", "year": 9, "number": 3, "marks": 3, "cards": [{"term": "Electromagnetic wave", "definition": "A wave, such as light or radio, that can travel through empty space."}, {"term": "Ionisation", "definition": "An atom or particle becoming charged by losing or gaining electrons."}], "quiz": {"q": "Which electromagnetic waves travel at the same speed in a vacuum?", "opts": ["Only radio and sound.", "All types of electromagnetic wave.", "Only visible colours."], "a": 1, "why": "All electromagnetic waves have the same vacuum speed. Sound is not an electromagnetic wave."}, "misconception": {"q": "Which electromagnetic waves travel at the same speed in a vacuum? Sam answers: “Only visible colours.” Explain why this is wrong.", "m": 2, "ms": ["All types of electromagnetic wave.", "All electromagnetic waves have the same vacuum speed. Sound is not an electromagnetic wave."]}, "more": [{"q": "Which EM wave is used to cook food in a microwave oven?", "opts": ["Microwaves.", "X-rays.", "Radio waves."], "a": 0, "why": "Water molecules absorb them."}, {"q": "Which EM wave can cause sunburn?", "opts": ["Radio.", "Infrared only.", "Ultraviolet."], "a": 2, "why": "UV can damage skin cells."}, {"q": "Which EM wave has the highest frequency?", "opts": ["Visible light.", "Gamma rays.", "Radio waves."], "a": 1, "why": "Gamma has the most energy."}, {"q": "All EM waves travel through a vacuum at…", "opts": ["the same speed (the speed of light).", "different speeds.", "the speed of sound."], "a": 0, "why": "About 300 000 km/s."}], "ladder": [{"q": "Name the EM wave used in TV remote controls.", "m": 1, "ms": ["Infrared."], "step": "Remember"}, {"q": "Give two uses of X-rays and gamma rays.", "m": 2, "ms": ["X-rays: seeing broken bones / airport security.", "Gamma: killing cancer cells / sterilising medical equipment."], "step": "Apply"}, {"q": "Explain why radiographers stand behind a screen when taking X-rays.", "m": 3, "ms": ["X-rays have high energy and can damage cells and DNA.", "Radiographers take many X-rays every day, so their exposure would add up.", "The lead screen absorbs X-rays and protects them."], "step": "Explain"}]}, {"key": "earth", "title": "Inside Earth and types of rock", "notes": ["Earth has a thin solid crust and a thick mantle. The mantle is mostly solid rock that can slowly change shape. The outer core is liquid and the inner core is solid.", "Igneous rock forms when molten rock cools and becomes solid. Sedimentary rock often forms from layers of small pieces pressed and cemented together. Metamorphic rock forms when heat and pressure change existing rock without melting it.", "Igneous rock forms when magma or lava cools. Sedimentary rock forms from layers of sediment that are squashed and cemented. Metamorphic rock forms when heat and pressure change existing rock without melting it."], "worked": "Magma that cools slowly can form large crystals. Lava that cools quickly usually forms smaller crystals. Melting and cooling a rock makes a new igneous rock.", "question": "How are igneous and metamorphic rocks made?", "scheme": ["Igneous rock forms when molten rock cools and becomes solid.", "Metamorphic rock forms when heat and pressure change existing rock.", "Metamorphic change happens without the rock melting."], "mistake": "The mantle is not a giant ocean of liquid magma.", "model": null, "id": "y9-unit-09-earth", "unit": "y9-unit-09", "year": 9, "number": 1, "marks": 3, "cards": [{"term": "Crust", "definition": "Earth's thin, solid outer layer."}, {"term": "Mantle", "definition": "The mostly solid rock layer below the crust that can slowly change shape."}, {"term": "Igneous rock", "definition": "Rock made when molten rock cools and becomes solid."}], "quiz": {"q": "Which statement about Earth is correct?", "opts": ["The crust is Earth's thickest layer.", "The mantle is mostly solid and the outer core is liquid.", "The whole mantle is liquid magma."], "a": 1, "why": "The mantle is mostly solid rock, even though it can move very slowly over long times."}, "misconception": {"q": "Which statement about Earth is correct? Sam answers: “The whole mantle is liquid magma.” Explain why this is wrong.", "m": 2, "ms": ["The mantle is mostly solid and the outer core is liquid.", "The mantle is mostly solid rock, even though it can move very slowly over long times."]}, "more": [{"q": "Which type of rock forms when magma cools?", "opts": ["Igneous.", "Sedimentary.", "Metamorphic."], "a": 0, "why": "Granite and basalt are igneous."}, {"q": "Which layer of the Earth is liquid?", "opts": ["Inner core.", "Crust.", "Outer core."], "a": 2, "why": "The outer core is liquid metal."}, {"q": "Marble forms from limestone by…", "opts": ["weathering only.", "heat and pressure (metamorphism).", "cooling lava."], "a": 1, "why": "Limestone is changed into marble."}, {"q": "Which rock is most likely to contain fossils?", "opts": ["Sedimentary.", "Igneous.", "Metamorphic."], "a": 0, "why": "Sediment can bury and preserve organisms."}], "ladder": [{"q": "What is the thin outer layer of the Earth called?", "m": 1, "ms": ["The crust."], "step": "Remember"}, {"q": "Granite has large crystals and basalt has small crystals. Explain the difference.", "m": 2, "ms": ["Granite cooled slowly underground, so crystals had time to grow.", "Basalt cooled quickly from lava at the surface, so the crystals are small."], "step": "Apply"}, {"q": "Name the three types of rock and describe how each forms.", "m": 3, "ms": ["Igneous: from cooling magma or lava.", "Sedimentary: layers of sediment compacted and cemented.", "Metamorphic: existing rock changed by heat and pressure."], "step": "Explain"}]}, {"key": "sediment", "title": "Weathering, erosion and fossils", "notes": ["Weathering breaks rock into smaller pieces where it is. Erosion removes and carries rock material away. Water, wind and ice can move the pieces.", "Sediment settles in layers. Pressure and natural cements can turn layers into sedimentary rock. Fossils are remains or signs of past living things preserved in rock.", "Freeze–thaw weathering happens when water in cracks freezes, expands and splits rock. Rivers carry sediment and drop it in layers when they slow down. Over time, layers are compacted and cemented into rocks such as sandstone and limestone."], "worked": "An animal buried quickly in sediment may be protected from scavengers. Its remains may then be preserved as the sediment becomes rock. Most dead organisms do not become fossils.", "question": "How is weathering different from erosion? How can burial help a fossil form?", "scheme": ["Weathering breaks rock down in place.", "Erosion carries rock material away.", "Quick burial can protect remains so they have a better chance of being preserved."], "mistake": "Fossils can be traces such as footprints, not just bones.", "model": "rockcycle", "id": "y9-unit-09-sediment", "unit": "y9-unit-09", "year": 9, "number": 2, "marks": 3, "cards": [{"term": "Weathering", "definition": "Rock breaking down where it is."}, {"term": "Erosion", "definition": "Rock material being removed and carried away."}, {"term": "Fossil", "definition": "Preserved remains or signs of a past living thing."}], "quiz": {"q": "How is erosion different from weathering?", "opts": ["They always mean exactly the same thing.", "Erosion only happens inside Earth's core.", "Erosion carries material away; weathering breaks it down in place."], "a": 2, "why": "A river carrying broken rock is erosion. Cracking rock in place is weathering."}, "misconception": {"q": "How is erosion different from weathering? Sam answers: “They always mean exactly the same thing.” Explain why this is wrong.", "m": 2, "ms": ["Erosion carries material away; weathering breaks it down in place.", "A river carrying broken rock is erosion. Cracking rock in place is weathering."]}, "more": [{"q": "What is freeze–thaw weathering?", "opts": ["Wind blowing rocks away.", "Water in cracks freezes, expands and breaks the rock.", "Rock melting in the sun."], "a": 1, "why": "Ice takes up more space than water."}, {"q": "Erosion means…", "opts": ["rock pieces are carried away.", "rock forms from lava.", "rock changes by heat."], "a": 0, "why": "Water, wind and ice transport sediment."}, {"q": "Which is a sedimentary rock?", "opts": ["Granite.", "Marble.", "Sandstone."], "a": 2, "why": "Made from sand grains cemented together."}, {"q": "Why are fossils found in sedimentary rocks?", "opts": ["Heat makes fossils.", "Organisms are buried by sediment and preserved.", "Lava preserves animals."], "a": 1, "why": "Melting would destroy them."}], "ladder": [{"q": "What is weathering?", "m": 1, "ms": ["The breakdown of rock into smaller pieces where it is."], "step": "Remember"}, {"q": "Describe two stages that turn loose sand into sandstone.", "m": 2, "ms": ["Layers of sand are buried and compacted by the weight above.", "Minerals cement the grains together."], "step": "Apply"}, {"q": "Explain why a fossil found in a lower rock layer is usually older than one in a higher layer.", "m": 3, "ms": ["Sediment is deposited in layers over time.", "New layers settle on top of older ones.", "So lower layers, and the fossils in them, formed earlier."], "step": "Explain"}]}, {"key": "rock-cycle", "title": "The rock cycle", "notes": ["Rocks can change from one type into another. Weathering, erosion, heat, pressure, melting and cooling all play a part. These changes form the rock cycle.", "There is no single starting point or fixed route. Many rock changes take millions of years. Melting destroys the old rock's structure.", "Rocks are recycled slowly over millions of years. Uplift can bring buried rocks back to the surface, where weathering starts again. The rock cycle is driven by the Sun (weathering, erosion) and by heat from inside the Earth."], "worked": "A sedimentary rock may be buried and heated until it melts. The molten rock later cools and becomes solid. It is now igneous rock.", "question": "Describe how a sedimentary rock could become an igneous rock.", "scheme": ["The sedimentary rock is heated enough to melt.", "Molten rock then cools.", "It becomes solid igneous rock."], "mistake": "Heat and pressure without melting make metamorphic rock, not igneous rock.", "model": "rockcycle", "id": "y9-unit-09-rock-cycle", "unit": "y9-unit-09", "year": 9, "number": 3, "marks": 3, "cards": [{"term": "Metamorphic rock", "definition": "Rock changed by heat and pressure without melting."}, {"term": "Rock cycle", "definition": "The processes that change rocks from one type into another."}], "quiz": {"q": "What forms when molten rock cools and becomes solid?", "opts": ["Liquid sediment.", "Igneous rock.", "Only a fossil."], "a": 1, "why": "Igneous rocks form by cooling and solidifying molten rock."}, "misconception": {"q": "What forms when molten rock cools and becomes solid? Sam answers: “Only a fossil.” Explain why this is wrong.", "m": 2, "ms": ["Igneous rock.", "Igneous rocks form by cooling and solidifying molten rock."]}, "more": [{"q": "How long do most rock cycle changes take?", "opts": ["Millions of years.", "A few days.", "One year."], "a": 0, "why": "Rock changes are very slow."}, {"q": "What brings buried rocks back to the surface?", "opts": ["Rain.", "Photosynthesis.", "Uplift (movements of the Earth’s crust)."], "a": 2, "why": "Plate movements push rocks up."}, {"q": "Metamorphic rock that melts becomes…", "opts": ["sandstone.", "magma.", "sediment."], "a": 1, "why": "Melting forms magma."}, {"q": "Which process breaks down rock at the surface?", "opts": ["Weathering.", "Melting.", "Compaction."], "a": 0, "why": "Weathering happens at the surface."}], "ladder": [{"q": "What is magma?", "m": 1, "ms": ["Molten (melted) rock below the Earth’s surface."], "step": "Remember"}, {"q": "Describe how sedimentary rock can become metamorphic rock.", "m": 2, "ms": ["It is buried deep underground.", "Heat and pressure change it without melting it."], "step": "Apply"}, {"q": "Explain how a piece of igneous rock could become part of a sedimentary rock.", "m": 3, "ms": ["The igneous rock is weathered into small pieces.", "The pieces are eroded and transported, e.g. by rivers, and deposited in layers.", "The layers are compacted and cemented into sedimentary rock."], "step": "Explain"}]}, {"key": "space", "title": "The Solar System and space distances", "notes": ["The Sun is a star at the centre of our Solar System. Planets orbit the Sun. The Solar System is part of the Milky Way galaxy.", "A galaxy contains huge numbers of stars. Distances in space are enormous. A light-year is the distance light travels in one year. Stars make their own light, but planets and moons mainly reflect starlight. An astronomical unit is about the distance from Earth to the Sun.", "Light from the Sun takes about 8 minutes to reach Earth. Distances in space are often measured in light years, the distance light travels in a year. The nearest star after the Sun is about 4 light years away."], "worked": "A classroom Solar System diagram often makes planets too large. The gaps may also be much too small. Always check whether sizes and distances are drawn to scale.", "question": "What does a light-year measure? Give one problem with a typical classroom Solar System diagram.", "scheme": ["A light-year measures distance.", "It is how far light travels in one year.", "Planet sizes or distances may not be drawn to the same scale."], "mistake": "A light-year is a distance, not a time.", "model": null, "id": "y9-unit-10-space", "unit": "y9-unit-10", "year": 9, "number": 1, "marks": 3, "cards": [{"term": "Light-year", "definition": "The distance light travels in one year."}, {"term": "Solar System", "definition": "The Sun and the objects that orbit it."}, {"term": "Galaxy", "definition": "A huge collection of stars, gas and other matter held together by gravity."}], "quiz": {"q": "What does a light-year measure?", "opts": ["Mass.", "Distance.", "Time."], "a": 1, "why": "The word “year” is part of the name, but a light-year is a distance."}, "misconception": {"q": "What does a light-year measure? Sam answers: “Time.” Explain why this is wrong.", "m": 2, "ms": ["Distance.", "The word “year” is part of the name, but a light-year is a distance."]}, "more": [{"q": "What is a light year?", "opts": ["The distance light travels in one year.", "The time light takes to travel 1 km.", "A year on another planet."], "a": 0, "why": "It measures distance."}, {"q": "The Sun is…", "opts": ["a planet.", "a moon.", "a star."], "a": 2, "why": "It produces its own light."}, {"q": "Which is the largest?", "opts": ["The Solar System.", "The Universe.", "A galaxy."], "a": 1, "why": "Galaxies are in the Universe."}, {"q": "About how long does sunlight take to reach Earth?", "opts": ["8 minutes.", "8 seconds.", "8 days."], "a": 0, "why": "Light is fast but the Sun is far."}], "ladder": [{"q": "What is a galaxy?", "m": 1, "ms": ["A huge group of billions of stars (with gas and dust)."], "step": "Remember"}, {"q": "Put in order of size, smallest first: galaxy, Earth, Universe, Solar System.", "m": 2, "ms": ["Earth, Solar System.", "Galaxy, Universe."], "step": "Apply"}, {"q": "Explain why astronomers use light years instead of kilometres.", "m": 3, "ms": ["Distances between stars are enormous.", "Numbers in kilometres would be huge and hard to use.", "A light year is a much bigger unit, so the numbers are manageable."], "step": "Explain"}]}, {"key": "orbits", "title": "Days, years and seasons", "notes": ["Earth spins on its axis once in about 24 hours. Earth orbits the Sun once in about a year. Its axis is tilted.", "The tilt causes the seasons. A hemisphere tilted towards the Sun has longer days and more direct sunlight. The other hemisphere has shorter days and less direct sunlight. Gravity keeps changing the direction of an orbiting object. The orbit of the Moon is tilted, so eclipses do not happen every month.", "In summer, the UK is tilted towards the Sun, so days are longer and the Sun is higher in the sky. Sunlight is more concentrated when the Sun is higher, so it feels warmer. In winter the UK is tilted away, so days are short and the Sun is low."], "worked": "When the Northern Hemisphere has summer, the Southern Hemisphere has winter. Six months later the situation is reversed. Earth's tilt, rather than its distance from the Sun, explains this pattern.", "question": "Why do the Northern and Southern Hemispheres have opposite seasons?", "scheme": ["Earth's axis is tilted.", "One hemisphere gets longer days and more direct sunlight.", "At the same time the other gets shorter days and less direct sunlight."], "mistake": "Summer is not caused by Earth being much closer to the Sun.", "model": "seasons", "id": "y9-unit-10-orbits", "unit": "y9-unit-10", "year": 9, "number": 2, "marks": 3, "cards": [{"term": "Orbit", "definition": "The path of one object around another under gravity."}, {"term": "Axial tilt", "definition": "The lean of a planet's spin axis compared with its orbit."}], "quiz": {"q": "What mainly causes Earth's seasons?", "opts": ["A large yearly change in Earth–Sun distance.", "The Moon making its own light.", "Earth's tilted axis."], "a": 2, "why": "The tilt changes day length and how directly sunlight reaches each hemisphere."}, "misconception": {"q": "What mainly causes Earth's seasons? Sam answers: “A large yearly change in Earth–Sun distance.” Explain why this is wrong.", "m": 2, "ms": ["Earth's tilted axis.", "The tilt changes day length and how directly sunlight reaches each hemisphere."]}, "more": [{"q": "What causes the seasons?", "opts": ["The Moon blocking sunlight.", "The tilt of the Earth’s axis.", "The Earth getting closer to the Sun."], "a": 1, "why": "Distance changes very little."}, {"q": "How long does Earth take to orbit the Sun?", "opts": ["About 365 days.", "24 hours.", "28 days."], "a": 0, "why": "One year."}, {"q": "In UK summer, the northern hemisphere is…", "opts": ["tilted away from the Sun.", "not tilted.", "tilted towards the Sun."], "a": 2, "why": "Long days and high Sun."}, {"q": "What causes day and night?", "opts": ["The Moon orbiting Earth.", "The Earth spinning on its axis.", "The Earth orbiting the Sun."], "a": 1, "why": "One spin takes about 24 hours."}], "ladder": [{"q": "How long does the Earth take to spin once on its axis?", "m": 1, "ms": ["About 24 hours (one day)."], "step": "Remember"}, {"q": "Give two differences between summer and winter in the UK.", "m": 2, "ms": ["Summer has longer days / shorter nights.", "The Sun is higher in the sky in summer, so it feels warmer."], "step": "Apply"}, {"q": "Explain why it is summer in Australia when it is winter in the UK.", "m": 3, "ms": ["The Earth’s axis is tilted.", "When the northern hemisphere tilts away from the Sun, the southern hemisphere tilts towards it.", "So Australia gets longer days and higher Sun at the same time as the UK’s winter."], "step": "Explain"}]}, {"key": "moon", "title": "Moon phases and eclipses", "notes": ["The Moon reflects sunlight rather than making its own light. The Sun lights roughly half of the Moon. As it orbits Earth, we see different amounts of this lit half.", "These changing views are called Moon phases. A lunar eclipse happens when the Moon enters Earth's shadow. A solar eclipse happens when the Moon blocks sunlight from reaching part of Earth.", "A solar eclipse happens when the Moon passes between the Sun and Earth, blocking sunlight. A lunar eclipse happens when the Earth's shadow falls on the Moon. The Moon takes about 28 days to go through all its phases."], "worked": "A crescent Moon means we see only a small part of its sunlit half. Earth's shadow is not causing that ordinary phase. An eclipse needs the Sun, Earth and Moon to line up in a particular way.", "question": "How is an ordinary Moon phase different from a lunar eclipse?", "scheme": ["Phases happen because we see different amounts of the Moon's lit half.", "They happen as the Moon moves around Earth.", "A lunar eclipse happens when Earth's shadow falls on the Moon."], "mistake": "Earth's shadow does not cause normal Moon phases.", "model": "orbit", "id": "y9-unit-10-moon", "unit": "y9-unit-10", "year": 9, "number": 3, "marks": 3, "cards": [{"term": "Phase", "definition": "The amount of the Moon's sunlit half that we can see."}, {"term": "Lunar eclipse", "definition": "The Moon passing through Earth's shadow."}, {"term": "Solar eclipse", "definition": "The Moon blocking sunlight from reaching part of Earth."}], "quiz": {"q": "What causes normal Moon phases?", "opts": ["The Moon switches its own light on and off.", "We see different amounts of the sunlit half as the Moon orbits Earth.", "Earth's shadow covers it every night."], "a": 1, "why": "The Moon reflects sunlight. Its orbit changes our view of its lit half."}, "misconception": {"q": "What causes normal Moon phases? Sam answers: “Earth's shadow covers it every night.” Explain why this is wrong.", "m": 2, "ms": ["We see different amounts of the sunlit half as the Moon orbits Earth.", "The Moon reflects sunlight. Its orbit changes our view of its lit half."]}, "more": [{"q": "Why can we see the Moon?", "opts": ["It reflects sunlight.", "It makes its own light.", "It is on fire."], "a": 0, "why": "The Moon is not a light source."}, {"q": "About how long is one cycle of Moon phases?", "opts": ["About 24 hours.", "About 365 days.", "About 28 days."], "a": 2, "why": "Roughly a month."}, {"q": "A solar eclipse happens when…", "opts": ["the Sun moves behind Earth.", "the Moon blocks the Sun’s light from reaching part of the Earth.", "Earth’s shadow falls on the Moon."], "a": 1, "why": "The Moon is between Sun and Earth."}, {"q": "A full Moon happens when…", "opts": ["the Moon is on the opposite side of Earth from the Sun.", "the Moon is between Earth and the Sun.", "Earth’s shadow covers it."], "a": 0, "why": "We see the whole lit half."}], "ladder": [{"q": "What is a lunar eclipse?", "m": 1, "ms": ["When the Earth’s shadow falls on the Moon."], "step": "Remember"}, {"q": "Describe the positions of the Sun, Earth and Moon during a solar eclipse.", "m": 2, "ms": ["The Moon is between the Sun and the Earth.", "They are in a straight line, so the Moon’s shadow falls on Earth."], "step": "Apply"}, {"q": "Explain why the Moon appears to change shape during a month.", "m": 3, "ms": ["The Sun always lights half of the Moon.", "As the Moon orbits Earth, we see different amounts of the lit half.", "This gives phases from new Moon to full Moon and back."], "step": "Explain"}]}, {"key": "friction", "title": "Friction, drag and changing shape", "notes": ["Friction acts between surfaces and opposes sliding. Drag opposes motion through air or water. Both can transfer energy to the surroundings by heating.", "An elastic change is reversed when the force is removed. A plastic change is permanent. At steady speed on a level road, driving and resisting forces balance.", "Friction can be useful, such as grip on shoes and brakes on bikes. It can also be a nuisance, causing wear and wasted energy. Lubricants like oil reduce friction; streamlining reduces air resistance."], "worked": "A cyclist pedals to balance air resistance and friction. The bicycle can then keep a steady speed. Without the driving force, the resisting forces slow it down.", "question": "Why must a cyclist keep applying a driving force to move at steady speed on a level road?", "scheme": ["Friction and air resistance act backwards.", "A forward driving force balances these forces.", "The resultant is zero, so the speed stays steady."], "mistake": "Steady speed can still need a driving force when resistance is present.", "model": null, "id": "y9-unit-11-friction", "unit": "y9-unit-11", "year": 9, "number": 1, "marks": 3, "cards": [{"term": "Friction", "definition": "A contact force that opposes sliding between surfaces."}, {"term": "Drag", "definition": "A force opposing movement through air or water."}, {"term": "Plastic deformation", "definition": "A permanent change of shape."}], "quiz": {"q": "Why does a cyclist need a driving force at steady speed?", "opts": ["Because balanced forces must make the cyclist stop.", "Because the bicycle has no weight.", "To balance friction and air resistance."], "a": 2, "why": "A forward driving force balances the backward forces, giving no change in speed."}, "misconception": {"q": "Why does a cyclist need a driving force at steady speed? Sam answers: “Because balanced forces must make the cyclist stop.” Explain why this is wrong.", "m": 2, "ms": ["To balance friction and air resistance.", "A forward driving force balances the backward forces, giving no change in speed."]}, "more": [{"q": "Which reduces friction between moving parts?", "opts": ["Rough surfaces.", "Oil (a lubricant).", "Sand."], "a": 1, "why": "Lubricants let surfaces slide."}, {"q": "Air resistance on a cyclist can be reduced by…", "opts": ["crouching and wearing tight clothing (streamlining).", "sitting upright with a coat open.", "pedalling slower only."], "a": 0, "why": "A smaller frontal area reduces drag."}, {"q": "Which is a useful effect of friction?", "opts": ["It wears out engines.", "It wastes fuel.", "It lets car tyres grip the road."], "a": 2, "why": "Without grip, cars would skid."}, {"q": "Friction transfers energy to the…", "opts": ["nuclear store.", "thermal store of the surfaces.", "chemical store."], "a": 1, "why": "Rubbing hands warms them."}], "ladder": [{"q": "What is drag?", "m": 1, "ms": ["A force that opposes motion through air or water."], "step": "Remember"}, {"q": "Give one useful and one unwanted effect of friction.", "m": 2, "ms": ["Useful: grip for walking/tyres/brakes.", "Unwanted: wears parts / wastes energy as heat."], "step": "Apply"}, {"q": "Explain why racing cyclists wear smooth helmets and tight clothing.", "m": 3, "ms": ["They reduce the area and roughness facing the air.", "This reduces air resistance (drag).", "So more of the cyclist’s energy makes them go faster."], "step": "Explain"}]}, {"key": "spring", "title": "Stretching springs", "notes": ["A spring gets longer when a pulling force is added. Extension means the extra length. Extension = stretched length − original length.", "For a spring obeying Hooke's law, force = spring constant × extension. Use extension in metres with a spring constant in N/m. Too much force can stop the spring following this rule. To test a spring, measure its starting length and then add small loads. Wait for it to settle before recording length and calculating extension. Plot force against extension and look for a straight-line pattern.", "Hooke's law says extension is proportional to force, up to the limit of proportionality. A force–extension graph is a straight line through the origin for a spring obeying Hooke's law. Beyond the elastic limit, a spring will not return to its original length."], "worked": "A spring has a spring constant of 200 N/m and extends by 0.03 m. Force = 200 × 0.03 = 6 N. The rule only works while force and extension stay proportional.", "question": "A spring has a spring constant of 200 N/m and extends by 0.03 m. Find the force and say when Hooke's law works.", "scheme": ["Use force = spring constant × extension.", "200 × 0.03 = 6 N.", "The spring must be within its limit of proportionality, before the graph stops being a straight line."], "mistake": "Use the extension, not the spring's total length.", "model": "spring", "id": "y9-unit-11-spring", "unit": "y9-unit-11", "year": 9, "number": 2, "marks": 3, "cards": [{"term": "Spring constant", "definition": "How much force is needed for each metre of extension while the spring follows Hooke's law."}, {"term": "Limit of proportionality", "definition": "The point where force and extension stop following a straight-line pattern."}], "quiz": {"q": "Which length goes into force = spring constant × extension?", "opts": ["The extra length beyond the original length.", "The total spring length.", "The original length alone."], "a": 0, "why": "Extension = stretched length − original length."}, "misconception": {"q": "Which length goes into force = spring constant × extension? Sam answers: “The total spring length.” Explain why this is wrong.", "m": 2, "ms": ["The extra length beyond the original length.", "Extension = stretched length − original length."]}, "more": [{"q": "A spring stretches 2 cm with 1 N. If it obeys Hooke’s law, how far with 3 N?", "opts": ["3 cm.", "5 cm.", "6 cm."], "a": 2, "why": "Extension is proportional to force."}, {"q": "A force–extension graph for a spring obeying Hooke’s law is…", "opts": ["a horizontal line.", "a straight line through the origin.", "a curve from the start."], "a": 1, "why": "Proportional means a straight line through zero."}, {"q": "What happens if a spring is stretched past its elastic limit?", "opts": ["It does not go back to its original length.", "It gets shorter.", "It becomes magnetic."], "a": 0, "why": "It is permanently deformed."}, {"q": "Original length 10 cm, stretched length 14 cm. Extension?", "opts": ["24 cm.", "14 cm.", "4 cm."], "a": 2, "why": "14 − 10."}], "ladder": [{"q": "What does Hooke’s law say?", "m": 1, "ms": ["The extension of a spring is proportional to the force applied (up to a limit)."], "step": "Remember"}, {"q": "A spring extends 3 cm with a 2 N load. Calculate the extension with 6 N and state an assumption.", "m": 2, "ms": ["6 ÷ 2 = 3 times the force, so 3 × 3 = 9 cm.", "Assume the spring has not passed its limit of proportionality."], "step": "Apply"}, {"q": "Describe how to investigate the extension of a spring.", "m": 3, "ms": ["Measure the original length with a ruler at eye level.", "Add masses one at a time and measure the new length each time.", "Calculate each extension and plot force against extension."], "step": "Explain"}]}, {"key": "moments", "title": "Levers and turning forces", "notes": ["A force can turn an object around a pivot. The turning effect is called a moment. A pivot is the point the object turns about.", "Moment = force × perpendicular distance from the pivot. Perpendicular means at right angles to the force's line. A balanced lever has equal clockwise and anticlockwise moments.", "A lever can multiply force: a small force far from the pivot can balance a large force close to the pivot. When a seesaw balances, clockwise moments equal anticlockwise moments. Moment is measured in newton metres, N m."], "worked": "A 12 N force acts 0.5 m from a pivot. Its moment is 12 × 0.5 = 6 N m. A force on the other side at 0.3 m must be 6 ÷ 0.3 = 20 N.", "question": "A 12 N force acts 0.5 m from a pivot. What opposite turning force at 0.3 m will balance it?", "scheme": ["First moment = 12 × 0.5 = 6 N m.", "For balance, the other moment must also be 6 N m.", "Other force = 6 ÷ 0.3 = 20 N."], "mistake": "Use the right-angle distance to the force's line, not any distance from the pivot.", "model": "lever", "id": "y9-unit-11-moments", "unit": "y9-unit-11", "year": 9, "number": 3, "marks": 3, "cards": [{"term": "Moment", "definition": "The turning effect of a force around a pivot."}, {"term": "Pivot", "definition": "The point an object turns around."}], "quiz": {"q": "Which distance is used to calculate a moment?", "opts": ["The right-angle distance from the pivot to the force's line.", "Any sloping distance from the pivot.", "The total length of the object in every case."], "a": 0, "why": "Moment uses the perpendicular, or right-angle, distance."}, "misconception": {"q": "Which distance is used to calculate a moment? Sam answers: “Any sloping distance from the pivot.” Explain why this is wrong.", "m": 2, "ms": ["The right-angle distance from the pivot to the force's line.", "Moment uses the perpendicular, or right-angle, distance."]}, "more": [{"q": "A 20 N force acts 3 m from a pivot. What is the moment?", "opts": ["23 N m.", "6.7 N m.", "60 N m."], "a": 2, "why": "M = F × d."}, {"q": "What is the unit of moment?", "opts": ["Joule only.", "Newton metre (N m).", "Newton (N)."], "a": 1, "why": "Force × distance."}, {"q": "Why is a long spanner easier to use?", "opts": ["The bigger distance gives a bigger moment for the same force.", "It is heavier.", "It makes the nut smaller."], "a": 0, "why": "Moment = F × d."}, {"q": "A seesaw balances when…", "opts": ["both people weigh the same, always.", "the pivot moves.", "clockwise moments equal anticlockwise moments."], "a": 2, "why": "This is the principle of moments."}], "ladder": [{"q": "What is a pivot?", "m": 1, "ms": ["The point that an object turns about."], "step": "Remember"}, {"q": "A 300 N child sits 2 m from the pivot of a seesaw. How far from the pivot must a 400 N child sit on the other side to balance?", "m": 2, "ms": ["300 × 2 = 600 N m.", "600 ÷ 400 = 1.5 m."], "step": "Apply"}, {"q": "Explain why a door handle is placed far from the hinges.", "m": 3, "ms": ["The hinge is the pivot.", "A bigger distance from the pivot gives a bigger moment for the same force.", "So less force is needed to open the door."], "step": "Explain"}]}, {"key": "pressure", "title": "Pressure and area", "notes": ["Pressure tells you how spread out a force is over a surface. Pressure = force ÷ area. Pressure is measured in pascals, Pa, when force is in N and area in m².", "The same force on a smaller area gives higher pressure. A larger area spreads the force and lowers pressure. This helps explain sharp tools and wide snowshoes.", "Small areas give large pressures, so knives are sharp and nails are pointed. Large areas give small pressures, so snowshoes and tractor tyres are wide. Pressure = force ÷ area."], "worked": "A 120 N force acts over 0.04 m². Pressure = 120 ÷ 0.04 = 3000 Pa. Doubling the area with the same force halves the pressure.", "question": "A 120 N force acts over 0.04 m². Find the pressure. What happens if the area doubles with the force unchanged?", "scheme": ["Pressure = 120 ÷ 0.04.", "Pressure = 3000 Pa.", "Doubling the area halves pressure to 1500 Pa."], "mistake": "Pressure and force are different. The area matters too.", "model": "shoes", "id": "y9-unit-12-pressure", "unit": "y9-unit-12", "year": 9, "number": 1, "marks": 3, "cards": [{"term": "Pressure", "definition": "Force spread over an area, calculated as force divided by area."}, {"term": "Pascal", "definition": "One newton of force per square metre."}], "quiz": {"q": "What happens to pressure if area doubles but force stays the same?", "opts": ["It halves.", "It doubles.", "It stays the same."], "a": 0, "why": "The same force is spread over twice the area, so pressure is half as large."}, "misconception": {"q": "What happens to pressure if area doubles but force stays the same? Sam answers: “It doubles.” Explain why this is wrong.", "m": 2, "ms": ["It halves.", "The same force is spread over twice the area, so pressure is half as large."]}, "more": [{"q": "A 600 N person stands on 0.02 m². What is the pressure?", "opts": ["12 Pa.", "620 Pa.", "30 000 Pa."], "a": 2, "why": "600 ÷ 0.02."}, {"q": "Why do snowshoes stop you sinking into snow?", "opts": ["They are warm.", "They spread your weight over a bigger area.", "They make you lighter."], "a": 1, "why": "Bigger area, smaller pressure."}, {"q": "Why is a knife sharp?", "opts": ["A small area gives a large pressure for cutting.", "A sharp edge is lighter.", "It reduces friction only."], "a": 0, "why": "Same force over a tiny area."}, {"q": "What is the unit of pressure?", "opts": ["Newton (N).", "Joule (J).", "Pascal (Pa)."], "a": 2, "why": "1 Pa = 1 N/m²."}], "ladder": [{"q": "Write the equation for pressure.", "m": 1, "ms": ["Pressure = force ÷ area."], "step": "Remember"}, {"q": "A box weighs 200 N and rests on an area of 0.5 m². Calculate the pressure.", "m": 2, "ms": ["P = 200 ÷ 0.5.", "= 400 Pa."], "step": "Apply"}, {"q": "Explain why a stiletto heel can damage a floor but an elephant’s foot may not.", "m": 3, "ms": ["The stiletto heel has a tiny area.", "Even a person’s small weight gives a very large pressure.", "The elephant’s weight is spread over a large foot area, so the pressure can be smaller."], "step": "Explain"}]}, {"key": "gas", "title": "Gas pressure", "notes": ["Gas particles move in all directions. They hit the walls of their container. These hits cause gas pressure.", "Squeezing a gas puts the particles in a smaller space. They hit the walls more often. This increases pressure if the temperature stays the same.", "Heating a gas makes its particles move faster. They hit the walls harder and more often, so pressure rises. Air pressure acts on us all the time because air particles hit us from every direction."], "worked": "Seal the end of a syringe containing air. Push the plunger in to reduce the space. The trapped air pushes back more strongly.", "question": "Why does squeezing the air in a sealed syringe increase its pressure?", "scheme": ["The same gas is in a smaller volume.", "Particles hit the walls more often.", "More frequent hits increase pressure."], "mistake": "Pressure comes from particles hitting a surface. Particles do not grow when heated.", "model": "particles", "id": "y9-unit-12-gas", "unit": "y9-unit-12", "year": 9, "number": 2, "marks": 3, "cards": [{"term": "Gas pressure", "definition": "The force on each unit area caused by gas particles hitting a surface."}, {"term": "Compression", "definition": "Squeezing something into a smaller volume."}], "quiz": {"q": "What happens when you heat gas in a sealed container that cannot expand?", "opts": ["Its pressure rises.", "Its number of particles falls.", "Its particles stop hitting the walls."], "a": 0, "why": "The particles move faster and hit the walls more often and harder."}, "misconception": {"q": "What happens when you heat gas in a sealed container that cannot expand? Sam answers: “Its number of particles falls.” Explain why this is wrong.", "m": 2, "ms": ["Its pressure rises.", "The particles move faster and hit the walls more often and harder."]}, "more": [{"q": "What happens to gas pressure if the gas is heated in a sealed can?", "opts": ["It decreases.", "It stays the same.", "It increases."], "a": 2, "why": "Faster particles hit the walls harder and more often."}, {"q": "What causes gas pressure?", "opts": ["Particles sticking together.", "Particles hitting the walls of the container.", "Particles getting bigger."], "a": 1, "why": "Each collision pushes on the wall."}, {"q": "A balloon is squashed to half its size. The pressure inside…", "opts": ["increases.", "decreases.", "becomes zero."], "a": 0, "why": "Particles hit the walls more often in a smaller space."}, {"q": "Why does a crisp packet puff up at the top of a mountain?", "opts": ["The air inside gets colder.", "The crisps expand.", "Air pressure outside is lower."], "a": 2, "why": "Less pressure outside lets the gas inside push outwards."}], "ladder": [{"q": "What causes the pressure of a gas?", "m": 1, "ms": ["Gas particles colliding with the walls of the container."], "step": "Remember"}, {"q": "Explain why you should not heat a sealed can.", "m": 2, "ms": ["The gas particles move faster and hit the walls harder/more often.", "The pressure could rise enough to burst the can."], "step": "Apply"}, {"q": "A football is pumped up with more air. Explain why it feels harder.", "m": 3, "ms": ["More particles are inside the same space.", "They hit the inside walls more often.", "So the pressure increases."], "step": "Explain"}]}, {"key": "liquid-pressure", "title": "Pressure in liquids and hydraulics", "notes": ["Liquid pressure acts in all directions. It increases with depth. Deeper water has more water above it pressing down.", "A hydraulic system uses liquid to pass on a pressure change. At the same pressure, a larger piston area gives a larger force. The larger piston moves a shorter distance, so no extra energy is created.", "Dams are thicker at the bottom because water pressure is greater at depth. Divers feel more pressure the deeper they go. Hydraulic brakes and car jacks use liquid pressure to multiply force."], "worked": "A container has holes at different depths. The lower hole has a greater water pressure behind it. Its water jet can leave faster and travel further.", "question": "Why can a hole lower down a water container make a stronger water jet?", "scheme": ["There is more water above the lower hole.", "Liquid pressure is greater at a greater depth.", "The greater pressure pushes water out faster."], "mistake": "The same liquid pressure can give different forces on different areas.", "model": null, "id": "y9-unit-12-liquid-pressure", "unit": "y9-unit-12", "year": 9, "number": 3, "marks": 3, "cards": [{"term": "Hydraulic system", "definition": "A system using liquid to pass on a pressure change."}, {"term": "Liquid pressure", "definition": "The force from a liquid on each unit area."}], "quiz": {"q": "Why can a larger hydraulic output piston give a bigger force?", "opts": ["A bigger piston must move further than a smaller one.", "The same pressure acts on a larger area.", "The liquid creates extra energy."], "a": 1, "why": "Force = pressure × area. The bigger force is balanced by a shorter movement."}, "misconception": {"q": "Why can a larger hydraulic output piston give a bigger force? Sam answers: “The liquid creates extra energy.” Explain why this is wrong.", "m": 2, "ms": ["The same pressure acts on a larger area.", "Force = pressure × area. The bigger force is balanced by a shorter movement."]}, "more": [{"q": "Why is a dam thicker at the bottom?", "opts": ["Water pressure is greater at greater depth.", "To look stronger.", "Because water is lighter at the bottom."], "a": 0, "why": "Pressure increases with depth."}, {"q": "Liquid pressure acts…", "opts": ["only downwards.", "only upwards.", "in all directions."], "a": 2, "why": "Water pushes on all surfaces."}, {"q": "A hydraulic jack can lift a car because…", "opts": ["oil is very light.", "pressure is passed through the liquid and acts on a larger piston.", "liquids can be squashed easily."], "a": 1, "why": "A larger area gives a larger force."}, {"q": "Water spurts furthest from a hole…", "opts": ["near the bottom of a container.", "near the top.", "at the surface."], "a": 0, "why": "The pressure is greatest there."}], "ladder": [{"q": "How does liquid pressure change with depth?", "m": 1, "ms": ["It increases with depth."], "step": "Remember"}, {"q": "Describe what you would see if three holes at different heights were made in a tall bottle of water, and why.", "m": 2, "ms": ["Water spurts out furthest from the lowest hole.", "Because pressure is greater deeper down."], "step": "Apply"}, {"q": "Explain how hydraulic brakes in a car work.", "m": 3, "ms": ["The driver pushes a small piston, creating pressure in the brake fluid.", "Liquids cannot be compressed, so the pressure is passed through the pipes.", "It acts on larger pistons at the wheels, producing a bigger force to press the brake pads."], "step": "Explain"}]}], "sources": [{"title": "Department 2026–27 teaching sequence", "kind": "curriculum", "detail": "Adapted from the lesson folders and planning workbooks supplied by the department. Revision pages consolidate related teaching periods; original slides, staff allocations and school tests are not reproduced."}, {"title": "National curriculum: science", "url": "https://www.gov.uk/government/publications/national-curriculum-in-england-science-programmes-of-study"}, {"title": "NHS: young people and vaping", "url": "https://www.nhs.uk/better-health/quit-smoking/help-others-quit/young-people-and-vaping/"}, {"title": "Met Office: causes of climate change", "url": "https://weather.metoffice.gov.uk/climate-change/causes-of-climate-change"}, {"title": "BBC Bitesize: KS3 Physics", "url": "https://www.bbc.co.uk/bitesize/subjects/ztjqfdm", "detail": "Reading-level and vocabulary reference for this original plain-language revision content."}, {"title": "BBC Bitesize: variables", "url": "https://www.bbc.co.uk/bitesize/topics/zrv3jfr/articles/zyc9r2p"}]};
window.KS_PAPERS=[{"id": "y7-paper-a", "year": 7, "paper": "A", "title": "Year 7 · Practice paper A", "minutes": 35, "marks": 30, "coverage": ["Working scientifically", "Cells", "Movement", "Particle model", "Separating mixtures", "Energy costs", "Energy transfers", "Variation and adaptation", "Human reproduction", "Plant reproduction", "Acids and alkalis", "Metals and non-metals", "Current and charge", "Potential difference and resistance"], "questions": [{"title": "Question 1", "stem": "", "parts": [{"title": "Question 1", "q": "Test how water temperature affects sugar dissolving time. Name what you change, what you measure and one thing you keep the same.", "m": 3, "ms": ["Change water temperature.", "Measure time taken for sugar to dissolve.", "Keep sugar mass, water volume, stirring or sugar grain size the same."]}]}, {"title": "Question 2", "stem": "", "parts": [{"title": "Question 2", "q": "An empty balance reads 3 g. What type of error is this? How does it affect readings, and how would you fix it?", "m": 3, "ms": ["It is a systematic or zero error.", "Readings are all 3 g too high.", "Set the balance to zero or calibrate it before measuring."]}]}, {"title": "Question 3", "stem": "", "parts": [{"title": "Question 3", "q": "A microscope has a ×12 eyepiece and ×10 objective. Find total magnification. Give one rule for drawing a clear cell diagram.", "m": 3, "ms": ["Multiply 12 × 10.", "Total magnification = ×120.", "Use clear single lines, straight label lines or suitable proportions."]}]}, {"title": "Question 4", "stem": "", "parts": [{"title": "Question 4", "q": "Name three structures in a typical leaf cell that are not found in a typical animal cell.", "m": 3, "ms": ["A cell wall.", "Chloroplasts.", "A large permanent vacuole."]}]}, {"title": "Question 5", "stem": "", "parts": [{"title": "Question 5", "q": "Why do muscles work as an opposing pair to bend and straighten a joint?", "m": 3, "ms": ["Muscles pull rather than actively push.", "One muscle contracts to move the joint one way.", "The other contracts to move it back."]}]}, {"title": "Question 6", "stem": "", "parts": [{"title": "Question 6", "q": "Use particles to explain why a gas fills its container but a solid keeps its shape.", "m": 3, "ms": ["Gas particles move freely with large gaps.", "They spread throughout the available space.", "Solid particles vibrate around fixed positions."]}]}, {"title": "Question 7", "stem": "", "parts": [{"title": "Question 7", "q": "How would you get salt crystals from a dry mixture of salt and sand?", "m": 3, "ms": ["Add water to dissolve the salt.", "Filter out the sand.", "Evaporate some water and leave the solution to form crystals."]}]}, {"title": "Question 8", "stem": "", "parts": [{"title": "Question 8", "q": "A lamp takes in 240 J and gives 36 J as useful light. Find its efficiency and the unwanted energy transfer.", "m": 3, "ms": ["Efficiency = 36 ÷ 240 = 0.15.", "Efficiency = 15%.", "Unwanted energy = 240 − 36 = 204 J."]}]}, {"title": "Question 9", "stem": "", "parts": [{"title": "Question 9", "q": "A 1.5 kW heater runs for 2 hours. Electricity costs 24 p per kWh. Find the energy used and the cost.", "m": 3, "ms": ["Energy = 1.5 × 2 = 3 kWh.", "Cost = 3 × 24.", "Cost = 72 p."]}]}, {"title": "Question 10", "stem": "", "parts": [{"title": "Question 10", "q": "How are inherited and environmental differences different? Give one example of each.", "m": 3, "ms": ["Inherited differences come from genes passed on by parents.", "Environmental differences come from surroundings or experiences.", "Examples include inherited ABO blood group and an environmental scar; accept other correct examples."]}]}]}, {"id": "y7-paper-b", "year": 7, "paper": "B", "title": "Year 7 · Practice paper B", "minutes": 35, "marks": 30, "coverage": ["Working scientifically", "Cells", "Movement", "Particle model", "Separating mixtures", "Energy costs", "Energy transfers", "Variation and adaptation", "Human reproduction", "Plant reproduction", "Acids and alkalis", "Metals and non-metals", "Current and charge", "Potential difference and resistance"], "questions": [{"title": "Question 1", "stem": "", "parts": [{"title": "Question 1", "q": "What are fertilisation and implantation in humans? Say where each usually happens.", "m": 3, "ms": ["Sperm and egg nuclei join at fertilisation.", "Fertilisation usually happens in an oviduct, also called a fallopian tube.", "The embryo later attaches to the uterus lining at implantation."]}]}, {"title": "Question 2", "stem": "", "parts": [{"title": "Question 2", "q": "Describe two features of an insect-pollinated flower. Explain how a feature helps pollination.", "m": 3, "ms": ["A feature such as bright petals or scent.", "It attracts insects that can carry pollen.", "Nectar attracts insects, or sticky pollen attaches to them; link a second feature to its job."]}]}, {"title": "Question 3", "stem": "", "parts": [{"title": "Question 3", "q": "How is pollination different from fertilisation in a flowering plant? Include the step that links them.", "m": 3, "ms": ["Pollination moves pollen from anther to stigma.", "A pollen tube grows towards an ovule.", "At fertilisation, male and egg nuclei join."]}]}, {"title": "Question 4", "stem": "", "parts": [{"title": "Question 4", "q": "Name three conditions most seeds need to germinate. Explain why one is needed.", "m": 3, "ms": ["Water.", "Oxygen.", "A suitable temperature, plus an explanation such as oxygen being needed for aerobic respiration."]}]}, {"title": "Question 5", "stem": "", "parts": [{"title": "Question 5", "q": "A pupil says every strong acid must be concentrated. Why are these words different?", "m": 3, "ms": ["Strength describes how much the acid splits into charged particles in water.", "Concentration describes how much acid is in a given volume of solution.", "A strong acid can be dilute if mixed with plenty of water."]}]}, {"title": "Question 6", "stem": "", "parts": [{"title": "Question 6", "q": "Zinc reacts with dilute hydrochloric acid. Name the products and describe a test for the gas.", "m": 3, "ms": ["Zinc chloride.", "Hydrogen.", "A small sample makes a squeaky pop with a lighted splint in a teacher-supervised test."]}]}, {"title": "Question 7", "stem": "", "parts": [{"title": "Question 7", "q": "Magnesium is more reactive than copper. What happens when magnesium is put into copper sulfate solution? Explain why.", "m": 3, "ms": ["Magnesium displaces copper.", "Magnesium sulfate and copper form.", "Magnesium replaces copper because it is more reactive."]}]}, {"title": "Question 8", "stem": "", "parts": [{"title": "Question 8", "q": "Two parallel branches carry 0.35 A and 0.45 A. Find the supply current and explain your method.", "m": 3, "ms": ["Add 0.35 + 0.45.", "Supply current = 0.80 A.", "Total current into a junction equals total current out."]}]}, {"title": "Question 9", "stem": "", "parts": [{"title": "Question 9", "q": "A resistor has 9 V across it and a current of 0.3 A. Find its resistance. How should the voltmeter be connected?", "m": 3, "ms": ["Resistance = voltage ÷ current.", "9 ÷ 0.3 = 30 Ω.", "Connect the voltmeter in parallel across the resistor."]}]}, {"title": "Question 10", "stem": "", "parts": [{"title": "Question 10", "q": "A ball bounces lower each time. Why is the total energy of the ball and its surroundings still conserved?", "m": 3, "ms": ["Less energy remains in the ball for movement and height.", "Energy transfers to heating and sound in the surroundings.", "The energy is not destroyed, so the total stays the same."]}]}]}, {"id": "y8-paper-a", "year": 8, "paper": "A", "title": "Year 8 · Practice paper A", "minutes": 35, "marks": 30, "coverage": ["Interdependence", "Speed", "Gravity and forces", "Elements and materials", "Periodic table", "Breathing and health", "Digestion and nutrition", "Sound", "Light", "Reaction types", "Chemical energy", "Respiration", "Photosynthesis", "Working scientifically investigations"], "questions": [{"title": "Question 1", "stem": "", "parts": [{"title": "Question 1", "q": "In grass → grasshopper → bird, grasshopper numbers fall. What might happen to the grass and birds? Give one reason your prediction may not be exact.", "m": 3, "ms": ["Grass may increase because less is eaten.", "Birds may decline because they have less food.", "Other food sources or other changes in the food web could affect the result."]}]}, {"title": "Question 2", "stem": "", "parts": [{"title": "Question 2", "q": "How could you use quadrats to estimate how many plants grow in a field?", "m": 3, "ms": ["Place equal-sized quadrats at random points and count consistently.", "Calculate a mean number per square metre from several samples.", "Multiply by field area and state that the answer is an estimate."]}]}, {"title": "Question 3", "stem": "", "parts": [{"title": "Question 3", "q": "A trolley travels 3.6 m in 6 seconds. Find its average speed. Give one way to reduce timing error.", "m": 3, "ms": ["Speed = 3.6 ÷ 6.", "Speed = 0.6 m/s.", "Use electronic timing or a longer timed distance to reduce the effect of reaction time."]}]}, {"title": "Question 4", "stem": "", "parts": [{"title": "Question 4", "q": "Describe the forces on a skydiver falling at terminal velocity. Why is the speed steady?", "m": 3, "ms": ["Weight acts downwards.", "Drag acts upwards with the same size as weight.", "The forces balance, so speed does not change."]}]}, {"title": "Question 5", "stem": "", "parts": [{"title": "Question 5", "q": "What is an element, a compound and a mixture? Give an example of each.", "m": 3, "ms": ["An element contains one type of atom, such as iron.", "A compound has different elements chemically joined, such as water.", "A mixture contains substances not chemically joined to each other, such as air."]}]}, {"title": "Question 6", "stem": "", "parts": [{"title": "Question 6", "q": "How does reactivity change down Groups 1 and 7? Chlorine is more reactive than bromine. Can it displace bromine from a bromide solution?", "m": 3, "ms": ["Group 1 generally gets more reactive down the group.", "Group 7 generally gets less reactive down the group.", "Yes. Chlorine displaces the less reactive bromine."]}]}, {"title": "Question 7", "stem": "", "parts": [{"title": "Question 7", "q": "Give three features that help alveoli exchange gases quickly.", "m": 3, "ms": ["A large surface area.", "Thin walls give a short distance for gases to travel.", "A good blood supply and fresh air maintain concentration differences."]}]}, {"title": "Question 8", "stem": "", "parts": [{"title": "Question 8", "q": "How do enzymes and villi help digested nutrients reach the blood?", "m": 3, "ms": ["Enzymes break large food molecules into small soluble ones.", "Villi give a large surface area for absorption.", "Small molecules pass through the thin gut wall into the blood."]}]}, {"title": "Question 9", "stem": "", "parts": [{"title": "Question 9", "q": "What does a positive iodine test look like? What can and cannot be concluded from a negative result?", "m": 3, "ms": ["A blue-black colour shows starch was detected.", "A negative result means starch was not detected in that test.", "Other carbohydrates, such as sugars, may still be present."]}]}, {"title": "Question 10", "stem": "", "parts": [{"title": "Question 10", "q": "Why should young people not describe nicotine vaping as harmless? Give three points.", "m": 3, "ms": ["Nicotine can cause dependence, making it difficult to stop.", "It can affect health and the developing body.", "Less harmful than smoking does not mean harmless or suitable for children and non-smokers."]}]}]}, {"id": "y8-paper-b", "year": 8, "paper": "B", "title": "Year 8 · Practice paper B", "minutes": 35, "marks": 30, "coverage": ["Interdependence", "Speed", "Gravity and forces", "Elements and materials", "Periodic table", "Breathing and health", "Digestion and nutrition", "Sound", "Light", "Reaction types", "Chemical energy", "Respiration", "Photosynthesis", "Working scientifically investigations"], "questions": [{"title": "Question 1", "stem": "", "parts": [{"title": "Question 1", "q": "A wave has frequency 8 Hz and wavelength 0.5 m. Find its speed. What does frequency mean?", "m": 3, "ms": ["Speed = frequency × wavelength.", "Speed = 8 × 0.5 = 4 m/s.", "Frequency is the number of complete vibrations each second."]}]}, {"title": "Question 2", "stem": "", "parts": [{"title": "Question 2", "q": "How is a higher-pitched sound different from a louder sound?", "m": 3, "ms": ["A higher pitch means a higher frequency.", "A louder sound usually has a larger amplitude.", "Pitch and loudness can change separately."]}]}, {"title": "Question 3", "stem": "", "parts": [{"title": "Question 3", "q": "A ray hits a plane mirror at 28° to the normal. Find the reflection angle and the angle to the mirror surface.", "m": 3, "ms": ["The reflection angle is 28° to the normal.", "The normal is at 90° to the mirror.", "The angle to the mirror surface is 90 − 28 = 62°."]}]}, {"title": "Question 4", "stem": "", "parts": [{"title": "Question 4", "q": "A reaction in an open flask gives off gas and the measured mass falls. Why has mass not been destroyed?", "m": 3, "ms": ["Gas leaves the flask.", "The gas still exists outside the flask.", "Counting all reactants and products, including the gas, gives the same total mass."]}]}, {"title": "Question 5", "stem": "", "parts": [{"title": "Question 5", "q": "Explain why an exothermic reaction warms its surroundings. Include breaking and making bonds.", "m": 3, "ms": ["Breaking old bonds takes in energy.", "Making new bonds releases energy.", "More energy is released than taken in, so the extra energy warms the surroundings."]}]}, {"title": "Question 6", "stem": "", "parts": [{"title": "Question 6", "q": "A catalyst gives more gas after 30 seconds but the same final gas volume. Explain why.", "m": 3, "ms": ["A catalyst speeds up the reaction.", "The same starting amounts can make the same total gas.", "The reaction finishes sooner rather than making extra product."]}]}, {"title": "Question 7", "stem": "", "parts": [{"title": "Question 7", "q": "Write the word equation for aerobic respiration. How is respiration different from breathing?", "m": 3, "ms": ["Glucose + oxygen → carbon dioxide + water.", "Respiration is a chemical process in cells that releases energy.", "Breathing moves air into and out of the lungs."]}]}, {"title": "Question 8", "stem": "", "parts": [{"title": "Question 8", "q": "Name the two products of yeast fermentation. Explain how one helps bread making.", "m": 3, "ms": ["Ethanol.", "Carbon dioxide.", "Carbon dioxide bubbles make the dough rise."]}]}, {"title": "Question 9", "stem": "", "parts": [{"title": "Question 9", "q": "Why might brighter light stop increasing oxygen production by pondweed?", "m": 3, "ms": ["At first, too little light slowed photosynthesis.", "Another factor, such as carbon dioxide, may now be in short supply.", "Extra light alone cannot remove that other limit."]}]}, {"title": "Question 10", "stem": "", "parts": [{"title": "Question 10", "q": "Dye spreads faster in warm water. Give one control and explain why the result may not be due to diffusion alone.", "m": 3, "ms": ["Keep dye amount, water volume or container size the same and do not stir.", "Convection currents can carry the coloured water.", "The colour spreading therefore does not measure diffusion alone."]}]}]}, {"id": "y9-paper-a", "year": 9, "paper": "A", "title": "Year 9 · Practice paper A", "minutes": 35, "marks": 30, "coverage": ["Electromagnets", "Work and machines", "Heating and cooling", "Climate", "Earth’s resources", "Evolution and biodiversity", "Inheritance", "Waves and the EM spectrum", "Earth structure and rocks", "The Universe", "Contact forces", "Pressure"], "questions": [{"title": "Question 1", "stem": "", "parts": [{"title": "Question 1", "q": "Why does a compass turn near a bar magnet? Which way do field arrows point outside the magnet?", "m": 3, "ms": ["A compass needle is a small magnet.", "It turns to line up with the magnetic field.", "Field arrows outside a magnet point from north to south."]}]}, {"title": "Question 2", "stem": "", "parts": [{"title": "Question 2", "q": "How does an electromagnet operate a relay switch? Give one benefit of this type of magnet.", "m": 3, "ms": ["Current in a coil makes a magnetic field.", "The magnet pulls a metal part to operate a switch.", "Switching the current lets you turn the magnet on and off."]}]}, {"title": "Question 3", "stem": "", "parts": [{"title": "Question 3", "q": "A 30 N force moves a load 2.5 m in its direction. Find the work done. What does the unit mean?", "m": 3, "ms": ["Work done = force × distance.", "30 × 2.5 = 75 J.", "A joule is a unit of energy transferred."]}]}, {"title": "Question 4", "stem": "", "parts": [{"title": "Question 4", "q": "A 15 N force acts 0.4 m from a pivot. What force on the opposite side, 0.6 m away, balances it?", "m": 3, "ms": ["First moment = 15 × 0.4 = 6 N m.", "The other force × 0.6 must equal 6 N m.", "Other force = 6 ÷ 0.6 = 10 N."]}]}, {"title": "Question 5", "stem": "", "parts": [{"title": "Question 5", "q": "How does a vacuum flask reduce conduction, convection and radiation?", "m": 3, "ms": ["The vacuum greatly reduces conduction across the gap because it has almost no particles.", "The vacuum prevents convection across the gap.", "Shiny surfaces reduce infrared radiation transfer."]}]}, {"title": "Question 6", "stem": "", "parts": [{"title": "Question 6", "q": "How can burning fossil fuels change the carbon cycle and warm Earth?", "m": 3, "ms": ["Burning moves carbon from fuel into the air as carbon dioxide.", "Extra carbon dioxide absorbs more outgoing infrared radiation and sends some back towards the surface.", "This changes the energy balance and causes warming."]}]}, {"title": "Question 7", "stem": "", "parts": [{"title": "Question 7", "q": "Why can carbon extract some metals from their oxides, while aluminium is usually extracted using electricity?", "m": 3, "ms": ["The metal reactivity affects the extraction method.", "Carbon can remove oxygen from oxides of less reactive metals.", "Aluminium is more reactive than carbon, so electricity is used instead."]}]}, {"title": "Question 8", "stem": "", "parts": [{"title": "Question 8", "q": "Give two environmental benefits and one drawback of recycling metals.", "m": 3, "ms": ["It saves limited metal ores.", "It often uses less energy and reduces mining damage.", "Collection, sorting and processing still use resources."]}]}, {"title": "Question 9", "stem": "", "parts": [{"title": "Question 9", "q": "Describe natural selection in three linked steps.", "m": 3, "ms": ["Individuals have inherited differences.", "Those with helpful features are more likely to survive and reproduce.", "They pass on genes, so helpful features can become more common over generations."]}]}, {"title": "Question 10", "stem": "", "parts": [{"title": "Question 10", "q": "Why might a breeding programme alone not save an endangered species in the wild?", "m": 3, "ms": ["Enough animals must breed successfully with enough inherited variation.", "They also need a safe, suitable habitat.", "If threats remain, released animals may not survive and reproduce."]}]}]}, {"id": "y9-paper-b", "year": 9, "paper": "B", "title": "Year 9 · Practice paper B", "minutes": 35, "marks": 30, "coverage": ["Electromagnets", "Work and machines", "Heating and cooling", "Climate", "Earth’s resources", "Evolution and biodiversity", "Inheritance", "Waves and the EM spectrum", "Earth structure and rocks", "The Universe", "Contact forces", "Pressure"], "questions": [{"title": "Question 1", "stem": "", "parts": [{"title": "Question 1", "q": "How are DNA, chromosomes, genes and alleles related?", "m": 3, "ms": ["Chromosomes contain long DNA molecules.", "Genes are sections of DNA.", "Alleles are different versions of a gene."]}]}, {"title": "Question 2", "stem": "", "parts": [{"title": "Question 2", "q": "In a simple dominant model, cross Aa with Aa. Give the genotype ratio and the chance of the recessive feature.", "m": 3, "ms": ["Possible combinations are AA, Aa, Aa and aa.", "The genotype ratio is 1 AA : 2 Aa : 1 aa.", "The recessive feature has a 1 in 4 chance."]}]}, {"title": "Question 3", "stem": "", "parts": [{"title": "Question 3", "q": "An ultrasound echo returns after 0.00008 seconds. Sound speed is 1500 m/s. How deep is the reflecting surface?", "m": 3, "ms": ["Total distance = 1500 × 0.00008 = 0.12 m.", "Divide by two for the outward and return journeys.", "Depth = 0.06 m."]}]}, {"title": "Question 4", "stem": "", "parts": [{"title": "Question 4", "q": "Compare sound and electromagnetic waves. Which need a material to travel through, and which can be ionising?", "m": 3, "ms": ["Sound needs a material, but electromagnetic waves can cross empty space.", "Sound is not ionising.", "Some high-energy electromagnetic waves, such as X-rays, can ionise atoms and damage cells."]}]}, {"title": "Question 5", "stem": "", "parts": [{"title": "Question 5", "q": "How do igneous, sedimentary and metamorphic rocks form?", "m": 3, "ms": ["Igneous rock forms when molten rock cools and becomes solid.", "Sedimentary rock often forms when layers of sediment are pressed and cemented together.", "Metamorphic rock forms when heat and pressure change rock without melting it."]}]}, {"title": "Question 6", "stem": "", "parts": [{"title": "Question 6", "q": "Why do normal Moon phases happen? Why are they different from an eclipse?", "m": 3, "ms": ["The Moon reflects sunlight and roughly half is lit.", "Its orbit changes how much of the lit half we can see.", "The shadow of Earth causes a lunar eclipse, not normal phases."]}]}, {"title": "Question 7", "stem": "", "parts": [{"title": "Question 7", "q": "Explain the seasons on Earth using its tilted axis. Why does summer not depend mainly on Earth being closer to the Sun?", "m": 3, "ms": ["The axis of Earth is tilted.", "The hemisphere tilted towards the Sun has longer days.", "It also receives more direct sunlight, while the other hemisphere has winter."]}]}, {"title": "Question 8", "stem": "", "parts": [{"title": "Question 8", "q": "A 5 N force extends a spring by 0.025 m. Find the spring constant. State when this calculation is valid.", "m": 3, "ms": ["Spring constant = force ÷ extension.", "5 ÷ 0.025 = 200 N/m.", "The spring must be within the straight-line force–extension range, below its limit of proportionality."]}]}, {"title": "Question 9", "stem": "", "parts": [{"title": "Question 9", "q": "A 480 N force acts over 0.024 m². Find the pressure. What if the area doubles while force stays the same?", "m": 3, "ms": ["Pressure = 480 ÷ 0.024 = 20,000 Pa.", "Doubling area halves pressure at the same force.", "The new pressure is 10,000 Pa."]}]}, {"title": "Question 10", "stem": "", "parts": [{"title": "Question 10", "q": "How can a hydraulic system give a larger output force without creating extra energy?", "m": 3, "ms": ["A pressure change is passed through the enclosed liquid.", "A larger output piston area gives a larger force.", "The larger piston moves a shorter distance, so no extra energy is created."]}]}]}];
